INSERT INTO `food` (`id`, `name`, `tel`, `city`, `town`, `addr`, `feature`, `picurl`) VALUES
(1, '三富休閒農場(紫森林)', '03-958-8690', '宜蘭縣', '冬山鄉', '中山村新寮二路161巷88號', '【目前僅開放住客入園，暫停一日遊及入園參觀】\r\n  \r\n  三富休閒農場設立於1989年，佔地面積約14公頃，緊鄰仁山植物園及新寮瀑布，景緻天然怡人，生態景觀豐富而特殊，四季各具不同風情，營業項目有：特色餐飲、休閒住宿、會議研習、高空繩索、自然旅遊、套裝行程、環境教育、創意DIY。\r\n  \r\n  \r\n  三富休閒農場自成立以來，秉持對土地與生態環境保護的熱忱，結合四季時令，讓各種植物與昆蟲，保持其自然的食物鏈關係，利用自然生態工法維持生態平衡。這塊土地自轉型休閒農場以來，常年不使用農藥及化學肥料，以尊重環境倫理的方式，讓園內作物自然生長，為週邊的動物昆蟲提供天然的食物來源。\r\n  \r\n  \r\n  「營造一個好的自然環境能帶給人們啟發環境行動的重要生命經驗，引領民眾親近自然、體驗自然、學習自然，感受人與自然密不可分的關係，獲取環境保護的正確知識、技能與正向能量，與我們一起守護這份可貴的自然資源與環境，以追求人與人、環境、萬物間的永續和諧為目標。」\r\n本休閒農場取得台灣休閒農場服務認證，詳細資訊請參考「台灣休閒農場服務認證官方網站」\r\n【園區景觀】\r\n  \r\n  \r\n \r\n【住宿環境】 \r\n  \r\n  欒樹館住宿套房 \r\n紫屋館住宿套房 \r\n森林館住宿套房 \r\n  \r\n  \r\n \r\n夜間生態導覽\r\n  \r\n  住宿客人都可參加夜間生態導覽，跟著專業的導覽老師，一起探索可愛的青蛙、蜘蛛、螢火蟲等夜行性昆蟲與動物。\r\n度過悠閒舒適的美好時光\r\n  \r\n  三富園區內的紫屋森林庭園，有美麗的景觀魚池，清泉綠蔭、魚鴨成群，鳥兒自由嬉戲。您可以在池畔一邊享用紫森林的特色下午茶，度過悠閒舒適的美好時光。當然，也很適合放空囉！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25819/480x360_agrispots-image--i0uqxsgseicmbf12-ztpa.jpg'),
(2, '梅居休閒農場', '0905-169-176', '臺北市', '士林區', '平等里平菁街43巷99號', '位於陽明山平菁街43巷底的梅居休閒農場，印入眼簾的是群山環繞的壯闊，感受的是遠離塵囂的幽靜。\r\n感念長輩辛勞耕耘的橘子園地，郭大哥與安心姊將荒蕪橘子園，開創出與山林動植物和諧共生的永續環保農場。\r\n我們希望每位蒞臨的客人，都能好好享受山上新鮮空氣、眺望台北盆地美景，從體內至感官，都能享受友善自然的愉悅時光。\r\n在地美食\r\n農場附設無菜單蔬食餐廳，主廚運用時令蔬果，烹調出各式各樣的蔬食料理，堅持使用當地食材，縮短從產地到餐桌的時間，讓客人品嘗最新鮮、健康的料理。\r\n餐廳經中國回教協會核發的穆斯林友善餐廳、慈心友善認證，並通過特色農業旅遊認證，是一間可以放心享用美味的優良餐廳。\r\n◎ 11：30-14：00無菜單蔬食料理供應(需事前預約)\r\n◎ 14：00-17：00下午茶供應(最後點餐時間16：00)\r\n有任何相關問題歡迎來電0905-169-176\r\n體驗活動\r\n【農夫體驗】(4人開班)\r\n什麼是目前對生態最好的耕作方法？讓我們與大自然學習，在這一片圍繞著森林的田地，打開感官感受自然給予的，揮動汗水親手耕種。\r\n【花草槌染DIY】(4人開班)\r\n大自然是個神奇的魔術師，總是變出許多美麗又驚奇的禮物給我們；有五彩繽紛的花朵，還有各式形狀的樹葉。\r\n手作內容包含「筆袋」、「束口袋」、「筆記本」，大家可以依照自己喜歡的物品來報名活動項目唷！\r\n【芭蕉千層DIY】(4人開班)\r\n原料使用巧克力，再加上梅居農場親自栽培的芭蕉，天然100%無農藥，新鮮第一，讓您吃得安心又美味。\r\n【香草手工餅乾DIY】(4人開班)\r\n從梅居現摘現採，新鮮無毒香草，透過掌心的溫度及創意，揉捏出專屬自己的味道與造型。烘烤後，奶香四溢的餅乾從烤箱中出爐，壤您感受滿滿的幸福！\r\n【手摘現沖香草茶體驗】(4人開班)\r\n以芳香萬壽菊修剪下來的新鮮枝葉泡茶，百香果的香味，搭配檸檬香氣的香草，再加上一些薄荷葉與甜菊葉，就是一款非常好喝的新鮮香草茶。\r\n【野菜pizza DIY】(4人開班)\r\n各式食材裝點五顏六色的蔬食pizza，不僅色、香、味俱全又健康，重點是！這是讓你自己動手做的pizza！除了親手做，連食材都是小農當季現採的喔！\r\n【戶外瑜珈】(6人開班)\r\n靜心在戶外瑜珈，藉由老師的帶領， 從放鬆冥想，聆聽大自然給自己的訊息。在山林間盡情舒展身體，結束後啜飲一杯梅居新鮮現摘香草茶，讓您回歸初衷，放鬆身心。\r\n【攀樹體驗】(8人開班)\r\n呼吸著新鮮空氣、眺望台北盆地美景，享受友善自然的愉悅時光。由專業的教練引導，利用自己的身體協調與肌肉，以樹的視角來看大自然，更深入的體會戶外美好。\r\n伴手禮與農特產\r\n【三杯杏鮑菇外帶/冷凍包】\r\n300克，主廚研發的全素三杯醬，煸炒微焦金黃香料，口感擔當杏鮑菇，裹上滿滿醬汁，非常適合搭配主食享用。\r\n【福圓苦瓜外帶/冷凍包】\r\n350克，使用甘甜味十足的龍眼乾及豆豉，呈現出苦瓜的甘甜，加上梅居自產自釀的紫蘇梅汁，燉出微焦金黃的鹹甘脆口苦瓜。\r\n【香菇素燥外帶/冷凍包】\r\n350克，煸炒出溫潤的香菇及薑的氣息，搭上香椿及秘製中藥粉，最後加入其它菇類及黃豆製成的素肉燥，一起吸取飽滿湯汁，是醬香甘甜，十分下飯的一道菜品。\r\n【蜜菓芋棗外帶/冷凍包】\r\n天然的芋頭香氣，包裹酸甜蜜棗，外皮香脆，內餡綿軟，不論是一餐飯後的結尾或是下午茶搭配都推薦。\r\n◎其他架上農產品會依照季節做更換，請以現場商品為主\r\n專題報導\r\n【台灣真善美】無毒環保全方位有機農場\r\n【110年臺北好農】山坡上的世外桃源\r\n【食尚玩家熱血48小時】北台灣藏身在巷弄中的神秘美食 (29:08)', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25120/480x360_agrispots-image-khbonm2dh0udqkznzbk59a.png'),
(3, '天使花園休閒農場', '08-780-1699', '屏東縣', '竹田鄉', '鳳明村福安路120巷101號', '天使花園休閒農場是台灣第一間以「蘭花」為主題的休閒農場，農場內除了有蘭花溫室、大片草地、戲沙區之外，還有一座白色教堂玻璃屋是最為吸睛。\r\n為響應友愛環境、食農教育的政策，天使花園休閒農場所提供的無國界料理，食材均使用來自在地小農的安心食材，如：無毒檸檬、老鷹紅豆、搖滾雞、有機蔬菜等，希望提供給客人健康美味的各式料理。\r\n園區內除了餐飲外，也舉辦各式手作DIY活動，是一個「認識蘭花生態、觀賞蘭花之美、創作蘭花藝術」的遊憩教育場所，也是一處極為別緻的花園餐宴會所，無論是三五親友相聚、團體餐敘、特殊節慶、婚禮派對等，都能在這裡體驗到很不一樣的「蘭花饗宴」。\r\n來趟花園小旅行吧！感受花藝空間帶給生活的優雅與喜悅，品嚐來自在地食材的無國界料理，以及了解蘭花與大自然的奧秘，傳遞蘭花的幸福喜悅！\r\n體驗活動\r\n居家花藝、無毒檸檬醋、一日花農 / 花束DIY: 小束150元、大束250元 / 蘭花絹印:束口袋150元、手提側背袋300元\r\n天使花園戶外婚禮介紹  \r\n從入口處敲響幸福的鐘聲開始，一路沿著清澈見底的水道，引領您走進彷彿置身於國外般的英式自色庭園\r\n天使花園休閒農場在整體環境與建築都相當有特色，園區走歐洲英式的古典風格，以白色為基調的教堂建築營造出充滿異國情調的氛圍。\r\n園區內的餐飲食材及DIY體驗活動都是以屏東本土的農產品為主，老闆陳宏志先生秉持著「支持在地、發揚屏東」的理念來回饋對家鄉土地的感恩。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/4317/480x360_IMG_8716.jpg'),
(4, '田媽媽幸福田心', '04-9265-8350', '南投縣', '竹山鎮', '延平里東鄉路3之9號', '田媽媽幸福田心以貓頭鷹做造景，這裡有許多農特產品，最熱銷的奇仔冰冰棒有各種水果口味，特色手作貝果也是許多人熱愛的產品，例如：洛神花黎麥貝果、蜜地瓜貝果等，還有芒果乾、洛神仙楂茶和山芭樂茶等等。\r\n在地特色伴手禮：茶葉火龍果米香\r\n選用在地竹山富州休閒農業區的小農所種植的無毒和有機認證的糙米和火龍果，茶末也是在地茶農生產的茶葉研磨而成。希望用在地、食在地，減少食物里程，吃得更健康。\r\n茶葉火龍果米香以糙米為主原料，糙米富含膳食纖維，維生素B群、E和蛋白質&hellip;等，糙米爆開後，較易消化，解決了消化系統較差的人食用後的困擾，並佐以花生，茶末和火龍果乾天然的甜味，讓口感香氣更有層次。\r\n貓頭鷹造景\r\n水果冰棒\r\n火龍果冰淇淋\r\n蜜地瓜貝果\r\n洛神花黎麥貝果\r\n茶葉火龍果米香\r\n山芭樂茶\r\n鳳梨酵素\r\n由國道3下竹山交流道右轉&gt;由保甲路左轉&gt;到東鄉路左轉&gt;行經竹屋部落&gt;鄉村甕缸雞&gt;往前約200公尺即可抵達田媽媽幸福田心(初鄉橋頭前)', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/4353/480x360_kito-137(2).jpg'),
(5, '米國學校餐廳', '08-981-4903', '臺東縣', '關山鎮', '豐泉里昌林24-1號', '台東關山鎮農會休閒中心「米國學校田媽媽餐廳」，位於台九線上，是早期舊米廠的一部分，環境幽美餐廳舒適寬敞。\r\n來到學校當然就要吃午餐，這裡僅供應午餐，田媽媽們以低油、低鹽、高纖作為料理原則，推出復古碗公餐「無菜單料理」，選用當地當季食材，因此不同季節來此，將會吃到不同菜色的限量午餐，大碗公內盛著滿滿的關山米飯，以及當地時令蔬菜，還有田媽媽自製傳統客家料理梅干菜及爌肉料理等，份量大一定能吃得飽。\r\n米國學校設有水稻文物館、米食DIY教室、米雕教室、農產品展售中心等，除了吃限定版大碗公便當之外，還可以預約DIY親自體驗製米過程，在這裡可議獲得「看米、聽米、吃米、玩米、買米』的獨特體驗，還能將自己親手包裝的米當成紀念品帶回家。\r\n \r\n體驗活動\r\n◎真空香米-製米體驗(含製米認證盒+1kg香米)\r\n◎易煮米-製米體驗(含製米認證盒+1罐320g香米及1罐320g白米)\r\n◎米食糕點體驗米食應用介紹(體驗米苔目+艾草糕+麻糬)\r\n◎3D立體藝術陶瓷彩繪(以現場陶瓷素胚大小定價)\r\n◎蜂王乳體驗(含蜂蜜及蜂王乳乙瓶)\r\n◎蜂蠟蠟燭體驗(認識蜂蜜及蜜蜂，製作蜂蠟蠟燭)\r\n◎搓愛玉體驗(了解愛玉生長過程及搓愛玉體驗)\r\n◎豆腐乳體驗(了解製作過程、學習醃製技術，帶豆腐乳回家)\r\n◎葉拓杯套(捶打拓印-環保杯套，最多15人)\r\n伴手禮與農特產\r\n◎關山限定米乖乖(奶油口味、五香口味)\r\n◎米國學校系列產品-米香堅果酥\r\n◎米國學校系列產品-五穀海苔脆片\r\n◎米國學校系列產品-拌飯素香鬆', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/4362/480x360_2c8uxu3xsdnnxd8dz95310jtqmcsidjr.jpg'),
(6, '雲也居一休閒農場', '03-795-1530', '苗栗縣', '大湖鄉', '栗林村薑麻園6號', '「雲也居一」是苗栗山區知名的景觀餐廳，地處山腰上，遠眺大雪山山脈，每當天氣轉變、氣溫下降時，白色的霧氣瀰漫整個山嶺，讓人彷彿置身仙境，來到雲也居一不只可以欣賞優美的山景，還能感受到田媽媽彭麗貞親切誠懇的客家風情。\r\n客語「薑麻」是薑母的意思，麗貞媽媽一家人在這裡種出漂亮薑母，研發出一系列「薑」創意料理，還曾獲選為2011年十大神農獎第一名。薑麻園的薑是「種薑」,肉身較長、厚實、芽點多,種在排水性良好、土質紮實的帶石粒土壤中，薑很能吃肥，每種兩年要休耕五年，讓土壤以自然的方式恢復天然養份。\r\n老薑香氣 足、辣 度夠，無論煮湯或燉麻油雞、爆香都是很好的選擇，麗貞媽媽說：「老薑適合料理入菜、嫩薑適合醃漬或清炒，滋味各有不同。」，招牌菜「香薑雞」類似三杯做法，煸炒薑母、放入醬油和雞肉一起收 汁，遠遠就可聞到濃濃香氣，而且同時吃得到雞肉的鮮嫩和薑母的辛香；另一道「薑爆蝦」也是乾燒手法，在薑母清香的提味中吃得出鮮蝦的甜脆，除了餐 點之外還有薑飲料、餅乾等手工點 心，夏天爽口、冬天暖胃。\r\n \r\n香薑雞套餐\r\n香薑雞溢滿撲鼻的薑香入口溫順不辛辣，吸飽雞汁的薑片與鮮嫩的雞肉，讓人回味無窮。 \r\n薑母雞酒鍋\r\n用全酒烹煮的薑母雞酒，香氣逼人、濃郁芬芳，是冬日補、產後養身的最佳食補料理。 \r\n起飛雲朵\r\n將豬肉切成條狀後不斷的翻炒直到香氣四溢，再搭配雲朵（麵疙瘩）一起吃，超級美味。 \r\n自製草莓汁和草莓果醬，做成手工甜品', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3058/480x360_9pn1wt2xqnzdpnb2kzdse8t31ynwx51w.jpg'),
(7, '池農養生美食餐坊', '08-986-5936', '臺東縣', '池上鄉', '新興村85-6號', '「池農養生美食餐坊」店內有挑高，用餐環境非常寬敞明亮，紅色大圓桌上都鋪著有客家特色的花桌巾，餐坊是由6位客家媽媽所組成，每個成員都有拿手的客家料理如梅干扣肉、客家小炒、在地放山土雞肉，烹調以三低二高(低糖、低油、低鈉、高纖、高鈣)之健康養生為原則，讓客人品嘗農村媽媽製作無負擔的好料理、好味道。\r\n餐坊除了選用在地食材，也成為全台第一間通過溯源餐廳的田媽媽，並獲得溯源三星級的榮耀，目前提供特色風味餐，溯源食材有，紅燒焢肉(中央畜產)、泰式檸檬魚(福爾摩沙漁場)、椒鹽酥蝦(蝦覓世界)、香Q飯(池上鄉農會)等，另外還提供傳統農村豐收飯(割稻飯)結合在地小農所生產的放山雞、洛神花、季節性時蔬等，飯後還能將豐收餐具帶走，希望讓客人「食安心」、「玩開心」、「購用心」。\r\n　　\r\n平日除提供便當外帶服務外，並可預約好吃的池上米飯，搭配放山雞、客家福菜、筍乾扣肉、菜圃蛋及當地當季水果、湯品等在地客家美食，在地放山土雞肉選用飼養五個月的放山雞，油滋金黃的外皮與鮮嫩的肉質非常美味；紅燒控肉式餐坊招牌料理，一口肉一口飯，完全無法分辨誰是配角，兩種角色在飯桌上都很重要，吃過都讚不絕口。\r\n餐坊所使用的蔬菜都是在地小農所種植的，縮短產地到餐桌的距離，讓大家每一口都吃得到食物的新鮮。\r\n製作紅燒控肉\r\n紅燒控肉\r\n池農豐收飯\r\n養身饅頭', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/1299/480x360_g28tirtm3ecy1i9j5ia33h0tebtauurj.jpg'),
(8, '蘭欣辣汗花果休閒農場(蘭欣食坊)', '08-871-7370', '屏東縣', '枋寮鄉', '中正大路666-8號', '★ 親子觀光農場 ★ 景觀餐廳 ★ 優質民宿 ★無毒溫室 ★DIY手作體驗 ★食農教育 ★ 環境教育\r\n#枋寮美食 #枋寮景點 #親子共學 #網美景點 #民宿\r\n「讓爸爸安心當廢物、媽媽開心當貴婦，家中小惡魔解封開心玩」\r\n「你以為我在遊戲，其實我在學習；你以為我在學習，其實我在享樂趣；你以為我在享樂趣，其實我在累積能力」\r\n「好吃、好看、好拍、好玩，小朋友才選擇，我們全都要」\r\n蘭欣辣汗花果休閒農場源起蘭欣山莊，蘭代表女主人，欣代表男主人，農場主人戴大哥從民國90年起於此地開疆闢土，從生產山蘇嫩葉供應市場，後配合高雄區改良場種冬季黃秋葵量產試驗，並指導種辣椒，後建造農產品加工室一棟，升級二級加工與三級網路行銷，多年來生產全世界各種最辣的辣椒與加工，用傳統的加鹽醬漬日曬發酵工法製成有醬香的辣醬，用機器烘乾鮮紅的辣椒乾與粉，供應市場、餐廳與網購。\r\n戴大哥發願想為地球環保盡一份心力，期待能完成人生最後一項夢想，力推農場為縣政府食農教育場域，致力生產世界各種辣椒及蔬菜瓜果，銷售國內各市場，並供遊客採摘遊樂、辣椒醬等多項DIY製作體驗，歡迎安排2天一夜的遊程，品嘗農場鄉村料理。\r\n農場目前種植網室蔬菜瓜果辣椒等，備有停車場、涼亭、體驗教室等多項便利設施，為農遊體驗大大加分。\r\n農場位於往墾丁台一省道(473.5K)處水底寮加油站旁，目前生產死神、特立尼達蠍子、印度鬼椒、紅色殺手、巧克力等世界級辣椒以及溫室蔬菜瓜果等，並供遊客採摘、DIY製作、專業餐飲廚藝料理等。\r\n體驗活動\r\n＊農村蔬菜豬肉大骨湯個人鍋（＄400/人）（附導覽、百萬溫室採菜，現煮現吃）小火鍋40位，大火鍋、四人共鍋（有公夾母匙分享及個人餐具使用，無交叉感染疑慮）80位\r\n＊手作烏龍麵（＄350/組）（60～90分鐘）建議搭配火鍋用餐，做完直接煮來吃 人數8～20位（幼童需家長陪同）\r\n1.烏龍麵製程教學\r\n2.攪和麵團\r\n3.揉麵團\r\n4.醒麵糰\r\n5.切烏龍麵、捏麵疙搭\r\n＊DIY剝皮辣椒醬（＄350/罐）（60～90分鐘）人數6～40位，建議12歲以上\r\n1.嚴選辣椒\r\n2.去蒂頭\r\n3.辣椒過油\r\n4.泡冷水\r\n5.剝皮、去籽\r\n6.裝瓶、修飾\r\n7.填裝獨門醬汁\r\n8.封瓶\r\n＊DIY手作蔥油餅（＄350/組）（60～90分鐘）人數8～40位（幼童需家長陪同）\r\n1.溫室拔蔥\r\n2.麵糰製成教學\r\n3.桿麵團\r\n4.蔥油餅、蔥派製成\r\n5.成品打包\r\n＊辣椒盆栽種植（＄200/盆）（30分鐘）人數1～40位（幼童需家長陪同）\r\n1.辣椒介紹\r\n2.器具發放說明\r\n3.盆栽種植操作\r\n4.澆水完成\r\n＊DIY辣椒醬製作（＄300/罐）（60分鐘）人數6～40位，建議12歲以上\r\n1.製作說明\r\n2.切蒜、辣椒、蔥\r\n3.爆炒基底\r\n4.加入秘制辣醬\r\n5.裝瓶\r\n6.封瓶\r\n＊DIY特殊風味辣椒醬製作（＄350/罐）（60分鐘）人數6～40位，建議12歲以上\r\n1.製作說明\r\n2.切各式食材\r\n3.爆炒基底\r\n4.加入秘制配方\r\n5.裝瓶\r\n6.封瓶\r\n＊手作檸檬醋（＄250）（30分鐘）人數1～40位（幼童需家長陪同）\r\n1.切檸檬薄片\r\n2.將檸檬片與糖依序放入玻璃瓶中\r\n3.導入蘭欣特製果醋\r\n4.封瓶，靜置三個月\r\n5.食用說明解說\r\n＊薑黃染布（＄400）（60分鐘）人數8～40位（幼童需家長陪同）\r\n1.介紹各式綁布方法\r\n2.煮薑黃色料\r\n3.開始染布\r\n4.清洗染布\r\n5.風乾\r\n＊溫室翻土種菜（＄250）（30分鐘）人數1～40位（幼童需家長陪同）\r\n1.溫室介紹\r\n2.翻土除草\r\n3.蔬菜栽種\r\n4.採時蔬一斤，超過補差價\r\n＊桑葚果醬 DIY（350ml＊2）（$500）（60分鐘）人數1～40位（幼童需家長陪同）\r\n做法 :\r\n＊先將桑葚用清水清洗乾淨，並歷乾。\r\n＊把洗淨後的桑葚，加入砂糖 、檸檬汁 一起醃製靜置出水。\r\n＊後用中小火燉煮。\r\n＊煮置果醬上色，即可裝至罐中保存 。\r\n＊手作番茄蜜（＄550）（2.5小時）（12～3月）（幼童需家長陪同）\r\n1.刺番茄\r\n2.抹鹽\r\n3.烤箱\r\n4.熬煮\r\n5.烤箱\r\n6.風乾\r\n＊酒漬雞心椒罐（$150）（30分鐘）（1～5月）人數1～40位（幼童需家長陪同）\r\n1.雞心椒採摘說明\r\n2.採雞心椒\r\n3.秘方添加\r\n4.封瓶\r\n＊溫室小番茄採摘（＄150/斤）（15分鐘）（12～3月）人數1～40位（幼童需家長陪同）\r\n住宿＆夜間行程\r\n＊高級車庫兩人房（附按摩浴缸、早餐）\r\n平日＄2000 / 假日＄2500\r\n＊高級車庫兩人房（附按摩浴缸、早餐）\r\n平日＄2580 / 假日＄2980\r\n＊農場夜間觀星 / 夜間生態導覽\r\n6歲以上＄100 / 人\r\n3～6歲 ＄50 / 人\r\n3歲以下免費\r\n遊覽景點\r\n力里山步道、浸水營古道、卡悠峯瀑布、枋寮漁港、藍皮解憂號、藍皮意像館、保安宮、枋寮基督教會舊遺址、枋寮之心\r\n建議遊程\r\n一日遊\r\n兩天小旅行\r\n三天深度旅遊\r\n完全客製化設定\r\n在地美食\r\n多種口味湯底＋無毒蔬果個人火鍋套餐\r\n農村創意料理\r\n在地化美食饗宴\r\n伴手禮與農特產\r\n多款及多種辣度採古法釀製傳統辣椒醬\r\n各式獨門果醬\r\n闆娘秘制高麗菜酸\r\n獨家哈拉肉包\r\n在地青農無毒果乾\r\n創意美食\r\n以農場無毒溫室採摘各式蔬果結合在地食材研發創意料理 \r\n獨門辣拌醬\r\n愛吻辣拌醬\r\n鳳櫻辣拌醬\r\n薑黃蝦麻辣醬 \r\n古法辣椒醬\r\n墨西哥開胃蔭椒\r\n蒜味朝天辣椒醬 \r\n民宿\r\n高級車庫四人房 \r\n餐廳\r\n乾淨明亮 \r\n會議廳\r\n設備齊全 \r\n電控溫室\r\n無毒蔬果發源地 \r\n寬廣綠地\r\n安全的放電場域 \r\n食農教育\r\n全力推動食農教育 \r\n親子共學\r\n多項專業DIY體驗選擇', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25829/480x360_agrispots-image-wt9fnejhjkeikwuos4vycq.jpg'),
(9, '晁陽綠能休閒農場(附設田媽媽班)', '05-693-8238', '雲林縣', '麥寮鄉', '興華村興華路32號', '晁陽綠能休閒農場致力於推廣太陽能發電與農業發展共榮的模組，不僅以友善土地的方式生產安心農產品，更發展六級化農業，種植、加工及品牌經營，提升農業的價值。同時申設休閒農場並推動環境教育，打造以綠能、綠農及綠色教育為根基的綠色經濟平台，朝著深耕永續的目標邁進；除推出以體驗及實踐ESG的活動方案，亦提供戶外教育、食農教育、農事體驗及導覽、農藝手做DIY、餐飲宴會、露營住宿等多樣服務。\r\n晁陽綠能休閒農場-ESG農電共榮\r\n建議遊程\r\n《綠光尋寶一日遊》\r\n「綠能」跟「農業」如何在ESG太陽能農場激盪出火花？結合教育與體驗的豐富行程，等你來晁陽尋找「農電共榮」新答案！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/1392/480x360_vbn1h8mvppj1kpr4cbjcsgytkvfgsy6y.jpg'),
(10, '貝岩居農場', '0933-980-007', '苗栗縣', '三義鄉', '龍騰村13鄰龍騰3號', '在苗栗山區，有間一星期只在週末開放的窯烤麵包坊，有如秘境般的生態農場描繪著父子兩代的樸實夢想，兩座麵包窯在山野間冒著炊煙，出爐的不只是香軟麵包，還有膾炙人口的在地故事。「貝岩居農場」主打老麵低溫發酵且無油、無糖、少鹽的柴燒窯烤麵包！適合麵包天然發酵的環境，再加上柴燒窯烤工法，口感外酥內軟、愈嚼愈香，呈現出麵包最原始的美味。\r\n假日可提前預約DIY體驗，也可以直接和店家購買現成的麵包！但因為手工製作的麵包產量有限，建議要提前預約，以免撲空唷！\r\n鮮採南瓜\r\n使用園內自種無農藥的南瓜，以及老闆親手熬煮的柚子丁，口感Q彈紮實還有淡淡的南瓜香，是貝岩居的招牌窯烤麵包。\r\n核桃蔓越莓\r\n嚴選核桃搭配美國優鮮沛蔓越莓果乾，口感紮實有淡淡的小麥香及果香味。是深受女性顧客喜愛的窯烤麵包。\r\n養生綜合堅果\r\n選用葵花籽、南瓜籽、奇亞籽、亞麻仁、核桃等堅果製作，烘培出最純粹、最健康的窯烤麵包。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/1401/480x360_貝延居_0524_L(2).jpg'),
(11, '小半天風味餐坊', '0919-743-732', '南投縣', '鹿谷鄉', '竹豐村中湖巷3-5號', '位於南投鹿谷小半天風味餐坊，老闆堅持使用當地當季食材，因此乾脆研發無菜單料理，讓客人吃到的都是最原始新鮮的美味！\r\n「無菜單料理」以在地自栽鮮採無毒蔬（野）菜，秉持少鹽、少油、絕不添加味精的健康概念，融入阿嬤古早味的「醬筍丸子」等三代傳承料理鄉土特色，呈現最天然養生且古早味的傳統美食。\r\n食材新鮮是美味料理基本要素，餐坊蔬菜全是自家或當地小農栽種，無農藥吃得健康又安心，當季食材因烹調方式不同，風味也會有變化，要來享用山中美味之前，最好先打電話預定，讓老闆能提早準備豐富食材驚艷上桌。\r\n體驗活動\r\n手作黃金竹筍包、焙火風味輪體驗、製茶體驗、茶席體驗、鳳梨花綠手指體驗、手作竹燈籠點亮夜空\r\n遊覽景點\r\n溪頭妖怪村、鳳凰谷鳥園、杉林溪、麒麟潭、紫南宮、小半天休閒農業區...\r\n建議遊程\r\n仙境客庄循跡\r\n在地美食\r\n烏龍茶燻雞、阿嬤ㄟ 醬筍丸、陳年老梅滷豚蹄、啤酒香燉鴨、古月雞煲湯...\r\n伴手禮與農特產\r\n1、什菓誼｜農情義式冰淇淋（百大青農高山烏龍茶/百大青農友善枇杷）\r\n2、豐茶師｜地方特色茶系列（清香型特等獎禮盒、杉林溪高山烏龍茶、梨山高冷烏龍茶、日月潭紅玉紅茶、鹿谷凍頂烏龍茶、鹿谷金萱烏龍茶...等）\r\n3、豐茶師｜花果茶系列（豐茶師花果茶禮盒、枇杷花烏龍茶、薰衣草紅茶、玫瑰花紅茶、鳳梨金萱茶）\r\n4、豐享食｜小農農產加工品（香嫩筍、手工醬筍、手工筍絲、日晒檸檬乾、手作脆梅...等）\r\n5、豐享食｜田媽媽冷凍食品（烏龍茶燻雞、阿嬤ㄟ 醬筍丸、啤酒香燉鴨、古月雞煲湯、陳年老梅滷豚蹄...等）\r\n產業復興｜圓夢總在堅持後 ＠三立新聞台  \r\n青力串連｜簏山小農的青春夢 ＠公視台語台  \r\n \r\n食農教育｜土壤、茶、生態的關聯性  \r\n品牌介紹｜豐茶師  \r\n產業加值｜當茶與枇杷相遇 ＠客家電視台  \r\n三代傳承\r\n在歷經九二一創傷後，劉老闆與老闆娘從專職農夫（烏龍茶、竹筍），開使多元進修與學習，並下定決心往餐飲之路前行，在民國97年正式營業，更因為本身即是農民，故能更加瞭解食材的特性並運用之，而本店各式各樣招牌料理就是秉持著在地性、健康安全、美味可口三大元素，讓旅客來到本店，必能感受到老闆藉由佳餚所傳地出她對在地食材的用心。旅行之中能撫慰人心的，就是美景與美食，而我們提供美食給來鹿谷找尋美景的您！ \r\n古月雞煲湯\r\n隱性客庄：鹿谷 自家醃製的老菜脯甘甜味，搭配上胡椒的香氣，結合土雞的鮮美湯頭，讓您嚐到這正港到地的古早味。 \r\n阿嬤ㄟ醬筍丸\r\n選用新鮮上等鮮美的豬絞肉，加上以小半天盛產的麻竹筍配上阿祖祖傳三代的醃製醬筍，與蠔油慢火燉煮，成就鮮美多汁的古早味醬筍肉丸子，Q彈口感、古早味卻不死鹹，讓您可以直接嚐，更能白飯一碗接一碗，讓您像成為饕客們日夜牽絆朝思暮想的絕妙好滋味。 \r\n烏龍茶燻雞\r\n嚴選在地竹山放山雞，搭配上百大青農【#豐茶師】高山烏龍茶，細心烹煮超過120分鐘，燻烤出帶有烏龍茶香氣、肉質Q彈不軟爛。讓您冷的、熱的都好吃。 \r\n田媽媽在地料理\r\n陳年老梅滷豚蹄\r\n祖傳廚藝的溫潤火候把豬腳燉煮的Q彈有嚼勁，配上冰糖慢火熬煮的微酸自釀的南投陳年老梅，讓您咬下的每一口豬腳Q彈酸甜，梅開眼笑。 \r\n豐肉控竹筍\r\n皮Q軟嫩、肥瘦適中的蹄膀滷得入味，輕輕一夾就感受蹄膀吹彈可破的彈性，而竹豐所產的鮮脆筍絲，也將滷汁精華滿滿吸附，濃郁又清脆的口感，在拌上美味的滷汁，讓您欲罷不能，白飯一碗接一碗。 \r\n經典手工竹筍包\r\n外皮由地瓜製成，內餡則是地方特產:竹筍，經大廚熟練的技巧炒香竹筍、絞肉所製成；全手工製成，皮薄餡多，讓您一口咬下，滿滿的幸福感。 \r\n什菓誼 義式農情冰淇淋｜百大青農烏龍茶、百大青農友善枇杷\r\n我們種植了安全安心健康多元的農產品，做成了小農冰品，讓您在吃的時候有「すごい」的感受，給消費者驚奇的感覺，體驗農產品最珍貴的純粹，明白原來天然的滋味是如此容易。秉持的三大原則：1.健康、2.安全、3.無毒採取自然農法，無農藥栽培，堅持友善環境。皆以手工採收。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/6184/480x360_kito-67(3).jpg'),
(12, '林園茶香美食', '05-256-1523', '嘉義縣', '竹崎鄉', '中和村20鄰19號', '林園茶香美食位於阿里山公路61.5公里處，是往來阿里山、奮起湖、達邦、特富野的必經之路，民國70幾年，阿里山公路開通之後，石棹地區因為地理環境適合茶葉生長，紛紛改種茶，而對於採茶便當的需求因應而生，林園茶香美食就是在這樣的環境下開始了田媽媽餐廳的經營。\r\n石棹地區以阿里山高山茶聞名，因此老闆娘會將自家生產的阿里山茶結合料理，增添餐點風味，在餐點中能品味淡淡茶香，感覺清爽無負擔，餐點以當地當季盛產的鮮蔬為主，因此餐點充滿變化與創意，有明日葉雞湯、棕梠心湯等。\r\n趁著假日安排一趟阿里山採茶與製茶的體驗過程，結束後一定要享用豐盛美味的特色茶餐點。\r\n炸茶葉\r\n炸茶葉這道料理在茶葉產區幾乎是必點的一道菜，茶葉炸過後嚐起來沒有苦澀感味道相當特別。\r\n苦茶油雞肉\r\n冬筍魷魚螺肉蒜\r\n冬筍魷魚螺肉蒜，是山上人家小時候的最愛的好滋味。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/1403/480x360_127312(2).jpg'),
(13, '鵝鄉園餐廳', '06-679-2318', '臺南市', '下營區', '中興南路21號', '田媽媽鵝鄉園餐廳位於台南下營，沿途道路寬闊，路邊停車方便，餐廳明亮寬敞，非常適合家人或親友出遊聚餐。\r\n老闆顏爸是下營的養鵝世家，從養鵝到成立產銷班，後來開啟了下營第一間屠宰場自產自銷，將鵝肉賣到全台各地，不過在下營卻沒有自己的鵝肉店，所以成立鵝鄉園餐廳，老闆對鵝的了解可說是專家等級，用自家生產新鮮美味的鵝肉料理征服了許多饕客的味蕾。\r\n餐廳以鵝肉料理為主題，除了招牌蜜汁燻茶鵝外，也發展出許多的鵝肉特色料理，例如：鵝肉香腸、麻香鵝米血、鵝肉貢丸、蠔油鵝掌等等，從鵝頭吃到鵝腳，各式料理絕對可以滿足每一位客人。\r\n燻茶鵝風行全台各地，而以「下營燻茶鵝」最有名，店裡招牌「蜜汁燻茶鵝」經過數小時的製作，將香醇濃郁的蜜汁香氣與鵝肉完美融合，金紅色的鵝肉一口咬下鮮嫩多汁，每一口都能品嘗到鵝肉的鮮美與蜜汁的甘甜！\r\n鵝肉香腸是將鵝肉與豬肉以特定的比例調配製作而成，每一口都能感受到鵝肉的香氣，加上豬肉的咬勁，口感豐富且層次鮮明，非常有特色！\r\n下營景色優美，許多景點是以生態為主很適合親子旅行，周末假日全家出遊到下營來看看這片土地上的多元生態樣貌，在安排享用在地盛名的下營鵝肉料理\r\n蜜汁燻茶鵝\r\n麻香鵝米血\r\n麻辣鴨血鵝肉', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/6196/480x360_BEER8274.jpg'),
(14, '王家燻羊肉食坊', '06-594-1393', '臺南市', '龍崎區', '土崎里烏樹林34號', '台南龍崎的「王家燻羊肉食坊」是一些爬完中興林場後會來這裡小憩用餐的地點。\r\n目前已經是第三代經營，招牌料理「燻羊肉」延續祖傳古法燻煮羊肉，連皮帶骨放入甕中，再加入十幾種中藥材與米酒，然後用黏土將蓋子封住，接著採用稻穀慢慢燻煮一天一夜而成，完成之後飄散一股非常濃郁的香味，羊肉鮮紅肉質非常軟嫩，輕輕一撥就骨肉分離，皮的部分則是Q滑彈牙。\r\n羊肉選自草山月世界放養的山羊，羊齡控制在2至3年之間，正好是體格強健有力、肉質極為鮮甜的階段。據傳羊食百草屬於涼補，且膽固醇低，是現代人的食補盛品，王家的燻羊肉料理不僅美味還能養生健體，許多饕客不遠前來就是要品嘗這一味。\r\n羊肉爐禮盒\r\n王家古法燻羊肉是選擇2-3年的台灣本土野放山羊，加入多種中藥材並採用公賣局米酒，一起放入甕，倒入稻殼點燃燜燒一天一夜，完成之後，肉色深紅，香濃四溢，入口即化。\r\n白斬土雞\r\n選用南屏農場的放山土雞，不注射多餘的藥物，用最健康的方式讓雞隻天然生長，為了讓客人吃得新鮮健康每日現宰，數量有限，放山土雞，肉質鮮嫩多汁，美味好吃。\r\n▲圖說：由於餐廳空間腹地廣闊，後方山坡上常會看見店家放養的土雞跑來跑去。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/6202/480x360_kito-24.jpg'),
(15, '大坑休閒農場', '06-594-1555', '臺南市', '新化區', '大坑里82號', '位於台南新化的「大坑休閒農場」是知名的台南景點，由三代同堂共同經營，蔡家阿公阿嬤原來在這塊山坡地種竹筍、種蔬果、養雞，直到第二代蔡爸蔡媽接手後從事畜牧業，並逐漸轉型為休閒農場，這裡不僅有超夢幻超好拍的紫藤花隧道，此外還有山泉SPA、高空滑車、繩索吊橋等多元化休閒設施，不管大人小孩都能玩得很開心！\r\n到這裡當然不能錯過美味佳餚，農場獨創的鄉村特色菜非常多，讓許多饕客都為了他們家的料理與熱情而來，農場的食材都是自家生產，不管是炭烤土雞、炭烤迷你豬或是鮮筍料理都非常受歡迎，尤其竹筍料理更有多達十幾種吃法，每一樣都鮮嫩甜美又可口，絕對會讓愛吃竹筍的客人吃得超級滿足。\r\n大坑休閒農場以「創意鄉土料理」著名，尤其是「柴燒筍香燜飯」是餐廳的招牌菜，以豬肉、麻竹筍、香菇、蝦米、油蔥，炒香生米柴火燒致熟透，是當地村莊很有特色的古早飯，由於備製需要時間最好先預訂；「櫻花蝦焗烤地瓜」及甘甜的「鳳梨筍醬燒魚」，是運用當地食材的創新作法；「炭烤迷你豬」、「炭烤山土雞」是農場超人氣王，全程炭火燻烤，並搭配360度翻轉烤法，品嘗時充滿燻烤香氣；「藥膳破布子雞湯」鮮甜回甘的雞湯與軟嫩的雞肉，是超夯的年菜伴手禮，餐廳內所有野菜、水果全部由農場蔡阿公蔡阿嬤親手栽種，希望每位客人享受美食還能夠接地氣的感受當地特色。\r\n著名的紫藤花隧道\r\n炭烤迷你豬與炭烤土雞\r\n炭烤迷你豬還有幫忙分切\r\n筍香燜飯\r\n黃金珍珠樹子雞湯\r\n黃金珍珠樹子雞湯伴手禮', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/34709/480x360_agrispots-image-dminiktug0knrfr9znufjq.jpg'),
(16, '仙湖休閒農場(仙湖農場)', '06-686-3635', '臺南市', '東山區', '南勢里大洋6-6號', '台南東山的「仙湖休閒農場」除了有好吃的料理之外，還有絕美景觀與電視劇拍攝熱門景點，很值得到品美食賞美景。\r\n農場內種植了龍眼、荔枝、咖啡等各類果樹，還有山茼蒿、山蘇等野菜，餐廳內的料理不論是主食或者是甜點都運用當地當季蔬果製作， 以傳統烹調結合創意作法呈現食物本身風味，包含森林排餐、田園燒雞以及龍眼冰淇淋等，都是必嘗美食。\r\n農場還另外設立自助野菜川燙灶，當季新鮮現採的野菜讓客人依照自己的喜好挑選，再沾上自製的橄欖醬，風味中帶著爽口的橄欖微酸，野菜輕燙後新鮮清甜；點餐方式分成「案食」以及「桌餐」，從獨享到十人一桌的需求都可滿足。\r\n來到這裡可以優閒放鬆的享受山中的微風，運氣好的話還可以觀賞到「雲湖」。\r\n▲餐廳外觀\r\n▲內部用餐環境\r\n月桃燉子排\r\n村宴的人氣主菜，將豬子排與野生月桃葉燉至軟嫩而成。\r\n桂圓燒虎掌\r\n農場獨家紅燒慢燉肉塊再加入自產烘焙的桂圓乾，豐富的口感，是其他地方吃絕對不到的好味道。\r\n灶寮鹹肉\r\n農場獨有的醃料配方所製成的客家鹹豬肉，融入五花油脂香氣，肉質口感軟嫩。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25795/480x360_agrispots-image-x9xtlqfvvuonape6ecv_vw.jpg'),
(17, '台南鴨莊休閒農場', '06-690-1101', '臺南市', '官田區', '渡拔里三塊厝178-1號', '「台南鴨莊休閒農場」位於台南官田，是祖傳三代的養鴨人家，生產各種皮蛋、鴨蛋等。老闆蘇清發養鴨超過一甲子，利用從父親身上學到養鴨的知識，積極地擴展養鴨事業，並且研發鴨蛋加工產品，推出的皮蛋、鹹蛋、酒香蛋等鴨蛋製品不但成為鴨莊的最佳伴手禮，也是菜單上的最佳開味菜。\r\n加入田媽媽體系後，台南鴨莊發展成休閒農業園區，採用自家所養的鴨子推出許多鴨肉家常料理，滿足遊客們旺盛的味蕾。此外，他也將農場開放給學童們，從事戶外教學農村體驗活動，有鴨蛋教室、鴨蛋DIY及可愛淘鴨彩繪等趣味體驗，是小學生戶外教學的一個好地方！\r\n農場也提供露天烤肉區、懷舊焢窯與露營場地，非常適合親子或朋友歡聚的地方。\r\n寬闊的焢窯場地\r\n鴨肉盤\r\n選用 120 天以上的鴨子製作而成，鮮嫩味美，每一口都是大大的滿足。\r\n酸菜鴨肉湯\r\n將鴨肉的甜味與酸菜獨特的風味一起燉進湯裡，喝得到清甜的湯頭，而且湯中的鴨肉塊肉質鮮嫩，也保留住酸菜的脆度。\r\n紅燒魚\r\n吃鹹蛋清長大的台灣鯛，肉質清甜。做成紅燒料理後，相當下飯。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25802/480x360_agrispots-image-jpglharow0gzb1liaz1tmw.jpg'),
(18, '東遊季休閒農場(東遊季養生美食餐館)', '08-951-6111', '臺東縣', '卑南鄉', '溫泉村溫泉路376巷18號', '台東知本是著名的溫泉村，進入知本溫泉區，即可看到由台東縣農會經營的「東遊季溫泉度假村」，園區占地十多公頃相當廣闊，擁有大片綠地讓遊客可以無拘無束的徜徉在寧靜的山谷森林浴中，還有住宿區、田媽媽餐廳、露營區、烤肉區、以及養生溫泉等，泡在露天浴池觀看滿天繁星，或是享受大眾溫泉、山泉泳池與SPA水療設施等，讓人完全放鬆。\r\n東遊季是溫泉區裡唯一的田媽媽養生餐廳，田媽媽們靈活運用台東各地的特色食材，包含：金針、洛神、薑黃，還有成功漁港直送的新鮮海產，料理出滿滿一桌好菜是東遊季養生美食餐廳最大的特色。\r\n薑黃養生豬\r\n先用麻油拌炒松阪豬肉，再加入一點薑黃粉調色，是一道色香味俱全的也富含營養的料理。\r\n洛神排骨\r\n以洛神原汁取代糖醋，洛神的天然果酸沒有醋酸嗆鼻，又富含營養價值，吃起來酸酸甜甜。這道料理曾入選台灣田媽媽十大招牌菜！\r\n刺蔥鹹豬肉\r\n經薄鹽醃漬的鹹豬肉烤至香氣四溢後，再將刺蔥嫩葉撒在豬肉上，吃起來爽口辛甜，提升味覺層次。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25809/480x360_agrispots-image-o3jzjwfic0gthupwpoaljq.jpg'),
(19, '一晴食坊', '0937-356215', '嘉義縣', '阿里山鄉', '茶山村4鄰96號', '「一晴食坊」位於嘉義縣阿里山鄉茶山村，個性爽朗的茶山媳婦晴姊，喜歡晴天賦予活力朝氣，便將食坊取名「一晴」，希望能掃除山嵐霧氣帶來的抑鬱。\r\n他自幼跟在客家母親身旁見習廚藝，因而練就一身好本領。\r\n茶山村春天產梅，以糖醃漬封存數月至一年，越陳越香，入秋後至十一月是洛神花產季，採收後的新鮮洛神糖漬製成蜜餞，醃製的花果單吃不膩口，晴姊喜歡入菜拌炒，招牌梅子雞酸甜滋味易下飯或將竹筒搖身變成烹調器具，料理帶有竹筒香氣，特製山筍扣肉及竹筒蒸蛋、古早味炒芋頭梗、烏龍茶雞湯等都是不錯選擇。\r\n在一晴食坊沒有譁眾取寵的料理方式，只有依循季節調整食譜，採用在地農產入菜，提供最接地氣的好味，晴姊說： 「大家品嘗料理時露出的笑容，就是最大的動力」。\r\n竹筒蒸蛋\r\n竹筒做成蒸蛋容器，讓蒸蛋吸收飽滿的竹子香氣，吃起來綿密又滑順。\r\n山筍扣肉\r\n茶山村盛產竹筍，來一晴食坊一定可以吃到「最對時」竹筍料理。脆口山筍讓軟嫩的扣肉清爽不油膩，恰到好處的調味，非常下飯。\r\n茶香雞湯\r\n當地茶葉與雞湯完美結合而成茶香雞湯，茶葉的香氣中和雞湯的油膩，喝起來爽口無負擔。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/6721/480x360_kito-31(3).jpg'),
(20, '北門嶼輕食風味餐廳', '06-786-0303', '臺南市', '北門區', '北門里1鄰3號之5', '「北門嶼輕食風味餐廳」是台南北門區在地特色餐廳，隔壁就是雲嘉南海濱國家風景區管理處，加上四周有許多著名景點，位置相當好找。這裡的餐點多樣且有特色，提供簡餐、小火鍋、風味餐、飲料、甜點等選擇，是適合家人同遊聚餐、朋友聚會的台南美食餐廳。\r\n餐廳主要以虱目魚料理為主，招牌餐點是虱目魚套餐，無刺的虱目魚讓人吃起來過癮無負擔，搭配豐富新鮮的配菜，非常下飯；而甘露煮虱目魚則是鹹中帶甜，還有無刺虱目魚海鮮鍋都是必點美食！此外，「北門嶼輕食風味餐廳」也是經過認證的穆斯林友善店家。\r\n飯後，還可以到北門遊客中心欣賞唯美的裝置藝術，鄰近還有烏腳病紀念館和北門出張所等特色景點。\r\n北門嶼是老建築改造的餐廳，內部保留傳統工法建構木造屋頂，搭配雙面落地玻璃窗，打造明亮舒適的用餐環境，是北門最具特色的風味餐廳。\r\n乾煎虱目魚\r\n虱目魚乾煎得十分香嫩，油脂豐厚，肥滋滋的吃起來好過癮。而且經過無刺處理，大人小孩都超愛。\r\n虱目魚黑豆醬油\r\n採用新鮮沒有腥味的虱目魚精，加上嚴選黑豆，經過處理，等待時間醞釀出香、醇、甘、甜，晶瑩剔透如琥珀般的手工醬油。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/6914/480x360_kito-20(3).jpg'),
(21, '生力農場', '05-258-6785', '嘉義縣', '番路鄉', '公田村隙頂9之5號', '阿里山的茶葉向來有名，而這間位於阿里山的生力農場，因得天獨厚的地理條件，農場種出來的茶常常在各大比賽中拿到冠軍，茶味濃韻又回甘，深受品茗人士的喜愛。\r\n來這裡除了品茶之外，還有茶料理更不能錯過，農場採用自產的茶葉入菜，並結合在地當季食材進行料理，菜色豐富，清爽不油膩，，招牌菜色有阿里山紅茶豬腳、苦茶油雞、茶香檸檬魚、烏龍茶排骨湯。此外，生力農場也有許多自家烘焙的美味點心，阿里山紅茶乳酪捲\r\n鮮奶吐司厚片、老麵法棍、無油義式脆餅，都很值得品嘗喔。\r\n農場可遠眺一路綿延茶園美景，也能飽覽雲海及日出視野，讓生力農場成為許多攝影愛好者的必訪之地！\r\n歡迎您前往阿里山生力農場，來一趟滿足視覺與味蕾的深度之旅！\r\n焙香烏龍茶\r\n茶種：小葉種軟枝烏龍\r\n產地；台灣阿里山海拔1250公尺以上\r\n發酵度：15%~20%\r\n烘焙度：輕\r\n米麩香、蔗糖香、輕炭火味，風味甘醇甜美、飲後生津、餘韻綿長\r\n阿里山紅茶\r\n茶種：小葉種軟枝烏龍\r\n熟果香、蜂蜜香、龍眼乾香，甘甜喉韻、厚實芬芳。\r\n攜帶型冷熱泡茶包，阿里山紅茶一盒裡面有二十小包裝，每一小包都是高規格充氮包裝，確保茶葉品質。\r\n阿里山紅茶乳酪捲\r\n濃郁茶粉當蛋糕體，搭配微鹹乳酪慕斯餡，不甜不膩，微鹹讓茶味跳脫出來，搭配一杯熱熱的阿里山高山茶，享受來自阿里山的幸福滋味。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/6954/480x360_S__14974985_1(1)(1).jpg'),
(22, '仁農美食工坊', '07-3711331', '高雄市', '仁武區', '中正路137號', '仁農美食工坊位於高雄市仁武區農會內，由5位對料理充滿熱情的家政班員所組成，主打商品是滷，美食工坊的滷味由數十種中藥材作為滷汁的基底，加入雞翅、雞腿、豆干等，小火慢滷淬鍊而成，滷味入口前就聞到濃濃的香氣，品嚐起來Q彈的口感與淡淡的清甜，帶有中藥香氣，會讓人涮嘴一口接著一口。\r\n田媽媽們秉持安全、健康與美味的理念，製作過程中不添加任何人工調味劑與保鮮劑，希望讓客人能嚐到充滿媽媽味道的感動，也讓顧客們能買的放心、吃的安心，是這群媽媽們唯一堅持的初衷！\r\n美食工坊推出黃金滷味、珍珠滷味跟玫瑰滷味等三種口味，黃金滷味具有醬油的香氣，當下酒菜或是單吃都非常適合；珍珠滷味像鹹水雞，可以拿來涼拌蔬菜，也可以當零嘴；玫瑰滷味則是除了基底的中藥材之外更添加了紅麴醃製而成，這可作為餐桌一道主菜，清甜而不膩。\r\n \r\n黃金鳳翅\r\n黃金鳳翅具有醬油的香氣。\r\n珍珠鳳腿\r\n珍珠鳳腿較像鹹水雞，可以拿來涼拌蔬菜或做成其他料理。\r\n玫瑰鳳捲\r\n雞肉捲裡帶著紅棗與苟杞，肉質軟Q適中帶著清甜而不膩，香味在味蕾裡蔓延。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/29585/480x360_agrispots-image-5yedzwwxxua37ymrybsrog.jpg'),
(23, '噶瑪蘭美食', '03-9251316', '宜蘭縣', '宜蘭市', '林森路155號', '位於宜蘭市的噶瑪蘭美食不同於一般餐廳，原先是以經營生鮮超市為主，後續由宜蘭縣農會為協助推展農業與永續農會發展，衍生出生鮮處理場，進而開設大型中央廚房，採用超市內新鮮蔬菜與肉品，以在地特色食材為主，並提供客製化料理，深受縣政府倚重與信任配合許多縣內大型活動美食供應。\r\n現主要以外燴服務為主，近年來參與縣內大型活動，如宜蘭國際童玩節國內外團隊膳食供應、2013全國區中運、2014全國科展、2016全國運動會(製作宜蘭風味美食饗宴)、2018年國慶晚會點心製作供應。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/6967/480x360_qk97s4jsddvgkvyn0g5sij45gys4f8ng.jpg'),
(24, '福樂休閒漁村', '03-556-2690', '新竹縣', '竹北市', '鳳岡路五段155巷65弄86號', '「福樂休閒漁村」園內養殖池佔地廣達兩公頃，老闆郭大哥早期養殖草蝦與吳郭魚，除了魚之外，還飼有多種類型的小型白蝦，養殖烏魚已經有20多年的經驗，擔任烏魚子產銷班班長多年，並榮獲「神農獎」肯定。\r\n竹北也是是台灣重要的烏魚產地之一，每到秋天經新竹的九降風吹過的烏魚乾，會呈現金黃透亮的光澤，咬起來扎實口感，味道更勝其他產地，所以竹北的烏魚子是全台灣品質最好的烏魚子之一。\r\n「福樂休閒漁村」早期做魚塭養殖，後來開放做休閒漁釣，客人常常釣魚釣到肚子餓，所以加入田媽媽的家政班，開始學習將在地食材融入料理，近年來更結合經營「田媽媽」餐廳及豐富的產銷班經驗，積極推廣食農教育，帶動不少國內外團體到此參訪。\r\n老闆郭大哥希望客人來到這裡，除了可以品嚐到各種以新鮮烏魚為主角的招牌料理，還可以在導覽下認識烏魚生態，同時，還能藉由豐富的烏魚子、烏魚丸DIY體驗活動，深刻了解「從魚池到餐桌」的過程&mdash;&mdash;包括餵食烏魚、撒網抓魚、洗烏魚子、曬烏魚子等，，非常適合大人小孩一起同樂。\r\n「福樂休閒漁村」自製研發生產的烏魚鬆、烏魚香辣醬、烏魚子Q餅等特有產品，不僅具有在地代表性，而且新鮮好吃，送人自用兩相宜。\r\n為了讓客人能夠吃到最新鮮的料理，所以要事先預約，這裡沒有提供單點菜，老闆郭大哥會將養殖的新鮮漁貨結合當地小農新鮮蔬菜，打造獨一無二的私房料理。\r\n園區內除了魚類養殖，還有許多動物悠遊其間。\r\n糖醋魚 \r\n烏魚香腸 \r\n桔醬魚 \r\n手作烏魚丸', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/6969/480x360_BEER8397.jpg'),
(25, '大安區農會飛天豬主題餐館', '04-26710131', '臺中市', '大安區', '大安港路541號', '位於大安肉品市場的安農飛天豬主題餐館，強調食材從產地到餐桌透明化，經過多年努力後終於通過「溯源餐廳」驗證，只要掃描店內QR code，包括安農五寶等食材來源一清二楚，讓客人吃得放心又安心。\r\n大安區農會致力推廣在地產銷履歷食材，安農飛天豬主題餐館加入「溯源餐廳」行列，比照米其林星級評鑑獲得二星驗證，所選用當地食材取得「產銷履歷TAP標章」，只要透過掃描QR code，就可掌握食材來源資訊。\r\n安農飛天豬主題餐館以生產履歷豬肉、芋頭、青蔥、芋燒酎及安泉米等飛天豬安農五寶為主要食材，推薦料理包含杏福元蹄寶、花開富貴腸相守、酸甜知味鍋等產銷履歷食材特色料理餐點。\r\n杏福元蹄寶\r\n花開富貴腸相守\r\n酸甜知味鍋', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/6982/480x360_IMG_0453.jpg'),
(26, '三才•心靈芝旅養森食堂', '02-2663-8289', '新北市', '石碇區', '中民里十八重溪52-1號', '【113年記憶中那一味】石碇靈芝宴席獨步全國 必訪百年石屋田媽媽靈芝的故事\r\n農場栽培靈芝及其它菇菌等，另也種植天然藥草及香草植物，為了寓教於樂並開放多種DIY體驗課程，其中「靈芝香菇元寶餃DIY」採用農場栽培的靈芝，搭配青農返鄉所栽種的香菇及當地小農所種新鮮蔬菜結合，DIY活動後煮熟後，大人小孩讚不絕口。\r\n此外三才靈芝農場還推出十分特別外面絕對吃不到的靈芝養生膳食，榮獲農業部農村水保署回憶的那一味及新北特色嚴選商品之殊榮，能來三才靈芝農場走上一回住上一宿，悠遊悠哉的小坐、小憩、慢食人生豈不快意似神仙！周邊景點甚多石碇老街、五路財神廟、黃帝殿登山步道、雲台山櫻花林海、菁桐、文山煤礦、平溪小火車、十分寮瀑布、深坑豆腐、千島湖、坪林茶葉博物館、大東北角風景區&hellip;&hellip;等。\r\n石頭屋\r\n靈芝培育\r\n靈芝御皇膳食一品鍋\r\n靈芝香菇元寶餃\r\n靈芝香草風味菇', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/6987/480x360_IMG_9730.jpg'),
(27, '海膳廚房', '03-9907998', '宜蘭縣', '五結鄉', '成興村利興二路11號', '宜蘭五結工業區的隱藏版田媽媽餐廳「海膳廚房」，位於溪和水產觀光工廠內，環境溫暖的友善餐廳。\r\n來到宜蘭當然要吃宜蘭的美味海鮮，運用本海在地美味鮮獲，從漁港直送工廠，經三去一工法後(去鰓、去鱗、去內臟、清血合)，送進cas細胞活存冷凍設備，保存漁獲的鮮度與養分，讓到餐廳時品嚐到宛如現撈的美好滋味，也能將廠內的鮮凍美味帶回家。\r\n在觀光工廠內設有漫畫館、各種DIY課程、水產市集等，將宜蘭的漁業文化，與海洋永續的觀念，帶給來參觀的朋友。\r\n入館需知：\r\n■ 普通門票： NT$ 100，可全額抵消費(餐飲DIY體驗券50元+商品抵用券50元)。\r\n■免費入館：120 cm 以下孩童免費入場。\r\n■優待票：50元 ，含65歲以上遊客、身心障礙者陪同者一位(商品抵用券50元)\r\n■ 營業時間：早上9:00~16:30 (星期一至星期日，每周三休館)\r\n■ 寵物友善：寵物可進館，但不落地、不落地、不落地(很重要，所以講三次) (需：寵物推車、寵物提籃。)\r\n■團體遊客：請來電預約0975-760351\r\n體驗活動\r\n【職人體驗】採現場報名，開放時間:09:00~16:00\r\n本活動特地設計簡易水產加工的DIY空間，讓大家透過漁獲汆燙體驗工廠加工的流程，並可以品嚐到親手汆燙完成的鮮美漁獲。\r\n【生米煮成熟飯&海鮮押片】採現場排隊報名(活動時間約1小時)\r\n上午場:10:00 /最多25人\r\n下午場14:30 /最多15人(國定假日&週日無下午場)\r\n本活動使用小釜鍋動動小手diy煮飯，米飯與美味小魚拌飯一起做三角飯糰，搭配串場小活動diy將海鮮用熱押機押成餅乾，讓大小朋友體會食材的珍貴與製作海味的樂趣。\r\n【海底世界-貝殼DIY】採現場報名(活動時間約50分)\r\n上午場09:30/10:30/11:30(每場最多15人)\r\n上午場12:30/13:30/14:30(每場最多15人)\r\n本活動特地將充滿童趣的打卡海底世界做為活動場地，以美麗的貝殼作為素材，製作各種貝殼相關作品，讓大家來到大海女神的懷抱裡，動動小手盡情發揮源源不絕的想像力。\r\n【現押-魩魚米仙貝】採現場報名，開放時間:週一到週五09:00~16:00(平日限定)\r\n本活動使用大型熱押機，讓大家diy將海味米飯押製成米餅，每一口都能吃到米的甜味與大海的鮮，自己動手押仙貝~\r\n【搖滾吧!飯糰diy】採現場報名，開放時間:09:00~16:00\r\n使用熟米飯搭配小魚拌飯，放進搖搖飯糰工具中，讓大朋友小朋友盡情搖擺，成品飯糰球球超級可愛!!完全捨不得挑食~活動後，搖搖工具還能帶回家繼續搖喔!\r\n \r\n在地美食\r\n海膳特餐:(限時供應:11:00-13:00)\r\n嚴選北海道帆立貝柱、九孔鮑、海大蝦、美卷、雞蛋、高麗菜，品質保證的美味食材，組成的海鮮魚盤，搭配魚滷肉飯、魩仔魚羹、XO醬、東北角石花凍的特色餐點。\r\n魚滷肉飯:\r\n嚴選本海鰹魚魚肉與魩魚醬油熬煮的魚滷肉，搭配五結在地白米飯與菜脯，清爽不油膩。\r\n魩仔魚羹:\r\n嚴選宜蘭本海魩魚，經HACCP工廠加工煮熟，直接灑在清爽的羹湯上，美味無負擔。\r\n海鮮炸物:\r\n嚴選宜蘭本海鬼頭刀、白帶魚等鮮魚，去刺、裹粉下鍋炸，外酥內軟超級美味~\r\n現蒸鮮魚:\r\n選用漁港直送食材，經CAS細胞活存冷凍保留鮮度與養分，加入鹽巴青蔥、薑絲、洋蔥簡單清蒸，口感宛如現撈般美味。\r\n伴手禮與農特產\r\n【本海．鮮魚/鮮凍產品】\r\n嚴選宜蘭本海新鮮水產，經CAS細胞活存冷凍，口感新鮮宛如現撈。產品皆已去鰓去鱗去內臟，無需清洗，即可料理。\r\n【空海運．鮮貨/鮮凍產品】\r\n嚴選來自外國的漁獲，經HACCP認證工廠加工，品質掛保證。產品皆已去鰓去鱗去內臟，無需清洗，即可料理。\r\n【開胃．調理/罐裝、鮮凍產品】\r\n各式XO醬、小魚拌飯等醬料與開胃小食，簡單就能上菜的美味幫手。\r\n【嚴選乾貨/常溫、冷藏產品】\r\n各式XO醬、小魚拌飯等醬料與開胃小食，簡單就能上菜的美味幫手。\r\n【休閒零嘴/常溫產品】\r\n日本名古屋仙貝、堅果類零嘴等美味健康的零嘴，追劇、野餐隨身帶著走~\r\n \r\n【最適合親子出遊的好去處!!】溪和水產觀光工廠\r\n江之島 台版現押魩魚米仙貝在溪和\r\n動動小手~ 自己的海洋自己做~~\r\n搖滾吧!飯團DIY', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/1868/480x360_zypm6iws0f090zj82ti53gs806zbxvdg.jpg'),
(28, '天然茶莊', '0925-205555', '新北市', '汐止區', '汐碇路380巷30號', '溯源三星餐廳、茶葉料理\r\n在地美食\r\n冉冉飄揚的茶香搭配上各式不同的食材可以變化出多種料理呢？答案就在您到訪茶莊後揭曉。茶莊男主人的好手藝加上女主人的創意巧思，讓茶與食材擦撞?美麗的火花，一道道不侷限於傳統的料理完美的挑起人食的慾念，成為每一位饕客的最愛。\r\n保留傳統風味的招牌茶油飯、茶油麵線，清新爽口的雙喜拼盤，五星級餐廳大廚傳授的泰式檸檬魚，冰鎮山霸是一道需要真功夫的料理，入口即化的普洱煨蹄筋，鮮美淡雅的茶葉雞湯，讓人回味無窮的茶葉醉雞，酸甜適中的糖醋魚，帶有濃郁茶香的烏龍燻蝦，健康養生的有機炸地瓜 &hellip;&hellip;，每一道餐點講求新鮮、衛生以及兼顧各種食材相互搭配起來的口感，創意加上巧思讓天然茶莊的每一道餐點有著感動人們味蕾的魅力，這是身為茶莊主人也是茶莊主廚最引以為傲的地方，而天然茶莊的熱情就像一壺好茶的杯底餘香，久久無法散去。\r\n天然茶莊也推出多項冷凍茶食，讓大家在家就能嘗到美味茶餐點~~\r\n★ 冷凍茶食\r\n☆ 觀音自在煨東坡\r\n茶改場技術輔導，天然茶莊與台中大安區農會(飛天豬)推出茶餐料理冷凍調理包，期待「以茶入菜」為民眾帶來健康與味蕾上的驚喜。\r\n透過鐵觀音茶葉入菜，可以去除豬肉的腥味、油膩，還能提味，入口具有淡淡的芳香與甘醇的尾韻，調理包無防腐劑與化學添加物，復熱即可上桌，兼顧美味、營養又方便。\r\n☆ 老包種茶醉蝦\r\n茶改場技術輔導，天然茶莊推出茶餐料理冷凍調理包，期待「以茶入菜」為民眾帶來健康與味蕾上的驚喜。\r\n使用鮮甜的活水蝦，酒醮提味、去海鮮腥味，再加入茶葉，入口具有淡淡的芳香與甘醇的尾韻，調理包無防腐劑與化學添加物，退冰即可上桌，兼顧美味、營養又方便。\r\n☆ 茶香豬腳\r\n透過茶改場技術輔導，天然茶莊嚴選究好豬豬腳，推出茶餐料理冷凍調理包，期「以茶入菜」為民眾帶來健康與味蕾上的驚喜。\r\n以鐵觀音茶葉熏製入菜，可以去除豬肉的腥味、油膩，還能提味，入口具有淡淡的芳香與甘醇的尾韻。此為豬腳圈，喜歡吃具有豐富膠質的朋友，千萬別錯過了~~調理包無防腐劑與化學添加物，復熱即可上桌，兼顧美味、營養又方便。\r\n☆ 包種茶小饅頭/紅豆包\r\n天然茶飽包系列是用自家的有機茶磨成粉狀，創作出全新的茶葉特色點心，將自產的包種茶揉進麵粉裡，再包入手工製作的紅豆泥，甜而不膩。\r\n伴手禮與農特產\r\n★ 茶點心\r\n☆ 茶米花&mdash;蜜香紅茶/包種茶/鐵觀音\r\n茶莊特別與優質的爆米花製造商合作，將茶莊自產的包種茶、紅玉紅茶與鐵觀音茶研磨成特色茶粉，裹在圓型的爆米花上，將茶與爆米花作結合，如同中、西式的搭配，給予茶、爆米花全新樣貌，因有茶的加入，讓爆米花甜而不膩，入口後還有淡淡茶香。\r\n☆ 包種茶/蜜香紅茶茶糖\r\n使用自家有機包種茶製成，濃厚的包種茶香讓入口的糖甜而不膩，屬於大人口味的糖果，可以放幾顆在包包裡，讓愛喝茶的你隨時都可以解解饞。\r\n★ 茶葉/茶飲\r\n☆ 繽紛果茶禮盒\r\n「茶」來自於汐止天然茶莊，因應茶葉生長狀態不同、季節的不同、蟲害的不同，所產生不同的風味，用最適當的技法，將茶的特殊性展現出來。\r\n玫瑰花園包種茶：玫瑰與包種的組合，中西合併，順口不衝突。\r\n小桃氣蜜香蘋果紅茶：水蜜桃、蘋果加入蜜香紅茶中，讓桃香陪你渡過每一天。\r\n和風櫻花包種茶：櫻花不只可欣賞也能入茶，櫻花與包種茶的結合讓人意想不到。\r\n金芒蘋果包種茶：用芒果的香氣幫您舒解平日的辛勞~\r\n金黃雙菊蜜香茶：以黃杭菊、洋甘菊雙菊幫你降降火，適合秋高氣爽的日子來喝。\r\n紅果草莓蜜紅茶：使用蜜香紅茶，以草莓與紅龍果為提味，淡淡香氣，粉嫩討喜。\r\n☆ 全有機天然茶研紅茶豆奶\r\n天然茶莊有機紅茶豆奶是一支全有機的植物性蛋白質飲品，使用慈心驗證的國產有機黃豆，搭配自家栽種的有機紅茶而成，濃厚的豆香混合底蘊厚實的紅茶，蹦出獨特新滋味，作為早餐或者下午茶的飲品都很合適。\r\n☆ 有機包種茶/有機蜜香紅茶\r\n天然一心精品茶，產自新北市汐止區與南港區的交界處茶山(古地名為大坑)，亦是台灣文山包種茶的發源地。在第四代主人的推動下，保留了傳統精神與創新的製茶工藝，「先躬身種茶，後親手製茶」，運用有機，友善大地的農法，並以同理心看待茶樹與品茗者的關係。\r\n老包種茶醉蝦\r\n茶香豬腳\r\n茶米花&mdash;蜜香紅茶/包種茶/鐵觀音\r\n包種茶/蜜香紅茶茶糖', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25828/480x360_agrispots-image-qpdl146peekte7b3rdab2q.jpg'),
(29, '嵩屋餐廳', 'xx', '宜蘭縣', '大同鄉', '松羅村玉蘭20號', 'xx', 'xx'),
(30, '口湖鄉農會田媽媽', '05-7892701#37', '雲林縣', '口湖鄉', '口湖路46之1號', 'xx', 'xx'),
(31, '漫行林韻', '05-3103639', '嘉義縣', '梅山鄉', '太興村橫山5號', 'xx', 'xx'),
(32, '臺南市柳營區農會田媽媽', '06-622-3994', '臺南市', '柳營區', '柳營路二段77號', '由台南市柳營區農會所輔導的田媽媽於民國84年所成立，主要為在地食材的傳統美食坊，採用台南柳營在地酪農每天新鮮現擠的香甜鮮奶製作鮮乳包子與饅頭，製作過程不加任何牛奶香精、色素、漂白劑、化學膨鬆劑，堅持百分百純牛奶製作，只為帶給消費者最高品質且安全的食品，化身為食安守門員為您的健康把關。\r\n田媽媽為推廣在地鮮奶，研發並製作各式鮮乳包子與饅頭，現今提供數10種口味選擇，且製作時絕不添加任何一滴水，手工揉製並發酵饅頭，出爐的饅頭帶有濃郁奶香味，甜而不膩，一口咬下口感綿密、絲絲入口。\r\n可點選加入柳營區農會田媽媽的LINE', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3476/480x360_g78u92jp0fp3b1rdnhveei01nnbbekqa.jpg'),
(33, '一佳村養生餐廳', '03-958-8852', '宜蘭縣', '冬山鄉', '中山村中城二路58巷11號', '一佳村養生餐廳位於冬山河源頭，宜蘭中山休閒農產區仁山植物園入口旁，地處山區中週遭山林環抱綠意盎然，來此用餐除，讓人有一種身處世外桃園的感覺。\r\n走進田野間遠遠看到「一佳村」，這裡的水質純淨無汙染，當地自然生態資源完整，諾大的青草園中種滿龍葵、金銀花、赤道櫻草等兩百多種原生種藥草和野菜。\r\n田媽媽沈淑惠夫妻運用豐富的藥草知識，從 200 多種藥草中選出 15 種適合食用的青草，烹調入菜；藥草性寒，因此這裡的青草餐多加薑、枸杞、紅棗來中和屬性；餐廳使用的全是自家栽種的有機藥用植物，在沒有污染與不使用農藥及除草劑的青草園中，讓客人能夠享受大自然薰陶，同時並能品嘗五行五色健康、繽紛的美味料理。\r\n山油麻葉有清熱解毒的功能，將油麻葉磨泥後煮小魚乾、地瓜丁，葉湯吃起來黏黏稠稠的、尾韻微苦，搭配地瓜的甜，炎炎夏日，喝上這碗湯可以清涼退火；「五色酒釀湯圓」在糯米糰中揉入紅麴、杜仲、茯苓、山黃梔、臺灣人參及落葵，做出色彩繽紛的小湯圓，加入甜酒釀、枸杞，最後打上一顆蛋花，吃進肚裡的甜品對身體五臟皆有益處。\r\n餐廳內每道菜、茶、點心都是田媽媽親手自製，無人工防腐劑、無人工色素等，五行養生佳餚皆取自天然食材的原色原味，讓每位客人都能吃的安心健康。\r\n \r\n新鮮又大隻的蝦子，簡單的用鹽烘烤，加上一點八角的香氣，讓這道鹽烤蝦增添了不同的風味。\r\n魚腥草燉排骨湯，聞起來很特別的魚腥草拿來入菜之後變成湯鮮味美的一道湯品，湯裡可以嚐到淡淡的魚腥草特有氣味，豬軟骨軟嫩入味也是相當可口\r\n五色酒釀湯圓', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25785/480x360_agrispots-image-lfrgw1kt9ukt6nbyajzsja.jpg'),
(34, '八五山泉養殖場', '03-584-2560', '新竹縣', '尖石鄉', '新樂村8號36之2號', '「八五山泉山莊」位於新竹尖石鄉的鳥嘴部落，環境相當幽靜。老闆張先生夫婦自食品加工業退休後，憑著一份執著尋找一個心目中的山莊奇地，他們選中八五山泉山莊，這裡腹地廣大，有如世外桃源般的山林美景，群山簇擁、空氣清新，擁有很棒的景觀。山莊這裡提供舒適的民宿，能讓遊客在山林中享受愜意時光，\r\n山莊裡活水養的鱘龍魚以及冷泉水養殖的鱒魚，經過田媽媽的料理後， 都成為一道道美味佳餚，除了鮮魚之外，還有烤土雞、當地節令蔬菜，食材新鮮不須過多的調味，每一道都讓人驚豔！\r\n老闆希望來到這裡的客人可以盡情享受大自然的環抱，以及健康美味的山產料理，山莊還提供舒適的民宿，有空就來八五山泉走走，在山林中享受愜意時光。\r\n綠意盎然的環境，非常適合飯後散步，享受芬多精的薰陶。\r\n整棟以台灣紅檜為主的建築，只要走進就會嗅到濃濃的檜木香。潔凈典雅的餐廳陳設和明亮的落地窗，讓客人可以一邊大啖美食一邊欣賞戶外的山林花木。\r\n鹽焗烤魚\r\n採用鹽焗方式烤魚，將魚肉的湯汁牢牢的鎖住，魚肉品嘗起來更加鮮甜，肉質也很Q彈！\r\n野生溪蝦\r\n溪邊現撈的溪蝦，清炸後蝦殼酥脆，再沾些胡椒盬連殼吃，別有一番滋味。\r\n蒜味鮮魚\r\n鮮嫩的鱒魚肉配上嗆辣的蒜泥醬油，讓人出乎意料的清爽，嘴裡沒有殘留蒜頭的嗆味，取而代之的是魚肉的鮮甜。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25732/480x360_agrispots-image-xlzf56h-puy3v9w3entnzw.jpg'),
(35, '千戶傳奇生態農場', '02-2672-0748', '新北市', '三峽區', '有木里有木154-3號', '千戶傳奇農場位於新北市三峽的深山中。老闆林典以清澈冷冽的山泉水養殖珍稀的鱒魚、高山鱸魚、鴨嘴鱘、鱘龍魚等，場內可見身長超過2.5公尺的水中鱘龍魚以及外型獨特可愛的鴨嘴鱘。\r\n千戶傳奇採用自產自銷的經營模式，讓客人能品嚐到最新鮮的料理，有活化石之稱的鱘龍魚只生長在乾淨的水域，肉質鮮甜完全沒有土味且無刺，店家推出各種鮮魚創意口味料理，絕對可以滿足挑剔的味蕾。\r\n不只如此，園區以觀光養殖漁場為主題，提供豐富的DIY活動讓遊客體驗，可以徒手抱超大鱘龍魚、親自下廚料理鮮魚，還有農場主人親自解說魚苗的成長過程，讓客人也能了解到漁夫的辛勞。\r\n戶外用餐庭園充滿綠意與溪流，拉卡溪、中坑溪與大豹溪等多條溪流清澈湍急，四季各有不同美景，附近還有森林步道，可以在飯後順便踏青呼吸新鮮空氣。\r\n養生鱘骨湯\r\n鱘龍魚全身都是寶，連骨頭都晶瑩剔透，用鱘龍魚骨熬成的湯盡是滿滿的膠原蛋白精華，味道濃厚，是養顏美容聖品。\r\n清蒸鱘龍魚\r\n來店必嚐的清蒸鱘龍魚是老饕的最愛。老闆娘葉福花表示，喜歡吃魚的朋友一定會點清蒸來吃，味道淡雅，肉質帶點Q度，清蒸鱘龍魚更能吃到滿滿的膠質。\r\n香煎鱘龍魚\r\n香煎鱘龍魚煎得皮脆肉嫩、膠質黏唇，每一口都讓人非常滿足。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/412/480x360_328c09e6c90f498fbb5208aa689c8257(1).jpg'),
(36, '仁上風味坊', '04-9245-1372', '南投縣', '國姓鄉', '大石村昌榮鄉40-1號', '沿著大石村的方向前進，經過大片果園，看見大石峽谷的指標後再往上，即可達半山腰的「仁上風味坊」。\r\n田媽媽廖瑞篙、徐明珠夫妻原本是經營果園的農民，921地震之後改變人生方向，積極學習手藝、考取執照，民國96年加入田媽媽行列，將原本果園的包裝倉庫改建成餐廳，為遊客提供古早農家媽媽的手路菜。\r\n招牌料理橄欖養生豬腳與五花肉炒桂筍是必吃佳餚，餐廳門口一顆蘋婆樹（鳳眼果），除了可以像栗子般當零嘴吃，也可以跟絲瓜、蛤仔一起燉湯，成了當地特色湯品，還有清炒蘆筍或是涼拌都可吃出它的清脆滋味、客家小炒、野菜料理都是經典美食。\r\n田媽媽選用當地食材，山上大片果園種滿各種香甜多汁的水果，有甜柿、水蜜桃，還有木瓜、柑橘、芭蕉等，還有豐富的筍類、野菜與香草，經過田媽媽巧手後變成桌上一盤盤美味料理。\r\n徐明珠是客家媽媽，自製的筍乾、梅醬、桔醬都非常道地，用果園產製的小金桔熬製桔醬、搭配放山玉米白斬雞，簡單的酸甜口味越讓人食指大動。\r\n這裡採預約制，希望遊客可以放鬆心情，到山上採果、享用簡樸的田園料理，餐後再來一杯香蜂草茶，享受悠閒恬靜被大自然擁抱的感覺。\r\n田媽媽廖瑞篙、徐明珠夫妻\r\n橄欖養生豬腳\r\n五花肉炒桂筍\r\n宮保客家小炒', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3497/480x360_kito-111(3).jpg'),
(37, '元貝田媽媽海上料理舫', '06-993-2305', '澎湖縣', '白沙鄉', '岐頭村20-2號', '「元貝田媽媽海上料理舫」是台灣第一個海上田媽媽，餐廳就在蔚藍大海上，客人將乘坐田媽媽準備的平底作業船，先來一場體驗漁夫工作的行程，之後再到位於海上的用餐平台享受碧海藍天的美食逍遙遊。餐廳使用的海鮮都是當天捕獲直送，經由田媽媽的巧手搖身一變成為餐桌上的美食，讓遊客大啖新鮮零時差的海味。\r\n享用美食之外，元貝海洋牧場規劃豐富多樣化的海上行程，依據季節、氣候、潮汐等自然因素設計各式活動，讓您看得到、釣得到、摸得到、玩得到、吃得到，享受高品質的海上休閒旅遊。\r\n除海上活動外，元貝島潮間帶發達，資源豐富。有美麗的沙灘，壯觀的柱狀玄武岩，珍貴的野鳥生態。於島上眺望，澎湖本島及東北海盡收眼底，景觀十分美麗，讓人有心曠神怡、海闊天空的感覺。\r\n海鱺生魚片\r\n澎湖在地優良養殖的海鱺魚，又有「澎湖國寶」之稱，肉質潤肥甜美，加上帶有咬勁的口感與瀰漫味蕾的鮮甜滋味，是許多美食老饕的最愛！\r\n冰卷\r\n現撈澎湖小卷經由高溫汆燙後，立刻放入極低溫的冰水中冰鎮處理，完全保存小卷的甘​甜美味、百分百的鮮度，口感彈牙有嚼勁，咬下去的每一口都是來自大海最天然的新鮮美味。\r\n小魚干貝禮盒\r\n小魚干貝醬的丁香小魚、干貝等食材皆選自無汙染的澎湖海域。元貝田媽媽精心煨炒獨家醬汁，封存大自然的海味，香濃醇厚的口感，不論是作為下酒菜或烹煮料理都是最佳極品。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/416/480x360_74b229aa59074e3bb5d7cce0a993cb6d.jpg'),
(38, '友茶居田園料理館', '0910-835884', '嘉義縣', '梅山鄉', '太和村1鄰樟樹湖5號', '友茶居位於嘉義縣梅山鄉太和休閒農場，是當地的熱門美食，老闆娘陳伯蓉將山野食材變成人間美味的烹飪技巧，讓所有饕客都不遠千里慕名而來！\r\n太和地區因為早晚溫差大、雲氣環繞，種出來的烏龍茶葉片片豐沃厚實，是著名的高山烏龍茶區，這裡除了主要種植烏龍茶，蔬果園裡還有筍子和紅李。田媽媽陳柏蓉一家人住在這裡已經40多年，原本從事茶園的工作，自種、自烘、自售，於民國90年加入田媽媽轉型成休閒農場兼營民宿。\r\n透過田媽媽課程輔導，精進廚藝，善用農場裡種植的蔬果，推出特色風味餐，客人預約訂餐後根據當季蔬果發想菜色，用農場生產的食材為客人製作美味佳餚。\r\n油雞切盤\r\n來自農場內養足8個月的放山雞，田媽媽對火候掌控精準，油雞皮滑肉嫩、滋味濃郁，滿口肉香。\r\n茶葉酥\r\n將茶葉炸到金黃酥脆，信手拈來成了一盤獨具特色的茶料理，令人口齒留香。\r\n筍乾控肉\r\nQ彈軟嫩的油亮肉塊格外誘人，搭配細火慢慢的滷煮、吸收了肉汁和香氣的筍乾，入味又好吃。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3504/480x360_kito-50.jpg'),
(39, '火雞森林', '05-374-1851', '嘉義縣', '新港鄉', '宮前村新民路254之300號', '田媽媽火雞森林是由火雞繁殖場轉型而來的，餐廳結合從民國62年開始從事火雞養殖的志元畜牧場以及當地的菜農，開發出適用於各種場合的餐點，提供低食物里程的輕食!老闆娘加入田媽媽之後為了讓大家有火機大餐可以吃，認真研發火雞入菜，並且接受火機大餐的預約定席。\r\n餐廳裡最具特色的餐點是黃金烤火雞，採用的是本土飼養四個半月的母火雞，先用30多種藥材香料醃過，再經麥芽糖水澆淋，吊著風乾4小時後，才進爐燒烤，以類似北平烤鴨的手法採明爐燒烤，，平均要烤3小時以上。烤火雞肉質鮮美多汁，使用特殊的料理方式，讓肉質吃起來與平常雞肉的肉質有著與眾不同的風味。\r\n火雞肉可以單吃，也可以搭配當季鮮甜的蔬菜做成墨西哥捲餅、潛艇堡等，要享用火雞料理最好事先預定以免落空。\r\n黃金烤火雞\r\n潛艇堡\r\n墨西哥捲餅', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3509/480x360_kito-11(3).jpg'),
(40, '牛奶故鄉餐坊', '03-756-1126', '苗栗縣', '造橋鄉', '豐湖村5鄰上山下2號', '牛奶故鄉餐坊位在苗翔牧場內，園區具有30多年的牧農史，飼養超過80頭的優質乳牛，每天生產200多公斤鮮乳，除了供給鮮乳公司，還提供牧場餐坊使用每日當天現擠的生乳將保存在攝氏3度的低溫下，再以隔水加熱方式以不超過攝氏70度的低溫進行長時間殺菌，確保牛乳中的營養及風味能夠完整保留；因為乳源新鮮、乳質好，田媽媽利用用鮮奶製成雪糕、奶酪和鮮奶饅頭，百分百牛奶製成的乳製品，每一口吃起來都特別濃郁綿密。除了牧農外，場內栽種許多觀賞食用性質的南瓜並開闢南瓜隧道，致力於提供遊客完善的食農體驗。\r\n田媽媽牛奶故鄉餐坊利用園區內以天然肥料種植的新鮮瓜果蔬菜與每日現擠牛奶，製作饒有客家特色的風味餐，像是「三杯土雞」、「金沙南瓜炒鹹蛋」與「南瓜海鮮濃湯」，都是遊客來到這裡必嚐的招牌特色餐點！\r\n三杯土雞\r\n金沙南瓜炒鹹蛋\r\n南瓜海鮮濃湯\r\n用餐環境', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25694/480x360_agrispots-image-ompke42ue0qkxjjyaejzbw.jpg'),
(41, '北海驛站石農肉粽', '02-2638-1005', '新北市', '石門區', '石門村中央路2號', '位於石門區的最北端，沿著美麗的海岸線有著一家門口總是大排長龍的「北海驛站石農肉粽」，遠處走來就能聞到空氣中的粽葉香氣。「田媽媽北海驛站石農肉粽」相關產品有糯米系列則有傳統肉粽、蛋黃粽、素粽、健康養生粽等產品，將圓糯米Q香特性揉合獨家烹調方式，加入自煮紅蔥酥、獨門黃金比例滷汁、精選之金鉤蝦拌勻後，最後將所有餡料一同加入，遵循古早味作法，香氣十足；發芽系列則有傳統口味粽、甜素粽、芋泥蛋黃粽等產品，由於發芽米纖維高於傳統白米四倍，有助於腸胃蠕動與消化，是許多追求養生族群的不二首選。\r\n「田媽媽北海驛站石農肉粽」提供客製化服務，每種粽子餡料皆可以自行調整與增加，現今更貼心提供宅配送貨到府服務，增加消費者購買上的便利性。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/30136/480x360_agrispots-image-ohyrfwlhikiojqdcbx0hdw.jpg'),
(42, '古早雞休閒農場(古早雞傳統米食)', '04-9252-2215', '彰化縣', '芬園鄉', '彰南路五段451巷36號', '「古早雞休閒農場」位於彰化縣芬園鄉最初從養雞場起家，轉型為休閒農場後增闢生態教育園區和果園，並開始經營田媽媽品牌。\r\n農場充滿濃濃復古風，自家果園以荔枝產量最多，除了鮮嚐外還融入菜餚中，餐廳以農場自產自銷方式推出古早雞風味餐，並結合荔枝創造出各式佳餚，包含鳳荔鮮魚、荔枝雞湯、荔枝九層塔煎蛋、荔枝香腸等荔枝鹼粽等荔味佳餚。\r\n風味餐中串連兩大特產的「荔枝雞湯」，以農場飼養半年重兩斤半的小土雞加入整顆荔枝、破樹子、薑母，一起熬煮出馥郁香氣，而原本容易上火的荔枝，經過熬煮之後褪去熱性，轉為涼補勝品，加入荔枝的雞湯鮮甜可口，雞肉滑嫩好吃。\r\n「沙燻鴨公」屬於古早味的燉法，將鴨及古早雞米血、醬油、老薑母上等麻油裝進甕裡，下面放上沙子及鐵鍋用柴燒炙甕裡的鴨公熟成，是最古早味的燻法上桌的時候併入手工麵線一起食用，既飽實補身又滿足。\r\n白斬雞是餐廳的招牌料理之一，油亮薄嫩的外皮，紮實的肉質，搭配蒜醬更是絕佳美味，荔枝香腸也是必點料理，品嘗時有淡淡的水果香氣，搭配蒜片提味又是另外一種味道。\r\n農場以荔枝乾為主開發出的產品還有荔枝醋、荔枝香腸、荔枝酥餅等，近幾年屢屢獲得台灣好伴手的殊榮，其中荔枝酥餅，每一口都能感受到淡淡的玫瑰荔枝香味多層次口感，酸酸甜甜，體會道地的台灣風味，再加上不油又酥嫩的餅皮，咬上那一口總令人愛不釋手，不油不膩，老少咸宜，是年節送禮的最佳伴手禮。\r\n農場飼養的土雞\r\n白斬雞\r\n荔枝香腸\r\n雞佛跳牆', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25597/480x360_agrispots-image-iahmydqxyus9trgu_nuk8a.jpg'),
(43, '古道廚娘', '05-256-1645', '嘉義縣', '竹崎鄉', '中和村奮起湖165-2號(奮起湖鐵道旁)', '「古道廚娘」就位在奮起湖火車站旁，田媽媽陳素抹採用阿里山特產，轎篙筍、山葵、茶葉等入菜，進行創意烹調，做成一道道美味的料理。\r\n她擅長透過料理傳遞在地的口味，運用阿里山特產轎篙筍、茶葉及高冷蔬菜設計菜色，且以自製菜餚介紹奮起湖地區的當地文化、人文故事，光以轎篙筍設計出的筍餐就多達45種做法。\r\n來到這裡必點的菜餚之一就是老闆娘自家手工製作的新鮮豆腐，配上新鮮現磨的山葵，這道山葵豆腐味道不嗆辣，非常好吃。\r\n茶香茗排\r\n得獎名菜「茶香茗排」，以烏龍茶泡出茶湯、放入山上的黑毛豬肉浸泡去腥味；排骨油炸後，再用醬油、味淋和紅糖燉煮，最後灑上金萱茶鬆和白芝麻，入口滿口茶香。\r\n筍鮭魚\r\n阿里山特產轎篙筍的纖維柔軟、滋味清甜，搭配入口即化的鮭魚清爽不膩口，唇齒留香。\r\n山葵豆腐\r\n自製手工豆腐搭配阿里山新鮮山葵研磨而成的哇沙米，是遊客到此必點的美食。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3532/480x360_kito-140(1).jpg'),
(44, '成農花田餐坊', '08-987-1909', '臺東縣', '成功鎮', '美山路139-2號', '台東成農花田餐坊位於台東成功鎮農會，旁邊即是美山驛站，每年春季成功鎮農會都會在此舉辦成功花海，各色美麗的花朵搭配創意的漂流木裝置藝術，讓行經東海岸的遊客們又多一處賞玩的景點。\r\n成農花田餐坊餐點中所供應的海鮮都是來自成功漁港漁民現撈的漁獲，例如：新鮮的鬼頭刀以及種類豐富的蝦蟹與貝類等，而蔬菜也都是來自當地農會超市，每一道料理都最新鮮、最道地，也最貼近成功鎮山海風情的特色餐飲。\r\n到此可以品嘗木虌果料理，這是臺東特色農作物，當地原住民會食用木虌果的葉子以及青果，臺東區農業改良場研究後，發現木虌果具有豐富營養價值，其中含有的茄紅素是蕃茄的70倍，還具有多種人體所需的營養元素，田媽媽將木虌果融入料理中推出當地獨特的木虌果料理。\r\n餐廳後方的觀景平台可遠眺海岸美景，遊客們在飽餐一頓後也可至鄰近的三仙台、石雨傘等台東海岸著名景點，是欣賞東海岸景觀絕佳的私房景點之一。\r\n木虌果海鮮鍋\r\n木虌果含有豐富營養素，包含茄紅素、葉黃素、胡蘿蔔素等，成田媽媽們將木虌果與在地的新鮮海產結合，創造木虌果海鮮火鍋營養又美味。\r\n避風塘白蝦\r\n來自東海岸無污染的純海水來養殖白蝦，肉質緊緻扎實、甘甜美味，整隻白蝦放入口中卡滋卡滋的咬，香氣十足、鮮甜口感一次滿足。\r\n鬼頭刀魚排\r\n鬼頭刀肉質細嫩又少刺，鮮而不腥，餐坊將魚肉稍微醃漬後下鍋油炸，外酥內軟。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3534/480x360_nc5j102p9sa1mcbhfqz5k2b9v94uxiem.jpg'),
(45, '巧軒餐館', '03-722-6868', '苗栗縣', '公館鄉', '石墻村11鄰223-1號', '巧軒餐館在苗栗公館鄉是一間當地知名的老店，成立於九十六年，餐廳旁是紅棗園；公館鄉是全台灣唯一種植紅棗的地區，有「紅棗之鄉」盛名，因當地氣候非常適合種植紅棗，還有後龍溪提供的優良水質，所以種植的紅棗品質良好。\r\n老闆為了希望為客人打造良好的用餐環境，用餐時小朋友有遊憩的空間，有一塊空地方便停車,讓客人安心,悠閒的品嘗老闆用心準備的佳餚，滿足客人的需求。於是舉家回到故鄉自家的紅棗園裡,開設屬於自己的夢想餐館，\r\n餐館內食材以當地生產為主，像是店裡的招牌菜，好吃的香煎芋糕就是選用公館當地優質的檳榔心芋加上現磨的在來米漿和香菇、絞肉、油葱及蝦米蒸製成的手工點心，切片後經由熱鍋煎過，金黃香脆的酥煎外皮，一口咬下就可以吃到綿密的芋頭香氣與彈牙的口感。\r\n紅棗香腸採用在地的紅棗露搭配上等黑豬肉灌製而成，增添了香腸得獨特香氣，相當與眾不同，紅棗香腸是店裡熱銷伴手哩，客人常常會買回家跟家人一起分享。\r\n田媽媽賴如玉的婆婆。\r\n店內點菜率最高的菜莫過於「田媽媽手工水餃」及「香煎芋糕」都是店裡宅配最夯的伴手禮，其中韭菜水餃用自家種的韭菜加上特選黑豬肉包的「手工韭菜水餃」是私房菜色，下鍋後的餃子顆顆晶透飽滿，看似樸素卻滋味十足，吃了還想再吃!\r\n遊覽景點\r\n客家大院、客屬園區、陶瓷博物館、採油博物館\r\n在地美食\r\n客家小炒、薑絲大腸、香煎芋糕、客家粄條、白斬土雞、蘿蔔絲蛋、酸菜肉片湯、福菜肚片湯、紅棗炒飯、紅棗香腸、烤鹹豬肉、也有海鮮料理。\r\n伴手禮與農特產\r\n香煎芋糕、紅棗香腸、韭菜水餃、高麗菜水餃、福菜水餃、香酥花生、紅棗乾、杭菊、紅棗麵\r\n香煎芋糕\r\n紅棗炒飯\r\n手工水餃', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25660/480x360_agrispots-image-4vvu6xiwuumtqwtiagv1lg.jpg'),
(46, '巧婦米食烘焙點心坊', '03-439-5333', '桃園市', '平鎮區', '南東路2號', '位於平鎮市農會裡的巧婦米食烘焙點心坊於民國100年成立，由6位對於烘焙有濃厚興趣的家政媽媽們組成，透過參與研習課程與不斷的精進，以在地食材秈香米（台農秈22號）為主要原料，輔以三低一高（低油、低鹽、低糖、高纖維）之健康料理概念，開發出多元化且深受消費者喜愛的烘焙產品與伴手禮。踏入店面就能看見Rice and me的精巧設計，透過明亮現代化的空間設計，希望可以吸引更多年輕族群認識農業與客家，並且推廣在地優質農產品。每周二與周四固定販售吐司、鮮香米卷，因其實惠的價格與高品質，往往吐司一出爐即販售一空，成為桃園平鎮農會的搶手熱門產品！\r\n火腿起司吐司\r\n葡萄吐司\r\n綜合吐司', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25743/480x360_agrispots-image-uj9fxal_auefhdw7sran5w.jpg'),
(47, '傅姐風味餐', '08-955-1818', '臺東縣', '鹿野鄉', '永安村永安路588號', '來到台東鹿野鄉永安村的農特產品展售中心，這裡兼具遊客旅遊資訊中心，也是田媽媽餐廳「傅姐風味餐」，寬敞的停車場、悠閒的庭園造景，偶聞店內飄出的茶香與菜香，所謂「偷得浮生半日閒」的輕鬆愜意，只有來到這裡才有這般心隨境逸的茶趣。\r\n客人暱稱傅姐的傅錦英總以親切的：「來呷茶！」迎接每一位到店客人，除了茶藝功夫了得，中式風味餐料理手藝也是「頂港有名聲，下港有出名」，傅姐將鹿野紅烏龍入菜，變換一道道精緻又健康的好料理！她笑說：「或許是因為了解紅烏龍茶特性，所以烹煮入菜時才能畫龍點睛。」。此外，傅姐也結合客家烹飪技巧，改良原住民料理的烤鹹豬肉，先將五花肉、香菇、菜脯、香蔥爆香，再用月桃葉包起來蒸，他因為這道「和烤山豬肉」，得到原住民創意料理獎。\r\n餐廳距離鹿野高台熱氣球場域不到2公里，飯後還可以體驗熱氣球、飛行傘，或是到附近知名景點踏青都是很不錯的選擇，田媽媽傅姐風味餐目前沒有固定公休日，採不定時店休，建議來之前先訂位，以免白跑一趟。\r\n剝皮辣椒三味香\r\n剝皮辣椒、皮蛋、香菜串在一起的三味香，開胃又下飯，是外面少見的特色菜！\r\n紅烏龍茶蝦\r\n利用紅烏龍入味的鮮蝦料理，每一口都嚐得到清甜的香氣，只要吃過一次就讓人深深著迷。\r\n客味烤鹹豬肉\r\n皮焦脆的鹹豬肉，光是看到表面油亮亮的就讓人食指大動了，鹹香滋味超級推薦。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3551/480x360_kito-49.jpg'),
(48, '玉露茶驛棧', '03-980-1111', '宜蘭縣', '大同鄉', '松羅村鹿場路10-2號', '位於宜蘭太平山腳下的「玉露茶驛站」以茶起家，田媽媽莊翠月以獨特的料理方式將在地新鮮食材融入自家生產的玉露茶業，做出美味的茶餐料理。\r\n她說：「茶味濃的熟茶如烏龍茶、紅茶適合燻鴨、滷肉，讓肉充分入味、去除油膩感。」她 利用烏龍茶當八角來滷肉，包進有機綠茶做的刈包，成為獨樹一格的「虎咬豬」。清香的茶 葉如金萱則適合蒸、炒。頗受好評的「雪茶燉雞湯」裡看不到茶葉，卻能喝到雪茶獨特的花 香，雞湯下肚暖胃、茶香撲鼻。\r\n茶園出產金萱、翠 玉、烏龍、綠茶、紅茶、雪茶等好茶，堅持施有機肥、生態平衡已 達十多年。這裡還有景觀度假民宿，從民宿露臺即可看到蘭陽平原，眼下盡是一片片茶園，大口呼吸山中的清新空氣，身心靈都獲得滿足。\r\n茶燻鴨\r\n選用在地用3至5斤的宜蘭鴨，先稍微將鴨肉醃製、用茶湯燜泡，再煙燻，這道菜非常耗時費工，因此茶燻鴨的美味可說是用時間換來的。\r\n茶香虎咬豬\r\n這一道菜是用綠茶跟蜜香紅茶磨粉後再製成刈包皮。控肉先油炸去油後，再下鍋滷製，最後起鍋加上蜜香紅茶粉末拌炒，讓蜜香紅茶的香氣散發出來。朴菜是當地栽種並醃製而成的， 加上花生粉跟香菜，這樣的刈包只有這在裡可以享用的到。\r\n金萱茶蒸魚\r\n金萱茶蒸魚先在魚肚裡填進金萱茶葉後蒸煮，再將茶湯熬成醬汁，魚的鮮味和茶味兩者巧妙融合在一起。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25765/480x360_agrispots-image-ftwtewrnkkkwdlarcqtziq.jpg'),
(49, '田媽媽QQ米香屋', '05-380-5306', '嘉義縣', '六腳鄉', '蒜頭村3鄰23號', '「田媽媽QQ米香屋」是嘉義縣六腳鄉的熱門美食，擁有別人學不來的阿嬤級的經典米食料理，主打傳承古早味美學的食品為主：油飯、肉粽、菜包、紅龜、米苔目、麻糬、鹹粿都是本店的必吃招牌菜。\r\n由六腳鄉農會輔導牛埔田媽媽-QQ米鄉香屋，由一群熱愛鄉土、各個都專精傳統米食廚藝的阿嬤們所組成，透過口耳相傳的美味絕活，打響了QQ米香屋的知名度。嚐起來帶著純樸、像回到兒時阿嬤親手煮的古早味米食料理，讓人身心靈都獲得療癒。不只CP值高，美味程度更是沒話說。\r\n「在地人吃的是美味，遊客則吃的是家鄉味」由黃謝翠領軍的祖母級田媽媽班，用紮實、深厚、道地的精湛手藝，讓上門的顧客回訪、回購率都超高，看到這群田媽媽忙碌穿梭在店裡的身影，熱情的招呼聲，用心製作充滿古味的米食的心意，就是田媽媽的最佳代言人。逢年過節必備的蒸發粿、年糕，端午節的肉粽、中秋節的麻糬、農曆七月中元普渡常見的艾草粿、油飯、糯米腸、蘿蔔糕道道都是獨家保證的好風味，「QQ米香屋」堅持著傳統米食點心的Q軟和米香，也蔓延著那股彷彿復刻自己阿嬤親手煮出的「家鄉味」。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/441/480x360_米香屋3304(1)(1).jpeg'),
(50, '石岡傳統美食小舖', '04-2572-1490', '臺中市', '石岡區', '豐勢路889之1號', '一場無情的921大地震震垮了石岡區的家園，房子倒了、甚至連工作機會也沒了。但是這群田媽媽們沒有被逆境擊倒，她們靠著自己的傳統手藝，擦乾淚水，樂觀、勇敢地重新出發，成立「石岡傳統美食小鋪」。\r\n體驗活動\r\n鳳片粿 DIY。\r\n課室和果子DIY。\r\n客家三角圓DIY。\r\n遊覽景點\r\n1.石岡水壩\r\n2.食水嵙休閒園區\r\n3.情人木橋\r\n4.客家文化園區\r\n5.東豐自行車道\r\n建議遊程\r\n景點都在石岡小舖附近\r\n可任意搭配\r\n在地美食\r\n石岡美食小舖用餐\r\n伴手禮與農特產\r\n拌手禮&mdash;蜂巢蛋糕、紅麴龍眼米糕\r\n客家點心&mdash;芋頭粄、綜合粄、肉粽\r\n石岡傳統美食小舖就開在農會旁，不少客人預約到這用餐，享受客家媽媽的傳統口味。媽媽們用照顧家人的心製作料理，強調低油、低鹽、低糖，自製的養生紅麴醬更為餐點的營養和口味 加分，讓人吃飽又吃巧。回程時別忘了挑選桔醬和醃梅，讓田媽媽的美味一路伴隨回家。\r\n紅糟龍眼米糕\r\n純手工做的紅糟桂圓米糕，把龍眼乾、紅麴醬和酒先炒香，最後跟蒸熟的圓糯米拌在一起；糯米 炒出Q度，紅麴有軟化米粒的功用，越嚼越香。\r\n紅麴醉雞捲\r\n紅麴中富含益菌，美味又營養，散發微微酒香搭配雞肉捲，相當開胃。\r\n蜂巢蛋糕\r\n蜂巢蛋糕是石岡田媽媽自創風味蛋糕。結合傳統發糕 及蜂蜜蛋糕用料，改蒸為烤，蛋糕體蓬鬆成蜂巢 狀，有濃濃的乳香與焦糖香氣，已成為石岡名產。\r\n臉書： https://www.facebook.com/0425721490.Hakka/\r\n地址：https://goo.gl/maps/c4J5QDwwQuGgJsjM8', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25624/480x360_agrispots-image-mhwbnuyo4eg9uumu_mylua.jpg'),
(51, '原夢觀光農園', '0987-239-826', '南投縣', '仁愛鄉', '南豐村松原巷80號', '「原夢觀光農園」位於南投仁愛鄉南豐村，是一間一間超過二十幾年的餐廳，南豐村（眉溪部落），居民大都為「賽德克族」。\r\n「愛，是在別人的身上，看見自己的責任」，原夢觀光農園在江嬌媚班長從七二水災無私投入救災的強勁生命力中幫賽德克族傳統美食打出名號。\r\n現以二代王孝良接棒並以「知足，就是生活的根本」作為飲食文化的傳承，餐廳內所有的食物基本選用當地特色食材為主，並以原住民傳統辛香料調味，沒有複雜的作法和調味，在傳統及現代飲食中取得平衡，以滿足不同族群對吃的需求。\r\n使用當地當季食材研發的幾道料理中，如紅豆糯米飯、香蕉小米糕、香烤小米醃豬肉、刺蔥香烤鯖魚、香烤馬告雞、馬告泰式蝦等，食材皆以本地養殖的豬肉、山土雞，並選用在地農友種植的高山高麗菜、牛番茄等，加入原住民傳統調味料如刺蔥、山當歸、山胡椒等加以烹調而成，希望呈現給客人最新鮮、最道地的風味菜餚。\r\n店內不僅僅可以用餐，也可安排一系列的賽德克文化之旅，讓蒞臨的朋友可以真正了解賽德克族文化。\r\n近幾年，二代王孝良更在飲食方面推動飲食文化體驗，讓蒞臨的朋友可以學習如何製作在地料理，並藉由活動讓大家更能夠認識在地賽德克的飲食文化。\r\n \r\n體驗活動\r\n賽德克居住文化課程\r\n賽德克傳統狩獵體驗課程\r\n賽德克編織文化課程\r\n飲食文化體驗課程\r\n蝴蝶生態課程\r\n遊覽景點\r\n夢谷瀑布\r\n清境農場\r\n紅豆糯米飯\r\n紅豆糯米小米飯浸泡超過十個小時以上，使用傳統木桶在火上直接烹煮而成，米飯帶有紅豆香氣Q有彈性。 \r\n烤豬肉\r\n這道烤豬肉是餐廳必點美食，上桌前，還會經過火槍再燒過一次，為的是要逼出油脂，讓客人吃到食物的美味。 \r\n馬告泰式蝦\r\n香烤馬告雞腿', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3603/480x360_kito-47.jpg'),
(52, '后里傳統米食舖', '04-2557-5171', '臺中市', '后里區', '仁里村圳寮路67號', '民國93年在農會的輔導下成立「田媽媽后里傳統米食舖」，當時由10位田媽媽成員與班長柯參秋的參與下，將傳統米食以標準化、規格化、多元化的方式加工，研發出許多令人讚不絕口的粿製品。田媽媽對於吃有一定的堅持，堅持不採用防腐劑、色素、味素，用最簡單的調味呈現出天然健康好滋味。\r\n米食舖成立之初，配合后里區中社花市舉辦玫瑰花宴，田媽媽以拿手米食烹飪技術，揉合玫瑰花入味，一炮打響了后里傳統米食舖的知名度。目前產品有：九層糕、肉粽、草仔粿、芋仔粿、菜頭粿、菜包粿、純米發粿、紅龜粿等。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25670/480x360_agrispots-image-egq47tcsuuagqjpjgrp4_a.jpg'),
(53, '羊咩咩的家', '07-696-1317', '高雄市', '路竹區', '甲北里永華路302之96號', '「禾光牧場&mdash;羊咩咩的家」位在高雄路竹，是一間可以免費參觀的牧場，專們飼養羊隻為主，牧場內有400隻以上的羊，以自產自銷新鮮羊奶、羊奶冰棒、羊奶片等羊奶製品、以及有機牧草汁等飲品，喝過禾光牧場羊奶的遊客都會驚呼：「這裡的羊奶新鮮香醇，完全沒有羊羶味！」\r\n除了鮮羊奶、羊奶饅頭等美味的點心外，農場旁種植六公頃的狼尾草，因不噴灑農藥，榨出的100 %純淨牧草汁充滿原始的青草味，新鮮、營養又健康，也很值得遊客品嚐。\r\n牧場平日採團體預約制、假日才對外開放，在這裡不僅可以在牧場餵小羊喝奶、吃牧草，還能體驗擠羊奶、參加母羊選美比賽，玩累了來杯新鮮羊奶搭配牧草做的點心，吃得到羊奶與牧草的營養與美味。\r\n圖說：體驗餵小羊喝奶。\r\n牧草汁\r\n牧場種植的台畜二號狼尾草營養是一般蔬菜水果的5~10倍，營養價值豐富，榨成汁後喝起來有淡淡的牧草清香。\r\n鮮羊奶\r\n牧場內的羊群以狼尾草為主要飼料，所採集的羊奶採巴氏得低溫滅菌法，無任何添加劑，完整保留羊奶中酵素及機能性成份，品嚐起來有天然牧草芳香。\r\n羊奶饅頭\r\n使用牧場的新鮮羊奶揉製而成的手工饅頭，不僅營養又健康，還嚐的到鮮醇濃郁的羊奶香氣。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/452/480x360_862e3d98f45d4581a6525bb33c77aefd.jpg'),
(54, '艾馨園', '04-787-4012', '彰化縣', '花壇鄉', '灣東路239號', '「艾馨園」一座結合艾草與特殊菇類的生態教育園區。老闆李振輝於民國84年回到故鄉彰化 花壇，推廣研發有機無毒的食品，加 入有機協會發展自家品牌「艾草之家」，並與農會合作 經營艾馨園，發展出小型生態農村。\r\n李振輝說：「艾草本身生命力旺盛，平時不用特別照顧，只需要營養調合、曬太陽、雨水 滋潤、排水良好等生長條件。」艾草是一種殺菌的植物，有天然驅蟲的特性，此外，艾草的葉綠素和纖維質豐富，其中葉綠素更是波菜的七倍，可促進人體循環和新陳代謝。\r\n為了製作素食的艾草粿，他說服父親將家裡的 一塊荒地拿來栽種有機艾草，田裡不施肥、不用農藥。\r\n艾馨園的田媽媽們秉持著低糖、低鹽、低 油的健康料理目標，將艾草與新鮮摘採的菇蕈做完美的 結合，烹飪成一道道養身美味的料理，例如：古早艾草粿、艾草麵線、艾草陶盤蝦、艾草根雞湯等，除了色香味俱全之外，還搭配園區內當季有機蔬果，以符合現代人講究生機飲食的養身原則。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25604/480x360_agrispots-image-nf-uk9hoxugj3srvofxhjg.jpg'),
(55, '快樂農家米食餐飲坊(坪林田媽媽農村小廚)', '02-2665-6041', '新北市', '坪林區', '北宜路八段141號', '坪林的文山包種茶享譽國際，來這裡除了買茶之外，更要品嘗具有當地特色的料理，這間快樂米食餐飲坊是最佳選擇。\r\n快樂米食餐飲坊是由當地田媽媽所組成的，成員多來自製茶人家，對茶葉十分熟悉，將坪林茶葉融入料理當中，為菜餚增添與眾不同的風味，讓茶葉及在地食材做了完美的結合。\r\n翁玉蘭班長表示，茶葉入菜不但風味好還兼具養生健康，不同發酵程度及作法的茶葉有不同的香氣，與食物搭配能為茶點及菜餚帶來不同風味，而且茶葉可去油解膩，料理中加入茶葉還能幫助消化。\r\n快樂米食餐飲坊使用坪林最具代表性的茶葉與在地農產製作料理，努力呈現出具地方特色的創意，每道菜都散發出濃濃的茶香，讓來客人享受美味的茶鄉田園料理。\r\n茶油雞湯\r\n茶油含天然葉綠素、茶多酚、維生素E，以包種茶油調理，雞肉吃來嫩甜多汁、清爽不油膩。\r\n茶油煎香魚\r\n香魚煎得外皮酥脆、肉質細膩，搭配茶油的香氣，吃下去的每一口都是享受。\r\n茶油炒雞\r\n茶油清香不油膩、雞肉鮮嫩完全不柴，配上薑片和梅子，十分美味！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25748/480x360_agrispots-image-iqeqyebm40c4b59pzc1esg.jpg'),
(56, '村長庭園咖啡餐坊', '06-686-1885', '臺南市', '東山區', '高原里100之9號', '村長庭園咖啡餐坊位於台南市東山區，咖啡園區就位於天池周邊，週邊為森林保育區，擁有極佳的生態環境，擁有適宜的氣溫與海拔，提供絕佳的咖啡生長環境，孕育出甘、醇、香、不苦不澀的頂級咖啡。沿著天池步道，還可一覽咖啡山的壯闊景色。\r\n村長從80年代開始種植咖啡，種植面積約4公頃多，是目前東山咖啡產量最多的莊園，村長堅持一條龍作業，控每一批咖啡的品質，從種植到生產、採收、去皮、發酵、洗淨、曬乾、儲存、脫殼、烘培、包裝、銷售等過程都是夫妻倆一手包辦，以確保每位來品嘗咖啡的客人，都能喝到最優質的咖啡。\r\n在這裡除了咖啡之外更不能錯過店裡的美食，老闆娘極佳的手藝，運用在地野菜與食材結合自家生產的咖啡，創造出獨家佳餚，包含養生咖啡雞湯、咖啡豬腳、黃金糕、金瓜米粉、涼拌過貓卷等都是讓人讚不絕口的咖啡料理。\r\n招牌養生咖啡雞湯需要耗時燉煮建議先預約，加入枸杞、紅棗、咖啡、獨家藥膳燉煮帶出雞本身的甜味，嚐起來肉質扎實，帶有咖啡與雞肉本身的香甜味道，湯頭會從一開始的淡雅風味，漸漸熬煮到道後面的渾厚咖啡香帶雞肉甜味，像是品咖啡一樣，帶有深淺度的韻味，嘴裡環繞咖啡甘甜香氣，令人回味無窮。推薦這一道涼拌過貓卷，是老闆娘的獨家創意料理，過貓蔬菜用海苔捲起來，淋上獨門咖啡醬提味，非常爽口帶有咖啡韻味。村長自家烘烤的咖啡加入豬腳一起滷，豬腳Q彈還帶有甘甜清爽的咖啡香氣，讓豬腳吃起來不油膩，反而增加清甜風味，讓豬腳更加好吃。這些創意料理是只有在這裡才有機會吃到的美味佳餚，吃飽稍作停留，再來品味一杯優質咖啡，真的非常愜意。\r\n除了品咖啡享美食之外，這裡還另提供一系列體驗活動，從咖啡山的探訪到DIY烘豆體驗，了解咖啡生長到成為杯中飲品的過程，喜愛自己煮咖啡的朋友，還能學習咖啡沖煮法、虹吸式煮咖啡等教學體驗課程，而喜歡在森林中漫步的朋友，可以到天池沉浸在群山環繞的清幽靜謐，欣賞水中生態。\r\n咖啡園\r\n咖啡樹上的咖啡果實\r\n養生咖啡雞湯\r\n咖啡豬腳\r\n涼拌過貓卷', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3631/480x360_kito-4(1).jpg'),
(57, '走馬瀨田媽媽草香餐坊', '06-576-0121', '臺南市', '大內區', '二溪里唭子瓦60號', '「田媽媽草香餐坊」位於台南走馬瀨農場裡，以健康飲食為主軸，提供注重樂活的現代人「三低一高」的養生餐點。每天現採農產種植的油菜、蘿蔔、番茄等蔬果供應餐廳，讓客人吃到最新鮮的蔬果。\r\n草香餐坊利用走馬瀨農場所種植的牧草台畜二號狼尾草，製作出百變的牧草料理，餐坊裡有用牧草麵條煮的牧草肉燥麵、牛肉麵、排骨麵，以及結合牧草高湯與台南虱目魚丸的牧草魚丸湯等。\r\n除了提供餐飲外，也有各種牧草DIY活動，其中以牧草饅頭DIY最受歡迎，自己動手作饅頭、麻糬，兩個小時內就可享用親手揉製的牧草食品，非常適合親子同樂，年節時則推出牧草湯圓製作，全家可在農場裡搓湯圓、吃湯圓，餐坊也會針對在地農特產品推出DIY活動，如梅子一夜漬、情人果製作等。\r\n農場裡不僅有好吃的養生餐、好玩的活動，還有廣大的青青草原及花田可以欣賞，歡迎來走馬瀨農場共享綠色饗宴！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3635/480x360_kito-98(2).jpg'),
(58, '那都蘭工作室', '03-861-2213', '花蓮縣', '秀林鄉', '秀林村11鄰53之1號', '在秀林鄉裡的那都蘭工作坊，身懷傳統織布技藝的胡秀蘭，從16歲開始學習太魯閣族的傳統織布，應用多元的手工藝技巧與織品相互搭配，將太魯閣族人的傳統生活記憶及古老傳說織入一塊塊的布匹之中，讓傳統織布文化與現代生活用品結合，創作做出具有原民圖騰的實用商品，讓太魯閣的文化能被看見。\r\n胡秀蘭表示每一線一絲都代表著對自己技藝的堅持，因此產自於那都蘭的產品皆有售後維修服務，近年來更積極參與國內文創工藝認證及各式設計比賽，分別獲得台北市原民局與中央原民會的標章認證，以及許多比賽的獲獎肯定。\r\n那都蘭工作坊將現代織布機的技術傳授給各族原住民外，也進行織布推廣教學，將染布工藝與實用商品結合，在教學的同時，也積極向部落耆老們請益，多方汲取傳統織布知識與技藝。那都蘭工作坊努力將織布成品生活化，由織布展現生活美學中更多元的變化，使每件作品的創作與開發都能讓大眾更了解且接受太魯閣族文化，受到肯定與重視。\r\n工作坊推出多種DIY體驗活動，運用桌上型迷你織布機，體驗織布世界的奧秘。來到這裡，可以做個富有原住民風格的吊飾或是項鍊，或是製作一條屬於自己的幸運織帶，在一線一線有耐心慢慢手作的過程中，形成美麗的成品，會非常有成就感。甚至還可以體驗古老的紋面刺青，用特殊材料做成的貼紙，只要貼在臉上，就有刺青的效果，隨時要拿掉都可以。\r\n工作坊也有販售有製作好的背包或飾品， 每樣都獨具特色，歡迎周末假日一起來學習，太魯閣族的編織技藝。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25825/480x360_agrispots-image-knjxwdxt3k-0cky4cxmvsq.jpg'),
(59, '卓也小屋田媽媽', '03-787-9198', '苗栗縣', '三義鄉', '雙潭村崩山下1之9號', '以山林村落為概念所設計的「卓也小屋」，隱身於茂盛的蒼翠林蔭間，占地2000坪的園區，一點一滴、一草一木，全是店主人卓老闆花了10年歲月親手打造的，呈現早期台灣農村的在地生活，讓來此的每位賓客都能體驗懷舊的鄉村風格。\r\n站在卓也小屋的門外，能看見以竹材、茅草搭建的門戶，大紅燈籠高高掛，好似早期的台灣農家，更宛若陶淵明筆下的桃花村豁然映入眼前。園內結合天然染色工坊、特色民宿、蔬食餐廳以及藍染文創市集，將農業生態精神與人文元素完美融合。漫遊於此，復古又唯美的木造建築與山林景觀交織如畫，夏季蝴蝶紛飛，隨手就能捕捉空靈美照。\r\n「藍染DIY課程」豐富有趣，提供方巾、束口袋、托特包、門簾等多樣項目選擇，從紋樣的製作細節到染製程序，在專業人員一步步帶領下，旅人能親手製出獨一無二的藍染紀念品，與家人、好友或情人一同留下難忘回憶。\r\n我們以保留食物的真實原味為前提，追求健康好風味。美味的佳餚來自使用有朔源管理認證小農的農產品：雲林玉米、南瓜、高麗菜、南投有機金針、桃園無農藥，無重金屬水耕蔬菜，讓消費者吃的安心健康。卓也小屋希望透過食當季、吃在地、食材溯源、產地到餐桌透明化，提供給客人更優質、更安全的料理。\r\n彩色酸菜包\r\n色彩繽紛令人驚喜的包子色彩，來自卓也染房自製青黛、甜菜根及薑黃，從植物取得健康又養生的天然顏色。\r\n酸菜遵循古法醃製、天然發酵，味道甘醇香甜。卓也主廚以自製酸菜炒製內餡，配以彩色包子麵皮揉成彩色酸菜包。\r\n卓也烤雞\r\n酸甜檸檬魚\r\n卓也蛋黃酥', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25680/480x360_agrispots-image-k_x0_7lkakg5q6qrdlm6xw.jpg'),
(60, '官豐美食餐廳(暫停營業)', '06-579-1238', '臺南市', '官田區', '隆田村文化街25號', '官豐美食餐廳原是官田農會所屬員工餐廳，因為價廉物美口碑好，後來應大眾要求對外開放，成為人人可以走進來享用的社區餐廳，田媽媽以菱角為主題，結合在地蔬菜特產，推出菱角風味餐，讓遊客品嘗官田菱角入菜的多種變化。\r\n餐廳平日以便當為主，負責料理及採買的田媽媽們手藝精湛，菜餚看似樸實無華，吃來卻是滋味無窮。\r\n台南官田是台灣最大的菱角產地，因此，在地的田媽媽們常常利用當地特產菱角，結合本地蔬菜特產做出各式各樣的美味料理，最常見的菱角料理手法是紅燒，剝殼後的菱角肉與豬腳或排骨一起料理， 讓菱角豐富的澱粉飽吸濃郁湯汁；或是酥炸成菱角酥，配上家常的紅蘿蔔炒蛋、豆乾大腸或炒高麗菜，少油少鹽的田園家常菜，保留食材的原汁原味。\r\n官豐美食餐廳推出的菱角風味餐，以套餐呈現，遊客可以透過預約方式品嘗。\r\n排骨便當\r\n排骨便當主打家常口味，堅持少油、少鹽的料理方式，美味卻不減分。那口感軟嫩排骨更是令人魂牽夢縈的家鄉味啊！\r\n雞腿便當\r\n滷成金黃色的雞腿飯，雞肉入味又鮮嫩多汁。配菜的部份看似簡單，卻也不馬乎，堅持保留食物最原始、最純粹的味道，就是要讓大家吃得美味又健康。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/460/480x360_IMG_0099 - 400-20160930115921.jpg'),
(61, '欣燦客家小館', '04-2534-5178', '臺中市', '潭子區', '興華一路219號', '位於台中潭子的「欣燦客家小館」，發揮健康創意料理精神，讓傳統客家菜跳出不一樣的思維。田媽媽羅美蘭說，因現代人注重健康養生，所以將許多健康食材加到菜餚中，結合傳統及創新風味的菜色，希望讓大家品嘗到好吃又將康的客家料理。\r\n國宴珍珠竹筍包\r\n用蓬萊米和西谷米結合的珍珠包，外皮晶瑩通透、吹彈可破。\r\n桔醬排骨\r\n桔醬排骨是傳統的客家私房菜，金桔醬的濃郁香味搭配鮮嫩多汁的豬小排骨，是一道非常開胃又下飯的料理。\r\n客家水粄\r\n水粄是傳統的客家點心，純米漿製作的白粿，上面淋肉燥菜脯，Q彈的純正口感是傳統的客家好味道！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25664/480x360_agrispots-image-g_uuwxs5rkogx-zq3gtb0g.jpg'),
(62, '花泉田園美食坊', '03-922-1506', '宜蘭縣', '員山鄉', '尚德村八甲路15之1號', '花泉休閒農場位於湧泉源頭，佔地廣闊，有著豐富的大自然生態，在綠意盎然的園區裡，可以體驗各種DIY活動，農場主持堅持做有機，也有田媽媽在地料理可以品嘗！\r\n農場內種植大片野薑花，到處都可以當嗅到淡淡的野薑花氣息，這裡有咖啡園、樹葡萄果園、西印度櫻桃園、藥用植物園、野薑花田、可愛動物區、湧泉戲水區、露天咖啡區、觀景台等；還可以自己採摘最新鮮的蔬菜，DIY手作麵條，結合田媽媽提供的滷肉變成豐富的一餐。\r\n這裡非常適合全家一起共遊，讓大小孩子們學習與大自然為伍的好地方，而慢步於花泉有機休閒農場，猶如來到世外桃源，農場的一草一木盡顯大自然生生不息的景象，河中樹叢與天空倒影使人忘卻塵世喧囂。\r\n樹葡萄醋\r\n採用自產有機樹葡萄，以天然發酵的方式製成，營飬價值高，好喝又順口。\r\n野薑花粽\r\n採用自家有機野薑，切碎後拌入糯米，加入特選梅花豬肉、上等蝦仁、嚴選香菇、蒜頭等在地食材，經過調味再以鮮採野薑花葉包覆於外，蒸熟後撲鼻而來的野薑花香氣十足讓人食指大動。\r\n麻椒醬\r\n新鮮辣椒採純手工製作，用文武火反覆翻炒，入口濃厚的香麻辣味席捲你的味蕾，是拌飯、拌麵、料理的好夥伴。\r\n手炒紅豆蛋黃酥\r\n自家翻炒的紅豆餡，採用的是屏東青農生產的紅豆，搭配嚴選鹹蛋黃，讓您吃出健康與幸福味。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25769/480x360_agrispots-image-gxgyuvnan0seqps2rzjo0w.jpg'),
(63, '采竹香食堂', '06-594-1114', '臺南市', '龍崎區', '崎頂村7鄰新市子223號', '台南龍崎擁有「采竹之鄉」的美譽，當地特有的沙質土壤種植出的竹筍別有特殊風味，龍崎田媽媽餐廳「采竹香食堂」的招牌都是利用當地盛產的竹子所製成的，非常有特色，餐廳採用當地盛產的竹筍結合在地的新鮮食材，料理出一道道具有龍崎特色的風味餐。\r\n餐聽是由早期糧食局的稻穀倉庫改建而成的，保留舊倉庫的壁面及結構，天花板上可以看見日式檀木的屋樑，具有色古香的懷舊特色及現代化的農村風味食堂。\r\n當遊客到龍崎觀光旅遊時，就是采竹香食堂的田媽媽們大展廚藝絕活的日子，當每一位遊客填飽五臟六腑後，臉上露出口齒留香的神情，便是給予田媽媽們最大的讚美與鼓勵。遊客可以透過預約方式訂桌，吃飽後還可以到龍崎休閒農場、虎形山公園走走。\r\n鹽焗雞\r\n使用新鮮的放山雞，以傳統作法使雞皮保有Q彈口感並鎖住肉質本身的鮮嫩、多汁，吃起來不油膩帶點鹹香滋味的鹽焗雞，絕對能開啟您味蕾的豐富饗宴。\r\n綠竹筍\r\n龍崎的綠竹筍，清脆鮮甜帶有Ｑ度的口感，田媽媽選用在地新鮮竹筍，開發出涼拌筍沙拉、小封筍乾及酸筍絲大腸等特色料理，歡迎大家來龍崎品嚐竹筍大餐。\r\n古早味鹹飯\r\n古早味鹹飯是將香菇、竹筍等食材爆香後，加入米炒香入味，再用大骨熬煮的高湯拌勻以文火燜煮至熟，製作過程非常繁瑣，製作時間超過 2 小時以上。最後起鍋後飄出陣陣的傳統古早味，總是讓遊客們忍不住吃上一碗又一碗。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3673/480x360_鹽焗雞_2563_L.jpg'),
(64, '官夫人田園料理', '03-925-3517', '宜蘭縣', '壯圍鄉', '新南村霧罕路3號', '官夫人田園料理位於宜蘭縣壯圍鄉的新南村，當地以盛產哈密瓜出名故有哈密瓜的故鄉之稱，在這裡用餐，彷彿置身於瓜田中，視野寬廣遼闊，綠蔭環繞，用餐環境相當舒適，還有許多特色料理可供選擇。\r\n官夫人田園料理餐廳內的瓜瓜風味餐，都是結合當地的食材所研發出來的菜色，例如「哈密瓜雞湯」主要是用在地生產未成熟的哈密瓜，利用古早的醃製手法，經過一年的熟成後，製成的哈密瓜醬瓜，將哈密瓜醬瓜放入滾水熬煮出味道後，搭配新鮮的雞肉與南瓜還有菇類進行烹煮，不再加入任何的調味料，湯頭清爽還能嚐到淡淡的哈蜜瓜香氣，雞肉鮮甜，風味特殊，並且一年四季都可以品嚐到的好滋味，是ㄧ道不容錯過的美味料理。\r\n官夫人田園料理採用在地栽種的南瓜、哈密瓜做成特色佳餚，讓蔬食者大飽口福，像是店裡招牌料理「南瓜米粉」，先將南瓜、蔬菜等料爆香，再與燙軟的米粉一起拌炒，讓米粉油量較少，口感Q彈，十分受歡迎，風味餐的菜色還有哈密瓜杏鮑菇、蜜瓜鮮肉、瓜瓜炸拼盤、南瓜燒豆腐等，都是讓客人讚不絕口的美味佳餚。\r\n哈密瓜飲食質地推廣\r\n廚房一角\r\n清潔整齊的廚房備料區 \r\n用餐環境\r\n四方休閒桌(共16桌)可調整會議*自助式*十人桌餐 \r\n遊憩場區\r\n古物區*DIY區*益智遊樂區 \r\n哈密瓜雞湯\r\n取出醬瓜100g，斜切，放入2公斤水中，慢火煮開，到瓜肉成透明色再放入預先川燙過的雞肉、南瓜塊、香菇數朵及少許調味料，直到肉熟即可食用。\r\n哈密瓜佐雞柳\r\n薄片雞胸肉+少許鹽+胡椒粉+蛋白+太白粉醃漬後與木耳先川燙置旁。彩椒與新鮮哈密瓜切塊置旁。哈密瓜醬瓜切薄片加300cc水煮透後將所有配料放入拌勻勾芡既完成。\r\n哈密瓜小丸子\r\n哈密瓜醬瓜30g，清洗後剁碎。新鮮絞肉300g，加入少許的蒜蓉、玉米粉\r\n、水、醬油、米酒及備好的醬瓜、拌勻後手捏定型再高溫油炸定型，放入電鍋3杯水悶煮，即是香噴噴非常下飯的蜜瓜小丸子。\r\n販賣部\r\n提供在地二級農產品滿足遊客購買力 \r\n伴手禮\r\n伴手送禮兩相宜 \r\n哈密瓜杏鮑菇\r\n準備油鍋，放入川燙後的杏鮑菇熱炒\r\n，再加少許的鹽、胡椒粉、香菇精及切塊的紅、黃、青椒再炒，最後將7分熟哈密瓜果肉切塊加蒜蓉再熱炒，直到湯汁滾即完成。\r\n黃金白玉扣\r\n豆腐擠碎篩細，加入南瓜丁、蝦仁丁與調味料拌勻，倒入碗皿中蒸熟倒扣。再將備好的南瓜泥煮成勾芡，倒入盤中撒上蔥花即成。\r\n南瓜米粉\r\n先準備2個鍋子，第一鍋將南瓜絲和蛋爆香後撈起靜置，再放入500cc的水及少許的鹽、胡椒粉、醬油、香菇精，煮成湯汁做準備。\r\n第二鍋將水煮滾後放入米粉，煮熟撈起，直接放入第一鍋備好的湯汁，轉小火翻攪，直到所有湯汁被米粉吸乾，再放入爆香物拌勻，即是又Q又香的南瓜米粉。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25778/480x360_agrispots-image-utenovtfiug6fccyqd_cfw.jpg'),
(65, '長盈海味屋', '0917-549-736', '臺南市', '北門區', '慈安里484號', '田媽媽長盈海味屋\r\n連續三年米其林必比登推介，四代養殖漁家，遊客可以品嘗到一夜乾系列產品、虱目魚香腸、虱目魚腱、泰式魚柳，還有黑糖「粉粿」，期許大家都能吃到健康又美味的在地料理，同時了解不同物種的生長特性，來一場將大海複製到魚塭的教育之旅。\r\n長盈海味屋為了讓客人吃得安心，堅持使用無毒養殖虱目魚，有產銷履歷與歐盟養殖場雙認證，可以在餐廳品嘗美味的虱目魚料理之外，還可以外帶真空包裝魚菲力、鱸魚一夜干、鱸魚下巴等相關產品，回家自行料理享受美食。\r\n餐廳內除了虱目魚料理外，還有麵線糊以及假日限定的粉粿、冰品等，絕對值得安排假日來一趟長盈海味屋。\r\n長盈海味屋三代皆從事養殖漁業，目前是第三代黃國良經營，他說：「不用藥只是基本，養殖中如何對土地和環境也能友善才是真正重要的事！」，這些堅持也讓長盈海味屋的水產榮獲水產精品海宴獎（國內水產界最大獎項）和輸出歐盟養殖場認證的肯定。\r\n鱸魚一夜干\r\n選用去刺新鮮鱸魚，經冷風乾燥處理，鎖住魚肉的營養成分。佐以些許鹽，魚背肉質Q彈、魚肚香醇中帶鮮甜魚汁，帶有大海氣息的鹹香，紮實飽滿的口感。\r\n不易油爆、不易沾鍋，無須退冰，乾煎或清蒸都很美味，是媽媽們能輕鬆料理的好食材！\r\n鱸魚一夜干下巴\r\n鱸魚下巴是魚鰓蓋後下方至魚肚前段間，連帶胸鰭的彎月形魚骨部位，運動量足夠，絲狀肉質Q彈鮮甜。\r\n元氣飲\r\n萃取虱目魚精華與全雞，熬製3天2夜的元氣飲，喝起來溫潤順口。鋁箔的包裝加熱方便，浸泡熱水即可飲用。適合當作術後、產後、哺乳期間，或是成長發育中的小朋友最佳天然補充品。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3695/480x360_k4p1zyum8vy7qwbfisf2ukw09p4pn6r0.jpg');
INSERT INTO `food` (`id`, `name`, `tel`, `city`, `town`, `addr`, `feature`, `picurl`) VALUES
(66, '青山農場', '08-978-1677', '臺東縣', '太麻里鄉', '大王村17鄰佳崙196號', '｢青山農場｣位於台東縣太麻里鄉金針山，海拔800公尺，除了金針花之外，農場內有種植不少櫻花樹。農場建築原為1967年間所建的木造金針工廠，蔡青山老闆早期在金針山種植50公頃的金針花，並在金針山上搭建木造的金針乾燥加工廠，也是採收工人的休息所在，現在改建為民宿、餐飲部、農特產販售區及繡球花園區，為了使遊客能夠了解金針產業，農場保留原有的作業機器讓遊客參觀。\r\n農場大門\r\n山嵐\r\n農場內的田媽媽餐廳會隨季節變換不同菜色，餐廳採預約制，不定時推出採用在地新鮮食材製作出兼具美味的手工點心，例如：農場自家種植生產的肉桂露，搭配金針山生薑製作而成的手工肉桂薑餅等，另外，農場把以前工廠工人休息的地方改建為遊客住宿區，遊客若想到金針山上看日出，可考慮在青山農場宿一晚唷！ \r\n農場內種植各式各樣的花木會在不同季節綻放，所以四季看到的景緻都不一樣，每年六月有滿山滿野的繡球花，到了八月換成一片金黃的金針花，尤其推薦親子一起來此旅遊，透過接觸大自然的方式，讓小朋友更懂得尊重地球上的每個生態，也教育小朋友保護大自然的重要性，更可以增進親子間的感情交流，這裡是一處放鬆心靈與放慢生活步調的好地方。\r\n繡球花 \r\n櫻花', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3702/480x360_64ibby9mpvhu8yiiypr45xmzkn1559c4.jpg'),
(67, '品佳客家田園料理', '04-2587-0502', '臺中市', '東勢區', '東蘭路34-7號', '品佳客家田園料理的田媽媽張葉碧霞發揮客家媽媽的硬頸精神，扭轉大眾對傳統客家菜重油、重鹹的刻板印象，將料理改良成低鹽、低油的烹調方式，兼顧美味與健康。除了客家料理外，張媽媽也將東勢夏季盛產的高接梨入菜，研發出在地特有、新鮮脆甜的創意料理。\r\n此外，張媽媽醃漬醬菜的好手藝也是非常有名的！他運用餐廳頂樓空間曬福菜與菜脯，除了將它們直接入菜，現場也販售各種手作醃漬物，嫩薑、醃梅、桔醬都是人氣伴手禮。\r\n大甲溪燜魚\r\n選用大甲溪的溪魚，加入破布子、蔥、蒜、辣椒後，清蒸六小時魚骨漸漸化開，肉質細嫩。\r\n黑豆豬腳\r\n這道招牌料理是從阿嬤手中傳承下來的好味道。除了舊食譜中的黑豆和米酒，現在還加入枸杞、紅棗等15種中藥燉煮，讓這道菜更豐富養生。\r\n客家雞酒\r\n以全米酒料理再加入白玉米，是很傳統的客家湯頭味道，嘗過的客人都很推薦喔！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25622/480x360_agrispots-image-cdepg56f7e67aa8qsbdzig.jpg'),
(68, '星月灣海田料理餐廳', '06-998-3455', '澎湖縣', '西嶼鄉', '大池村131號', '星月灣田媽媽海田料理餐廳食材新鮮，挑選在地上等海鮮、肉類等食材，班員們於自家菜圃種植的時蔬，其中包含澎湖絲瓜、澎湖南瓜、高麗菜、落花生、蘆薈、玉米火龍果、楊梅、無花果、蕃茄、香蕉&hellip;&hellip;等數十種蔬果符合低食物里程及在地產銷的健康慨念，完全採用天然有機栽培。加上「頭家嬤」及班員的用心照顧，符合現代健康有機概念，享用最美味的餐點外還能夠將健康有機的概念一起帶走。\r\n園內栽種包含有迷迭香、九層塔、綠紫蘇、辣椒、甜菊、薄荷、巴西里等香料植物。不論是異國飲食或是傳統食材香料，都可以在這裏找到；運用在地食材加以變化，兼顧傳統美味精神及料理創新的研究，提供消費者不同於一般餐廳的佳餚。如此用心的目的是為了呈現更多不同風味的美味料理。\r\n快來澎湖星月灣田媽媽海田餐廳民宿，由澎湖在地味道的健康美食帶給您味蕾全新的感受吧！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25585/480x360_agrispots-image-rrzkgl3nmuqydmiuvuhvlq.jpg'),
(69, '柿菓子手作烘焙坊', '0963-017-207', '嘉義縣', '番路鄉', '新福村下宅仔8鄰10號', '走進嘉義縣新福村，「柿果子手作烘焙坊」的招牌就在往仁義潭方向的路旁，向人們微笑招手，原來新福村其實是幸福村，富含心意的手作甜點，吃過的人都說讚。\r\n嘉義番路鄉有一大片柿子林，每到秋天柿子將整片山頭染紅非常美麗，烘焙坊老闆張泗沄是第二代田媽媽使用當地盛產的柿子，結合嘉義特產，研發出許多創意甜點。\r\n「柿鳳酥」榮獲2010年嘉義縣嚴選伴手禮，裡面的餡料就結合了番路特產的柿餅和在地的珍珠鳳梨，以手工熬煮的鳳梨果肉與柿餅結合，唇齒間充滿果醬和果肉的濃厚口感。\r\n用疼愛孩子的心情做烘焙，溫柔對待每一樣食材、仔細斟酌味道與份量，「這些點心都是我的小孩。」張泗沄如此說道。\r\n柿果子禮盒\r\n「柿鳳酥」結合了番路特產的柿餅和在地的珍珠鳳梨，手工熬製飽實的鳳梨果肉，讓唇齒間充滿果醬的滑口和果肉的口感。\r\n核桃派\r\n使用當地純正的龍眼花蜂蜜與香、酥、脆的核桃，一改傳統喜餅甜膩 的刻板印象，口感滿分、絕對是回味無窮的好味道。\r\n蛋黃酥\r\n蛋黃酥剖開後，可以看見一層層又鬆、又酥的外皮，裡面是綿密細緻的烏豆沙，其中包裹著恰到好處又不搶戲的鹹蛋黃，口感層次分明。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3717/480x360_柿果子禮盒_0184_L(1).jpg'),
(70, '耄饕客棧', '0933-522-530', '南投縣', '竹山鎮', '延和里安定巷142號1樓', '耄饕客棧隱身在巷弄底，外觀為繞著竹籬笆，進入後會發現是一間充滿創意料理的餐廳。\r\n餐廳結合在地與當令食材，老闆娘喜歡嘗試各種烹飪方法與調味、將懷舊口味創新、賦予食材新的生命、提升田園料理的豐富層次、用味道延續童年記憶，讓客人享受愉快健康的美食體驗。\r\n除了菜單上的料理之外，偶爾會有自家釣的魚出現，餐後還會附上甜蜜蜜的蜜地瓜，為一頓美食畫下句點。\r\n老闆娘表示烹飪是創意，不應受限於做法的拘束，應該尋求無限的可能，以料理寫詩作畫，致力創造記憶最真實珍貴的感官經驗。\r\n雞肉創意料理\r\n雙筍悶三鮮\r\n筍丁打拋肉\r\n蜜地瓜', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25590/480x360_agrispots-image-qqugqieiq0y18xscjhnnsg.jpg'),
(71, '飛鳳傳情米點坊', '03-592-3873 #23', '新竹縣', '芎林鄉', '文山路626號', '飛鳳傳情米點坊是一間位於新竹縣芎林鄉的餐廳，餐廳主打的是客家田媽媽們所製作的道地傳統的客家米食料理，及各式各樣好吃又健康的米點。這裡的食材都是選用在地新鮮的農產品，並透過低油、低鹽、低糖、高纖維的健康料理概念，烹飪出健康美味且具地方特色的田園米食料理。\r\n來到芎林鄉想要品嘗最道地的料理，絕對不能錯過飛鳳傳情米點坊！\r\n客家鹹豬肉\r\n一條條肥瘦剛好的三層肉，用獨特香料醃製而成，退冰後只要用烤箱烤30分鐘，或是直接切片快炒，不需另外調味，馬上就可上桌。\r\n紅燒豬腳\r\n選用優質國產黑豬肉，滷得入味的客家紅燒豬腳，皮和骨頭幾乎分離，充滿膠質的豬皮，包覆著入味的瘦肉，彈牙的口感還帶點嚼勁的香氣。\r\n手工芋圓\r\n真材實料的芋圓每一顆都是手工揉製而成，顆顆飽滿，烹煮後粒粒晶瑩軟Q彈牙滑順口感 ，濃厚芋頭味越嚼越有味。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25716/480x360_agrispots-image-1eoo1tbr6eogkx5cl0hqoq.jpg'),
(72, '桃仔園烘焙坊', '03-336-5597', '桃園市', '桃園區', '新生路165號', '「桃仔園田媽媽烘焙坊」設立於桃園市農會三樓，田媽媽們透過農會的輔導與栽培，不僅在這學會第二專長，更是開班授課找到事業的第二春。「桃仔園田媽媽烘焙坊」採用在地特色原料，強調新鮮純手工製作，將許多道地且傳統的糕餅點心，以最健康且美味的方式呈現到消費者手中，像是過年時祭祖用的菜頭粿、廟會時農民拜拜用的紅麵龜、生日婚禮的慶祝蛋糕等，也有饅頭、瑞士捲、奶油捲等日常小點心。田媽媽們為了提供給消費者最卓越的產品，更是特別聘請日本的野上師傅教學，一同創造出每每一出爐便被販售一空的「秒殺吐司」，烘烤至金黃色、內層鬆軟拉絲，香濃的味道讓人意猶未盡。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25761/480x360_agrispots-image-koowekm--ukdhrjae25hwa.jpg'),
(73, '泰雅風味餐', '03-980-1903', '宜蘭縣', '大同鄉', '松羅村玉蘭巷2號', '田媽媽泰雅風味餐廳是位於宜蘭大同鄉玉蘭部落的一家特色餐廳，主打原住民特色料理並融入現代人的養身概念，堅持使用山上新鮮現摘的季節野菜，調味也都是用天然的調味料為主， 多以馬告（俗稱山胡椒）、打那（俗稱刺蔥）入菜調味。打那雞、山豬肉刈包、馬告香腸都是這裡的特色餐點。\r\n餐廳可以選擇單點或是套餐，如果是素食者也不用擔心，餐廳也提供素食套餐。\r\n第一代「田媽媽」陳美玉不但推廣泰雅美食，還成立西雅諾手工藝坊，教導原住民傳統手工藝，創造社區婦女就業機會，2005年榮獲神農獎。兒子陳智仁退伍後，也加入推廣原住民美食的行列，透過研發各式各樣的料理，讓餐廳的菜單推陳出新，跳脫原住民傳統菜色，打造多樣化創意料理。\r\n打那雞\r\n用刺蔥做醬料然後淋在醉雞身上，再搭配百香果青木瓜，這道菜在夏天是很多饕客最愛的餐點。醉雞Q彈多汁，搭配百香果青木瓜,讓整個味道提升到另一種層次。\r\n山豬肉刈包\r\n早期原住民以刺蔥和珊瑚礁馬告做為食材或是調味料，而這刈包的特色即在於刈包皮是加入刺蔥粉做成；裡面的豬肉則是自家山上養大的山豬，大火快炒之後，夾入刈包皮裡即完成，是原住民的漢堡 。\r\n地瓜昭和葉\r\n地瓜條搭配自採的炸昭和葉（山芹菜），這絕對是在地特色美味料理！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3746/480x360_817A7686_L.jpg'),
(74, '海岸風情', '03-536-4805', '新竹市', '北區', '南寮街 195 號', '「海岸風情」駐足在新竹南寮海岸觀光帶，一眼望去以藍白雙色為主軸的店面非常搶眼，二樓座位可以邊用餐邊近距離欣賞海港風光，是南寮當地老字號的景觀餐廳。店內牆上呼應海岸風情的店名，處處可見海豚、貝殼及珊瑚等，充滿海洋氣息，店內所有的裝潢擺飾像是牆壁上的水彩畫、店內小飾品、門外的彩色木雕，都是田媽媽駱麗美一家人創作的藝術作品。\r\n「海岸風情」套餐內容以當地每日現捕海鮮為主，夏天有小卷、透抽，冬天有烏魚，一年四季供應鯖魚、白鯧，來到這裡別忘了點上店內的招牌餐點「綜合海鮮套餐」、「烤鯖魚套餐」，不吃海鮮的朋友可以點「宮保雞丁套餐」，套餐配菜更多達五種，均衡的營養健康，吃得到媽媽細心料理的溫暖。飯後還有以鯛魚為造型的「紅豆麻糬鯛魚燒」，多元化的選擇讓大家都能滿足口腹之慾。\r\n海岸風情田媽媽\r\n烤鯖魚套餐\r\n紅豆麻糬鯛魚燒', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25718/480x360_agrispots-image-dwvzqekn8eaya_rqxrn1ca.jpg'),
(75, '海景蜂鍋物(原 海景咖啡簡餐)', '02-2499-2073', '新北市', '貢寮區', '福隆村東興街6之19號', '海景咖啡簡餐\r\n沿著濱海公路101K往福隆漁港方向走，沿途是美麗的東北角海岸，炎炎夏日陽光下來參加沙雕季活動，一邊享受冰涼海水，一邊考驗體力的鐵馬行。\r\n忙碌的心情想要放鬆舒緩，找個地方舒服地看海喝咖啡，移動您的腳步走進位於福隆漁港旁的「海景咖啡簡餐」。這裡由張思淑帶領著一群年輕活潑的田媽媽們，堅持使用本地食材，變化出海鮮簡餐料理。\r\n簡餐主打料理「透抽雙吃」的主角是從澳底漁港捕來的漁獲，除了清燙過後肉質飽滿Q彈(佐上自製五味醬)，還有田媽媽研發的歐式焗烤口味組合雙吃料哩，香脆滋味難以言喻！\r\n以及那入口綿密的「山藥」，是來自貢寮山區的農友伯伯栽種，完全不灑農藥，採用天然的有機肥栽種出來的山藥外型雖不起眼，卻是健康養生的至寶。田媽媽們運用有機山藥搭配當地時令蔬菜或海鮮，推出可葷可素的「山藥養生火鍋」，秉持低油、低鹽、低糖、高纖維「三低一高的理念」，把健康養生的料理推薦給大家。\r\n餐後所附上的手工石花凍並淋上田媽媽自製的檸檬汁，真是清涼消暑的一道甜點，田媽媽還把甜點加入了冰拿鐵，組合成「漁村冰咖啡」，這樣的搭配吃的到海洋的感覺。\r\n \r\n水果鬆餅\r\n透抽雙吃\r\n附餐甜點(石花凍)\r\n季節火鍋\r\n \r\n季節水果茶', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3754/480x360_43012b3bb1384896b74eda9b955f1c01.jpg'),
(76, '烘焙西點米食坊', '03-732-0530', '苗栗縣', '苗栗市', '玉清里11鄰復興路四段197號', '苗栗市農會田媽媽米食烘焙坊於民國95年設立，原先以提供家政班教學為初衷，民國102年時決定落實田媽媽米食烘焙坊，並以苗栗著名的2號米為主原料，致力於推廣在地特色稻米。\r\n田媽媽將稻米轉化成米穀粉，並以此為配方研製米蛋糕、米吐司等等，由於米穀粉所製成的麵包較難延展塑型，因此田媽媽從煮米、發酵時間、烘焙時間等環節上反覆操作，終於研發出外觀漂亮、口感香綿蓬鬆的米蛋糕，打破大眾對傳統米蛋糕的框架。除了提供美味的烘焙製品，田媽媽更是扮演起食安源頭的重要把關人員，不添加過多的膠體、泡打粉，提供消費者安全、健康的食品選擇。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25714/480x360_agrispots-image-3v_3yb9xnkesooubxpe9ig.jpg'),
(77, '神仙的窩', '02-2496-5363', '新北市', '瑞芳區', '龍潭里逢甲路39號', '神仙的窩\r\n雙溪的山藥是神仙的食物。野生山藥切開後非常濃稠，裡面富含黏蛋白跟消化酵素，不但幫助消化、是很好的健康食品。「基隆山藥」是世界排名第二名的原生種山藥，因為產量少、價格高，缺乏市場競爭力，瑞芳區農會協助農民開發山藥點心，民國91年成立田媽媽，把山藥點心推廣給更多民眾，改善農民生活。\r\n山藥饅頭、山藥土司\r\n山藥饅頭、山藥粿、山藥土司、山藥銅鑼燒等十多種品項，打響瑞芳區農會山藥點心的名號。白白胖胖的「牛奶山藥饅頭」。另外以山藥、南瓜子、枸杞打入麵糰揉製成的「金黃饅頭」口感Q軟帶勁、層次分明，是健康養生的新選擇。\r\n▲山藥饅頭 \r\n▲山藥土司 \r\n山藥銅鑼燒、山藥粿\r\n「山藥銅鑼燒」是另一項主打點心，煎到金黃鬆軟的麵皮中夾進綿密的山藥餡。「山藥粿」將在來米粉中加入山藥、紅蘿蔔、臘肉或素火腿，用傳統炊粿手法製作而成，看得到一塊塊白色山藥，吃起來鬆軟清香，是山藥鹹點的代表作。\r\n▲山藥銅鑼燒 \r\n▲山藥粿 \r\n野薑花粽\r\n「野薑花粽」純天然香料完全不添加人工香精，蒸過的粽子一打開就聞到濃濃野薑花的香氣。常態生產十多種山藥應景點心，端午節的山藥養生粽、中秋節的山藥酥、元宵和冬至的山藥湯圓、過年期間的山藥八寶年糕、山藥紅麴發糕，都是田媽媽們的山藥用心之作，「山藥專家」實至名歸。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/491/480x360_28ec6a07759a4116b01b2043db0d91b8.jpg'),
(78, '神雕邨複合式茶棧', '03-787-5858', '苗栗縣', '三義鄉', '廣盛村廣聲新城2巷26號', '「邨」是「村」的古字，民國84年三義木雕博物館開館，沿途兩條木雕街有各家師傅展現神 乎奇技的木雕工法，因此這裡被稱之為「神雕」邨。當年客人的一 句玩笑話：「這裡全是木 雕店家，沒有餐廳，難道大家都吃木頭嗎？」讓性格豪爽的阿雪媽媽，決定打頭陣開餐廳，主 打擂茶、簡餐和農特產，後來轉型成複合式餐廳。\r\n阿雪媽媽是彰化的閩南人，個性開朗、喜愛與人交流。婚前不會做菜的她當了客家媳婦後，跟 著婆婆學習做客家菜，她說：「客家人吃鹹不吃甜、菜餚裡鮮少放糖，也因為客家人大部分住山城裡，到平地取貨不易，因此客家媽媽們都發展出一套自給自足的本領，自製蘿蔔乾、梅乾菜、桔醬等。」來這裡用餐經濟實惠，可視人數調整餐點份量，梅干扣肉、薑絲大腸、客家小炒、蘿蔔乾豬肉湯，都是道地的客家美味；菜餚可會依據季節變化，炒桂竹筍、鹹蛋苦瓜都是開胃下飯的好選擇。\r\n此外還可以來這裡體驗客家擂茶。阿雪媽媽說，古早時代擂茶是某種身分象徵，家裡經濟條件不錯才有多餘穀物可以曬乾、擂茶。阿雪媽媽 說，閩南人「泡」茶 葉，客家人「磨」茶 葉。「客家擂 茶」將茶葉、堅果和穀物依照順序 磨成細粉，產生熱氣將食物磨成黏稠狀，再用湯匙從大缽上把它們刮下來、以熱水沖泡後飲 用。現在擂茶已成為大眾皆知的客家精神代表，早晨起來喝上一 杯，堅果和米香的香氣在鼻 腔久久不散，精神充沛。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25700/480x360_agrispots-image-v27hkczalkysxh0lnzjiyq.jpg'),
(79, '秘密花園', '03-792-3029', '苗栗縣', '西湖鄉', '金獅村9鄰6之1號', '祕密花園景觀餐廳位於苗栗山中，四周都被森林環抱著，園區內的制高點有一棟紅磚砌成的復古小屋就是餐廳了，餐廳內樸實的裝潢，讓人身心都放鬆了起來。\r\n「秘密花園」的料理都是選用當季在地食材，融入客家飲食文化，其中迷迭雞腿、客家醬鴨、香茅東坡、迷迭宮保雞丁等多項料理，都是推薦必吃料理，飯後甜點都是田媽媽手工製作，會因季節變化而有不同。\r\n廣大的園區內種植多種花卉，用餐後可在園區散步欣賞山林景觀，如果喜歡享受山林環繞的氛圍，園區內還有露營區，可以安排在這裡夜宿一晚，尤其在柚花盛開時，與花香共眠，更是難得的體驗。\r\n復古的紅磚餐廳。\r\n紅色課桌椅是眺望山景VIP位置，也是遊客必打卡拍照的景點。\r\n翡冷翠\r\n充滿淡淡水果清香的沙梨橄欖，爽口又帶脆度，讓人難以停手。沙梨橄欖有季節性，餐廳用的是園區內無農藥的橄欖，新鮮採收後所製成的。\r\n荷葉飯\r\n當荷葉打開時，熱氣中帶著一股淡而清香的荷葉味。飯中有花生、蓮子和香菇等食材，看似粽子包料，但是嘗起來口感卻不同，原來秘密武器就是芝麻，它為荷葉飯增添風味、好吃極了！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25702/480x360_agrispots-image-68co-z9y0eaf_utszw2jsw.jpg'),
(80, '麻芛糕餅工作坊(林金生香)', '04-2389-9857', '臺中市', '南屯區', '萬和路一段59號', '麻芛是黃麻的嫩葉，主要產區在台中南屯，當地老一輩的人夏天煮麻芛湯，清火消暑。台中南屯的老街上，一家傳承百年的老字號餅店「林金生香」，同時也是田媽媽「麻芛糕餅工作坊」的所在地。\r\n田媽媽陳富美回憶起林家糕餅的百年大業，第一代以製麵開啟了麵點類美食的大門。第二代林阿塗以麵龜及各式糕餅奠定家族事業的基礎；傳承到陳富美手上已是第四代，以麻芛為主題成功創造出台中代表性地方美食。她說：「吃的事業是良心事業，我們產品的顏色全來自原料麻芛，非添加色素；用料實在、堅持手工古法製作，才能奠定百年老店的地位。」\r\n要將麻芛融入進糕點中，最麻煩的是去除苦味這道程序，以手工去梗留葉、再在畚箕上不斷搓揉、洗淨苦水後才可以使用。富美媽媽研究多時，在太陽餅的麥芽糖餡中加入乾燥打碎的麻芛粉，讓麥芽平衡了它的苦味，吃起來甜而不膩、不苦。\r\n加入麻芛的狀元糕切開後質感綿細、滋味紮實，入口後微微的甘中帶苦，吞入喉順口清香，是非常適合配茶的點心，在考季和節慶時是最常缺貨的明星商品。\r\n以萬和宮為中心的南屯老街是全台中市最老的街道，這裡的土角厝和紅磚牆讓人彷彿進入時光隧道，有濃濃的古早味氣息。目前堂堂邁入第五代百年老店，堅持口味不變，成功結合台中地方特產，希望跟著南屯老街的發展，讓年輕人認識這個傳統滋味。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25655/480x360_agrispots-image-9uhzht-rc0ewwzp2ylfcgg.jpg'),
(81, '心蓮蕊養生餐坊', '03-882-1873', '花蓮縣', '富里鄉', '羅山村9鄰7號', '田媽媽養生餐坊位於花蓮富里鄉的羅山村入口處。羅山村是國內第一個有機農業村，田媽媽採用自家農園栽種的有機蔬果與稻米，以及農會的火山豆腐與羅山村特有的放山雞等，變化出各式各樣養身健康的美食。\r\n自家蓮花池的蓮花不僅可供觀賞，用餐時每桌都會泡上一壺天然的蓮花茶提供客人品嘗，餐廳還將蓮花煮成「蓮花養身湯」清熱解膩；另外每天現採荷葉包成的「荷葉飯」香氣四溢，養身餐坊希望讓客人吃到樸實自然的客家味。\r\n羅山村也發展出獨特的農村旅遊，這裡還可以體驗製作火山豆腐、富麗米炒米香DIY，品嘗產自當地的有機米、洗愛玉等，來一趟有機村生態之旅，體驗純樸農村風味！\r\n荷葉飯\r\n使用每天現採的新鮮荷葉，包裹蒸煮的荷葉飯，米飯軟Ｑ有著荷葉清香，加入炒香瘦肉丁，色香味俱全。\r\n蓮花雞湯\r\n清熱解膩的蓮花加上紅棗跟枸杞，提升雞湯甜味，美味又養生。\r\n梅干扣肉\r\n這道傳統客家菜，自家曬製的梅乾菜與滷到軟Q的三層肉，一口梅干菜與加上三層肉，搭配富里自產的白米飯，實在是絕配。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3793/480x360_kito-16.jpg'),
(82, '富麗禾風', '03-882-1705', '花蓮縣', '富里鄉', '羅山村9鄰東湖9號', '花蓮縣的富里鄉恰好是花東縱谷旅遊的中繼站，空氣清新、水質良好，這裡所生產的「富麗米」與池上米和關山米齊名。\r\n富麗禾風位於台9線道旁，餐廳位置於「富里鄉農會農特產品展售中心」二樓，一群熱愛家鄉的在地田媽媽們，為了讓南來北往的遊客可以品嘗當地美食，特別推出具有代表性的「便當」，「便當」原本是在地人在農忙的時候最方便吃食的午餐，希望透過物美價廉的農村便當來推廣好吃的米食。\r\n田媽媽們選用富里當地種植的蔬菜，依季節性將配菜做調整，滷蛋、香腸、豆乾、酸菜、青菜、醬瓜、炸肉、麵圈全都是自製，每天新鮮現做，吃得到食材原味。濃濃的滷汁香配上香Ｑ的米飯，讓便當美味又健康。\r\n餐廳內空間寬敞宜人、窗外景觀可看見大片綠油油的稻田、花東縱谷景色盡收眼底，除了提供各式富麗米便當，若是團體客人，還可以預約這裡的風味餐合菜，各式豐富菜色是在地田媽媽們一直致力於找尋記憶中的家鄉味。\r\n梅干扣肉\r\n自家曬製的梅乾菜與滷到Q彈滑潤的三層肉，梅干菜搭上三層肉，可以吃上好幾碗富麗米煮成的白米飯。\r\n梅干水餃\r\n特別的梅乾水餃，採用自家曬成的梅干菜搭配國產豬肉，嘗起來鮮甜多汁。\r\n胡椒肚湯\r\n這道可以暖胃驅寒的湯品，非常適合天冷時來上一碗。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/502/480x360_7da4fa5b35744a968961498a491452dc.jpg'),
(83, '東勢林場森林咖啡屋', '04-2587-2191', '臺中市', '中區', '勢林街6之1號', '東勢林場號稱「中部的陽明山」，是一片占地225公頃的森林花園，開在其中的「森林咖啡屋」被一整片廣袤樹林包圍，放眼望去樹樹相連，綠意一路迤邐到天際，是都市人最奢侈的享受。\r\n春櫻、夏桐、秋楓、冬梅四大主題，還有螢火蟲季、鳥類、蛙類等生態活動，讓東勢林場一年四季都是前來感受自然樂趣的好時機。\r\n林場內的「東勢林場森林咖啡屋」，結合咖啡香與自然美景，讓漫步在森林裡的遊客有一個 輕鬆歇腳的好所在。這裡提供主廚精緻套餐和下午茶點心，嚴選在地當季食材，菜色融入園區有機栽種的香草植物，為料理妝點淡雅風味。歡迎來這裡悠閒地享受下午茶，沏一壺香草養生茶品，搭配現做精緻點心，讓身心靈放鬆消除都市生活的緊張壓力。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25594/480x360_agrispots-image-ppjbgmk9bu2ebjkqtqndsa.jpg'),
(84, '蛤仔輝漁產料理', '05-698-4911', '雲林縣', '斗南鎮', '台西鄉五港村五港路428號之1', '雲林台西是蛤仔的故鄉，自民國六十年開始發展養殖漁業，現在是台灣文蛤養殖量最大的區域，在台西五條港安西府旁隱藏了一家美食蛤仔輝特產中心，喜愛吃蚵仔朋友有機會一定要來一趟。\r\n田爸爸林江輝在父親過世後回鄉接手家裡的養殖工作，跟太太林祝妃運用家裡養殖的文蛤、鹹水蝦、虱目魚和鮮蚵產品加工，累積心血、建立起台西海口小吃的風味。因為醃製文蛤出名，被好友們取名「蛤仔輝」的綽號，成為店裡的活招牌。\r\n特產中心最出名的「蚵仔湯包」在網路上被封為天下第一鮮，採用自家養殖的新鮮文蛤土砂清洗後，用蒸汽萃取原汁和新鮮豬肉、蔬菜加工攪拌製成，不加一滴水、鹽巴、味素，完全由文蛤萃取的原汁代替，這過程都是經過高溫蒸煮後，急速冷凍安全衛生，完全將大海的鮮甜的美味鎖在湯包中！麵皮用蔬菜、地瓜和在來米漿調製而成，口感清爽鮮美、不油膩。除了在店內品嚐也可訂購冷凍湯包，以高溫蒸煮後再急速冷卻、確保安全衛生。\r\n推薦愛吃蚵仔朋友絕不能錯過外型貌似日式蛋包飯的「蚵仔蛋包」，上桌後將薄嫩的蛋包切開、蚵仔滿溢出來、粒粒飽滿紮實、不糊爛，份量十足有誠意，吃過的人都讚不絕口。\r\n台西一帶的文蛤多採混養方式，將混養文蛤魚塭裡的鹹水虱目魚加工變化，以70：30的比例與新鮮豬肉調製而成「虱目魚香腸」保證無刺、爽脆、彈口；還有處理好、經過簡單調味的虱目魚肚，都是台西的人氣伴手禮。\r\n蚵仔蛋包\r\n蚵仔湯包\r\n煎虱目魚', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3815/480x360_kito-50(3).jpg'),
(85, '陽光水棧', '04-893-3323', '彰化縣', '芳苑鄉', '王功村漁港六路38號', '彰化王功漁港地區在潮間帶養殖蚵仔，漲潮時蚵仔浸泡在海水裡，退潮時受到陽光照射，蚵仔生長速度較慢、個頭小、蚵仔肚Q，擁有「珍珠蚵」的美稱。田媽媽洪金釵為了提供給客人各 式更好的魚蝦海鮮料理，運用在地食材研究出多種蚵仔吃法。\r\n體驗活動\r\n坐採蚵車體驗採蚵趣、潮間帶行程-王功漁港含有豐富的潮間帶生態及大量蚵田，環境也備受保護，不受汙染，為了讓旅客更加了解在地特色，特別與當地的蚵農合作，提供下海體驗潮間帶行程（因潮汐之故須事先預約）。\r\n遊覽景點\r\n芳苑燈塔、王者之弓景觀橋、潮間帶、王功漁港、風力景觀\r\n建議遊程\r\n坐採蚵車體驗採蚵趣、潮間帶行程-王功漁港含有豐富的潮間帶生態及大量蚵田，環境也備受保護，不受汙染，為了讓旅客更加了解在地特色，特別與當地的蚵農合作，提供下海體驗潮間帶行程（因潮汐之故須事先預約）。\r\n在地美食\r\n鮮蚵pizza、黃金煎麵線、麻香鮮蚵麵線\r\n伴手禮與農特產\r\n王功&quot;珍珠蚵&quot;\r\n認真的料理最美味\r\n認真對待每一份料理，讓每一位到訪的客人嚐到美味的在地料理，留下難忘的美食記憶。 \r\n網美打卡必選之地\r\n「陽光水棧」位於王功漁港旁，是一棟醒目的地中海式風格的藍白色建築，前身曾是養殖池，洪金釵與先生一磚一瓦 打造出這間夢幻小屋，順著青綠色的草皮和石板走進來，彷彿進入另一個國度。 \r\n優雅的用餐環境\r\n鮮蚵pizza\r\n陽光水棧招牌菜之一鮮蚵煎披薩榮獲103年田媽媽十大招牌菜。 \r\n用麻油炒出新鮮文蛤甜份的「松坂文蛤」，襯托出松坂豬肉軟嫩的口感，香氣在口中久久不散；貴妃魚則是一道吃法豐富的料理，原產於澳洲的銀鱸，特色是有豐富的膠原蛋白，多年前引進台灣後加入海水養殖，肉質甜美，新鮮的貴妃魚肉質Q脆，做成生魚片、煮湯，各有不同滋味。 \r\n以芳苑的麻油搭二林蕎麥麵線加上王功在地的珍珠蚵。 \r\n王功漁港含有豐富的潮間帶生態及大量蚵田，環境也備受保護，不受汙染，為了讓旅客更加了解在地特色，特別與當地的蚵農合作，提供下海體驗潮間帶行程（因潮汐之故須事先預約）。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3827/480x360_86eybba3vf4k59nvr7bm1xjg65f93ity.jpg'),
(86, '新屋庄米點烘焙坊', '03-4772124#503', '桃園市', '新屋區', '中華路242號', '桃園新屋是北台灣最大的稻米產區，且留有七棟歷史將近百年的老穀倉，「新屋庄米點烘焙坊」就位於在其中，這間獨特的烘焙坊是由一群認真活潑的田媽媽所經營，為推廣當地的稻米，選用在地優良稻米製成的米穀粉，研發出各式各樣米點心。\r\n田媽媽們在製作米點心時降低小麥粉使用，加入了當地地農民所生產的稻米，讓容易麩質過敏的人可以吃到好麵包與甜點。而且米穀粉做成的米點心吃了會比較有飽足感又同時減少熱量攝取。\r\n所生產麵包採用低溫老麵發酵，為了堅持品質與口感，每一個產品都是田媽媽們手工製作產量有限，為讓每位顧客能品嚐到最好的產品及預防買不到，建議先訂購才不會沒買到。\r\n米戚風蛋糕\r\n輕盈柔軟的米戚風蛋糕，猶如雲朵般的綿軟口感在嘴裡化開，帶點一絲絲的米香味，每一口都有食材的天然滋味。\r\n土司\r\n純手工製作的湯種土司，軟綿又富彈性的口感，讓您吃了還想再吃，適合當作大人小孩的早餐或及點心。\r\n養生饅頭\r\n手工揉製的饅頭口感扎實、用料實在，每一口都咬的到餡料，健康又營養。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/512/480x360_b29b4d9586bd43f6842248d8b4f32531.jpg'),
(87, '新埔田媽媽特有餐飲美食坊', '03-589-1658', '新竹縣', '新埔鎮', '四座里楊新路一段 322 號', '新竹縣新埔鎮是有名的客家聚落，盛產楊梅、紅李、柿乾、茂谷柑。「新埔鎮農會特有餐飲美食坊」坐落在一大片綠油油的稻田旁，餐廳舒適明亮，窗外風景看過去可見美麗的田園風光及在地小農的菜園，有別於一般塵囂喧擾的用餐環境。\r\n客人一到，熱情的田媽媽們就拿出自家醃製的陳年老菜脯、花瓜和改良式水果韓式泡菜，讓客人解饞開胃，為即將上桌的客家料理揭開序幕，餐廳以在地季節性食材，讓客人現點後進行料理，客人也可以預約辦桌宴席，這裡的主廚們秉持著尊重食材原形的烹調方式，讓客人吃到新鮮、美味與健康。\r\n詹莊双阿嬤是有五十年經驗的田媽媽，他遵循古法醃製的老菜脯有退火、降血糖、降血壓的 功能，除了炒菜還可以燉雞湯、包粽子。老菜脯入口時，有一 點鹹、尾韻回甘。詹阿嬤自豪的還有改良式水果韓式泡菜，用南瓜、蘋果、檸檬、鳳梨等蔬果自然發酵，完全不含防腐劑，微酸辣的味道裡蘊藏自然水果甜味。\r\n明亮整潔的用餐環境\r\n梅干扣肉\r\n香氣十足的梅干菜，搭配滷得軟嫩入味的五花肉，醬汁鹹香拌飯也很剛好。\r\n悶筍控肉\r\n悶筍與控肉的組合是一道兼具美味與健康的料理，箭筍是維質頗高的食蔬，口感清爽，可去除控肉的油膩感。\r\n客家小炒\r\n客家小炒是店內十分受歡迎的菜餚，鹹香的豬肉、豆干、帶有咬勁的乾魷魚，搭配恰到好處的醬油調味，令人百吃不厭。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25709/480x360_agrispots-image-srwi_7rl6kwjdmiqncztuw.jpg'),
(88, '新農食品加工坊', '04-2581-1511#271', '臺中市', '新社區', '新社里中和街四段228號', '由新社農會成立的新農食品加工坊位於台中市新社區，透過田媽媽們高超的手藝結合在地新鮮食材，純手工製作，深受當地民眾喜愛。其中「杏鮑菇泡菜」是這裡的招牌明星伴手，採用新社區特產帶有淡淡杏仁香味的有機杏鮑菇，並將市場上賣向不好的杏鮑菇經由田媽媽們手工切片，再加上韓式的調味醬汁做成Q彈多汁、令人回味無窮的杏鮑菇泡菜，每一口都能吃到驚艷無比的好滋味，非常開胃下飯。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25595/480x360_agrispots-image-yi7s5opuleqgyqp5kwnriq.jpg'),
(89, '農特產水果酥烘焙坊', '06-578-3649', '臺南市', '山上區', '南洲里6號(山上區農會供銷部)', '台南山上區農會田媽媽烘焙坊於11年前成立，台南山上區盛產多種水果當初是為了解決當地水果產銷的問題，而研發製作水果酥，因為存手工製作，料好實在，且秉持著田媽媽料理精神，運用在地食材，少鹽、少油、少糖、高纖等原則，讓客人吃沒有負擔，因此讓吃過的民眾口二相傳，創造好口碑，打響了知名度。\r\n農會內15位在地田媽媽們利用農事閒暇，以在地水果，手工製做各式點心，除了招牌好口碑的鳳梨酥外，田媽媽還陸續研發桑椹和芒果酥，同樣獲得好評，是春節、端午、中秋三節熱門的伴手禮，因為手工製作，生產數量有限，需要事先預訂。\r\n愛i鳳醬\r\n遵循著傳統方法釀製而成鳳梨漬，酸甜的滋味，是簡單上菜的好幫手，除配飯直接吃之外，也可以用於煮湯、炒菜等各種料理。\r\n鳳梨酥\r\n以在地新鮮鳳梨為原料，由田媽媽班員們手工精製，為山上區農會老字號的旗艦伴手禮，推出至今一直深受民眾喜愛。\r\n無糖芒果乾\r\n愛文芒果香氣濃郁、肉質細緻且纖維少。烘製過程不添加色素與防腐劑，保留芒果的香氣，讓你客人吃得健康無負擔。\r\n綜合水果酥禮盒\r\n山上區農會自產的系列水果酥，堅持以手工製作，內餡取自台南在地知名水果，包含玉井芒果、麻豆文旦，以及鳳梨、桑椹等，值得您嚐一嚐！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25815/480x360_agrispots-image-a9n8jtukte6bhqlwjlc_eq.jpg'),
(90, '達基力部落屋', '038621033', '花蓮縣', '秀林鄉', '崇德村96號', '位於花蓮縣秀林鄉「達基力部落屋」鄰近太魯閣，從蘇花公路沿台9線往崇德方向，在山腳下有兩根原住民圖騰木雕，轉進山上彷彿進入一座原始叢林的後花園，部落屋就位於此處，「達基力」是很多石頭的意思，用原木與竹林搭建出戶外用餐的空間，可遠眺海洋相當舒適。\r\n「Embiyax Su Hug」是太魯閣族打招呼的問候語，田媽媽彭秀蘭以親切的笑容與客人互打招呼，25年來，她用心經營原住民風味餐的成果備受肯定，國內許多重要單位介紹外賓體驗台灣原住民美食，第一站都會到這裡。\r\n這裡沒有固定菜單，食材多來自於家中三分地中種出來的野菜，隨手可摘野生番茄、南瓜、番龍眼、龍葵、湯匙花，7、8月香蕉樹結實纍纍時還可以成串帶去餐廳跟客人一起享用，秀蘭媽媽希望讓大家知道原住民食材的美味，所烹調的刺蔥鯛魚、牧草心炒時蔬、原味黑毛豬烤肉都是她的私房菜，其中「八寶野菜」可以吃到野生竹筍、麵包果籽、龍葵、木鱉子等外面少見的野菜，是原住民野菜一家親的代表作。\r\n用漂流木改造成的桌椅、切菜板、盛菜用的木盤，全出自於田爸爸~郭文貴老師之手，用餐環境中聞得出淡淡的檜木香，除了用餐還有許多原住民的活動體驗與文創藝術可以參與，例如：石頭彩繪、木雕的手作課程等體驗太魯閣族的文化內涵。\r\n部落屋旁到處都有花草植物，綠意盎然，順著步道往上走有一顆40多年的老樟樹，沿著海岸山脈旁邊就是太魯閣國家公園，這裡的農地完全是原生態，沒有外來種，簡直像是世外桃源。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/516/480x360_nk7zz9apmerriay2fntctnwcq1m055tv.jpg'),
(91, '夢田食堂', '03-950-3190', '宜蘭縣', '五結鄉', '孝威村孝威路402號', '夢田食堂位於五結鄉農會夢田觀光米廠內，「夢田觀光米廠」係由原宜蘭縣五結鄉農會孝威穀倉轉型而來，其原為「蘭陽五農米」加工儲存中心，是北台灣乾燥量最大的糧倉貯藏中心之一。現今「夢田觀光米廠」以食農教育方式讓民眾以有趣生動的方式來認識米飯的出處，米廠二樓設置「夢田食堂」米食推廣教室，在食堂內，遊客可初步了解稻米的生長過程，現場活動中也包含了DIY體驗碾米及自己動手做米漢堡、肉粽、粿&hellip;等米食，並且提供米類相關伴手禮供遊客選購。\r\n「夢田越光米粽」將晶瑩剔透的越光米與糯米以黃金比例揉合，口感Q潤柔綿，清爽順口；內餡包裹的胛心肉瘦而不柴，嚼感十足，金黃鹹鴨蛋黃，一口咬下濃郁香醇。\r\n「夢田米菓」以五結鄉農會契作生產之糙米為原料，經高壓高溫擠壓自然膨發而成。產品天然無添加，香脆可口。\r\n「夢田米麩」以全榖物製作，無添加防腐劑', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3859/480x360_0P7A6629.jpg'),
(92, '福農食坊', '04-784-1517', '彰化縣', '福興鄉', '橋頭村復興路28號', '福興鄉農會在農委會的輔導下成立了田媽媽福農食坊，以福興鄉的特產長糯米為主軸並搭配田媽媽們的好手藝，將福興鄉具高品質、安全、光澤亮麗及口感甘黏等富含多種特色的長糯米推廣給遊客，另聘美食專家技術傳承，教學指導鄉內田媽媽們，將特色糯米結合粽葉與獨特内餡，包出粽葉飄香，『福』氣『興』隆的的「福粽」。田媽媽福農食坊的肉粽食材皆採用在地優良新鮮食材，像是新社香菇、北港花生、自製豬油與滷製三層肉等等，糯米也必須經過獨家熬製的滷汁和自製的油蔥酥一起拌炒爆香，再加上傳統紅土鹹鴨蛋一起料理，增加鹹香口感，最後放入壓力鍋用水燉煮至米軟爛卻不失Q度與嚼勁，每一顆肉粽都經過層層把關，不容錯過每一個小細節，致力於呈現出色香味俱全的福粽，每一口都能吃到真材實料滿滿的內餡，層次豐富的口感更是讓人難以忘懷。\r\n福粽\r\n福興長糯米油飯', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3869/480x360_7nwtzs21hvd5trrggcdjt3x304qg8a6c.jpg'),
(93, '臺江美食棧', '06-284-2427', '臺南市', '南區', '安四草里大眾路360-6號', '田媽媽『臺江美食棧』位在臺江生態文化園區的四草紅樹林旁，入口有許多花草植栽，綠意盎然。\r\n臺江地區盛產鮮蚵、虱目魚，產量居全台之冠，還有草蝦、台灣鯛等優質養殖漁獲，餐廳主人也擁有自己的魚塭，所以堅持使用最新鮮的在地食材，還可依照客人需求進行不同的烹調料理，提前預訂有機會品嚐到老闆的隱藏版料理美食。\r\n餐廳特色就是新鮮，選用當地當季的新鮮食材，以在地特色料理方式烹調，讓客人享用美味又健康的餐飲。\r\n虱目魚肚\r\n虱目魚肚油脂豐厚，魚刺少，是虱目魚的精華部位，最受歡迎的料理方式之一即是乾煎虱目魚肚，外皮煎至酥脆，魚肉則是鮮嫩多汁，豐富的魚肚油脂入口即化口，不禁令人食指大動。\r\n虱目魚皮\r\n虱目魚皮表面經過微煎後， Q彈的虱目魚皮， 香氣四溢，富有滿滿的膠質與營養, 是天然的養顏美容聖品。\r\n虱目魚香腸\r\n有別於一般香腸的油膩，以新鮮虱目魚為內餡的虱目魚香腸，沒有魚腥味，吃起來的肉質也比純豬肉香腸更細密，味道更香甜。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3872/480x360_虱目魚肚_3040_L.jpg'),
(94, '蓉貽健康工作坊', '04-2535-3748', '臺中市', '潭子區', '中山路三段275巷47號', '熱愛烹飪的莊姿儀媽媽原本做便當生意，加入田媽媽後成立蓉貽健康工作坊，田媽媽莊姿儀說：「我們的食品先要求產品完善、再添加熱情進去；講究新鮮手工，希望讓更多年輕人認識在地食材與推廣健康養身的概念。」\r\n為了健康，自小阿嬤就會煮益母草汁給田媽媽喝，在明代的本草綱目中記載：「益母草氣味苦澀，有婦科疾病和美容養生之功效」，想要發揚阿嬷教授的料理與技術，莊姿儀媽媽，創新益母草的使用，將益母草曬乾後熬做滷汁，花一個多月時間調整口味，推出益母草鐵蛋、豆乾等滷味，成成為兼具美味與健康的食品。\r\n酵素泡菜，也是歷經多次試驗，最後以蘋果作為酵素的主食材，因為它含水量少，製作泡菜不易失敗，而山東大白菜是製作泡菜的最佳食材，因為夠脆且高纖，蔬菜紋路清晰漂亮不易腐爛，再加上洋蔥天然的甜味，另外用紅蘿蔔磨成泥替代紅辣椒的顏色，並以青蔥提升泡菜的香氣與色澤，調配出最健康又符合國人口味的酵素泡菜！\r\n益母草鐵蛋、豆乾，酵素泡菜以及客家鹹豬肉等，都是來到工作坊必買的伴手禮，別忘了帶回家與家人親友一起分享。\r\n蓉貽健康工作坊一路秉持著「健康、創新、美味」的理念，致力研發農村好味，期待以素樸初心，透過餐桌滋養生活，讓田園風味陶冶心神。\r\n \r\n益母草鐵蛋\r\n酵素泡菜\r\n酵素泡菜：使用蔬果低溫自然發酵，口感清脆、微辣清甜，適合製作料理，如：主食(韓式蓋飯、泡菜涼麵、辣味炒烏龍)、煲湯(海鮮冬粉、什錦火鍋)、燒烤、涼拌。\r\n手作鹹豬肉\r\n將優質胡椒磨成細粒後，低鈉鹽醃，不鹹的軟嫩口感，適合煎煮烤蒸。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25628/480x360_agrispots-image-tya-p2w4lkojtuoysce98a.jpg'),
(95, '劉員外傳統米食餐點', '04-2683-2197', '臺中市', '外埔區', '六分路280巷8號', '外埔區「田媽媽劉員外米食餐點」是由農會家政班班長劉黃碧霞與班員共同經營，取名「劉員外」是因為劉黃碧霞的先生之祖父早期是新竹地區的客家望族，由新竹遷徙到外埔置產定居時人人都稱呼他為「劉員外」，代代相傳所以順期自然地就取名為「劉員外米食餐點」。\r\n「田媽媽劉員外米食餐點」利用外埔區所生產的高品質的良米，製作多種具有古早味特色的鄉點米食。而且強調所使用的原料是完全天食材的色素，保證不含化學色素，就是要讓客人吃得安心又健康。\r\n餡多材料實在、口味獨特的特色米食點心，常吸引許多外地遊客不遠千里前來品嚐，也常提供喜慶、外燴、各單位辦活動的伴手禮，歡迎電話訂購。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25632/480x360_agrispots-image-f-w0czffvkqegt4q00ipxw.jpg'),
(96, '龍門口餐廳', '03-782-2829', '苗栗縣', '南庄鄉', '獅山村15鄰165號', '龍門口餐廳位於苗栗南庄，餐廳外相當開闊停車方便，有大庭院與涼亭，一到這裡讓人整個心情開闊起來。\r\n餐廳主打客家料理，由幾位手藝精湛的媽媽們所組成，一起努力三十多年讓餐廳的餐點豐富有特色， 平日的南庄遊客並不多，媽媽們也沒閒著，一早就去田裡照顧蔬果、摘摘野菜，就是餐廳裡吃得到最簡單而鮮美的山蔬。\r\n媽媽們各自分工，負責炒菜的媽媽可以將客家小炒、鳳梨炒木耳炒出客家本色；負責燉煮的媽媽所料理的客家炆筍，用的是本地的桂竹筍，口口吃得到竹筍的鮮甜，最近媽媽們也開始賣起了古早味的柴燒仙草茶，把這傳承了多年單純的好滋味，分享給來店裡的客人。\r\n來到店裡必點的推薦菜餚有南瓜飯將飯與南瓜一起燉煮，南瓜的甜味融入白米中，吃起來有一點像燉飯的感覺，可以同時吃到南瓜與米飯的香甜；花生豆腐相當特別嘗起來有奶酪的口感，淡淡的花生香味拌上帶有鹹味的客家碎肉香菇醬，口味非常獨特；紅麴排骨採用自家釀製的紅麴醃製再行烹調，帶有芳香的紅麴氣味，口味不會太重，香香鹹鹹的很下飯。\r\n餐廳秉持著使用當地當季的食材，採用少鹽少油的健康烹煮，菜餚不油不膩，有機會來到南庄，歡迎來品嘗改良式的客家特色佳餚。\r\n南瓜飯\r\n花生豆腐\r\n紅麴排骨', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25641/480x360_agrispots-image-ymxpnscjiuot94g3wkizmw.jpg'),
(97, '鮮豐食堂', '08-2351633', '金門縣', '金沙鎮', '國中路7號', '位於金門沙美老街的鮮豐食堂，堅持使用金門在地當季食材，不斷推陳出新研發新菜色，採用少油、少鹽的清淡的烹調方式，讓客人同時享有美食與健康。\r\n老闆黃奕泰原先從事家具業，後來因為身體出狀況而轉職開餐廳，推廣少油、少鹽的健康飲食觀念，十多年過去，夫妻兩人同心經營的鮮豐食堂，憑藉著他們的好手藝，除了當地人也引來自台灣、香港、日本、中國等地遊客造訪，成為沙美老街最熱門的必吃美食店。\r\n為保持食材新鮮，大多採事前預約的無菜單料理，為每位客人客製化在地特色料理，因此前往時記得提前預約！店內還是有常態性的菜單，為了避免沒有預約而來的客人無法品嘗美味料理。\r\n東坡肉\r\n鮮豐食堂的「東坡肉」是饕客的必點招牌菜，老闆特地選用金門在地的酒糟豬的三層肉，吃起來比較不會有腥味，入口即化的東坡肉搭配入味的筍干，以及香醇特調的醬汁相當下飯。\r\n石蚵飯\r\n金門在地的肥美海蚵，口感Ｑ彈有勁且無任何腥味，經過充足日曬後，鮮甜口感濃縮好幾倍，搭配油亮鹹香的米飯一口咬下，口齒留香的滋味讓人讚不絕口。\r\n豬肚炒肉絲\r\n金針菇、豬肉、芹菜、香菇及豬肚等食材切絲，佐以調味料簡單炒煮，一道金門的傳統料理「豬肚炒肉絲」隨即上桌，這道是金門人逢年過節必吃的家常菜，每一口都是家的幸福滋味。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3901/480x360_kito-90(1).jpg'),
(98, '寶聰牧場點心坊', '03-3818015', '桃園市', '大園區', '中正東路二段428號的左邊', '桃園大園交流道旁的「寶聰牧場點心坊」，由老闆黃寶聰每天固定運送鮮奶，低溫冷藏後直送給點心坊製作成各式鮮奶乳品，新鮮程度沒話說。\r\n  \r\n  \r\n  民國95年當選神農獎十大優良農家婦女的許寶桂說：「我跟著夫家學習經營牧場、看長輩做手工藝，自己對糕餅點心也很有興趣，於是主動參加農會田媽媽，夢想哪天可以成為糕餅師傅。」\r\n  \r\n  \r\n  點心坊從早餐店慢慢開始，小小的店面從鮮奶、優格、奶茶、鮮奶饅頭等乳製品，逐漸發展成近二十種小點心。\r\n  \r\n  \r\n  新鮮食材當天做、當天賣完，因此沒有提供宅配服務，田媽媽們一起經營點心坊忙得不亦樂乎，牧場與點心坊凝聚了彼此的感情，讓人感受到媽媽們濃濃的溫馨味。\r\n遊覽景點\r\n  \r\n  XPark 水族館\r\n  \r\n  桃園兒童美術館\r\n  \r\n  竹圍漁港\r\n  \r\n  桃園國際棒球場\r\n在地美食\r\n  \r\n  地瓜、西瓜\r\n交通資訊\r\n  \r\n  高速公路-行駛國道2號機場線，於大竹交流道下往青埔左出口，第一個紅綠燈左轉，就看到囉 :) （位於7-11旁邊)\r\n  \r\n  公車- 桃園&rarr;搭乘5086(桃園-五塊厝-大園)公車，五權牧場站下車。\r\n  \r\n  - 中壢&rarr;搭乘5078(中壢-建國八村)公車，五權牧場站下車。\r\n  \r\n  \r\n  高鐵- 桃園站下車，轉乘206(高鐵桃園站-桃園)公車，寶聰牧場站下車。\r\n  \r\n  捷運- 桃園捷運A17站下車，轉騎U-BIKE10分鐘', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25752/480x360_agrispots-image-ta8thtqfwu-6_bctwffmvg.jpg'),
(99, '耀輝牧場點心坊', '03-475-8049', '桃園市', '楊梅區', '桃園縣楊湖路一段654巷81弄88號', '位於桃園楊梅的耀輝牧場，是假日親子休閒好去處，這是一座兼具生產與休閒的畜牧場，以飼養乳牛為主，也開放體驗餵乳牛吃草、餵牛寶寶喝奶，還可以看見擠牛乳的過程，現場也有工作人員導覽介紹平常喝的鮮乳怎麼來的非常具有教育意義。\r\n耀輝牧場所生產的牛奶沒有太厚重的奶味，喝起來非常順口，牧場除了生產鮮奶之外，也使用鮮奶製成許多美味點心，鮮奶饅頭、吐司、鮮奶麻糬、奶茶、奶凍等，每一樣都散發清淡奶香，口味健康營養滿分。\r\n牧場內還有大片的牧草及活動區，可以來此地舉辦露營、烤肉，或親子活動等，是假日休閒旅遊的好去處。\r\n▲圖說：耀輝牧場的老闆娘非常熱情，會親切地向遊客解說牛的一生、如何照顧小牛、如何分辨母牛的牛奶多寡等，許多關於乳牛的知識。\r\n▲圖說：牧場內販售的都是最新鮮、最香純的牛乳\r\n鮮奶手工饅頭\r\n使用牧場最新鮮、香純的牛奶製作的鮮奶饅頭，手工揉製口感Q度十足，咬下去的每一口都有香醇的鮮奶滋味，給人滿滿的幸福感。\r\n鮮奶麻糬\r\n客家麻糬結合自產的新鮮牛乳，再備好紅豆內餡讓遊客DIY。鮮濃柔嫩的口感，是餐後、下午茶的最佳點心，一起享用，讓大家更麻吉！\r\n▲圖說：牧場餵牛體驗活動', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25728/480x360_agrispots-image-cbmrn2xfw0eiwzktc2fiyw.jpg'),
(100, '議蘆餐廳', '0423310868', '臺中市', '霧峰區', '台中市霧峰區中正路734號民主議政園區內', '「田媽媽議蘆餐廳」位於台中市霧峰區立法院中部辦公室暨民主議政園區內，其前身為議員會館，是早期議員們用餐與住宿的地方，現今為使古蹟活化再利用，餐廳重新修整成田媽媽議蘆會館，提供簡餐、喜慶宴客、團體聚餐等服務，食材採用當地特色新鮮農特產品，其中以霧峰所生產的菇蕈類為特色料理，嚴選在地益全香米、以及霧峰酒莊生產的初鹿清酒，美味又具有風格的餐點，深受許多饕客好評喜愛。\r\n議員會館入口\r\n議蘆餐廳入口\r\n明亮寬敞的用餐環境\r\n涼拌菇蕈\r\n炒三鮮\r\n荔茸香酥雞\r\n避風塘中蝦\r\n合菜', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25651/480x360_agrispots-image-yz8q1jumlu64ndl3kx-bva.jpg'),
(101, '戀戀蚵仔寮', '07-617-7161', '高雄市', '梓官區', '漁港2路32號', '戀戀蚵仔寮\r\n梓官區漁會展售中心隔壁，田爸爸孫基興經營「蚵仔寮田媽媽海產餐廳」，位置靠近蚵仔寮漁港，讓客人來這裡逛魚市、買伴手禮、享日落之餘，有個地方可以大啖新鮮海產。\r\n孫基興卸下高級飯店行政主廚的光環，與漁村媽媽們一起圓夢；從進魚市喊價買魚，到餐廳裡與客人互動交流，「新鮮、平價」是他們給客人的承諾。他說：「做吃的最重要有三件事，食材新鮮、料理認真用心、像做給自己家人吃一樣。」\r\n餐廳裡的海鮮90出自於蚵仔寮漁港。蚵仔寮漁港屬於近海漁業，漁船凌晨出海、中午回來，每天中午12點和下午4點漁船入港，孫基興會到魚市喊價買魚貨，從魚市到餐廳走路不用5分鐘，食物里程極短；魚市旁也有小農市集，海產餐廳佔地利之便，無論海鮮或蔬菜都可以吃到最新鮮、當令的自然鮮甜。\r\n菜單內的菜色是一年四季供應的魚種，門口冷凍箱裡則是每日現撈的當令漁獲，依客人口味、人數做不同搭配。孫基興最自豪的「花雕活鮮蝦」靈感來自於傳統燒酒蝦，他將煮熟的白蝦浸泡在酒裡一天半，蝦肉不但更緊實而且充滿香氣。\r\n「白切小卷」可以沾五味醬或蒜蓉醬，吃新鮮原味最好。另外滿滿餡料的「炸魩仔魚」、「豆醬煮魟魚」都是菜單上吃不到的特色料理。此外，冬至前後更是品嚐烏魚料理的大好時機！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3928/480x360__CWJ3147.jpg'),
(102, '鹽水意麵工坊', '066521177', '臺南市', '鹽水區', '中山路49號', '台南鹽水相傳是台灣意麵的發源地。鹽水意麵與一般麵條不同的地方，在於製麵過程中不加一滴水，完全以鴨蛋取代水分，因此做出來的麵條軟嫩滑Q，有一股特殊的香氣，鹽水意麵全手工製作，因為製麵時必須出力，原稱「力麵」，後來因出力時會發出「噫」的聲音，因而成為「意麵」。\r\n意麵只加蛋黃沒有添加水份，這樣的做法增加了麵團厚實與香氣，製麵過程遵循古法，不添加防腐劑，以傳統日曬方式曬乾麵條，所產製出來的意麵香Q有嚼勁，擁有傳承的美味，讓人回味無窮。\r\n手工意麵\r\n鹽水意麵完全以純手工製作、無任何化學添加物，製作出的意麵有一股自然的香味，麵條色澤金黃誘人，適合乾麵、炒麵、湯麵等各式意麵料理。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/3934/480x360_kito-49(2).jpg'),
(103, '綠朵休閒農場', '0426522125', '臺中市', '龍井區', '台灣大道六段85號', '綠朵休閒農場鄰近台中龍井交流道，緊鄰台灣大道旁，為一山坡地保護區，一個能讓您遠離都市塵囂，眺望整個西部平原與台灣海峽，水天一色，藍天白雲，陽光柔和一片綠意盎然，聆聽蟲鳴鳥叫聲交織成的交響樂，夜幕低垂夜色星海盡收眼底，提供排餐、義大利麵、火鍋、燉飯、素食、點心、飲料、下午茶及客製化團體buffet等各式餐點。已是求婚聖地、婚禮、婚宴、公司團聚、商務開會、親朋好友聚餐、各式車聚..等最理想景點，歡迎舊雨新知一同共享盛舉。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/32563/480x360_agrispots-image-qwitkthvcui_phdggkxigw.jpg'),
(104, '一畝田琉璃仙境休閒農場', '048373888', '彰化縣', '員林市', '香山路87-11號', '坐落彰化員林，琉璃仙境休閒農場結合網美拍照、親子互動、自然教育與在地美食。可愛羊駝、麝香豬餵食體驗，戲水區、玩沙坑、校外教學都適合。園區餐廳提供火鍋、咖哩鍋與特色飲品，還有黑豆醋、擂茶等伴手禮，玩樂與美食一次滿足。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/33623/480x360_e8a8622158864bdc951f1af61b7bd16e.jpg'),
(105, '小路休閒農場', '0932658222', '臺中市', '新社區', '崑山里食水嵙6-2號', '小路休閒農場那片湛藍的天空，清新純淨，微風輕拂；山巔間時有陽光灑落，如金色線條般牽引整片營地，帶來溫暖與笑容。「小路」在日文意為秘密基地，園區位於夢幻湖峽灣，環境清爽舒適，山中靜謐隱密，正是適合放鬆心情、遠離塵囂的好地方。園區內安排了多樣體驗，親子同樂的生態導覽、食農手作體驗、溫馨的親子露營。設備乾淨整潔，搭配輕柔音樂，讓每一次洗沐都能自在舒心。寬廣的草皮空間，孩子們可以盡情滑草、奔跑，探索大自然的奧祕。每週六夜間生態導覽，帶著孩子親近環境，學習自然知識，也增進親子情感交流。園內還有不定期的食農體驗活動，遊客可親手研磨馬告與咖啡、填充氮氣封裝，製作專屬於自己的馬告咖啡。在這片綠意環抱的基地裡，留下與家人共享的笑聲與回憶。', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/1516/480x360_20200324-02.jpg'),
(106, '清香休閒農場', '0928539948', '臺北市', '內湖區', '大湖街206號', '清香休閒農場位於台北市內湖區大湖山莊通往五指山的路上，99年通過為合法休閒農場、109年通過為特色農遊認證水果類場域～農場裡種植產銷履歷草莓、有機草莓、安心椪柑、有機桶柑、玉女小番茄、蘿蔔、地瓜、楊梅、桂竹筍～農場主人許三奇曾當選過全國模範農民，是個熱愛土地用心耕耘的樸實農民。農場視野遼闊、停車方便有50個停車位，內溝溪流經園區，依山傍水生態豐富，擁有道地的植種農作物，有椪柑、桶柑、草莓、番茄、地瓜、白蘿蔔……前來採果、DIY、食農體驗、休閒、放鬆、或在柚子林下遠眺發呆都很是絕佳的選擇喔！農場裡幾乎一年四季皆有水果可採，10-12月採柚子；11月初至隔年2月椪柑、柳丁、桶柑成熟；9月–12月挖地瓜；12月–翌年5月採草莓；小番茄12月–7月，來到清香休閒農場陣陣的花香果香隨著微風處處飄送到身邊很是舒服愜意！除了採果之外特別的材火窯烤地瓜更是道地的農家美食你一定要來嘗嘗看喔。自產的草莓、橘子、楊梅、桑葚做成草莓醬與橘子醬、楊梅果醬、桑葚果醬，草莓冰淇淋、純滴絲瓜水、純蜂蜜的天然伴手禮，也歡迎大家選購。近期來可以採草莓、有機草莓、玉女小番茄、採楊梅、做草莓果醬DIY、柑橘果醬DIY、楊梅果醬DIY、桑葚果醬DIY、竹器童玩DIY、彩繪撲滿DIY。20人以上的團體可以預約的套裝中行程中還有草莓麻薯DIY、地瓜湯圓DIY、窯烤肉桂雞DIY、柑橘精油洗潔劑DIY體驗活動遊覽景點1)清香休閒農場位於五指山麓，可遠眺汐止、東湖、南港～山谷河谷萬戶人家襯上山巒層疊景象開闊宛如畫境令人心曠神怡。2)大湖公園～內湖最經典的湖光水色拱橋景點約3.5里可到達。3)龍船岩～宛如神話傳說的龍船岩走步道約3公里可到達4)開眼山～龍船岩再往上走約1公里即為開眼山可居高遠眺台北盆地的風景5)內湖防災科學教育館～距離約4公里多，半日遊可搭配預約建議遊程清香休閒農場一日遊或半日遊～互動式生態導覽、蔬果採摘體驗、享用農家風味餐、草莓果醬DIY、竹器童玩DIY，或可加窯烤肉桂雞DIY或地瓜湯圓DIY、或搭配草莓盆栽移植DIY、柑橘果醬DIY、柑橘精油洗潔劑DIY等等。在地美食香菇雞湯、滷肉飯、烤地瓜、草莓鬆餅、草莓吐司、草莓牛奶、草莓冰沙、柑橘冰沙、冷/熱柑橘汁、冷/熱楊梅汁、火龍果冰沙、桑葚冰沙、現煮咖啡、草莓冰淇淋。伴手禮與農特產草莓果醬、楊梅果醬、柑橘果醬、桑葚果醬、草莓冰淇淋、純滴絲瓜水、純蜂蜜食當季～季節限定農特產品～1）有機桶柑（1/1起至2月底止）2) 安心椪柑 (11月至12月)2）產銷履歷草莓、有機草莓（即日起至5/31止）3）蘿蔔（1/1起至3月)4）玉女小番茄（即日起至6/30止）因農產品乃配合天侯生長如有異動將另行公告！謝謝！草莓果醬DIY草莓果醬DIY是享受親子或朋友溫馨互動的最佳活動，只要2罐$400即可開煮一爐喔！', 'https://ezgo.ardswc.gov.tw/_api/content/images/agrispots/25289/480x360_agrispots-image-n-mk01wnqk6ithob6tusqa.jpg');
INSERT INTO `gift` (`id`, `name`, `feature`, `addr`, `tel`, `picurl`, `lat`, `lng`) VALUES
(1, '烏魚子- 六六大順禮盒', '新竹地區農曆九月後，因地理環境關係，常颳著每秒20公尺的東北季風，且乾燥冷冽，稱之為九降風。每年11月開始是烏魚成熟季節，烏魚卵經過九降風風乾，風味口感極佳。新竹縣市養殖業者及南寮漁港合計有相當多的產量，在地理環境及原料相當充足之下，有很好的發展空間，且烏魚卵經北台灣和煦陽光及九降風自然風乾，風味獨特，質冠全台。新竹市漁會產銷班以多位養殖業者合作，自產自銷，並且維持一貫的優良品質，首度風城十大伴手禮選拔即入圍獲獎！\r\n購買位置：慶豐水產實業社', '新竹市北區東大路四段315號', '03-536-2216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31824/480x360_souvenir-image-xislcjnzmkynvgrhorntgq.png', 24.84692709999, 120.9244968999),
(2, '虱目魚香腸', '在歷經數各多月的研發，終於研發出來了吃得到虱目魚肉細緻綿密的魚肉口感，魚肉跺碎沒經過打漿直接灌入腸衣成型，就外觀上完完全全就是香腸的面貌，口感上絕對是真實的虱目魚口味。虱目魚肉，低脂肪、低熱量、高蛋白的美味健康訴求，將會是您的新選擇！', '臺南市安平區大平路66號', '06-222-2210', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18963/480x360_55420201209.jpg', 22.99682, 120.15362),
(3, '蓮藕粉組合式禮盒', '現有蓮藕粉產品包裝比較傳統，普遍無法吸引年輕消費族群購買本產品；擬由本計畫設計製作優質具吸引力之蓮藕系列產品包裝袋及包裝禮盒結合各式產品豐富組合式伴手禮盒內容，吸引更多國人與年輕人購買慾望。提高蓮藕系列產品價值，增加消費者購買意願，可讓消費者送禮自用兩相宜。', '臺南市白河區三民路412號', '06-685-0923', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18965/480x360_60720201209.jpg', 23.3516817, 120.4157373),
(4, '湖苺戀系列', '精選新鮮豬肉，以特殊配方及加入「湖莓戀」 (草莓酒系列)來增加酒香，精心調製而成。口感香嫩、口齒留香，可以冷鍋、冷油、小火調理或用汆燙後再烤口感更佳。吃上一口香腸再加上一杯湖莓戀更能享用美食。', '苗栗縣大湖鄉富興村八寮村2-4號', '03-799-4800', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31823/480x360_souvenir-image-qk-qogx7le2jsmspazworq.jpg', 24.4289864, 120.8660828),
(5, '有神酵系列、青梅養生系列', '有神酵系列 \n1.好好酵-梅子酵素+精神強-古法梅精+有好醋-果釀梅醋共三罐。 \n2.完全採用信義鄉出產之優質青梅。 \n3.易開罐設計，取用方便，開封後完整密封。 \n4.採用梅果原釀而成，自然健康。 \n5.不添加任何防腐劑、色素。 \n6.稀釋5-8倍食用。  \n產地同步特價優惠實施中。 \n信義鄉農會本著奉茶的分享精神，堅持採用信義鄉在地嚴選青梅，並將本地流傳數十載的傳統養生加工法，傳承保留再藉由大葉大學的製程分析研究創新，技術完整轉移後開發出一系列養生梅產品。\n（梅子酵素-好好酵 ）\n梅子酵素-好好酵 完', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18969/480x360_55120201209.jpg', 23.68870099999, 120.861791),
(6, '凍頂茶原片茶包', '本級茶使用優良之凍頂茶，經本社品管之烘焙，品質佳，價位適中，是上選之原片茶包。', '南投縣鹿谷鄉初鄉村中正路3段293號', '080-008-8118', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18971/480x360_55820201209.jpg', 23.7603933, 120.7376796999),
(7, '金瓜濃湯精緻禮盒', '南瓜濃湯-純台灣在地生產的南瓜製成，原料新鮮，無藥物殘留。添加澳洲有機脫脂奶粉、洋蔥、小麥、卵磷脂、葡萄糖、葡萄糖胺等製成。\n南瓜粉-純台灣在地生產的南瓜製成，原料新鮮，無藥物殘留。可做為牛奶、豆漿、麥片...等流質食品的添加物，亦可做為料理食材，使用方便，營養不流失。產品主要原料與本鄉蔬菜產銷班契作本產南瓜，使用在地農產品比例佔90%以上。\n純台灣農產品製成，原料新鮮，包裝具鄉土味，送禮大方實惠。', '雲林縣四湖鄉中山西路94號', '05-787-2008', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18973/480x360_56020201209.jpg', 23.6377404, 120.2226555),
(8, '凍頂蜜香貴妃茶', '很香很好喝', '賣茶的地方', '080-008-8118', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31845/480x360_souvenir-image-ebsmdk-x30skac_qhnsmpw.jpg', 23.7603933, 120.7376796999),
(9, '玫瑰花纖體醋', '以糯米釀造而成的釀造醋為基底，浸漬埔里山城特選優質安全的玫瑰花，將玫瑰獨特的香氛和有益成份完整的釋放到醋裡面陳年釀造醋滑潤順口，玫瑰清香濃郁；因取用天然現採玫瑰，即使稀釋後飲用，依然芳香撲鼻、香味持久，玫瑰花中的有\n益成份讓身體充分吸收，更是受女性朋友喜愛的飲品。\n主要成分：玫瑰花、糯米\n食用方式：以冷開水或冰塊稀釋二至四倍', '南投縣埔里鎮清新里西安路一段六號', '04-9298-6420', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18975/480x360_56520201209.jpg', 23.963721, 120.9641679999),
(11, '田中特選-田穗系列組合禮盒', 'Yes', '彰化縣田中鎮南北街80號', '04-874-9211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31849/480x360_souvenir-image-clsyeuxw0uku6mzv-ckqaq.jpg', 23.85965819999, 120.5863643),
(12, '烤冰薯', '購買資訊：農創家電商-沙鹿區農會', '臺中市沙鹿區沙田路131號', '04-2662-3111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31840/480x360_souvenir-image-qheormwqeu-cfh3_ihopwa.jpg', 24.2360788, 120.5589866999),
(14, '香得益彰禮盒', '經由農會挑選濁水溪流域之良質米稻米生產專區、田中酪農專區、二林雜糧作物生產等區所生產優質農產品加工組合而成的最佳伴手禮。', '彰化縣彰化市中山路二段349號13樓', '04-726-3460', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18985/480x360_59320201209.jpg', 24.0744019, 120.54353),
(15, '洛神花系列', '洛神花又名洛神葵，台東金峰鄉產量最多，因品質最好，先天環境極佳，加上環境和空氣純淨無污染，花萼果實製成的食品，讓人吃起來特別放心。', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18991/480x360_62420201209.jpg', 22.604987, 121.001855),
(16, '一口香鹹蛋', '翻轉鵪鶉蛋產業將小巧一口鳥蛋，化身各式風味蛋製品，鹹香鳥蛋，鹹度適中，蛋黃香氣濃郁，肚子餓時來一顆，補充蛋白、活化腦細胞。\r\n產地直送，如何訂購: 陽光鵪鶉牧場', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19001/480x360_64920201209.jpg', 0, 0),
(17, '純正野生烏魚鬆', '悟棲漁港所捕獲的野生烏魚品質優良，漁會為保留這彌足珍貴的季節滋味，進一步結合生產及專業加工廠，以傳統古法結合現代科技製成美味烏魚鬆；百分百純魚肉製成，不添加防腐劑，營養健康，老少咸宜。\r\n產地直送，如何訂購純正野生烏魚鬆: https://www.tcfish.org.tw/', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19003/480x360_66320201209.jpg', 0, 0),
(18, '戀戀大湖', '有大湖草莓精心釀製的微醺，香甜的草莓果香躍然而出，在唇齒間漸漸融化的甜蜜滋味；還有嚴選泰安紅肉李精心釀製的醉香，口感豐厚，略些澀味，餘韻散發淡淡杏仁香味，冰鎮享用後風味更佳。', '苗栗縣大湖鄉富興村八寮村2-4號', '03-799-4800', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19005/480x360_62820201209.jpg', 24.4289864, 120.8660828),
(19, '山蕉捲捲酥', '延續集集山蕉風光金蕉年代，完全使用100%山蕉果泥製作成蛋捲形狀，絕無添加任何人工添加物，使用德紐進口奶油，每一口都能吃到山蕉果泥綿密口感。\r\n產地直送，如何訂購: 集元果 線上訂購', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31876/480x360_souvenir-image-pgkdbcnjx0-ybzxv0nhmnw.jpg', 0, 0),
(20, '金孃紅', '以農場自產的蔬菜馬齒莧(代表堅持)+在地農產品草莓果實(代表甜蜜) + 社區區花桃金孃果實(代表愛神)研發而成，並以農場毗鄰的濕地同心池為造型，將手工製作的餅乾取名為「同心愛神餅」，要讓嚐到此餅的人都感受到幸福浪漫的滋味。\r\n產地直送，如何訂購: 農驛棧農場', '臺北市內湖區碧山路43號', '0912-472-001', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19007/480x360_20210301.jpg', 25.1012, 121.589639),
(21, '貓空山色茶明信片茶包', '傳承百年工藝的木柵好茶，藉由茶包明信片文字傳達關心，熱茶傳遞溫度。輕鬆沖泡享受三色好茶，清香淡雅的包種茶、蜜香甘甜的觀音紅茶、濃香醇厚的鐵觀音茶，茶煙繚繞看似深遠的貓空山色雲霧之美。\r\n產地直送，如何訂購: 美加茶園', '臺北市文山區指南路三段38巷19號', '02-2938-6277', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19009/480x360_20210302.jpg', 24.971146, 121.5877162),
(22, '鱘龍魚干貝XO醬', '本產品由農場主人親自研發調配,主食材採用自家漁場孵化養殖的鱘龍魚,從養殖到出貨均自產自銷一手把關,訴求天然營養、健康不油膩,讓大家也都輕鬆吃到帝王級的鱘龍魚伴手禮\r\n產地直送，如何訂購: 鱘龍魚干貝XO醬 千戶傳奇生態農場官網', '新北市三峽區有木里有木154-3號', '02-2672-0748', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19011/480x360_20210304.jpg', 24.8453226, 121.4494399),
(23, '親親草泥馬', '草泥馬呆萌超吸睛、療育人心，大人小孩都喜歡。觸感柔軟絨毛玩偶遇上農場香草植物自製的香囊，[親親香囊草泥馬]-要帶我回家喔!Live,Life,Love(Live The Life You Love, Love The Life You Live)\r\n產地直送，如何訂購: 富田花園農場', '桃園市大溪區福安里頭寮一路29巷59號', '03-387-2540', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19013/480x360_20210305.jpg', 24.839922, 121.284528),
(24, '魚香XO拌醬', '用在地漁業友善飼養及現撈魚貨為主原料製作，產地直送的差異性秉持傳統手工製法結合現代美食新概念堅持無色素無防腐劑保留漁獲的原色原味給顧客最安心的品質\r\n產地直送，如何訂購: 水月休閒農業區', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19015/480x360_20210306.jpg', 0, 0),
(25, '豆腐乳、哈密瓜醬瓜、洛神花蜜餞', '傳承ㄚ嬤的手路利用在地的產業，開發哈密瓜醬瓜、洛神花蜜餞、無添加防腐劑、吃得安心、還有媽媽的愛心與味道。\r\n產地直送，如何訂購: 官夫人田園料理', '宜蘭縣壯圍鄉新南村霧罕路3號', '03-925-3517', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19019/480x360_20210308.jpg', 24.71944885883543, 121.80688977241516),
(26, '叻沙湯包與鯛魚片', '鯛魚片:太平洋海水養殖的健康美味海鮮，用天然的飼料餵養健康的魚，加上低密度養殖，讓魚更活動空間，魚肉更Q彈。叻沙湯包:搭配南洋風味的叻沙獨特風味湯底，給你一個暖暖的胃、滿嘴的鮮美。\r\n產地直送，如何訂購: 大塭休閒農場', '宜蘭縣礁溪鄉玉龍路二段497號', '03-987-0558', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19021/480x360_20210309.jpg', 24.819497045332145, 121.79645597934723),
(27, '旺山綠蜂膠淨手液', '綠蜂膠珍貴素材可提高手部清潔效果，蜂蠟讓手部可達防護及保濕，台灣綠蜂膠及蜂蠟，結合酒精、茶樹、金銀花及尤加利，強化清潔、防護、速乾及保濕效果，最適合頻繁使用酒精淨手的使用族群，降低酒精導致手部乾裂情形發生。', '宜蘭縣壯圍鄉新南村新南路106-11號', '0932-088-992', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19023/480x360_202103010.jpg', 24.7266496, 121.807281),
(28, '有機三穀米', '一年一耕 地力飽滿 順性自然 米粒Q軟 民豐有機米為一年一期作，藉由二期休耕種植綠肥作物，使土壤有充足時間修養生息，恢復有機養分、地力重新飽足。人類友善地取之自然、大地豐沛地永續回饋，種出來的米粒才有風土的富饒馨香，煮出來的飯才會健康、營養、美味。成立民豐的礁溪鄉有機米產銷班，自83年實行有機耕法，默默俯仰天地、與自然共生，現已擴充栽種面積達50公頃，培育出纖維含量高的多元品種，將最真實的蘭陽人情味、在地味，帶給同樣熱愛這片土地的人們。\r\n產地直送，如何訂購: 民豐有機農場', '宜蘭縣礁溪鄉四結路27之12號', '03-928-2202', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19027/480x360_202103012.jpg', 24.792873, 121.757648),
(29, '點頭蒜香醬料、天生好辣醬料', '宜蘭以三星蔥及蒜為名，搭配在地青農的食材（合作社社員為主），使用次級的蔥、蒜、辣椒，開發出萬用的獨特醬料，除了符合循環經濟之精神，也讓消費者能在回家後輕鬆料理。\r\n產地直送，如何訂購: 青出宜蘭', '宜蘭縣人和村月眉圳路63巷36號', '03-989-1280', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19029/480x360_202103013.jpg', 24.706573, 121.712229),
(30, '那山那谷精釀啤酒', '那山那谷馬告精釀啤酒：使用泰雅族的傳統香料「馬告」釀製的精釀啤酒，擁有柑橘、檸檬、香茅等多層次清香，氣泡細緻滑順，單獨品飲或是佐餐飲用都是絕佳的享受。\r\n產地直送，如何訂購: 那山那谷FACEBOOK\r\n未滿18歲禁止飲酒，飲酒過量，有害（礙）健康', '宜蘭縣南澳鄉金洋路2號', '0933-119-250', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19031/480x360_202103015.jpg', 24.424623, 121.7493784),
(31, '戀戀冬山-柚花烏龍茶巧克力', '鮮為人知的宜蘭茶，運用地圖的方式讓大家認識宜蘭冬山地區，裡面使用在地友善環境無農藥的文旦柚花與烏龍茶，冷泡熱泡都適合，搭配72%紅茶黑巧克力杏仁豆，苦中帶甘，回甘花香，品嚐多層次的享受。\r\n產地直送，如何訂購: 星源茶園', '宜蘭縣冬山鄉中山村中城路115號', '03-958-8947', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19033/480x360_202103016.jpg', 24.6297604, 121.7480707),
(32, '果然幸福果汁、果然幸福果醬', '1.產品(確定)名稱：果然幸福 2.故事定位：來自中央山脈及雪山山脈的天然湧泉，用友善耕作蘊育天然、純凈、無毒的幸福果食，讓您體驗果然幸福的生態禮物。3.產品賣點(優於別人的地方)：用友善耕作-自然農法；蘊育天然、純凈、無毒的幸福果食4.產品與農場結合的特色：運用四季農作物透過生態體驗，讓遊客親身體驗手做DIY', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19035/480x360_202103017.jpg', 0, 0),
(33, '耕堡冰淇淋', '主打健康的理念，耕堡冰淇淋無添加人工色素，香料讓您每一口都吃的到健康幸福美味，產地直接用新鮮有機蔬果所製做的冰淇', '宜蘭縣三星鄉三星路八段238巷長埤68號', '0988-015-066', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19037/480x360_202103019.jpg', 24.6423883, 121.6079797),
(34, '祕釀樹葡萄醋', '採用自產有機樹葡萄,委託生偉生技股份有限公司製作,以天然發酵的方式製成，營飬價值高，好喝又順口。\r\n產地直送，如何訂購: 花泉休閒農場', '宜蘭縣員山鄉尚德村八甲路15-1號', '03-922-1506', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19039/480x360_202103020.jpg', 24.72731340064455, 121.70462250709534),
(35, '鮮奶起司棒、乳牛斑點饅頭', '鮮奶起司棒始以鮮奶麵粉跟帕瑪氏起司粉做成，吃起來脆脆的有濃濃的奶香起司味。乳牛斑點饅頭以純鮮奶加入麵粉內製作，過程中無任何添加物，斑點以竹炭可可粉製成來點綴，製作出可愛的乳牛斑點饅頭。\r\n產地直送，如何訂購: 田媽媽寶聰牧場點心坊', '桃園市大園區中正東路二段428號的左邊', '03-3818015', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19041/480x360_202103021.jpg', 25.02750172440004, 121.2300582964184),
(36, '雪霸明日葉粉', '1.低溫磨粉，營養不流失 2.輕巧包裝，方便攜帶3.滅菌處理，安全無虞4.富含有機鍺及查爾酮\r\n產地直送，如何訂購： 新竹五峰鄉雪霸休閒農場(官方網站)', '新竹縣五峰鄉桃山村民石380號', '03-585-6192', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19043/480x360_202103023.jpg', 24.5276476, 121.1178128),
(37, '風將烏魚(子)禮盒', '本產品由福樂休閒漁村自家養殖的烏魚加工製作生產:1.養殖過程都經過定期送檢2.製作出的產品皆經過ETC檢驗合格\r\n產地直送，如何訂購: 福樂休閒漁村', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19045/480x360_202103024.jpg', 0, 0),
(38, '大山珍竹 天然桂竹筍', '橫山鄉大山背山，中海拔，自然產出獨特鮮美的桂竹筍，堅持天然無化學添加，為新竹橫山特有伴手禮---大山珍竹，有客家「山」的味道。\r\n產地直送，如何訂購: 大山背休閒農場', '新竹縣橫山鄉豐鄉村大山背5 鄰 52 號', '0988-909-769', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19047/480x360_202103025.jpg', 24.695594, 121.144777),
(39, '香魚酥排', '香魚酥排是以自家天然湧泉養殖,全程低溫真空油炸緊緊鎖住鮮味,魚骨已化成酥脆,美食行家華麗享受。\r\n產地直送，如何訂購: 八甲休閒魚場', '宜蘭縣員山鄉尚德村八甲路1之10號', '03-922-5990', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19049/480x360_202103026.jpg', 24.7265114, 121.7029361),
(40, '鳳梨豆腐乳', '一般豆腐乳都以豆米發酵而一佳村則以鳳梨發酵鳳梨為活性酵素\r\n產地直送，如何訂購: 田媽媽一佳村養生餐廳FB', '宜蘭縣冬山鄉中山村中城二路58巷11號', '03-958-8852', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19051/480x360_202103027.jpg', 24.627306, 121.748639),
(41, '賀ㄟ米粉', '嚴選農場的手工日曬荷葉，100%純有機米製成，使用沖泡方式享用快速方便，口味絕不馬虎，獨特調製味噌及香菇口味，美味即刻上桌\r\n產地直送，如何訂購: 蓮荷園休閒農場', '桃園市觀音區藍埔里金華路690號', '03-477-6972', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19055/480x360_202103029.jpg', 25.0129601, 121.1158275),
(42, '烏樹林香草啤酒、烏樹林香草冰淇淋', '香草啤酒-烏樹林自產香草莢和委託龍潭當地冠軍啤酒廠釀製。香草莢為全世界第二貴之香料植物，其獨特的小起配合小麥啤酒的奶油氣味融合出獨特的香甜口感，是能夠細細品嘗的精釀啤酒。 有鑑於市面販售之香草冰淇淋多以化學合成香草精為添加物，烏樹林能以自產香草莢與飛牛牧場長久以來冰淇淋製成技術合作，生產之香草冰淇淋是以真食材製作，讓國人能夠品嘗真正的香草冰淇淋。\r\n產地直送，如何訂購: 烏樹林從前從前-烏樹林Before \r\n \r\n未滿18歲禁止飲酒，飲酒過量，有害（礙）健康', '桃園市龍潭區龍平路115巷138弄36號', '0905-016957', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19057/480x360_202103030.jpg', 24.889357223344508, 121.21816658012138),
(43, '精油聞香木', '能形成一瓶精油的背後，是需要大量的時間與精力照顧，日復一日到適當的時機後大量採收萃取出一瓶100%濃縮精油，讓我們能透過1-2滴便能享受數百朵植物精華的能量，芳香分子能活化我們的身心靈給予正面情緒，並能抗菌，也使顧客更重視自然生態植物的重要性一份香氣不單只是氣味上的感覺，氣味會連結大腦海馬體，用久了是一份回憶記憶、磁場、正能量與平衡身心靈的狀態，是大自然留給我們有生命的禮物，並不是虛假化學合成無生命的香精調製的都市人住的房子較沒有空間種花草、但你買一瓶、兩瓶精油猶如一座森林\r\n產地直送，如何訂購: 花露休閒農場', '苗栗縣卓蘭鎮西坪里43-3號', '04-2589-1589', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19059/480x360_202103032.jpg', 24.333245177629507, 120.82616686820984),
(44, '飛牛水果-乳清優格(百香芒果、紅龍果蜜桃、鳳梨)', '好function＋好放心的飛牛水果乳清優格，利用複方生乳製作新鮮乳清，結合小農水果及複合菌株發酵，開發成含免疫球蛋白與乳鐵蛋白等無人工添加物食品，讓兒童、上班族女性、銀髮族能透過日常飲食來進行保健\r\n產地直送，如何訂購: 飛牛牧場', '苗栗縣通霄鎮南和里 166 號', '03-778-2999', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19061/480x360_202103033.jpg', 24.441267, 120.741294),
(45, '能量黑寶貝/能量茶寶貝', '柴燒陶與在地小農農產品結合，位在客家庄的我們，仙草是小時候阿公年代家家戶戶幾乎都有栽種的植物，後來因種植過程工序繁瑣，漸漸很多人都沒有栽種了，培育友善仙草希望結合農事體驗及伴手禮開發，推廣這古早味的好。在地仙草乾、貓貍紅茶兩種產品(本農場已與在地小農長期合作在案)，並與休閒農業區小農契作共應，導入專屬柴燒杯與仙草及貓貍紅茶組合方式，並強調友善特色應可與其他農產品區隔。&#39;\r\n產地直送，如何訂購: 春田窯陶藝休閒渡假園', '苗栗縣三義鄉雙潭村大坪7號', '03-787-7820', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19063/480x360_202103034.jpg', 24.4093568, 120.7991899),
(46, '蘿蔔錢', '蘿蔔錢是用新鮮蘿蔔洗淨切薄片,直接曬成菜乾,不醃漬不加鹽,是苗栗縣內客家庄特有的名產\r\n產地直送，如何訂購: 神雕邨複合式茶棧', '苗栗縣三義鄉廣盛村廣聲新城2巷26號', '03-787-5858', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19065/480x360_202103035.jpg', 24.4054203, 120.7608063),
(47, '阿嬤的古早禮', '堅持選用零除草劑、零農藥、健康土壤栽培的老薑，在客家阿嬤的技術傳承下，純手工製作滿馥濃郁黑糖香氣的薑糖。\r\n產地直送，如何訂購: 水寨一方農場', '臺中市東勢區東崎路三段396號', '0920-210-383', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19069/480x360_202103039.jpg', 24.2591134, 120.8668735),
(48, '客家肉粽', '來自台中山城客家庄以古早傳統的道地口 味感覺，採買特選梅花肉、上等蝦仁、新社香菇、蔥頭等食材；將糯米大火蒸熟拌入蔥酥香油條味，包入炒香的餡料，再次蒸熟讓米香、餡香與粽葉香融合，呈現多層次口感與味覺。\r\n產地直送，如何訂購：石岡傳統美食小舖', '臺中市石岡區豐勢路889之1號', '04-2572-1490', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19071/480x360_202103042.jpg', 24.2738968, 120.7888619),
(49, '好樂農莊台灣籽苦茶油', '好樂農莊 來自台中新社賴建宏與農媳婦江嘉維承接長輩東勢區的苦茶園，夫妻都是農業門外漢一步一腳印堅持友善環境種植，種植採收到販售不假他人之手，延伸發展經營休閒農場，場域提供農事活動，深度體驗農村生活。秉持初衷 生產好的農特產品 樂於分享每件事情\r\n產地直送，如何訂購: 好樂農莊/阿公ㄟ公園 | Facebook', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19073/480x360_202103043.jpg', 0, 0),
(50, '山豬愛吃蘋果脆片', '農場為臺大園藝系實習場域，以友善環境方式生產蘋果，並採冷凍乾燥加工製作脆片，保留蘋果營養及風味，口感鬆脆清爽，單一材質包裝以利回收。\r\n產地直送，如何訂購: 國立臺灣大學生物資源暨農學院附設山地實驗農場', '南投縣仁愛鄉大同村仁和路215號', '04-9280-3891', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19077/480x360_202103045.jpg', 24.06987069999, 121.1678663999),
(51, '探好茶', '將孟宗竹炭與茶葉結合，包裝設計成伴手禮，「探好茶」它的自然甘醇、獨特鮮美的滋味，希望能成為當地特色伴手禮。\r\n產地直送，如何訂購：武岫休閒農場', '南投縣鹿谷鄉竹林村田頭巷35-66號', '04-9267-6262', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19079/480x360_202103046.jpg', 23.718823659569427, 120.7611232995987),
(52, '院落花草茶', '我們對【院落花草茶】的真.誠.訴.求1. 融合調香專業，調製獨特精緻風味2. 72小時冷風乾燥無毒花草 3. 無添加香料、色素、防腐劑 4. 選用台東無毒香草及南投「神農獎」茶師製作的茶葉 5. 四款茶均經過「560項無農藥殘留檢 驗合格 」6. 使用PLA玉米澱粉安全環保茶包', '南投縣名間鄉田仔村田仔巷16-8號', '04-9227-3797', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19081/480x360_202103047.jpg', 23.8646515, 120.6751937),
(53, '日月潭紅茶拿鐵米餅 (奶素)', '全台唯一『100%日月潭產地紅茶』米餅，清新紅茶香氣和入口即化的綿密口感，日月潭必買伴手禮！使用全日月潭產地紅茶，結合台灣米製作，入口即化輕食小點心，一口接一口的美味，搭配日月潭紅茶享受愉快的點心時光。\r\n產地直送，如何訂購: 日月潭-日月山莊 (facebook.com)', '南投縣魚池鄉魚池街443-36號', '04-9289-5899', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19083/480x360_202103048.jpg', 23.89716770159862, 120.93401849269867),
(54, '活體蛤蜊、魚鬆、醃蛤、醃蜆', '哈哈漁場處於 彰化名列台灣文蛤前三大產區，而位於斗苑休區、漢寶專業養殖區的「哈哈漁場」，也以養殖 文蛤著稱，並混養白蝦、虱目魚、黃錫鯛等魚蝦。漁場在主人陳明瞭的精心規劃下，來到這裡不但 可以下水「摸蛤仔」，還有「漁夫牽魚」、「收蛇籠捕蝦」等特色活動可以參加，藉由親自操作、 切實了解漁夫工作以及各種不同的捕魚工具如何利用。此外，在陳明暸親切活潑的帶領及講解下， 大家還能在充滿歡笑的輕鬆氣氛中進一步了解當地河口生態，並就地享用「尚青」魚場、採買新鮮 的活力蝦、元氣蝦等魚場特產，開心感受「一日漁夫」的生活！ 明瞭哥原本是做工廠的，後來中年的時候在思考要轉職，當時就決定回來家鄉做養殖業，起先 他先跟別人租養殖魚塭，慢慢拓展到有自己的魚塭，在做養殖魚塭的同時，他也思考要如何將這裡 的生態環境以及漁業概念傳遞下去，就先開啟作海岸教育的活動（講解生態等等），大約六年前左 右才開始規劃比較完整的一套體驗活動，明瞭哥採取的方式，適用較天然且貼近自然的魚塭做生態 講解，並且實地教大家如何牽罟、摸蛤仔，還可以體驗 DIY 做魚丸、魚鬆等，可以說是最好的教育 場所。\r\n \r\n產地直送，如何訂購: https://www.facebook.com/hahafish168', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19085/480x360_202103049.jpg', 0, 0),
(55, '珍的好蝦', '彰化生態蝦(白蝦)是以文蛤池混養海水養殖成長環境無用藥口感Q彈鮮甜海味。珍的好蝦以真空烘培不添加任何調味料保持原有鮮蝦味。健康安全鮮甜營養。其養殖過程全程無用藥，以自然生態方式飼養為用人工飼料天然飼養成，所以又叫人工蝦\r\n產地直送，如何訂購：王功陽光水棧海鮮餐廳', '彰化縣芳苑鄉王功村漁港六路38號', '04-893-3323', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19087/480x360_202103053.jpg', 23.969086, 120.3280699),
(56, '天使樂園無花果茶', '產品名稱：天使樂園無花茶 產品賣點：1.自然農法(運用蚯蚓土和天然酵素)、2. 380+1項農藥零檢出、 3.身心障礙者所運用自身能力種植出顆顆精華之果實。產品與農場結合的特色：無花果和農場身心障礙者一樣，似花飛花、似懂非懂，卻在這樣美麗錯誤釀成一顆顆晶瑩剔透之花蜜。產品最佳使用方法介紹：一包無花果茶可以沖泡2-3回，若想自行添加甜度可加入蜂蜜。', '彰化縣二林鎮華崙里光復路61巷41號', '04-8681199#166', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19089/480x360_202103054.jpg', 23.95070446156215, 120.44292211532591),
(57, '蝶藝．蘭舞', '40年來「展壯台大休閒農場」堅持以「品質第一，顧客優先」的理念，搭配即時的物流系統，將「幸福向你飛來」之蝴蝶蘭伴手禮送至客戶的手上。體積小巧的伴手禮，良好居家擺飾，品味提升。\r\n產地直送，如何訂購: 展壯台大蘭園', '彰化縣大村鄉大橋村中山路三段137號', '04-852-7335', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19091/480x360_202103055.jpg', 23.996891360090817, 120.55876806378365),
(58, '菇貓水餃', '菇貓水餃採用太陽能温室栽種的極品珊瑚菇與過貓、黑木耳、紅蘿蔔，葷食採用CAS認證當天現宰國產温體豬肉,激盪出味蕾新體驗\r\n產地直送，如何訂購: 晁陽綠能農場', '雲林縣麥寮鄉興華村興華路32號', '05-693-8238', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19093/480x360_202103056.jpg', 23.75121035973045, 120.29707629744584),
(59, '牛樟原萃手工皂', '山上種樹牛樟手工皂是採用自家農場萃取的牛樟純露配合牛樟精油製作而成，純天然製作，可以緩解皮膚過敏的問題。\r\n產地直送，如何訂購:山上種樹 牛樟森林休閒農場', '苗栗縣大湖鄉義合村南昌路41號', '03-799-7262', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19095/480x360_202103057.jpg', 24.397269808481468, 120.87851285934448),
(60, '紅棗香腸、香煎芋糕', '運用在地的食材，紅棗露搭配黑豬肉罐製出獨特香氣與美味的伴手禮也是店內的招牌菜之一。 香煎芋糕有別於傳統的芋粿，我們使用友善栽種的公館芋頭加上現磨的在來米、上等豬肉、香菇、油蔥等，手工制做的芋糕切片煎過後，吃起來口感外酥內軟，芋頭香味濃郁，而且沒有添加任何防腐劑，大家可以安心食用。\r\n產地直送，如何訂購: 田媽媽巧軒餐館', '苗栗縣公館鄉石墻村11鄰223-1號', '03-722-6868', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19097/480x360_202103058.jpg', 24.472237, 120.8195033),
(61, '金葉山莊《我們不一樣》橄欖', '臺灣橄欖、原汁鮮味，30年手藝經典天然再現吃過就知道不一樣，懷念的客家食療30年傳統古法手藝製作，經典再現橄欖鮮味，茶食、冰鎮、煲湯皆宜。', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19099/480x360_202103060.jpg', 0, 0),
(62, '紅茶麵、木耳麵', '貓裏紅茶具有紅茶與烏龍茶之果香，以此茶研磨成粉來製作麵條，讓麵條具有紅茶之風味。木耳皆是本地農民使 用友善耕作，所種植的新鮮木耳，木耳也富含膳食纖維可以幫助腸胃蠕動有助於保護腸胃。 木耳皆是本地農民使用友善耕作，所種植的新鮮木耳，木耳也富含膳食纖維可以幫助腸胃蠕動有助於保護腸胃。\r\n產地直送，如何訂購： https://pse.is/3gruap', '苗栗縣苗栗市玉清里11鄰復興路四段197號', '03-732-0530', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19105/480x360_202103063.jpg', 24.56744133048793, 120.83109274506569),
(63, '國宴珍珠包', '羅美蘭女士於90年榮獲神農獎肯定，蒙總統召見。[國宴珍珠包]為純手工精製，内餡特選潭子區特產-麻竹筍，經不斷的精進，結合Q彈的外皮，終獲選為91年總統招待外賓的國宴點心及107年總統府家庭日之佳餚。\r\n產地直送，如何訂購:欣燦客家風味餐廳', '臺中市潭子區興華一路219號', '04-2534-5178', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19107/480x360_202103065.jpg', 24.2088168, 120.7032117),
(64, '綿密狀元糕', '狀元糕源於喜事訂婚糕點，也為糕餅文化由來之一。糯米粉須以手工攪拌與各食材揉合才不會結團是糕仔好吃的秘訣，綿細紮實能入口即化，甜度適宜帶來樸實高雅的滋味。狀元糕承載喜餅禮俗、祈福祭祀等許多節日祝福象徵，更是林金生香百年最重要的傳承。\r\n產地直送，如何訂購:  林金生香', '臺中市南屯區萬和路一段59號', '04-2389-9857', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19109/480x360_202103066.jpg', 24.1380735, 120.6390802),
(65, '蔥師傅黑芝麻青蔥脆餅', '台中市大安區優質產銷履歷青蔥加上台灣在地產黑芝麻，青蔥香味加上營養的黑芝麻，青蔥香味加上營養的黑芝麻，口感豐富且帶層次性的風味，本次伴手禮開發以大安區農會師傅品牌為主導，將餅乾視為一道精心料理的佳餚\r\n產地直送，如何訂購: 台中市大安區農會', '臺中市大安區中庄里３鄰中松路６號', '04-2671-2229', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19111/480x360_202103067.jpg', 24.3463873, 120.5870304),
(66, '豐茶師花果茶', '在臺灣最知名茶區:鹿谷，深藏著許多茶葉職人。在這老茶區，茶葉由專業茶農師傅細心照料，再由製茶師 承襲傳統手藝經由委凋、揉捻等步驟製成臺灣好茶。我們串連了在地花果農民，開發出茶與花、果的複方產品。 讓您一同品嚐台灣農村的美好。\r\n產地直送，如何訂購: 田媽媽小半天風味餐坊', '南投縣鹿谷鄉竹豐村中湖巷3-5號', '0919-743-732', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19113/480x360_202103070.jpg', 23.731745, 120.7491051),
(67, '蜜地瓜', '將懷舊口味創新賦予食材新的生命，循古法慢火熬煮口感清香，綿密軟Q，是伴手最佳點心，冷凍後食用更好吃，包裝設計簡單清新攜帶方便，自用送禮兩相宜\r\n產地直送，如何訂購: 田媽媽竹山耄饕客棧', '南投縣竹山鎮延和里安定巷142號1樓', '0933-522-530', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19115/480x360_202103071.jpg', 23.7635541, 120.687042),
(68, '魔菇小食點-可口菇脆片', '可口菇脆片，嚴選魔菇部落特產黑美人菇和杏鮑菇，清香酥脆，健康享受美食，讓您愛不釋手，一口接一口。多種調味一次滿足送禮自用皆大歡喜。\r\n產地直送，如何訂購: 魔菇部落休閒農場', '彰化縣埔心鄉柳橋東路829號', '048521898', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19121/480x360_202103074.jpg', 0, 0),
(69, '龍眼乾', '今夜星辰休閒農場並效力於協助地方果農結合資源推廣地方農特產與人文特色觀光產品是與彰化石牌社區當地優質果農手工柴火燒而成，口感甜而不膩具獨特風味可作為可口零食又或者入菜調味，對人體養生非常有益\r\n產地直送，如何訂購: 今夜星辰休閒農場', '彰化縣彰化市石牌路一段428號', '04-732-3111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19123/480x360_202103075.jpg', 24.0521554, 120.6064615),
(70, '玫瑰洛神冰淇淋', '一款充滿著愛情浪漫與健康的冰淇淋，在不加色素及香精之堅持下，讓你看到多色玫瑰花瓣，聞到天然玫瑰花香，嚐到洛神微酸的滋味，感受到戀愛的滋味，浪漫的享受，在低卡低脂微甜的要求下，愛吃冰的你一定要愛上它!\r\n產地直送，如何訂購:  曙光玫瑰莊園', '嘉義縣番路鄉新福村大庄1-16號', '05-259-2932', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19125/480x360_202103076.jpg', 23.458475, 120.530321),
(71, '媠茶Sweet Day Herb Tea', '首創以四大美人西施黛玉飛燕貴妃為發想，設計開發出最具故事性，且最精緻的草木本植物沖泡飲\r\n產地直送，如何訂購: 大智慧養生農場', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19127/480x360_202103077.jpg', 0, 0),
(72, '鰲鼓海藻醋', '在風和日麗北緯23.5度東石向禾漁場營造以紅樹林生態的友善環境養殖，養殖低碳低電的海菜混養低密度的魚蝦蟹貝螺形成食物鏈，結合貓狗羊鳥等動物來協助管理漁場，不用任何藥物並搭配智慧水質管理系統，搭配在地小農養殖出高營養高膠原蛋白的海菜\r\n產地直送，如何訂購: 向禾休閒漁場', '嘉義縣東石鄉鰲鼓村12鄰四股67之6號', '05-360-0959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19129/480x360_202103078.jpg', 23.507773, 120.148785),
(73, '精油手工皂旅行組伴手禮', '讓消費者可以同時感受彷彿進入森林的芬多精體驗，並且盡力達到無毒無汙染的天然永續\r\n產地直送，如何訂購: 五柳園休閒農場', '嘉義市東區盧厝里8鄰盧厝44之13號', '05-271-9500', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19131/480x360_202103079.jpg', 23.48969824871362, 120.48877716064453),
(74, '琉璃茶享', '琉璃茶享茶便當系列:內包含3款阿里山特色茶-冷韻烏龍、甘醇金萱、蜜香紅茶，以原片包裝的長條形茶包，適合冷泡及熱泡，是外出旅行及上班族的不二選擇', '嘉義縣竹崎鄉中和村20鄰19號', '05-256-1523', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19133/480x360_202103080.jpg', 23.46530077658772, 120.68995624780655),
(75, '古法燻羊肉', '古法燻羊肉採用在地放野山羊、13種珍貴中藥材及台灣菸酒公司米酒一起放入大甕中，經一天一夜用稻殼燜燻而成，羊肉口感獨特，入口即化。\r\n產地直送，如何訂購 : 王家燻羊肉', '臺南市龍崎區土崎里烏樹林34號', '06-594-1393', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19135/480x360_202103081.jpg', 23.005962148216614, 120.3888487815857),
(76, '鴨爸爸的蛋-鴨爸蛋捲(原味)', '台南鴨莊自家生產新鮮鴨蛋 搭配天然奶油 低筋麵粉 砂糖 沒有防腐劑 香濃味美。\r\n產地直送，如何訂購: 台南鴨莊休閒農場', '臺南市官田區渡拔里三塊厝178-1號', '06-690-1101', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19137/480x360_202103082.jpg', 23.1735158, 120.3382861),
(77, '筍漬-醬筍', '農場女主人蔡媽手作的農情伴手禮，區別於一般醃醬菜的重鹹口味，只有甘甜復古滋味，循古法製作，融合了健康概念的筍漬，醬菜也可以很食尚。\r\n產地直送，如何訂購: 大坑休閒農場', '臺南市新化區大坑里82號', '06-594-1555', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19139/480x360_202103083.jpg', 23.0072204, 120.3904996),
(78, '無糖愛文芒果乾', '採用自家有產銷履歷的愛文芒果為原料，並用手工低溫烘焙，保留芒果的原汁原味，且用手工的善意呼應食材真正的價值\r\n產地直送，如何訂購: 小崇ㄉ果園', '臺南市玉井區中山路55號', '0980-036-320', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19142/480x360_202103084.jpg', 23.1205738, 120.4636415),
(79, '足達桑竹炭防潮除臭包', '竹材取材自龍崎在地筍園第二年生竹母，為有利竹筍生長而伐下之廢棄竹材，絕對不經化學使用過程，既環保又為安心竹材。為本會自產竹炭，生產過程皆經標準程序，所有加工都由農會自行作業，因此可反映實惠價格。\r\n產地直送，如何訂購: 龍崎區農會 (longcifa.org.tw)', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19143/480x360_202103085.jpg', 0, 0),
(80, '裏 台味', '明信片式的旅行感受分享，龍眼花茶獨特性高，並深度連結在地的「與山放伴」價值。\r\n產地直送，如何訂購: 仙湖休閒農場', '臺南市東山區南勢里大洋6-6號', '06-686-3635', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19145/480x360_202103086.jpg', 23.2659335, 120.4822898),
(81, '元氣飲', '500斤虱目魚骨+8隻全雞(雞隻選用牧大養雞場，動物用藥0檢出，無抗生素及成長激素)熬製3天2夜，萃取虱目魚精華，溫潤順口，鋁箔包裝加熱方便，浸泡熱水即可飲用。術後、產後、哺乳期間及成長發育中的小朋友最佳天然補充品。\r\n產地直送，如何訂購: 田媽媽長盈海味屋', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19147/480x360_202103087.jpg', 0, 0),
(82, '芭樂葉桂桑桑茶', '本農場有機芭樂客戶常談到自己或家人有血糖困擾，經查台灣目前有 200萬人有這個困擾。經有關中醫及學術界專家提供資訊將芭樂葉桑葉及肉桂葉結合有這方面養生功能，這些本農場都有種植，故江浙有機栽種的材料研發成袋茶包方便隨身攜帶使用，達養生效果。\r\n產地直送，如何訂購：乾坤有機生態農場', '屏東縣萬巒鄉新厝村新平路73號', '0937-692-657', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19149/480x360_202103088.jpg', 22.55917161715641, 120.62750101089476),
(83, '鳳梨豆鼓醬', '單一果園 自產自製自銷 使用鴻旗有機鳳梨 獨特客家手工釀製 少許鹽 慢慢甕釀製\r\n產地直送，如何訂購 : 鴻旗有機休閒農場', '屏東縣高樹鄉泰山村25鄰產業路330號', '08-796-7301', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19151/480x360_202103089.jpg', 22.7952705, 120.6111629),
(84, '阿信經典禮盒', '以一壺迷人香氣、不含糖、無咖啡因的可可茶，佐以健康烘烤可可杏仁果，嚴選阿信經典商品，一次品嚐精緻可可的美好\r\n產地直送，如何訂購 : 阿信經典禮盒', '屏東縣恆春鎮山海里萬里路27之8號', '08-886-9696', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19153/480x360_202103090.jpg', 21.9973517, 120.7048353),
(85, '天使之約花禮禮盒', '天使花園從事專業文心蘭及熱帶蘭花生產25年，希望讓花成為一種媒介，在人、空間和時間之間傳遞情感、建立關係，將大自然給予的禮物傳遞給每個人，所以將外銷日本、法國的技術運用在花禮盒上，讓台灣民眾也能與所愛的人共享美好。讓伴手禮不僅僅侷限在食品類，用不同以往的花卉禮盒帶來不同的感動。用舞動著生命美妙的檸檬綠文心蘭、熱情的火焰美人腎藥蘭、象徵勇敢的萬代蘭，注入一股溫暖幸福的力量，帶來一份花卉的驚喜饗宴。', '屏東縣竹田鄉鳳明村福安路120巷101號', '08-780-1699', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19155/480x360_202103091.jpg', 22.5646808, 120.5136058),
(86, '黃金果禮盒', '頂級黃金果，友善自然農法種植，營養成分極高，意象福氣，是健康伴手禮的好選擇\r\n產地直送，如何訂購: 不一樣鱷魚生態休閒農場', '屏東縣潮州鎮太平路600巷108號', '0911-746-860', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19157/480x360_202103092.jpg', 22.56269878679782, 120.535147190094),
(87, '微棲所', '每一個人心中都有一座秘密花園(或森林)，共享柚園對環境的美好傳遞對生態的愛與用心，你照顧植物，植物也照顧你。將「柚園」生態庭園的元素(如：植物，石頭、枯枝等)，裝入瓶中，耐陰植栽，容易照顧，偶爾澆水。在家自己安靜的依照說明書DIY，享受自己獨處的時光，與心林對話。\r\n產地直送，如何訂購 :柚園生態農場', '屏東縣麟洛鄉新田村16鄰民族路453-2號', '08-721-4446', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19159/480x360_202103093.jpg', 22.66577903929531, 120.55503845214844),
(88, '蘭欣辣汗辣椒醬伴手禮盒', '多年來生產全世界各種最辣的辣椒與加工，用傳統的加鹽醬漬日曬發酵工法製成有醬香的辣醬，用機器烘乾鮮紅的辣椒乾與粉，供應市場餐廳與網購\r\n產地直送，如何訂購: 蘭欣辣汗花果休閒農場', '屏東縣枋寮鄉中正大路666-8號', '08-871-7370', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19161/480x360_202103094.jpg', 22.37553554186325, 120.60230433940887),
(89, '芒果乾、黑豆、蘿蔔乾', '適地適種配合恆春季風生態種植開發農產品\r\n產地直送，如何訂購: 根源民宿自然生態旅遊休閒農場 | Facebook', '屏東縣恆春鎮省北路二段 568 號', '08-889-7858', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19165/480x360_202103096.jpg', 22.051521232957576, 120.72405517101288),
(90, '蜜汁燻茶鵝', '燻茶鵝風行全台各地，而以下營薰茶鵝最有名，在民國七十九年八月，製作出全台第一隻蜜汁燻茶鵝。田媽媽鵝肉料理餐廳18年來堅持以新鮮鵝肉製成蜜汁燻茶鵝，封存肉質鮮美，ㄟ營人的滋味，今年更定位品牌名稱為鵝鄉園，期待將美味鵝肉推出更上一層樓\r\n產地直送，如何訂購: 下營田媽媽鵝鄉園餐廳 (facebook.com)', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19167/480x360_202103099.jpg', 0, 0),
(91, '菱角五穀肉粽、菱角蓮子五穀素粽', '為了符合現代人的飲食養生觀念，菱成的菱角五穀肉粽與菱角蓮子五穀素粽採用高纖維的雜糧與糯米結合，讓營養與口感兼具。', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19169/480x360_2021030101.jpg', 0, 0),
(92, '九品蓮花茶蓮花好星情', '喝個蓮花茶，你的人生即將開始改變 最適合一週七天都能喝的茶 再忙再累也要補足正能量 消除體內的不安 煩躁與負面情緒 至少我們還能擁抱自己的身心靈 溫和安定的蓮花茶能讓人卸下身心壓力，放鬆享受淡淡的茶香與氣息。靜聽花開，坐喝茶舒\r\n產地直送，如何訂購: 九品蓮花生態教育園區 (wunme.com)', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19171/480x360_2021030103.jpg', 0, 0),
(93, '愛鳳醬', '打破傳統蔭鳳梨包裝，搖身一變成為時尚伴手禮，金色的山脈，象徵山上區物產豐饒，亦有金山銀山送到家之喜氣之意，附贈多道愛鳳醬料理食譜，方便料理，罐罐真材實料，不管是小資族或媽媽族絕對是您廚房缺一不可的烹飪幫手!\r\n產地直送，如何訂購 :山上區農會', '臺南市山上區山上村238號', '06-578-1811', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19173/480x360_2021030104.jpg', 23.10162989999, 120.3556409999),
(94, '桑椹蜜果', '一般的蜜餞都是濕濕的，也因為這樣他通常都需要比較多的糖及保存劑，有些甚至會為了增加風味而添加許多香料讓你覺得好吃，這款桑椹蜜果的做法 先使用新鮮的桑椹稍微蜜製後！直接低溫烘焙，這樣可以減少加入的糖分也能讓大家吃到新鮮桑椹的味道，由於烘焙控溫技巧的關係！他的口感吃起來有點像「軟糖」，也能吃到裡面桑椹籽「脆脆」的口感，市售真的非常少見！\r\n產地直送，如何訂購: 大樹張媽媽', '高雄市大樹區興田路116-1號', '07-656-3635', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19175/480x360_2021030105.jpg', 22.747174358116073, 120.44812560081482),
(95, '暖開雞', '我們的滷味在製作過程中皆是選用國產雞肉，並且不添加任何人工保鮮劑，讓民眾買時可以吃得安心健康並且強調在吃進第一口時就能回憶起小時候放學回家媽媽(阿嬤)從廚房裡端出的點心，那種難以忘懷的感動，雖是冷食但心卻是溫暖的!', '高雄市仁武區中正路137號', '07-3711331', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19177/480x360_2021030106.jpg', 22.702223897743032, 120.34944589656905),
(96, '鮮羊乳冰淇淋', '鮮羊乳霖淇淋使用人工授精楊枝所生產的100%低溫鮮奶羊乳全奶單一乳源的堅持下，讓濃濃奶香化在嘴裡就像簽了一隻羊\r\n產地直送，如何訂購 : 禾光牧場-羊咩咩的家', '高雄市路竹區甲北里永華路302之96號', '07-696-1317', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19179/480x360_2021030107.jpg', 22.8903306, 120.2756294),
(97, '台灣金石咖啡濾掛式咖啡隨身包', '在地經營15年從農地耕作後製處理最終加工自行包辦也幫助在地農民推廣可為屏東咖啡的代表\r\n產地直送，如何訂購:台灣金石咖啡休閒農場', '屏東縣萬巒鄉赤山村沿山路1段500號', '08-783-2558', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19181/480x360_2021030108.jpg', 22.5849127, 120.617113),
(98, '青芒果棒棒冰', '-在成熟之前遇見你，有點青澀卻依舊美好-和你見面之前，必須承認我是那樣的緊張 用洗、削、泡、剖、沖、漬、凍七道手續 把自己整理成最好的樣貌 或許看起來還是有點青澀 也沒有太過華麗的添加 但是酸中帶甜，甜中有酸的滋味 不是更耐人尋味嗎？\r\n產地直送，如何訂購: 枋山觀光農園', '屏東縣枋山鄉國中路3號', '0935-470-498', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19183/480x360_2021030109.jpg', 22.263342895876047, 120.66105008125305),
(99, '磚砌龍鳳-旺來酥', '三溪沖積的沃土與水質水源保護區的優良條、加上南國的艷陽豐日和長達20個月呵護，讓高樹鄉的「金鑽」鳳梨，不僅僅是14-16的高甜度，更有著香氣濃郁與風味十足的特性，透過一雙雙自信且不畏命運的小手，手工捏製，完成了一個個香酥不膩的旺來酥，不僅展現著手藝、也是向著希望的疾聲吶喊~', '屏東縣高樹鄉舊寮村10鄰萬興路33號', '0937-665688', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19185/480x360_2021030110.jpg', 22.85102052678838, 120.62931418418884),
(100, '蓮花雞湯', '蓮花雞湯採用自家生態有機蓮花池蓮花製作蓮花雞湯,花蓮羅山放山雞熬煮,自然而成的甘甜滋味,加上紅棗黃耆枸杞等中藥材,不添加人工添加物,且擁有SGS嚴格把關,品質有保障', '花蓮縣富里鄉羅山村9鄰7號', '03-882-1873', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19191/480x360_2021030113.jpg', 23.205299657514622, 121.27225041389465),
(101, '布農炮仔雞湯禮盒系列', '雞仔住在山中，族人為了保護小雞，就用沖天炮喊驅趕調皮的猴仔們，因此被稱為「炮仔雞」。 放山的炮仔雞，天然熬煮無味素，雞湯濃郁滑順，喝得到山林的野生與奔放。\r\n產地直送，如何訂購: 布農炮仔雞湯禮盒系列 | 線上購物 | 布農部落休閒農場 Bunun Tribe Leisure Farm', '臺東縣延平鄉桃源村11鄰昇平路191號', '08-956-1211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19193/480x360_2021030114.jpg', 22.905841725183507, 121.09098270535469),
(102, '水晶冰卷、小魚干貝醬（日式原味、和風沙茶）、小管醬', '水晶冰卷為來自無汙染的澎湖海域之大尺寸小管，加以汆燙製成。當漁船捕撈漁獲後會將小管放置於活魚艙，使之保持活體狀態，而後汆燙完需經一道冰鎮程序，再急速冷凍、真空包裝等程序。如此一來，讓您將之稍微退冰後，打開包裝並切片即可給予最特別的您品嘗到來自澎湖最新鮮、最甜美的澎湖水精靈－水晶冰卷！ 小魚干貝醬、小管醬之原料－丁香小魚、小管乾、蝦米等食材選自無汙染的澎湖海域。元貝田媽媽傳承美食經典工夫，存封大自然的海味，精心煨炒獨家醬汁，散發出細膩綿密、香濃醇厚的口感，最佳下酒、烹煮料理、私房小菜極品。\r\n產地直送，如何訂購: 元貝田媽媽 x 元貝漁場', '澎湖縣白沙鄉岐頭村20-2號', '06-993-2305', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19195/480x360_2021030115.jpg', 23.64964150101733, 119.6092700958252),
(103, '星月灣澎湖高麗菜酸', '看過30幾斤的高麗菜嗎?澎湖特有栽培的(烏崁種)高麗菜像桌面那樣.越大越好吃頭家嬤利用自家雞肥及農牧人家的羊肥.捨棄化肥無毒栽種更加健康.古法醃製不含畫添加物\r\n線上訂購:星月灣海田料理餐廳', '澎湖縣西嶼鄉大池村131號', '06-998-3455', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19197/480x360_2021030117.jpg', 23.614564525123814, 119.51455593109131),
(104, '文山包種茶粽', '「文山包種茶粽」是道地的北部粽，不但名字含有「包中」之寓意，餡料包括獨家滷汁慢火燉煮的瘦肉、農家自行炮製的蘿蔔乾、精選香菇、土豆等，以及當地茶農自產自銷的高品質包種茶末，保留茶葉中珍貴的維生素，讓茶粽吃起來多了清香味，不油膩，健康又美味。', '新北市坪林區北宜路八段141號', '02-2665-6041', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19199/480x360_20210303(1).jpg', 24.9347019, 121.7067455),
(105, '紫蘇梅', '每一顆梅子都是製程的期待每一個步驟都是認真的對待每一個客戶都是健康的交代\r\n產地直送，如何訂購: 田媽媽桑園工坊', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19201/480x360_202103068(1).jpg', 0, 0),
(106, '烏龍茶梅酥', '餅皮加入烏龍茶粉，以南投Q梅為內餡，烏龍茶粉的清香搭配Q梅的清爽口感，這是屬於竹山的味道。\r\n產地直送，如何訂購:田媽媽幸福田心', '南投縣竹山鎮延平里東鄉路3之9號', '04-9265-8350', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19203/480x360_202103069(1).jpg', 23.762702008880524, 120.72248574346304),
(107, '茶葉禮盒', '高山茶種植於海拔一千公尺以上，其氣候終年雲霧繚繞，氣溫涼爽，日夜溫差大，日照較短，使得茶樹生長速度較慢，芽葉成份中兒茶素類等苦澀成分低，茶胺酸等甘味成份含量提高，且芽葉柔軟、葉肉厚，果膠質含量高，因此茶湯色澤翠綠鮮活，滋味醇厚，喉韻強勁，香氣淡雅持久，口感清香順口、回甘，別有一股高山韻味，喉韻無窮。\r\n產地直送，如何訂購: 阿里山民宿-阿里山龍雲農場', '嘉義縣竹崎鄉中和村石棹1號', '05-256-2216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19205/480x360_2021030100(1).jpg', 23.48721860682342, 120.70360064506531),
(108, '活體蛤蜊', '哈哈漁場處於 彰化名列台灣文蛤前三大產區，而位於斗苑休區、漢寶專業養殖區的「哈哈漁場」，也以養殖 文蛤著稱，並混養白蝦、虱目魚、黃錫鯛等魚蝦。漁場在主人陳明瞭的精心規劃下，來到這裡不但 可以下水「摸蛤仔」，還有「漁夫牽魚」、「收蛇籠捕蝦」等特色活動可以參加，藉由親自操作、 切實了解漁夫工作以及各種不同的捕魚工具如何利用。此外，在陳明暸親切活潑的帶領及講解下， 大家還能在充滿歡笑的輕鬆氣氛中進一步了解當地河口生態，並就地享用「尚青」魚場、採買新鮮 的活力蝦、元氣蝦等魚場特產，開心感受「一日漁夫」的生活！ 明瞭哥原本是做工廠的，後來中年的時候在思考要轉職，當時就決定回來家鄉做養殖業，起先 他先跟別人租養殖魚塭，慢慢拓展到有自己的魚塭，在做養殖魚塭的同時，他也思考要如何將這裡 的生態環境以及漁業概念傳遞下去，就先開啟作海岸教育的活動（講解生態等等），大約六年前左 右才開始規劃比較完整的一套體驗活動，明瞭哥採取的方式，適用較天然且貼近自然的魚塭做生態 講解， 並且實地教大家如何牽罟、摸蛤仔，還可以體驗 DIY 做魚丸、魚鬆等，可以說是最好的教育 場所。\r\n \r\n產地直送，如何訂購: https://www.facebook.com/hahafish168', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19210/480x360_哈哈漁場.jpeg', 0, 0),
(109, '風將烏魚(子)禮盒', '本產品由福樂休閒漁村自家養殖的烏魚加工製作生產:1.養殖過程都經過定期送檢2.製作出的產品皆經過ETC檢驗合格', '新竹縣竹北市鳳岡路五段155巷65弄86號', '03-556-2690', '', 24.8624071, 120.9427021),
(110, '偷偷醬', '商品介紹\r\n採用安心草莓製作出全家都適合的草莓醬；有小孩愛的減糖甜草莓醬、媽媽愛的低糖酸草莓醬、爸爸愛的驚艷辣草莓醬；滿足全家需求。堅持無人工添加物、無添加果膠、無香精、無防腐劑、符合380項農藥檢查，生菌檢驗合格。美味之外更堅持安心！\r\n產品故事\r\n連果子狸偷都愛吃的草莓就是最好的認證！所以以果子狸為草莓代言人；以品質純凈甜水鴛鴦湖水源灌溉、室內網室栽種，精心挑選草莓品種，不使用化肥，增添益生菌栽種，讓每位朋友吃的安心\r\n品牌故事\r\n在地種約40年，堅持無農藥栽種、添加益菌種植，夜晚更有果子狸結群偷吃，讓大自然能以友善循環共生\r\n遊程規劃\r\n半日遊：莓圃位處台北的白石湖休閒農業區山區，週遭鄰捷運15分鍾，擁有全台最大的聖王公廟，被視為漳州人的守護神，再步行穿越白石湖吊橋一覽群山風光，探索天然湧泉古錐碑湧水、漫步在同心池裡，在到莓圃採安心草莓，品嚐草莓披薩及草莓大餐\r\n購買專線：02-27951108\r\n聯絡信箱：s382.garden@gmail.com\r\nFB：莓圃休閒農園\r\nIG：莓圃休閒農園 餐廳', '臺北市內湖區碧山路38-2號', '02-2795-1108', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19212/480x360_1-莓圃休閒農園-偷偷醬(4).jpg', 25.1025774, 121.5886641),
(111, '風味典藏禮盒', '商品介紹\r\n紅茶加入鐵觀音的烘焙特色，新開發出炎韻焙香紅，具有淺焙咖啡的烘焙香，超越市售紅茶的甘甜柔順口感\r\n產品故事\r\n茶職人追求比完美多一分，用鐵觀音的烘焙工法.提升紅茶風味層次，焙火韻味及紅茶香，刺激度下降更甘甜。\r\n品牌故事\r\n好茶是天地人的結合.張恩沛.政治大學神經科學所校友，生長在茶農世家，2014年張恩沛放棄穩定的生技業工作，離職後走回習茶之路。\r\n遊程規劃\r\n半日遊：貓空纜車站-茶路古道-鴻智茶場-茶園導覽--製茶程序解說導覽-品茶師體驗/一日遊:貓空纜車站-炭窯導覽-豬舍導覽-樟樹步道導覽-彩雲亭明鏡池賞花-水牛公園-光羽鹽套餐-鴻智茶場-製茶過程導覽-品茶師體驗-茶藝師茶席體驗\r\n購買專線：0918-108470、02-23935810\r\n聯絡信箱：wlh0000@gmail.com\r\nFB：鴻智茶場 Taipei Ancient Tea Road Space', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19214/480x360_2-鴻智茶場-風味典藏禮盒.jpg', 0, 0),
(112, '蜂蜜禮盒組', '商品介紹\r\n國產蜂蜜，特色蜂蜜、綠色保育及有機標認證休閒農場產出\r\n品牌故事\r\n農場主人帶著蜜蜂四處逐花而居，過著遊牧式的生活，養蜂人對四季的掌握、對環境的了解，在台灣不同的地點採集不同的蜂蜜，透過蜜蜂將自然的味道採集成蜂蜜呈現給消費者\r\n遊程規劃\r\n早上10點入園，10:15園區生態導覽，10:50蜜蜂生態導覽，12點用餐，13.30蜂蠟蠟燭DIY，14:00自由活動15:00回程\r\n官網：牧蜂農莊\r\nFB：牧蜂農莊', '新北市三芝區茂長里9鄰74號', '02-2636-3742', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19216/480x360_3-牧蜂休閒農場-蜂蜜禮盒組.jpg', 25.1991895, 121.465923),
(113, '手染方巾茶包組', '商品介紹\r\n從地方特色出發的天然染巾，採用在地農產茶葉和柚子葉為染材，適合隨身攜帶的手帕，純天然材質無負擔，染布花樣凸顯個人生活品味。\r\n產品故事\r\n古意手染真巾采，乃蘭陽天然手染技術製作，採用友善耕作無毒的茶柚農產為染材，染出獨一無二的色彩，帶有淡淡的茶柚香氣。冬山紅茶採用小葉茶品種，特有的製茶技術及自然氣候環境，培育出帶有花香味的冬山天然好茶。\r\n品牌故事\r\n104年成立的古意生活藝術館，是一個集&ldquo;古厝文化、民俗家居、鄉村人文&rdquo;為一體的集合空間，其位於宜蘭縣冬山鄉中山休閒農業區，原型為宜蘭傳統一條龍六開間老厝，經主人李日成夫婦改造，成就如今煥發人文生命力的古意館舍。 館舍名有思古之意，想要帶給人們的，是老空間、老家具的在地文化融合，是蘭陽特有的人情味，是返璞歸真的生活文化脈絡，是在地人文藝術的展演平台，也是友善小農、社區居民、藝文團體一同實踐地方永續發展的共好生活價值。\r\n遊程規劃\r\n一日遊：古意生活藝術館手染布巾/餐飲+仁山植物園（或新寮瀑布）踏青+茶園採茶體驗\r\n購買專線：03-9580990\r\n聯絡信箱：antiqueinn.bnb@gmail.com\r\nFB：古意生活藝術館', '宜蘭縣冬山鄉中山村新寮路461巷28號', '0921-100-818', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19218/480x360_4-古意生活藝術館-手染方巾茶包組.jpg', 24.6228431, 121.754128),
(114, '椿風滿麵', '商品介紹\r\n用苦茶油代替沙拉油，口味獨特，方便拌飯拌麵，兩款皆純素可以食用，露營夥伴更加喜愛，只要一罐，皆可料理不一樣菜色。\r\n產品故事\r\n家家戶戶廚房必備快速上菜拌醬，吃好油排壞油，輕鬆快速無負擔\r\n品牌故事\r\n好樂農莊是以友善土地、食農教育為出發點，結合桌遊與烹飪等體驗活動，期望以寓教於樂的方式，讓更多的民眾認識食物從產地到餐桌的歷程。第二代經營者賴建宏與江嘉維夫妻，繼承創辦人賴朝才的理念，採用山中流金龍眼品系小果茶籽，生產冷壓純鮮榨苦茶油。「苦茶油」是一種香醇味甘，氣味芳香的本產高級植物性油脂，華人食用苦茶油已經有超過兩千年的歷史，本草綱目、天工開物等古書皆有記載，坊間也流傳許多建胃強身、美髮護膚、坐月子等用途，加上近年消費者開始重視油品的食用安全，因此煎、煮、炒、炸、涼拌都合適的苦茶油逐漸在市場上展露優勢。 早期臺灣社會將苦茶苷拿來洗碗盤及沐浴，好樂農莊延續古人智慧，並透過技術改良創新，打造多元的苦茶清潔產品，希望將臺灣特有的苦茶文化永續傳承。我們除了分享美好的景色事物外，更希望能成為繁忙都市人心中的一片淨土，讓大家能遠離塵囂，放鬆心情、重新喚起人們對飲食生活與健康、農業、親子及自然環境的重視。\r\n遊程規劃\r\n半日遊：軟埤坑天梯健行與歷史文化導覽，午餐享用當地農村午餐，手作苦茶油DIY.一日遊：農場闖關食農實景體驗，農村廚房體驗親自下廚，體驗現榨苦茶油，手作體驗。\r\n購買專線：0910-989477\r\n聯絡信箱：amie0917@ymail.com\r\n官網：好樂農莊\r\nFB：好樂農莊\r\nIG：好樂農莊/禪林休閒農場', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19220/480x360_5-好樂農莊休閒農場-椿風滿麵.jpg', 0, 0),
(115, '籤詩福椒餅', '商品介紹\r\n黃金鵝油僅取至鵝隻臀部兩側油脂，一隻鵝僅能取出約500克鵝油，精製提煉後僅能產出約100~120公克的黃金鵝油，檢驗中反式脂肪酸的&ldquo; 0 &rdquo;檢出，表現出黃金鵝油的健康取向，使用黃金鵝油製作福椒餅，讓您放心呷零食呷健康。 福椒餅是大人們追劇配啤酒、好友聚會「紲喙」的好夥伴。 孩子們吃甜點不如吃鹹餅乾，特製微微微辣福椒餅，讓孩子們也可以一口接一口，減少蛀牙的機率。 籤詩餅裡的籤詩，希望也可以為人們帶來好心情。\r\n產品故事\r\n以金蔥鵝油為主要設計常溫產品，讓遊客可以延長帶回家的時間，健康的黃金鵝油每隻鵝只能取出121g，不飽合脂肪酸為動物油脂之冠，反式脂肪酸未檢出，可安心食用。\r\n品牌故事\r\n創意鵝肉料理．盡在鵝鄉園 鵝鄉園創立於1979年，最初主要以飼養與平衡鵝肉市場為主，後加入傳統鵝肉料理市場，成立了「下營鵝肉專賣店」，于2003年加入農委會田媽媽輔導體系，開創出有別於傳統鵝肉的鵝肉創意料理始端。 2020年由農委會輔導成立「鵝鄉園」品牌，以推廣在地鵝肉特產為理念，結合「下營香」在地民俗文化設計鵝鄉園logo，以傳統中帶點現代文化設計，加深顧客對鵝鄉園的印象。\r\n遊程規劃\r\n「鵝鄉園」周遭景點，下營武承恩公園、白鵝生態教育農場、新營糖廠五分車、柳營酪農區、德元埤荷蘭村、六甲落羽松、官田水雉復育區、麻豆總爺文化糖廠、烏山頭水庫&hellip;&hellip;等等多處休閒景點，上午時間可安排至白鵝生態教育農場參觀了解鵝的生態，體驗鵝蛋彩繪DIY活動，中午時間到「鵝鄉園」享用鵝肉特色餐點，選購鵝系列伴手禮回家贈送親朋好友，如金蔥鵝油平安麵、籤詩福椒餅、蜜汁燻茶鵝禮盒、香滷鵝翅．腳．胗真空包系列&hellip;&hellip;等等。\r\n購買專線：06-6792318\r\n聯絡信箱：cjoy670711@gmail.com\r\n官網：鵝鄉園\r\nFB：下營田媽媽鵝鄉園餐廳', '臺南市下營區中興南路21號', '06-679-2318', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19222/480x360_6-下營田媽媽鵝鄉園餐廳-籤詩福椒餅.jpg', 23.2399892, 120.2745169),
(116, '金蔥鵝油平安麵', '商品介紹\r\n黃金鵝油僅取至鵝隻臀部兩側油脂，一隻鵝僅能取出約500克鵝油，精製提煉後僅能產出約100~120公克的黃金鵝油，檢驗中反式脂肪酸的&ldquo; 0 &rdquo;檢出，表現出黃金鵝油的健康取向，讓您食好油呷健康。\r\n產品故事\r\n平安麵故事定位：\r\n1.結合下營的在地文化意象，期盼引領出思念故鄉的滋味。 下營北極殿玄天上帝廟，為下營當地重要的信仰中心，距今已有三百多年的香火歷史，每三年便有一次遶境，當地稱之為「下營香扛大轎」。運用上帝公的龜、蛇、犁轎等元素，將信仰文化融入包裝，拌上下營四寶之一~鵝油，呈現出最道地的下營香，讓大家平安、健康、歡喜、呷百二。\r\n2.愛鵝樂~「呷台灣五穀，思念丹麥香」 台灣肉鵝品種來自 丹麥 ，屋簷下飼養的白鵝昂頭思念丹麥的草香，低頭呷台灣的五穀雜糧， 鵝肉肉質鮮嫩甜美，鵝蔥油拌麵，品嚐故鄉的滋味。\r\n品牌故事\r\n創意鵝肉料理．盡在鵝鄉園 鵝鄉園創立於1979年，最初主要以飼養與平衡鵝肉市場為主，後加入傳統鵝肉料理市場，成立了「下營鵝肉專賣店」，于2003年加入農委會田媽媽輔導體系，開創出有別於傳統鵝肉的鵝肉創意料理始端。 2020年由農委會輔導成立「鵝鄉園」品牌，以推廣在地鵝肉特產為理念，結合「下營香」在地民俗文化設計鵝鄉園logo，以傳統中帶點現代文化設計，加深顧客對鵝鄉園的印象。\r\n遊程規劃\r\n「鵝鄉園」周遭景點，下營武承恩公園、白鵝生態教育農場、新營糖廠五分車、柳營酪農區、德元埤荷蘭村、六甲落羽松、官田水雉復育區、麻豆總爺文化糖廠、烏山頭水庫&hellip;&hellip;等等多處休閒景點，上午時間可安排至白鵝生態教育農場參觀了解鵝的生態，體驗鵝蛋彩繪DIY活動，中午時間到「鵝鄉園」享用鵝肉特色餐點，選購鵝系列伴手禮回家贈送親朋好友，如金蔥鵝油平安麵、籤詩福椒餅、蜜汁燻茶鵝禮盒、香滷鵝翅．腳．胗真空包系列&hellip;&hellip;等等。\r\n購買專線：06-6792318\r\n聯絡信箱：cjoy670711@gmail.com\r\n官網：鵝鄉園\r\nFB：下營田媽媽鵝鄉園餐廳', '臺南市下營區中興南路21號', '06-679-2318', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19224/480x360_7-下營田媽媽鵝鄉園餐廳-金蔥鵝油平安麵.jpg', 23.2399892, 120.2745169),
(117, '泥火山豆腐乳', '商品介紹\r\n鹹度經過無數次的試驗,韻味香濃的酒釀味，從唇齒間占據整個口腔，鹹的恰恰好入嘴鬆軟，再挑剔的味蕾，都只剩投降的份兒。加上無任何添加物，說是五星級的豆腐乳一點也不為過！泥豆府的豆腐乳，將有機的自產黃豆花蓮一號自然攤曬在暖陽下，米粕在一旁恣意地發酵，給予食材自由的結果，造就豆腐乳獨特的綿密口感 經過發酵製成的豆腐乳，不管是偏甜、辣味，都能與威士忌交融出特有風味。在此推薦可用高纖麥餅當作小湯匙，挖一小口豆腐乳佐威士忌，彷若起司的creamy口感與麥餅脆香，在威士忌帶來的尾韻中更能讓人細細品嚐豐厚滋味。\r\n產品故事\r\n羅山地區的居民早在日治時期， 因當時缺乏日常用品及生活物資，生活困苦在偶然間發現泥火山鹵水可代替石膏製作豆腐，但是新鮮豆腐的保存相對不易，於是有了豆腐乳的生產 將石磨與豆腐結合透過手寫字傳達出手作的溫度與親切感,一杯威士忌或麵包，配上一小匙的豆腐乳，是生活中的極簡美好！\r\n品牌故事\r\n羅山地區的居民早在日治時期， 因當時缺乏日常用品及生活物資，生活困苦在偶然間發現泥火山鹵水可代替石膏製作豆腐，但是新鮮豆腐的保存相對不易，於是有了豆腐乳的生產 將石磨與豆腐結合透過手寫字傳達出手作的溫度與親切感,一杯威士忌或麵包，配上一小匙的豆腐乳，是生活中的極簡美好！\r\n遊程規劃\r\n羅山有機村導覽(百年土角厝、羅山村大魚池、泥火山、羅山瀑布) &rarr;客家炒米香DIY（雞鳴園）&rarr;製作泥火山豆腐（羅山大自然體驗農家）\r\n購買專線：03-8821352\r\n聯絡信箱：mayaboa18@gmail.com\r\nFB：羅山大自然體驗農家', '花蓮縣富里鄉羅山村9鄰東湖6號(台9線310.3K)', '03-882-1705', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19226/480x360_8-羅山大自然工作坊-泥火山豆腐乳.jpg', 23.2068861, 121.2707853),
(118, '龍膽膠原蛋白飲', '商品介紹\r\n採用自家生態養殖龍膽石斑魚鱗新鮮萃取，無額外添加物，成分單純，無負擔。龍膽石斑不僅為珍貴的高膠原蛋白物種，且魚鱗蛋白分子小更好吸收。解凍即可直接飲用，適合全年齡層大小朋友。\r\n產品故事\r\n我們的魚塭內有超過20種魚種，從淨化功能的貝類到大型魚類龍膽石斑，形成一個自然的食物鏈，達到真正的生態養殖。且以自然微生物和益生菌自行發酵飼料，改善魚的免疫力。其中元氣飲、朝虱目想魚乾味、龍膽一夜乾，更是獲得海宴獎(水產界最高榮譽)的商品。\r\n品牌故事\r\n我們的魚塭內有超過20種魚種，從淨化功能的貝類到大型魚類龍膽石斑，形成一個自然的食物鏈，達到真正的生態養殖。且以自然微生物和益生菌自行發酵飼料，改善魚的免疫力。其中元氣飲、朝虱目想魚乾味、龍膽一夜乾，更是獲得海宴獎(水產界最高榮譽)的商品。\r\n遊程規劃\r\n田邊賞鳥，東隆宮文化中心參觀（不定期舉辦展覽活動），水晶教堂，北門遊客中心。\r\n購買專線：0917-549736\r\n聯絡信箱：s1072303@gm.pu.edu.tw\r\nFB：田媽媽 長盈海味屋', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19228/480x360_9-長盈海味屋-龍膽膠原蛋白飲.jpg', 0, 0),
(119, '巧克力禮盒', '商品介紹\r\n榮獲2018、2020年世界巧克力錦標賽亞太區2金2銀的原味黑巧及阿里山哇沙米巧克力超級組合禮盒，分享給您最在乎的人。\r\n產品故事\r\n來自屏東大武山下，以喜樂的心，堅持有機栽種，孕育出的世界頂級可可豆所打造的巧克力，呵護您最在乎的人。\r\n品牌故事\r\n一對夫妻來到好山好水的屏東大武山下石獅公故鄉，用喜樂的心，堅持有機栽種，孕育出世界頂級的可可豆。採tree to bar 巧克力製程特色，本著天然不添加的養生概念初衷，將自產可可歷經約1.5個月的繁雜製程工序，精煉出一片片味美香醇的黑巧克力，呵護您最在乎的人。\r\n遊程規劃\r\n走讀大路關客庄尋獅趣、屏北幸福185\r\n購買專線：0987-464633\r\n聯絡信箱：ckh560418@gmail.com\r\nFB：喜樂可可咖啡園\r\nIG：喜樂可可咖啡園', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19230/480x360_10-喜樂可可咖啡園-巧克力禮盒.jpg', 0, 0),
(120, '可可豆茶', '商品介紹\r\n以獲頒2019年世界可可豆錦標賽CoEx全球最佳前50及全球20強A級可可豆，直接經初級加工碾碎製成可可豆茶，與您分享。\r\n產品故事\r\n來自屏東大武山下，以喜樂的心，堅持有機栽種，孕育出的世界頂級可可豆所打造的巧克力，呵護您最在乎的人。\r\n品牌故事\r\n一對夫妻來到好山好水的屏東大武山下石獅公故鄉，用喜樂的心，堅持有機栽種，孕育出世界頂級的可可豆。採tree to bar 巧克力製程特色，本著天然不添加的養生概念初衷，將自產可可歷經約1.5個月的繁雜製程工序，精煉出一片片味美香醇的黑巧克力，呵護您最在乎的人。\r\n遊程規劃\r\n走讀大路關客庄尋獅趣、屏北幸福185\r\n購買專線：0987-464633\r\n聯絡信箱：ckh560418@gmail.com\r\nFB：喜樂可可咖啡園\r\nIG：喜樂可可咖啡園', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19232/480x360_11-喜樂可可咖啡園-可可豆茶.jpg', 0, 0),
(121, '蘭欣辣汗3罐組辣拌醬', '商品介紹\r\n以微辣羊角椒、炒食用青龍辣椒、中辣朝天椒結合在地鳳梨、芒果、農場薑黃與海味櫻花蝦、魩仔魚、蝦仁等，分別產出味道鮮美的辣拌醬與麻辣醬，可直接當菜餚或簡易拌炒食用，很符合現在生活簡單、方便、快的需求。\r\n產品故事\r\n低辣當菜餚、麻辣薑黃當運動流汗。\r\n品牌故事\r\n辣的驚喜：中央山脈大漢山與台灣海峽之間的平原，終日吹送溫熱的海風，加上日光照耀乾燥溫暖的環境，孕育出獨特的辣椒農場主人用傳統的加鹽醬漬，日曬發酵工法,製成有醬香的辣醬，每年結合在地小農當令水果，並添加當地新鮮魚獲，手工調製富含果香與鮮味的低辣拌醬，不僅是味蕾的驚喜，更是來自南台灣獨特的滋味。\r\n遊程規劃\r\n枋寮兩天一夜小旅行\r\nDay1 蘭欣辣汗花果休閒農場 - 芳興莊園 - 阮家天空餐廳 - 蘭欣辣汗花果休閒農場\r\n11:00~12:00 蘭欣辣汗花果休閒農場（方案二選一） \r\n12:00~ 14:00 蘭欣辣汗花果休閒農場採時蔬+火鍋 \r\n大人300  \r\n14:00~15:00 Check In 整理 \r\n15:00~17:00 1.蓮霧生長過程導覽解說 2.蓮霧雪Q餅製作 3.果乾試吃品嚐 4.谷哥評論五顆星，加贈清涼可口蓮霧冰沙一瓶 5.多採的部份另外計費\r\n17:30~19:00 阮家天空餐廳晚餐\r\n19:30~20:30 蘭欣辣和花果休閒農場夜間生態導覽＋觀星\r\nDay2 饗魚樂 - 平田永序有機芭樂農場\r\n10:00~12:30 饗魚樂 2.5小時＿含用餐 20人成團\r\n13:00~17:00 平田永序-有機芭樂農場\r\n購買專線：08-8717370\r\n聯絡信箱：a0919171042@gmail.com\r\n官網：蘭欣山莊\r\nFB：蘭欣辣汗花果休閒農場', '屏東縣枋寮鄉中正大路666-8號', '08-871-7370', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19234/480x360_12-蘭欣辣汗花果休閒農場-蘭欣辣汗3罐組辣拌醬.jpg', 22.37553554186325, 120.60230433940887),
(122, '台灣の梅禮盒組', '購買專線：04-92791949\r\n聯絡信箱：hsinifa@gmail.com \r\n採用台灣南投縣信義鄉產出之優質青梅，包裝採易開罐設計，取用方便，開封後可完全密封。口感Q彈，酸甜綿密，感受健康的傳統工法手藝。全採用天然蔗糖，完全不加任何人工色素及甘味劑。', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18122/480x360_11-103-10-南投縣-信義鄉農會-愛旦 台灣梅禮盒組-情境(400X320)-20151027111505.jpg', 23.68870099999, 120.861791),
(123, 'HAKA好醬', '商品介紹\r\n我們的產品著重在使用在地最天然最安全 ,完全草生栽培自然生長的好物,加工過程只添加最天然的鹽和糖及現榨的檸檬汁本著幫助在地老農的好物尋找出路,創造價值,也希望好物可以與大家共分享\r\n品牌故事\r\n職人匠心 客庄好醬 客庄職人承襲客家人的傳統祕方與工法， 用勤奮堅持的心 ， 將天然食材醃製釀造， 延長食用價值， 用醬食留住季節的恩典,享受土地的豐盛, 以做好醬,留好樣為使命，知足常樂。\r\n遊程規劃\r\n彩繪 手拉坏 蛋捲 藍染等 diy  餐點  鐵路自行車各個行程自由搭配\r\n購買專線：03-7878916\r\n聯絡信箱：MA41921@GMAIL.COM\r\n官網：雙潭休閒農業區\r\nFB：三義鄉雙潭休閒農業區', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19236/480x360_13-雙潭休閒農業區-HAKA好醬.jpg', 0, 0),
(124, '海藻多醣飲', '商品介紹\r\n海藻多醣飲是多醣體高含量的休閒食品，跳脫填，以親近小孩的包裝讓長青者與小孩都方便輕鬆攝取海藻多醣體營養多醣體營養\r\n產品故事\r\n以台灣的海底龍鬚菜作為原料，經過6洗6曬工時去做前置處理，結合當地社區海藻復養，以不抽地下水的有閃養殖方式飼養出正統台灣優質海藻。\r\n品牌故事\r\n在風和日麗，北緯23.5度，位於鰲鼓的向禾休閒漁場以紅樹林自然生態，輔以低碳低電方式養殖海藻，並混養低密度的魚蝦蟹貝螺形成食物鏈，不用任何藥物搭配水質管理系統，養殖著高營養的海藻。\r\n遊程規劃\r\n魚塭運動會：划船、摸文蛤、釣魚、烤蚵蚵\r\n購買專線：05-3600959\r\n聯絡信箱：yolo@yolofun.com.tw\r\n官網：向禾休閒漁場', '嘉義縣東石鄉鰲鼓村12鄰四股67之6號', '05-360-0959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19238/480x360_14-向禾休閒農場-海藻多醣飲.jpg', 23.507773, 120.148785),
(125, '金極烏魚子蛋黃酥', '商品介紹\r\n藍鯨水產 自然源選~擁有60公頃烏魚專業養殖區的水月休閒農業區，每年11月產量十餘萬尾優質魚類；座落於園區內的藍鯨水產，多年來，始終堅持嚴選在地食材，以最佳的製作比例研發美味的當季好物。堅持不使用化學添加物、不含泡打粉、乳化劑、香精色素等廉價速成的化學添加物，手工精準傳遞食材特質\r\n產品故事\r\n在地養殖漁業區自產的「烏魚子-烏金」 \r\n&diams;   嚴選竹北濱海養鴨人家「鹹鴨蛋-蛋黃」 \r\n&diams;   創造新視覺及味覺的衝擊設計，鹹香營養-金極烏魚子蛋黃酥\r\n品牌故事\r\n經典蛋黃酥與鮮香烏魚子的美味融合，包裝以黑底的方式呈現，利用簡約的金色線條來襯托出優雅、高貴的氣息，在送禮時更能凸顯出時尚品味，用簡約的圖騰設計來呼應出中秋年節的氛圍，再搭配上具有象徵和平、快樂、長壽、幸運的梅花，不管是佳節或是平時要送禮，都有祝福的意涵\r\n購買專線：03-5565577\r\n聯絡信箱：sasha512588@hotmail.com\r\n藍鯨魚寮FB', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19240/480x360_16-藍鯨水產企業社-金極烏魚子蛋黃酥.jpg', 0, 0),
(126, '親親米香', '商品介紹\r\n輕親米香 翻轉傳統米香的口味  大塭休閒農場 採用宜蘭在地元素 蘭陽平原的純淨水源稻米 太平洋海水滋養出的海鮮 鮮蝦  小魚  烏魚子 佐以三星蔥入味 您從沒吃過的海鮮米香 鹹甜鹹甜  就是要讓您一口接一口 用舌尖來記憶 親子一起同樂共學 美好的旅行時光\r\n產品故事\r\n大塭休閒農場傳承兩代專業養殖，以太平洋的豐沛，滋養出大塭純淨鮮甜魚蝦，屢屢翻轉漁業新體驗，遠近馳名備受好評。現因廣大饕客需求，應將新鮮魚蝦製作成伴手哩，全新口感送禮自用兩相宜，讓您輕鬆帶回不一樣的宜蘭豐沛海味，品嘗回味與孩子的親子共學，與於和你相遇。\r\n品牌故事\r\n大塭休閒農場在2020年成立次品牌-輕親魚朵:是一個提供親子體驗休閒的漁業生產園區，也已經在上半年已經打開知名度及穩定成 長中，繼而延績這個品牌概念，我們推出了米香系列的伴手禮，則，命名為「輕親米香」，本次開發三種海味米香分別為蝦米香、魚米香、烏魚子米香。\r\n購買專線：03-9870558\r\n聯絡信箱：sobrinaa22@gmail.com\r\n官網：大塭休閒農場\r\nFB：大塭休閒農場', '宜蘭縣礁溪鄉玉龍路二段497號', '03-987-0558', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19242/480x360_17-大塭休閒農場-親親米香.jpg', 24.819497045332145, 121.79645597934723),
(127, '有機手採玉露綠茶／有機烏龍茶', '有機手採玉露綠茶\r\n施行有機自然農法耕作，特選小葉種茶葉，人工採收一心二葉最嫩部位，全程低溫萎淍，含豐富兒茶素及茶多酚，夏天非常適合冷泡茶。\r\n有機烏龍茶\r\n有機烏龍茶以中發酵中焙火傳統方式製作，濃厚「果香」、口感內斂滑順甘香耐泡，沖泡後葉片展開葉中間呈綠色、葉緣呈紅色，有『綠葉紅鑲邊』美稱\r\n購買專線：0911-231454\r\n官網：玉露茶園\r\nFB：玉露茶園(玉露製茶廠)', '宜蘭縣大同鄉松羅村鹿場路10-2號', '03-980-1111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19244/480x360_3-宜蘭縣-玉露茶園-有機手採玉露綠茶-_(2).jpg', 24.66665, 121.5886883),
(128, '古米傳奇', '以自家榮獲2018世界巧克力錦標賽亞太區銀牌的66%原味黑巧克力風味結合在地原住民部落的馬告及台灣油芒，使巧克力除本身風味外，增添了香茅、檸檬、及爆米花的香氣口感，也讓消失60年的原民穀物重啟新頁。', '屏東縣高樹鄉廣福村廣福路30-1號', '0987-464-633', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19308/480x360_古米傳奇巧克力禮盒照片.jpg', 22.7604991, 120.6142116),
(129, '第一鰻波~胭脂鰻', '第一鰻波的鰻魚外銷日本多年並獲得好口碑，透過研究養殖技術，以益生菌改良水質並配合產銷履歷制度，嚴格管理養殖過程。鰻魚含有維生素A、E、EPA 、DHA及豐富的鈣與鋅及膠原蛋白，營養價值豐富，本產品精選肉質肥美、口感細緻入口即化的幼齒鰻魚製成，故取名【胭脂鰻】。', '雲林縣口湖鄉外埔路1-2號', '0963-120-203', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19250/480x360_2.第一鰻波工坊-第一鰻波~胭脂鰻.jpg', 23.6178327, 120.1630864),
(130, '綠川黃金蜆精錠\n後山洄甘苦瓜原片茶\n立川嚴淬滴魚精', '綠川黃金蜆精錠：立川漁場利用無污染的天然湧泉，活水養殖出高品質的黃金蜆。蜆以濾食綠藻為主，終其一生過濾了近一萬公升的湧泉菁華，富含豐富的蛋白。綠川蜆錠以蜆精乾燥濃縮而成，每罐蜆精約等於3顆蜆錠，營養價值不變且攜帶更方便。\n後山洄甘苦瓜原片茶：花蓮2號山苦瓜富含維生素A、B群、維生素C、E、菸鹼酸、葉酸、膳食纖維及三帖類等營養成分，可以促進新陳代謝、幫助調節生理機能的調節。\n立川嚴淬滴魚精：以台灣東部後山天然湧泉養殖的活力鯛為原料，淬煉過程嚴格控管火侯，全程絕不添加任何一滴水，滴滴珍貴。滴魚精含有極高的膠原蛋白及牛磺酸，是忙碌生活中方便補充的營養聖品。', '花蓮縣壽豐鄉共和村魚池45號', '0800-007111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19252/480x360_3.立川漁場-綠川黃金蜆精錠、後山洄甘苦瓜原片茶、立川嚴淬滴魚精.jpg', 23.864724954942012, 121.52217864990233),
(131, '桑椹果醬', '選用自家生產的桑椹為原料，將桑椹打碎加入微量的糖，經過四個小時熬香以及高温殺菌製成，真材實料，沒有添加果膠、澱粉、防腐劑、香料、色素或任何化學成分，是一款低糖好吃的天然桑椹果醬。', '高雄市大樹區興田路116-1號', '07-656-3635', '', 22.747174358116073, 120.44812560081482),
(132, '青梅竹馬禮盒', '購買專線：04-92791949\r\n聯絡信箱：hsinifa@gmail.com \r\n台灣の梅系列-古味梅、陳年梅、紫蘇梅\r\n全採用台灣南投縣信義鄉產出之優質青梅。採易開罐設計，取用方便，開封後可完全密封。口感Q彈，酸甜綿密，感受健康的傳統工法手藝。全採用天然蔗糖，完全不加任何人工色素及甘味劑。', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18714/480x360_20200328-11.jpg', 23.68870099999, 120.861791),
(133, '松子蘿勒醬', '採用自家場域栽種生產的有機九層塔，以末端嫩葉加入頂級橄欖油及松子、起司等上等原料，手工製成松子蘿勒醬，絕無添加任何防腐劑，是塗抹麵包、炒菜、拌麵拌飯、沾醬的料理好幫手。', '屏東縣萬丹鄉竹林村大學路230號', '08-776-1151', '', 22.5968275, 120.5144039),
(134, '有機東方美人茶、有機烏龍茶', '有機東方美人茶：經手工摘採一心二葉，以傳統技術進行揉捻、解塊、烘乾製成毛茶，再經分級、精製、焙火、包裝而成。茶葉白毫肥大，葉身呈白、綠、紅、黃、褐五色相間，有濃濃蜂蜜香及熟果味。\n有機烏龍茶：採傳統製作中發酵中焙火、重「果香」的特色為原則。口感內斂滑順，甘香耐泡，滋味甘滑醇厚，是令人懷念的古早味。烏龍茶經沖泡後，葉片展開，可見葉中間呈綠色，葉緣呈紅色，因此有綠葉紅鑲邊的美稱。', '宜蘭縣大同鄉松羅村鹿場路10-2號', '03-980-1111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19260/480x360_7.玉露茶園-有機東方美人茶、有機烏龍茶.jpg', 24.66665, 121.5886883),
(135, '春鳳蜜荔蛋捲禮盒組', '本產品開發設計與大樹休閒農業區結合，選用在地玉荷包荔枝、鳳梨為食材，配以黑芝麻與白芝麻烘製，包裝設計則融入鳳梨、玉荷包荔枝、黑白芝麻及產業文化故事等元素，讓農遊伴手不只是食品，而是從商品內容到包裝設計都能凸顯大樹特有鄉村風味之農遊伴手。', '高雄市', '無', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19262/480x360_8.川醮企業社-春鳳蜜荔蛋捲禮盒組.jpg', 22.6959848011, 120.4333011975),
(136, '甘梅湯', '「甘梅湯」是傳統的消暑酸甜飲料，手工碳焙、古法精釀，選用烏梅、冰糖、山楂、甘草等材料，熬煮出酸甜口感與特有氣味；夏天冰飲生津止渴、消暑清涼，冬季建議溫熱飲用，潤喉爽聲、去油解膩，是一年四季皆可飲用的良品。', '南投縣竹山鎮延和里安定巷142號1樓', '0933-522-530', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19264/480x360_9.耄饕客棧-甘梅湯.jpg', 23.7635541, 120.687042),
(137, '枇杷花烏龍', '枇杷花烏龍：來自國姓鄉百大青農友善耕作的枇杷花，清香高雅，配以同樣是百大青農種植、香氣馥郁高山烏龍茶，香氣撲鼻，入喉之後風韻綿延。\n玫瑰花紅茶：仁愛鄉賽德克族東岸部落的玫瑰花，特選帶特殊莓果甜味的大花月季品種，搭配溫潤的合歡山高山烏龍紅茶，品茶之時彷彿置身在浪漫玫瑰莊園裡。\n薰衣草紅茶：當仁愛鄉天然栽培、芳香馥郁的薰衣草，遇上了合歡山高山烏龍紅茶，其茶香及口感層次變化豐富。', '南投縣鹿谷鄉竹豐村中湖巷3-5號', '0919-743-732', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19266/480x360_10.小半天風味餐坊-玫瑰花紅茶、薰衣草紅茶、枇杷花烏龍.jpg', 23.731745, 120.7491051),
(138, '知子茶', '知子茶是以手工將梔子花與烏龍茶拌合窨製之特有茶品，同時具有烏龍茶的水甜回甘以及梔子花淡雅香氣，入口時香氣與茶水的結合香郁恰到好處，是屬於清香型、水色輕柔、花香調的烏龍茶品。', '桃園市蘆竹區坑子里12鄰貓尾崎1號', '03-324-1888', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19268/480x360_11.竹峰茗茶休閒農場-知子茶.jpg', 25.08246031660114, 121.34680509567261),
(139, '天菊花茶(天菊+菊葉)', '茶包袋為PLA材質(玉米纖維)，加上菊花葉，性理調合，層次豐富。以菊葉來中和菊花的涼性， 菊花香氣中帶有青草的自然味，是清香護眼的天然飲品。', '屏東縣高樹鄉新南村慈新路三段51號', '0939-027-111', '', 22.7880015, 120.570933),
(140, '四重溪可以居溫泉Q米', '選用高雄147號稻米，堅持友善種植，澆灌四重溪流域擁有豐富礦物質的地下溫泉水及牡丹水庫的天然潔淨山泉水，加上南臺灣特有落山風的吹拂，掃除了病蟲害的煩惱，秧苗在群山環繞下，自然孕育出香Q飽滿，營養好吃的優質溫泉Q米。', '屏東縣', '0919899333', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31842/480x360_souvenir-image-wpnwncu6gkybdqwwwephma.jpg', 22.10054917737, 120.7586133812),
(141, '蘋果辣椒醬', '以溯源生產的辣椒為主食材、蘋果為基底、採純天然發酵手法將蘋果及生辣椒在室溫中運用糖酵解反應，轉化為天然醣類，讓口感更為甘甜，香氣更濃郁。', '臺北市內湖區碧山路38-2號', '02-2795-1108', '', 25.1025774, 121.5886641),
(142, '透紅佳人蓮霧果露', '產自國境之南屏東佳冬、吹著海風長大的蓮霧，與口感綿密的糖漿交織成濃郁香甜的鮮果露，是一款品嘗時幸福感倍增的完美甜品。', '屏東縣佳冬鄉佳冬村佳和路64號', '08-866-0012', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31869/480x360_souvenir-image-ga9ab4e5iugazzizpkm0pq.jpg', 22.412898, 120.5567282),
(143, '穀物蜜紅豆', '選用「高雄8號」品種特定栽種的紅豆，經大寮農會及食品公司多年研發出來的「穀物紅蜜紅豆」，有別於市場現有商品，口味獨特，令人回味無窮，攜帶方便，可以即時享用。', '高雄市大寮區鳳林三路351號', '07-781-1141', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19278/480x360_16.高雄市大寮區農會-穀物蜜紅豆.jpg', 22.601793, 120.3975389),
(144, '紅棗即飲醋', '使用台灣公館栽種的無毒紅棗，遵循古法釀造，無添加任何香料或化學成分，於天然環境中歷時靜製發酵而成，色香味俱佳。', '苗栗縣公館鄉館東村大同路266號', '03-722-5211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31871/480x360_souvenir-image-lkbpthmiy0edbjn9xasqdw.png', 24.50464069999, 120.8273643999),
(145, '飛天豬金磚肉鬆禮盒', '嚴選台中大安區產銷履歷、肉質結實有彈性的豬後腿肉，以現代化設備，遵循古法技術精心調理製作，展現高優質鮮美風味。包裝落實環保概念，以輕巧、精緻、尊榮之金磚風格呈現，象徵「百事大安、好事湧進、生生不息」，送禮、自用都相宜。', '臺中市大安區中庄里３鄰中松路６號', '04-2671-2229', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19282/480x360_18.臺中市大安區農會-飛天豬金磚肉鬆禮盒.jpg', 24.3463873, 120.5870304),
(146, '麻辣小魚分享包', '虎霸王麻辣小魚花生，採用國產履歷特大顆花生及澎湖小魚乾為原料，口感香辣獨特，通過農藥及黄麵毒素檢測，取得履歷認證，品質安全，是泡茶休閒的好零嘴。', '雲林縣虎尾鎮光復路197號', '05-632-3511', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19286/480x360_20.雲林縣虎尾鎮農會-麻辣小魚分享包.jpg', 23.709292, 120.4439359),
(147, '鬼頭刀干貝醬', '鬼頭刀干貝醬以鬼頭刀為原料，以黃金比列添加在地新鮮原料，獨特的調味及烹調方式，將鬼頭刀鮮味昇華而出，製作出獨特口味的鬼頭刀干貝醬。', '臺東縣成功鎮台東縣基翬路75號', '089-855008', '', 23.099351, 121.3794969),
(148, '冷泡輕享茉莉烏龍', '以安全農法栽種的芬芳茉莉，搭配阿里山特有的回甘香潤烏龍，以繁複工法製成口感細緻的茶飲；包裝輕巧攜帶方便，讓您在生活中輕鬆品嘗無毒茉莉的清香純韻。', '彰化縣花壇鄉花壇村花壇街273號', '04-786-7821', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19290/480x360_22.彰化縣花壇鄉農會-冷泡輕享茉莉烏龍.jpg', 24.02599, 120.537346),
(149, '赤尾青蝦醬', '使用梓官在地現撈赤尾青蝦，直送漁會ISO22000加工廠加工處理，口味獨特、料多實在且香氣十足，方便料理，提鮮增香，無論拌飯、拌麵或炒菜都十分適合。', '高雄市梓官區漁港2路32號', '07-610-7551', '', 22.727833, 120.2546205999),
(150, '美濃米夾心餅(鮮採海苔口味)', '清甜的米餅，搭配香濃酥脆的可口海苔，香鹹中帶有米的香氣，口感令人驚艷。本產品無麩質，無添加，自然清爽，是嘴饞時刻的最佳休閒零食！', '高雄市美濃區清水里中正路三段100號', '07-6831624', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19296/480x360_25.美濃區農會-美濃米夾心餅(鮮採海苔口味).jpg', 22.9025301, 120.541316),
(151, '柴燒桂圓', '堅持遵循手工古法以龍眼木材歷時48小時烘乾焙製而成。三斤新鮮龍眼僅能製成一斤龍眼乾，而三斤龍眼乾經過剝殼去籽才撥得一斤桂圓。本品果肉厚實甜蜜，帶股淡淡的龍眼木煙燻味，無任何人工添加物，讓您吃得安心沒負擔，是自古流傳的養生珍品。', '彰化縣社頭鄉社斗路一段360號', '04-873-2516', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19298/480x360_26.彰化縣社頭鄉農會-柴燒桂圓.jpg', 23.896825, 120.5847081999),
(152, '池農米蛋捲禮盒', '選用本農會稻米產銷契作生產之好米(台梗2號)，先將飽滿的米粒研磨製成米穀粉，拌入低油減糖蛋捲糊後，再以手工慢火煎焙層層捲起，口感紮實香酥不腻，咀嚼後能嚐出池上好米的香氣，是休閒零嘴的好夥伴，更是農遊特色伴手好禮，。', '臺東縣池上鄉台東縣新興村85-6號', '08-986-4880', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19300/480x360_27.台東縣池上鄉農會-池農米蛋捲禮盒.jpg', 23.08902709999, 121.2278084999),
(153, '100%鬼頭刀魚鬆', '盛夏時節，溫暖的黑潮帶來追逐飛魚的飛烏虎，也就是鬼頭刀。成功鎮農會所產出的100%鬼頭刀魚鬆，使用本地新鮮鬼頭刀製成，屬於刺比較少的魚種，肉質鮮甜營養價值高、脂肪低，口感香酥不膩，無論中式、西式料理皆可搭配。', '臺東縣成功鎮忠孝里美山路139號', '08-985-1005', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19302/480x360_28.成功鎮農會-100_鬼頭刀魚鬆.jpg', 23.1031364, 121.3784766999),
(154, '三月半芋香茶豆', '芋香茶豆為毛豆的兄弟，品種不同，因本身莢較深色且豆仁為茶褐色，故命名為茶豆。三月半茶豆莢於清晨採收，低溫殺菌、急凍鎖鮮，茶豆的芋香包裹在豆莢裡，入口後散溢在口中，溫潤鮮滑、層次豐厚、餘味悠久，令人回味。', '臺南市新市區復興路1之1號', '06-589-9888', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19304/480x360_29.新市區農會-三月半芋香茶豆.jpg', 23.0792851, 120.2955182),
(155, '茶詩雅集禮盒(阿里山高山烏龍茶)', '採集阿里山高海拔良質茶樹樹種生長的幼嫩茶葉，由中埔鄉製茶專家所製作，沖泡出的茶湯水色金黃且明亮清澈，滋味甘甜，喉韻圓潤，香氣清純。', '嘉義縣中埔鄉内山公路128號', '05-253-2201', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19306/480x360_30.嘉義縣中埔鄉農會供銷部-茶詩雅集禮盒(阿里山高山烏龍茶).jpg', 23.4728954, 120.5384742),
(156, '囍來了方便紅茶茶包', '茶品久泡不苦澀，其外包裝結合環保理念，使用環保布袋，曾為多家廠商客製伴手禮，推廣友善土地之綠色產品給更多消費者。\r\n主要販售地點：台中市北屯區軍和街401 號', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19349/480x360_4.淘圃國際有限公司-囍來了方便紅茶茶包.jpg', 0, 0);
INSERT INTO `gift` (`id`, `name`, `feature`, `addr`, `tel`, `picurl`, `lat`, `lng`) VALUES
(157, '山豬迷路', '購買專線：04-92791949\r\n聯絡信箱：hsinifa@gmail.com \r\n會讓山豬迷路的信義酒莊榖類精釀，故事來自日據時代受到強制遷村到山下的信義地利部落。據說當時部落裡有一位相當擅長釀酒的伍嬤（ wu ma）奶奶，由於日本人限制私釀，所以伍嬤（ wu ma）奶奶都會利用黑夜將自家窗戶緊密遮住，進行榖釀的最後蒸餾作業，以提供族人於慶典中飲用。待作業完畢，再利用深夜將蒸餾完的酒渣，運至山谷中丟棄。適巧倒完之後，出外覓食的山豬受到酒香的吸引，蜂擁而至，開懷品嚐起酒香四溢的酒渣。或許是不勝酒力也可能是意猶未盡，山豬們竟然循著味往伍嬤 （ wu ma）奶奶家中前進。', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18716/480x360_20200328-13.jpg', 23.68870099999, 120.861791),
(158, '烏魚子乾拌麵', '李記烏魚子來自雲林西岸最美麗的鄉鎮-口湖鄉，是台灣烏魚子主要產地。早期幾乎家家戶戶都曬著烏魚子以及扁魚，隨著人口外移，生產 力的老化，因為對故鄉的情感、親情渴望以及傳 承台灣特有美食的責任，努力做出自有品牌傳承烏魚子的美味，實現百年文化、百年企業的理想，認真寫著雲林海線的美麗故事!', '雲林縣北港鎮大同路353-1號9樓', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19378/480x360_11.jpg', 23.57121361545, 120.1757824624),
(159, '糖漬橘瓣', '桶柑來自生態共生的果園，園內處處可見蝴蝶飛舞，瓢蟲免食，是動物安心居住的家，酸甜濃郁的鮮果，連松鼠和白鼻心也聞香來採食，做成果乾，一打開包裝濃郁的柑橋香味就撲鼻而來，垂涎欲滴，保存自然酸甜好滋味，糖漬橘瓣略帶嚼勁，吃完齒間留香，饕客贊不絕口，除了美味安心亦具友善環境，是經濟活動和生態保育共存的最佳代表。\r\n主要販售地點：台中市石岡區大智街2-1號', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19380/480x360_12.jpg', 0, 0),
(160, '信義風情禮盒組', '購買專線：04-92791949\r\n聯絡信箱：hsinifa@gmail.com \r\n忘記回家－開懷梅露，又稱勇士的血液，因為它像獵槍一般陪伴勇士接受時間磨練及大自然的洗禮和體力的考驗與狩獵完成後族人的讚詠與榮耀。高品質黃熟梅果混合上等砂糖存封一年，再經昇華取其精華之50度部份結合高品質黃熟梅果加入上等冰糖及高質米酒糖經半年存封而成調和而成，造就出25度高質開懷梅露。 長老說話─橡木桶梅露-信義鄉農會頂級梅露之一，以進口橡木桶存封經長時間存封於恆溫環境之下，再裝瓶上市，口感甜滑香醇，且少了市面上一般梅露的燥味，非常適合開懷暢飲。', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18124/480x360_123-098 信義風情禮盒組_20120821 (400X320)-20151027112135.jpg', 23.68870099999, 120.861791),
(161, '菱角豬腳', '本會所生產之菱角仁，乃由產銷履歷班員供應，使用台灣國產畜產品豬腳，用傳統烹調方法，符合媽媽的味道。嚴選官田特優菱角與肉質豐潤的豬腳相融合，散發誘人的香氣，湯頭帶有淡淡的菱角清香，提供豐富的營養價值。這道美食既能滿足味蕾的享受，也能為身體帶來營養的補充。', '臺南市官田區隆田里文化街23-2號', '06-579-1221', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19341/480x360_20.官田區農會-菱角豬腳.jpg', 23.1933615, 120.3183362),
(162, '歡囍幸福婚宴酒禮盒', '是南投縣信義鄉農會嚴選在地優質青梅釀造而成的梅酒，溫潤的口感與酸甜討喜的滋味，常讓人忽略其酒精濃度達 12。 【農業易遊網提醒您：飲酒過量有礙身體健康，喝酒不開車】', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18125/480x360_124-099 歡囍幸福婚宴酒禮盒_20101015 (400X320)-20151027112304.jpg', 23.68870099999, 120.861791),
(163, '天菊禮盒-初曉', '茶包袋為PLA材質(玉米纖維)，加上菊花葉，性理調合，層次豐富。以菊葉來中和菊花的涼性，是不想添加枸杞時的好選擇。 菊花香氣中帶有青草的自然味，是常用手機人士的養眼好飲品。', '屏東縣高樹鄉新南村慈新路三段51號', '0939-027-111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19332/480x360_1.天菊農場-天菊禮盒-初曉.jpg', 22.7880015, 120.570933),
(164, '雨沐小米酒', '雨沐小米酒是於2014年國宴招待外賓指定用酒，也是全台唯一個是國宴小米酒。台東縣金峰鄉盛產小米，而排灣族在製作傳統小米酒時會加入小米，別於其他族群會加入糯米、白米，堅持傳統製作過程全以糯小米製成甜美的酒飲，另外在包裝上設計相關原住民元素，且用手提方式，不僅不失高質感，也常被作為送人的伴手好禮。', '臺東縣金峰鄉歷坵村3鄰42號-2', '08-977-2240', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19356/480x360_5.臺東金峰小米學堂-雨沐小米酒.jpg', 22.5273676, 120.8269231),
(165, '洛神蜜餞', '洛神花有植物界紅寶石之稱，富有極高的花青素及營養價值。因應現代人在食用上以健康議題著想，用天然衛生方法製成，不含添加物及防腐劑。洛神蜜餞外層無裹糖，為把屬於洛神花的味道展現出來，美味又養生，方便攜帶食用，口感酸甜有層次，讓人吃起來健康無負擔。', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19360/480x360_6.臺東金峰小米學堂-洛神蜜餞.jpg', 0, 0),
(166, '好樂農莊苦茶油香菇拌醬', '以苦茶油為基底，搭配產休區農友種植辣椒及臺中新社香菇，開發出苦茶油辣醬和苦茶油香菇醬。真材實料，方便又快速享受美味，不論是小家庭或辦公室都是必備的萬用調味料。辣醬麻而不辣的口感，讓人吃了會上癮，而香菇醬濃郁口感則適合搭配拌飯、拌麵或佐青菜食用，口感一級棒。這款禮盒不僅能滿足自己的味蕾，也是送禮自用兼備的好選擇。', '臺中市東勢區慶福街77之3號', '0910-989477', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19376/480x360_10.好樂農莊-好樂農莊苦茶油香菇拌醬(1).jpg', 24.19196742294, 120.8410153072),
(167, '饗米(法國松露風味/日本芥末風味/三星蔥風味)', '選用美濃稻米產銷專業區所生產的高雄147米，精心研磨成米穀粉，製作成脆口香酥的米食小點心，共有三種風味：濃郁香醇的松露、嗆辣清爽的芥末、鹹香有味的三星蔥，臺灣在地好米與特色風味的融合，讓人忍不住一口接一口。', '高雄市美濃區清水里中正路三段100號', '07-6831624', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19354/480x360_15.美濃區農會-饗米(法國松露風味日本芥末風味三星蔥風味).jpg', 22.9025301, 120.541316),
(168, '初霧純米吟釀', '特別嚴選霧峰栽種之益全香米，汲取清淨甘甜的埔里山泉名水，提升香米 之附加價值，成功釀造台灣最高級的初霧清酒。純米吟釀為本會酒莊第一支釀造之清酒，國際酒類競賽(布魯塞爾世界酒類評鑑金牌獎、法國巴黎國際酒類評鑑銀牌獎、德國國際烈酒評鑑金牌、 銀質獎)獲得佳績好評如潮。', '臺中市霧峰區中正里四德路10號', '04-2339-3404', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19337/480x360_22.霧峰區農會-初霧.jpg', 24.0651751, 120.679522),
(169, '巨峰葡萄禮盒', '產品簡介：\r\n草屯巨峰葡萄產自九九峰下平林社區，乾淨水源來自合歡山脈，由於日照充足且溫差大，獨特氣候孕育的葡萄具濃郁果香，果肉更彈牙，甜度平均18度以上。\r\n▶訂購網站(糧源九九)', '南投縣草屯鎮草溪路1061號', '04-9233-3151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/32143/480x360_souvenir-image-9iwe7dk55u-gam6zdrmolg.jpg', 23.97787569999, 120.6819778999),
(170, '栗子南瓜禮盒', '產品簡介：\r\n南投草屯擁有得天獨厚的氣候與土壤，農民們堅持使用傳統耕作方式，確保每一顆栗子南瓜的品質與口感，讓您品嚐到最自然的風味。肉質細膩，甜度高，口感滑順，無論蒸、煮、烤皆可，適合各種料理需求。\r\n▶訂購網站(糧源九九)', '南投縣草屯鎮草溪路1061號', '04-9233-3151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/32144/480x360_souvenir-image-vth5tuju1euvq4twnji74g.jpg', 23.97787569999, 120.6819778999),
(171, '苦茶油禮盒', '產品簡介：\r\n選用台灣本土的小果，透過先進的冷壓技術低溫萃取，保留了天然的香氣與豐富的營養成分。苦茶油富含單元不飽和脂肪酸和維他命E，無論是用於調味、烹調，還是日常保健，都是健康的選擇。讓您在享受美味的同時，安心選擇自然健康的生活方式。\r\n▶訂購網站(糧源九九)', '南投縣草屯鎮草溪路1061號', '04-9233-3151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/32151/480x360_souvenir-image-ddjdw8weeeybxlucmbei9q.jpg', 23.97787569999, 120.6819778999),
(172, '健康心薏禮盒', '產品簡介：\r\n精選自優質的台中3號紅薏仁，保留了天然的營養與風味。這款養生粉富含高纖維、維他命及礦物質，並有助於美容養顏。添加於熱水或牛奶調製成香醇飲品，皆能為您的每一餐增添健康與美味。\r\n▶訂購網站(糧源九九)', '南投縣草屯鎮草溪路1061號', '04-9233-3151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/32146/480x360_souvenir-image-8rdl9l4kveiwqw8q7ncojw.jpg', 23.97787569999, 120.6819778999),
(173, '豐源九九蜂蜜米禮盒', '產品簡介：\r\n荔枝龍眼蜜採用荔枝花與龍眼花交替期採集的蜂蜜，完美平衡了龍眼的濃郁及荔枝的清香。生態米栽種於生態豐富且無汙染的區域，取自合歡山山麓的純淨水源，選用最受國人喜愛的米種「台稉九號」，米粒飽滿，晶瑩剔透，口感甘甜Q黏，白米及糙米兩種選擇，自由搭配，美味又健康。\r\n「豐源九九」蜂蜜米禮盒，生態米選用小包裝，包裝外型輕巧，方便攜帶，分量剛好，適合現代小家庭的精緻化需求,送禮自用兩相宜。\r\n▶訂購網站(糧源九九)', '南投縣草屯鎮草溪路1061號', '04-9233-3151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/32147/480x360_souvenir-image-8prn9jmviu-bqh9a-hugow.jpg', 23.97787569999, 120.6819778999),
(174, '豐源九九籽有米好禮盒', '產品簡介：\r\n這款精緻禮盒是您送禮的不二之選，內含兩包生態米，每包380公克，以及一瓶150毫升的台灣籽苦茶油。生態米選用台稉九號，源自合歡山麓的純淨水源，確保其品質卓越。此白米煮熟後口感Q黏，令人回味無窮。苦茶油則選用台灣小果苦茶籽製成，由於台灣本土苦茶籽產量稀少，因此更加珍貴。將香噴噴的米飯淋上苦茶油，瞬間提升餐桌上的美味風采。這組禮盒不僅展現了台灣農產的精華，更是您表達心意的最佳選擇。無論是送禮或自用，皆能感受到來自台灣土地的溫暖與用心。選擇這款禮盒，讓每一餐都充滿幸福與驚喜。\r\n▶訂購網站(糧源九九)', '南投縣草屯鎮草溪路1061號', '04-9233-3151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/32148/480x360_souvenir-image-oc22v3oxxegkcny9v7vdqw.jpg', 23.97787569999, 120.6819778999),
(175, '生態雙米禮盒', '產品簡介：\r\n內含台稉九號米與台農77號米各一包，皆來自草屯優渥的地理條件與純淨水源，孕育出美味可口的稻米。台稉九號米香氣四溢，口感滑順Q黏，適合各種料理；而台農77號米則粒粒分明，含特殊香氣，無論煮飯或做粥，都能展現米的天然風味。這款禮盒不僅是品味的選擇，更是健康的象徵，讓您在每一餐中都能感受到自然的呵護與安心。\r\n▶訂購網站(糧源九九)', '南投縣草屯鎮草溪路1061號', '04-9233-3151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/32149/480x360_souvenir-image-jrsszmqu-egjo6z74tuhsg.jpg', 23.97787569999, 120.6819778999),
(176, '米最珍貴禮盒', '產品簡介：\r\n米最珍貴禮盒專為貴賓所設計，內含有兩包台稉九號米。草屯地區富含得天獨厚的優質水源孕育出香氣四溢、口感極佳的美味稻米，台稉九號米的滑順與彈性，讓每一口都充滿了豐富的層次感，彷彿在舌尖上舞動，帶來無與倫比的美食享受。這款米最珍貴禮盒不僅是對美味的追求，更是對生活品味的詮釋。無論是商務贈禮還是特殊場合，這份用心的選擇將成為您心意的最佳傳遞者，讓每一份關懷在舌尖上優雅綻放。\r\n▶訂購網站(糧源九九)', '南投縣草屯鎮草溪路1061號', '04-9233-3151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/32150/480x360_souvenir-image-dlb8uuogpum-ask5f9ks9a.jpg', 23.97787569999, 120.6819778999),
(177, '南投茶經禮盒', '台灣最大的茶葉生產區─南投縣，邀請您品嚐傳遞南投八大茶區最珍貴的茶禪文化。', '南投縣南投市南崗三路1號', '04-9225-1170', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18128/480x360_130-099 南投茶經禮盒_20101003 (400X320)-20151027113333.jpg', 23.9222475, 120.6723086),
(178, '棗茶兒-金棗濃糖果汁', '購買專線： 03-9605388*212\r\n聯絡信箱：kiwee0823@hotmail.com\r\n「棗茶兒」為阿來伯系列產品第一彈，百分之百使用宜蘭在地生產「金棗」，歡迎來香格里拉農場與阿來伯一起追逐夢想。', '宜蘭縣冬山鄉大進村梅山路168號', '03-951-1456', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18067/480x360_014-101 棗茶兒-金棗濃糖果汁_20121003 (400X320)-20151023180652.jpg', 24.632506, 121.729009),
(179, '美人腿湯麵', '購買專線： 04-92423828\r\n聯絡信箱：pulidistillery@gmail.com\r\n茭白筍是埔里的農特產，以潔白無晳的外形博得「美人腿」之譽，透過特殊冷凍乾燥技術，保留原有營養成分，沖泡後口感鮮嫩爽脆，美人腿泡麵共推出牛肉、肉燥及素食等三種口味，方便又營養。', '南投縣埔里鎮清新里西安路一段六號', '04-9298-6420', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18132/480x360_139-100 美人腿湯麵_20111031 (400X320)-20151027144124.jpg', 23.963721, 120.9641679999),
(180, '菇鄉香酥禮盒', '購買專線：04-92898453\r\n聯絡信箱：serviceyuchi@hotmail.com.tw\r\n來自優質的香菇栽培場，嚴選外貌佳、顆粒較大的香菇，是頂級的爽脆咬勁。本產品無添加任何化學物質，保證新鮮、自然、美味，更是貼心的伴手禮。', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18136/480x360_144-099 菇鄉香酥禮盒_20101014 (400X320)-20151027144637.jpg', 23.89618859999, 120.9350395999),
(181, '日月潭典藏茶包', '購買專線：04-92898453\r\n聯絡信箱：serviceyuchi@hotmail.com.tw\r\n魚池農會典藏禮盒以「農委會茶業改良場魚池分廠製茶工廠」的紅茶傳奇；時間軸從畫面左方的台灣紅茶之父─新井耕吉郎以貓囒山常見樹種，象徵921重生力量的橄欖樹為中心，有點出回顧與展望的心情。日月潭典藏茶包，包裝採用原色牛皮紙兼具美觀及環保，舊有包裝為裝禮盒包裝，體積大攜帶不便且成本高，消費者購買意願低，經改變包裝後為3包裝禮盒，型態體積減少60包裝成本減少20將可提高消費者購買意願。', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18137/480x360_145-100 日月潭典藏茶包_20111019 (400X320)-20151027144720.jpg', 23.89618859999, 120.9350395999),
(182, '日月潭茶之捲禮盒', '由阿薩姆茶末製成紅茶蛋捲，慢慢咀嚼，淡淡的茶香迴盪在唇齒之間，再搭配淡淡麥芽香的阿薩姆紅茶，最大的享受莫過於此。', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18139/480x360_147-101 日月潭茶之捲禮盒_20121005 (400X320)-20151027144905.jpg', 23.89618859999, 120.9350395999),
(183, '貴妃枇杷、宋媽媽葡萄', '農場內枇杷甜度都在12度以上，食後具有清甜的風味。每年葡萄產期有兩季，口感Q、香氣濃厚、甜度都在19~20左右。此外葡萄園以人工除草，不使用除草劑。', '南投縣國姓鄉昌榮巷 55-12 號', '06-726-4625', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18142/480x360_153-099 貴妃枇杷、宋媽媽葡萄_20101011 (400X320)-20151027145406.jpg', 23.99595689999, 120.8515059999),
(184, '大城土豆麥酥', '購買專線：04-8944565*307\r\n聯絡信箱：wekchang@hotmail.com\r\n傳承大城鄉的老農夫不服輸的精神的「土豆麥酥」，取自大城鄉最好的土豆，最健康的小麥絕對讓您吃出「不會輸」的感覺!', '彰化縣大城鄉東城村南平路256號', '04-894-4565', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18147/480x360_160-103 大城土豆麥酥_20141127 (400X320)-20151027161033.jpg', 23.8531731, 120.3229006),
(185, '阿春姐古早味雞精', '購買專線：04-92522215\r\n聯絡信箱：yang04190518@yahoo.com.tw\r\n一隻成熟的古早雞，歷經十二個小時隔水慢火精煉，完全不加一滴水，利用高溫將整隻雞之精華一滴一滴的逼出。用心的經過去油、過濾、去渣等多道工序，讓純淨的營養，不油不膩。', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18148/480x360_161-099 美春姐古早味雞精_20101011 (400X320)-20151027161119.jpg', 0, 0),
(186, '阿春姐荔枝酥餅', '購買專線：04-92522215\r\n聯絡信箱：yang04190518@yahoo.com.tw\r\n以農場著名產品荔枝乾作為酥餅原料，棗紅色的內餡飽滿厚實，融合荔枝特有的果香及餅皮的奶香，整體味道非常豐富。小巧造型一口恰恰好，讓人越吃越順口。', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18149/480x360_162-100 阿春姐荔枝酥餅_20111023 (400X320)-20151027161209.jpg', 0, 0),
(187, '米樂禮禮盒', '在青青的田中央看見了微笑的稻子，農友以快樂用心的專業精神，細心灌溉，將最好的都給上，因此也種出了會微笑的稻子，那麼田中農會用無比歡欣的態度，從農友手中接到快樂的稻子，將之傳送與人們與消費者，讓禾樂禮成為快樂的傳播者。 台梗九號米：用清純的濁水溪灌溉，用富有黑色黏質的壞土栽培，每一粒米都身懷飽滿，口感香Q，還有在田中這片青青土地所沾染的幸福滋味。\r\n牛奶手打麵：與田中乳牛產銷班合作依循曝晒日照方式，手工製造，麵條Q彈，每一口都有酪農的心意。 古早味麵線：純天然、古報曝晒乾燥製成，純手作，獨門甩、拉、彈巧勁運用，口感嚼勁十足，百分之百原味天然，給你帶點陽光般的新好滋味。 胡麻油：遵循古法釀造，回歸自然，香濃淳、營養成分高，是健康調味、烹調時的最佳幫手。', '彰化縣田中鎮南北街80號', '04-874-9211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18151/480x360_165-098 米樂禮禮盒_20091016 (400X320)-20151027161541.jpg', 23.85965819999, 120.5863643),
(188, '穀意禮', '台稉九號米：用清純的濁水溪灌溉，用富有黑色黏質的壤土栽培，如同自己的孩子般細心照料呵護，每一粒米都身懷飽滿香Ｑ口感。還有，在田中這片青青土地所沾染的幸福滋味，濁水溪流載了農家生活與土地情感，黃土沙泥涵養了田中生命悸動，豐沃了對故鄉風味的無窮思念！玄米醋：100純發酵釀造有益人體新陳代謝。嚴選「台灣米倉」濁水溪平源、八卦山脈穀物，田中稻米產銷專區台稉九號米，秉持傳統古法釀造，二年以上多重靜置發酵，酵素豐富無添加任何香料及化學合成品，入口回甘。', '彰化縣田中鎮南北街80號', '04-874-9211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18152/480x360_167-100 穀意禮_20111019 (400X320)-20151027161915.jpg', 23.85965819999, 120.5863643),
(189, '芭樂玄米茶', '購買專線：04-8752376\r\n聯絡信箱：da8752376@yahoo.com.tw；da8747498@gmail.com\r\n精選芭樂小果、一花二葉的嫩葉，搭配擁有產銷履歷驗證的台梗九號米製成風味特殊的芭樂玄米茶。茶汁初入口，盡生芭樂清香；飲下入喉，深刻感受玄米獨有的烘炒米味。可重複沖泡，浸泡越久越甘醇。', '彰化縣溪州鄉成功村庒北巷７號', '0958-893-396', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18159/480x360_179-100 芭樂玄米茶_20111023 (400X320)-20151027172455.jpg', 23.83316715125864, 120.54958820343018),
(190, '陽光芭樂果乾', '購買專線：04-8752376\r\n聯絡信箱：da8752376@yahoo.com.tw；da8747498@gmail.com\r\n採用｢草生栽培｣法的鮮甜芭樂，手工製作，經過冰鎮、冷藏的方式處理，口感特別Q甜、有嚼勁，絕無添加色素、香精、防腐劑、甜味劑，為天然的果乾。', '彰化縣溪州鄉成功村庒北巷７號', '0958-893-396', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18160/480x360_180-103 陽光芭樂果乾_20141127 (400X320)-20151027172540.jpg', 23.83316715125864, 120.54958820343018),
(191, '溪州黑鑽紫黑米溪州紫黑米系列-貢米禮盒', '本紫黑米產自彰化縣溪州鄉濁水溪沿岸，泥土含有多種礦物元素，無農藥無化學肥料，是特別栽種的人氣產品，可天天食用，香氣逼人、好食又美味。', '彰化縣溪州鄉溪州村中央路三段324號', '04-889-5610', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18164/480x360_189-103 溪州黑鑽紫黑米_20141127 (400X320)-20151027173311.jpg', 23.85153659999, 120.4949632),
(192, '大安好酒禮盒', '九降風白蘭地-萃取金香葡萄所釀製的，釀製後做二次蒸餾，再經由橡木桶內熟成，吸收橡木桶獨特沉穩熟香。口感之濃郁、柔滑順喉、芳香甘冽不可言喻，層次豐富，後勁十足痛快，久久難忘。 竽燒酎-沿襲日本燒酌製作流程，再依芋頭的的特性加以改良，並運用酒本身的溫度，將天然芋頭香氣封存於酒中。', '臺中市大安區中庄里３鄰中松路６號', '04-2671-2229', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18166/480x360_193-101 大安好酒禮盒_20121004 (400X320)-20151028094238.jpg', 24.3463873, 120.5870304),
(193, '建國百年頭等倉米寶島雙星伴手禮', '本會所生產頭等倉米是採用台梗九號（蓬萊品種），使用第一頂級好米，還有台灣造型保鮮盒，可當收納盒或微波盒是多功能用途。', '臺中市西區向上路1段95號', '04-2302-3560', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18167/480x360_195-100 建國百年頭等倉米寶島雙星伴手禮_20111018 (400X320)-20151028094421.jpg', 24.14655949999, 120.6632846),
(194, '幸福穗稻伴手米禮盒頭等倉-幸福穗稻伴手米禮盒', '嚴選台灣中部頂級好米-越光米，用心栽培，粒粒飽滿，邀您細嚐滿滿的幸福味。', '臺中市西區向上路1段95號', '04-2302-3560', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18168/480x360_196-103 幸福穗稻伴手米禮盒_20141127 (400X320)-20151028094533.jpg', 24.14655949999, 120.6632846),
(195, '純南瓜粉', '宜蘭旺山休閒農場，主要栽種各式各樣品種南瓜，瓜果隧道中充滿驚奇，總是吸引著許多遊客駐足觀賞，南瓜粉純淨天然，沖泡飲用或是煮濃湯使用，健康又美味。', '宜蘭縣壯圍鄉新南村新南路106-11號', '0932-088-992', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18071/480x360_021-103 純南瓜粉_20141127 (400X320)-20151023181340.jpg', 24.7266496, 121.807281),
(196, '黃金活力地瓜餐包', '購買專線：04-26623111*263 \r\n聯絡信箱：n8045.lfm@msa.hinet.net \r\n黃金活力地瓜餐包是使用沙鹿品質優良的紅土地瓜，香甜又鬆軟，搭配14種蔬菜穀物，便利、高纖、口感滑順，只要沖入熱開水，輕輕攪拌，即可享用，沖調鮮奶或牛奶，更為香純美味。', '臺中市沙鹿區沙田路131號', '04-2662-3111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18173/480x360_202-101 黃金活力地瓜餐包_20121004 (400X320)-20151028113409.jpg', 24.2360788, 120.5589866999),
(197, '韭讚の麵', '清水區農會精心製作的「韭讚麵」是將韭黄及韭菜打汁後經過濾直接和入麵粉，讓麵條有天然食物纖維，吃起來健康且更具韭香，Q彈爽口，幸福入味。', '臺中市清水區中山路94號', '04-2623-2101', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18174/480x360_203-101 韭讚 麵400X320-20151028113927.jpg', 24.2668384, 120.5747573),
(198, '菇賞禮盒', '香菇採收後馬上嚴選分級，經過24小時70℃烘乾後，封存濃郁菇香，再分裝成家庭號「小菇意」；鮮菇爭鮮加工成香菇酥或香菇蘇打餅，讓人得以品味菇香、滿足味蕾。', '臺中市新社區新社里中和街4段226號', '04-2581-1511', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18176/480x360_206-100 菇賞禮盒_20111023 (400X320)-20151028114407.jpg', 24.2421857, 120.8072061),
(199, '將軍花翎百年紀念酒', '用臺灣最好的霧峰香米、最甘甜的埔里礦泉和日本嚴選麴菌，釀造全國唯一台式頂級清酒。讓每個人在微醺飄然中，看見霧峰鄉的壯闊山林，感受文化經典的優雅華美。', '臺中市霧峰區中正里四德路10號', '04-2339-3404', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18177/480x360_210-100 將軍花翎百年紀念酒_20111018 (400X320)-20151028115403.jpg', 24.0651751, 120.679522),
(200, '金棗健康家族', '金柑又稱金橘或金棗,果實呈金黃色,果肉酸中帶甜.礁溪鄉地層結構特殊,全年氣候溫和,雨量充沛,是著名著溫泉風景區.適合金棗的種植,所生產的金棗質佳味美,有金棗的故鄉美譽.礁溪鄉農會為發展多元產品,委由專業認證的杏輝藥廠研究開發「金棗軟糖」保留金棗的健康元素與美味分享給大家。', '宜蘭縣礁溪鄉中山路1段175號之1', '03-988-2033', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18072/480x360_022-097 金棗健康家族_20081220 (400X320)-20151023181423.jpg', 24.82079209999, 121.7705359999),
(201, '台農鮮奶酪', '購買專線：04-26880713\r\n聯絡信箱：star@farm.org.tw\r\n台農鮮奶酪以新鮮生乳煮沸殺菌製作而成，且因未加防腐劑，採定時定量供應，來到本牧場一定要嚐鮮一下!', '臺中市外埔區二崁路700號', '04-2687-2724', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18179/480x360_212-103 台農鮮奶酪_20141127 (400X320)-20151028115657.jpg', 24.329301830008905, 120.62045350670815),
(202, '香草系列產品', '西洋香草經過多年的推廣，已經逐漸成為國人健康與休閒生活的一部分。雲林土庫鎮農會香草產銷第一班藉由產學合作研發各種香草產品，在市場上廣受好評，其中又以，「奇香妙草─香草醋系列」最受到消費者的青睞。 香草醋是將香草透過蘋果發酵醋的萃取香味，再包上蜂蜜的甜美，調配出薰衣草、玫瑰、檸檬草、迷迭香、紫蘇等多種口味的香草醋，稀釋飲用，冷熱皆宜，不但風味絕佳，更有調理身體平衡，增加活力的功能。「奇香妙草─香草醋系列」產品包裝精美，送禮也十分大方。', '雲林縣土庫鎮建國路37-1號', '05-662-9111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18180/480x360_213-093 香草醋系列_20150913【From Ezgo】400X320-20151028115751.jpg', 23.67755049999, 120.3898291),
(203, '莿桐說的蒜-蒜泥厲害', '莿桐的黑葉丫蒜頭，香辣夠味，莿桐蒜醬更是麵包的好佐料，健康、安全，只在莿桐說的蒜。', '雲林縣莿桐鄉中正路54號', '05-584-6161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18187/480x360_224-103 莿桐說的蒜-蒜泥厲害_20141127 (400X320)-20151028134210.jpg', 23.7569755, 120.502628),
(204, '杏鮑菇脆片', '購買專線：05-3799174*120\r\n聯絡信箱：chee01@yahoo.com.tw\r\n候鳥，季季來來回回，終在千里之外的東石尋得最佳棲息地，度過每個冷冽的寒冬。杏鮑菇生長在高溼氣山區，94年東石鄉農會，改建原有的雜糧廢棄倉庫，成為環控式低溫及RO逆滲透的培養環境，量身訂做一個屬於杏鮑菇的家。東石是候鳥避寒的家，也是杏鮑菇成長的家，一個最幸福的所在。', '嘉義縣東石鄉港墘村60號', '05-379-9174', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18190/480x360_228-098 杏鮑菇脆片_20091021 (400X320)-20151028134734.jpg', 23.4606346, 120.212115),
(205, '溫泉米粉', '口感香Q、綿密好吃，以冰水研磨法一貫作業完成，食用安全、衛生。', '宜蘭縣礁溪鄉中山路1段175號之1', '03-988-2033', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18074/480x360_024-098 溫泉米粉_20091016 (400X320)-20151026094931.jpg', 24.82079209999, 121.7705359999),
(206, '湯戀組合禮盒', '著名的溫泉鄉，好山好水的地理環境，以溫泉的圖像結合「湯」的概念，營造礁溪鄉溫泉蔬果的特色，充滿活力與生機，代表礁溪鄉農特產品獨創的品牌標誌。', '宜蘭縣礁溪鄉中山路1段175號之1', '03-988-2033', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18075/480x360_025-099 湯戀組合禮盒_20101015 (400X320)-20151026095102.jpg', 24.82079209999, 121.7705359999),
(207, '回味玉井-愛文芒果禮盒', '玉井好山、好水的自然環境條件，加上充足陽光與特殊氣候與緯度和芒果達人的經驗傳承，讓玉井芒果集聚『香、濃、Q、甜、美』風味於一身，令人回味與懷念的滋味，讓玉井擁有聞名中外「芒果之故鄉」美譽。', '臺南市玉井區中正路139號', '06-574-2216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31821/480x360_souvenir-image-fjqiy2a9quchlfms_ncu2q.png', 23.17685709999, 120.4852097),
(208, '玉井鮮芒果多千層蛋糕熱情小子-芒果多千層', '新鮮香濃味美在地愛文芒果，融合香草甜點與層層岩燒蛋皮，濃滑奶香、果香在嘴裡交融得恰到好處，迴盪舌尖，層次豐富味美濃郁，猶如跳著華麗圓舞曲甜蜜戀人，令人陶醉其中，是仲夏季節最令人心動幸福美食與必選清涼有勁的甜蜜伴手。', '臺南市玉井區中正路139號', '06-574-2216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18198/480x360_243-103 玉井鮮芒果多千層蛋糕_20141127 (400X320)-20151028150509.jpg', 23.17685709999, 120.4852097),
(209, '胡麻油', '購買專線：06-5922121\r\n聯絡信箱：joy3397@hotmail.com\r\n台南市安定區於日治時代名為直加弄，後改為安定社，台灣光復後更名為安定區，追溯到古曾文溪逐年河道移位，年年河水氾濫，大水自山上沖刷肥沃土壤，淤積到下游河段。 安定區正處於曾文溪畔，年第年年有沃土覆蓋，適合種植胡麻，產量大品質好，利潤較其他作物佳，農民皆以自產自銷的型態發展沿襲至今。', '臺南市安定區安定里58號', '06-592-2121', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18199/480x360_246-098 國產優質胡麻油_20091016 (400X320)-20151028150700.jpg', 23.1219137, 120.2373331),
(210, '玉井之門水果乾系列', '「玉井之門」創立於民國八十九年，創辦人本著客家人淳樸務實的精神，以夫家玉井為名，聯合了台南玉井地區50位農民所創立，玉井的特產為始，讓農民苦心栽種的水果，除了以新鮮水果的方式販售外，還能有另一種不同的品嚐方式，以最簡單無防腐添加物的加工方式，保有水果的原味，製作成各類水果乾，讓大家嚐到不同的美味，以期將產地的農特產推薦給台灣消費者，甚至行銷到全世界。 　\r\n「玉井之門」專門製造天然有機蜜餞，使用更天然更衛生的製作方式，讓蜜餞不但保有原本的美味，也變得很健康，其中以芒果乾為的主打產品，其他熱賣產品包括黑糖芒果乾、水蜜桃乾、鳳梨乾、芭樂乾、情人果乾、蕃茄乾、楊桃乾、葡萄乾、無花果乾、茶葉梅、甜乾梅等數種，送禮自用兩相宜。', '臺南市南化區小崙里57之3號', '06-577-1086', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18201/480x360_玉井之門水果乾系列 (400X320)-20151028152337.jpg', 23.0565007, 120.5054228),
(211, '溫泉糙米茶', '購買專線：03-9882033*110\r\n聯絡信箱：john.4h@gmail.com\r\n溫泉糙米茶採用在地的溫泉糙米與天然漢方-決明子加以組合，到礁溪泡湯旅遊之後，再喝上一杯「溫泉糙米茶」充滿幸福快樂的感覺！', '宜蘭縣礁溪鄉中山路1段175號之1', '03-988-2033', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18076/480x360_026-101 溫泉糙米茶_20121004 (400X320)-20151026095154.jpg', 24.82079209999, 121.7705359999),
(212, '善緣女兒禮', '以芝麻提煉而成的胡麻油，油質清澈、風味獨特，且品質優良有保障，並且富含對人體有益的不飽和脂肪酸，有助於保持健康及抗老。而芝麻麵口感Q彈，散發淡淡清香，以乾炒或湯食方式烹煮皆宜。', '臺南市善化區中山路242號', '06-583-6111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18208/480x360_260-100 善緣女兒禮_20111018 (400X320)-20151028154440.jpg', 23.132757, 120.2976479999),
(213, '南澳椴木香菇伴手禮盒', '百分百椴木香菇產自好山好水南澳地區，當地具有多個部落，且每個部落皆有其落部特色，是來到宜蘭南澳鄉旅遊最佳的伴手選擇。', '宜蘭縣蘇澳鎮龍德里福德路156號', '03-990-5181', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18077/480x360_028-103 南澳椴木香菇伴手禮盒_20141127 (400X320)-20151026113518.jpg', 24.6404134, 121.8317068999),
(214, '關廟鳳梨麵', '採用在地新鮮台3號鳳梨，遵循嚴謹製麵流程，堅持不填加任何防腐劑，人工打理製作，微黃色的麵體散發鳳梨清香，口味獨特，耐煮不爛。', '臺南市關廟區中正路963號', '06-596-6278', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18216/480x360_273-100 關廟鳳梨麵_20111018 (400X320)-20151028171127.jpg', 22.9624989, 120.3284754),
(215, '手作果干', '大坑休閒農場的阿公阿嬤自己生產水果，每季盛產時，就會將水果烘烤乾以保存作為點心，歡迎客人到大坑作客，希望能將阿公阿嬤的果干，用最善意的方式讓大家延續旅遊的記憶。', '臺南市新化區大坑里82號', '06-594-1555', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18219/480x360_277-103 手作果干_20141127 (400X320)-20151028171801.jpg', 23.0072204, 120.3904996),
(216, '有機梅精', '購買專線：07-6754123\r\n聯絡信箱：q2221942@yahoo.com.tw；cs.in@msa.hinet.net\r\n高雄縣梅樹種植面積達兩千公頃，種植面積居全台之冠，梅子品質十分良好，製作出優良養生之梅精。', '高雄市甲仙區中正路26號', '07-675-1001', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18706/480x360_20200328-07.jpg', 23.083031, 120.588494),
(217, '茶籽油禮盒', '購買專線：02-2783-6121*13\r\n聯絡信箱：rickyeh99@gmail.com\r\n南港因當地海拔約200至300公尺，土壤富含岩礫，適合茶樹的生長，本茶籽油精選高品質茶籽，經過日曬、脫殼、炒熟、壓榨、過濾、沉澱、等複雜步驟煉製而成，是茶籽油首選。', '', '', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18078/480x360_1-區農會-茶籽油禮盒(400X320)-20151026134152.jpg', 0, 0),
(218, '蒲燒鰻', '選用上乘等級鰻魚搭配獨特醬汁，肉質細膩軟嫩，味道鮮美，入口即化，製作過程講求真材實料，不添加化學物品調味，含有豐富的蛋白質、維生素A、E與多量的鈣，營養價值豐富。', '高雄市湖內區中正路2段158號', '07-699-5528', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18228/480x360_293-100 蒲燒鰻_20111031 (400X320)-20151028180752.jpg', 22.9085617, 120.21207),
(219, '芒果冰淇淋', '使用高優質枋山芒果，加上濃醇的奶香，入口即化的綿密感，一種協調味道在口中讓味蕾陶醉，享受冰冰甜甜的美麗境界！', '屏東縣枋山鄉國中路3號', '0935-470-498', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18233/480x360_300-101 芒果冰琪淋_20121004 (400X320)-20151029112251.jpg', 22.263342895876047, 120.66105008125305),
(220, '旗魚鬆', '購買專線：08-8328064\r\n聯絡信箱：tk.sam168@yahoo.com.tw\r\n東港旗魚白中透肉色、味道甘美，是養分極高的魚類，在台灣及日本常是壽司與生魚片中的珍品。東港區漁會用心製作嚴選新鮮旗魚入口即能感受香酥鮮美的原始海洋風味。本產品係選用新鮮旗魚肉特製而成，不添加任何防腐劑及色素，是佐飯的上上之選。您充分體驗海味故鄉「東港」的懷古鮮味。', '屏東縣東港鎮新生一路73號', '08-832-3121', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18236/480x360_303-097 旗魚鬆_20090106 (400X320)-20151029112446.jpg', 22.4677798, 120.4417895),
(221, '稻鴨香伴手禮', '以源自大武山水源保護區之山泉水孕育，採用老祖先最具智慧的耕作方式─稻鴨共作以達到病蟲害防治，米粒大、外觀晶瑩剔透、口感好、風味佳。', '屏東縣高樹鄉泰山村25鄰產業路330號', '08-796-7301', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18239/480x360_307-099 稻鴨香伴手禮_20101011 (400X320)-20151029112746.jpg', 22.7952705, 120.6111629),
(222, '桑椹原汁', '購買專線：08-9781531\r\n聯絡信箱：taimali03@taimalifarmer.com.tw\r\n濃縮原汁無添加防腐劑，可稀釋7-10倍，不需冷藏，期限2年。', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18696/480x360_20200328-02.jpg', 22.604987, 121.001855),
(223, '袋茶', '購買專線：08-9781531\r\n聯絡信箱：taimali03@taimalifarmer.com.tw\r\n純粹洛神花粉碎包裝、無任何添加物、熱開水沖泡後加糖調勻滋味酸甜可沖泡2次，期限2年。', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18698/480x360_20200328-03.jpg', 22.604987, 121.001855),
(224, '釋迦、洛神休閒食品', '釋迦、金針、洛神、桑葚是太麻里地區主要特產，特製成可口的小點心，每一種口味皆散發其香醇風味，經典好滋味。', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18242/480x360_316-097 釋迦、洛神休閒食品_20081230 (400X320)-20151029113106.jpg', 22.604987, 121.001855),
(225, '洛神元氣餅', '為薄餅狀，吃起來除了有奶香還有洛神的酸甜口感，好吃清爽不油膩。', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18243/480x360_317-098 洛神元氣餅_20091016 (400X320)-20151029113141.jpg', 22.604987, 121.001855),
(226, '臺灣臺東好茶', '紅烏龍係結合烏龍茶與紅茶之特色所創造的一種新興特色 茶，屬重發酵、著重烘焙的半球形烏龍茶，茶湯水色琥珀橙 紅如紅茶，滋味則如烏龍茶，具熟果香，醇厚圓滑、耐泡， 不但適合一般熱水沖泡，冷泡更顯其特色，廣獲市場好評。', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18252/480x360_329-100 臺灣臺東好茶_20111031 (400X320)-20151029114106.jpg', 22.7555108, 121.142776),
(227, '洛神花軟Q糖', '購買專線：08-9513111*15\r\n聯絡信箱：lucky.a168@msa.hinet.net\r\n「洛神軟Q 糖」採台東火紅盛開的洛神花萼製作，保留了其原始的酸味及香氣，以優良的技術開發洛神花新口味，符合小朋友、長青者及各種年齡層的消費者的口感，是適合全家人的休閒零嘴。', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18253/480x360_330-101 洛神花軟Q糖_20121016 (400X320)-20151029114149.jpg', 22.7555108, 121.142776),
(228, '平溪原生種山藥', '「平溪山藥」經過嚴格篩選之優良品種來復育，每年的產季於9月中旬至12月期間，由於培植不易，所以更顯格外珍貴，口感Q、耐烹煮、風味極佳，可料理多道山藥佳餚。', '新北市平溪區嶺腳里中華街15號', '02-2495-1051', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18081/480x360_034-101 平溪原生種山藥_20121004 (400X320)-20151026113907.jpg', 25.0253945, 121.7393406999),
(229, '瑞穗柚花茶', '每年三月間是文旦柚樹開花的時節，當柚花遇到瑞穗有名的天鶴茶，就成了香氣迷人的上品柚花茶。運用了一年才綻開一次的柚花與茶葉共同烘焙而成的花茶，不但可 以喝到茶葉的甘醇，回甘時還帶有誘人的天然芳香。', '花蓮縣瑞穗鄉中山路一段128號', '03-887-2226', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18267/480x360_352-099 瑞穗柚花茶_20101014 (400X320)-20151029142559.jpg', 23.496431, 121.381484),
(230, '伊糯千金', '黑糯米性溫，在本草綱目中記載：『溫養五臟益脾胃、補中益氣、縮小便』。適量食用，益養肝血、補腎 氣、預防骨質疏鬆、延緩人體老化，所以也有『貢米』的稱號，阿美族人將之視為老人的養生米，且任何人皆可食用，更是婦女朋友的養生美容聖品。', '花蓮縣壽豐鄉豐文路105號', '03-865-3101', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18268/480x360_354-101 伊糯千金_20121004 (400X320)-20151029142746.jpg', 23.8453491, 121.4976064),
(231, '醋老爺健康日記', '用本土100天然純蜂蜜作基底與純淨雪山泉水釀造，加上首創的「雙層三階多菌相工法」完全發酵。每天一小瓶果醋來寫自然養生日記，你今天「醋」進健康了嗎？', '宜蘭縣員山鄉湖東村德湖路二段122號', '03-922-0601', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18271/480x360_361-099 醋老爺健康日記_20101014 (400X320)-20151029150526.jpg', 24.746018, 121.726996),
(232, '紅棗干', '購買專線：037-231626\r\n聯絡信箱：kungnon.food@msa.hinet.net\r\n公館得天獨厚，具有特殊氣候與土質，為全台唯一生產紅棗地區，是紅棗的家！每年七、八月間觀光果園開放遊客採果，紅棗富含的營養成份，是提供藥膳之聖品。', '苗栗縣公館鄉館東村大同路266號', '03-722-5211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18272/480x360_364-102 紅棗干_20150913【From Ezgo】400X320-20151029150854.jpg', 24.50464069999, 120.8273643999),
(233, '紫香御品-香芋片', '採用大甲芋頭產銷班所生產的特級新鮮芋頭，透過製程的改良讓芋頭香氣能保存於芋片內，酥脆的口感及濃郁的芋頭香，讓您一口接一口。', '臺中市大甲區中山路1段372號', '04-2686-3990', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18275/480x360_373-102 紫香御品-香芋片_20150913【From Ezgo】400X320-20151029161823.jpg', 24.334949, 120.615858),
(234, '茶香冰淇淋', '測試產品說明', '新北市坪林區坪林村坪林街103號', '02-2665-7227', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18946/480x360_54020201209.jpg', 24.936102, 121.7117779999),
(235, '棗紅公館蜜餞系列', '棗紅公館蜜餞系列嚴選在地紅棗、紫蘇、洛神花、梅、金桔製造，不添加色素、防腐劑、漂白劑、甘味劑等，讓您食的安心。', '苗栗縣公館鄉館東村大同路266號', '03-722-5211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18282/480x360_389-103 棗紅公館蜜餞系列_20141127 (400X320)-20151029163821.jpg', 24.50464069999, 120.8273643999),
(236, '鳥兒歡唱-養生禮盒組', '來自原鄉的紅藜、小米、樹豆，以自然的耕作方式栽培，營養豐富，邀您享用大地母親的恩賜。', '臺東縣卑南鄉台東縣溫泉村(路)388號', '089-513111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18283/480x360_390-103 鳥兒歡唱-養生禮盒組_20141127 (400X320)-20151029163858.jpg', 22.6955793, 121.022134),
(237, '燒仙草禮盒', '以即溶燒仙草熱情好客的特性，搭配新時代健康養生「磁炭杯」， 具抗菌、抗臭、釋放微量負離子及將水活化等效能，能讓受禮者充分感受到所傳達的友誼、愛和溫暖，在寒冬中泡杯熱騰騰的燒仙草，會讓食客感到無比的滿足與喜悅。', '新竹縣關西鎮北山里10鄰高橋坑6號', '03-587-4277', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18285/480x360_392-102 燒仙草禮盒_20150913【From Ezgo】400X320-20151029164252.jpg', 24.8032728, 121.1601904),
(238, '洛神花蜜餞', '購買專線：08-9513111#15\r\n聯絡信箱：lucky.a168@msa.hinet.net\r\n「山海經」是中國最早介紹有關於自然界礦物質的一本著作，在此「山海」與台東天然的山、海景相呼應，期許心靈、生理養生觀念，可以沿著人體的經脈運行，採台東火紅盛開的新鮮洛神花萼製作，保留了其原始的酸味及香氣，味道酸甜似初戀的滋味，風味絕佳，希望傳遞台東優質農產的特色。', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18702/480x360_20200328-05.jpg', 22.7555108, 121.142776),
(239, '金碧椪柑', '石岡鄉以其得天獨厚的土壤、氣候、陽光，共同滋養著纍纍結實的椪柑，「金碧椪柑」乃此中嚴挑精選的頂級產品，果形完整豐滿，色澤澄黃亮麗，入口甜中帶酸甘醇多汁，而象徵財源滾滾、大吉大利的「金碧」之名，在椪柑熟成的年節期間更增添圓滿的喜氣。', '臺中市石岡區萬安里石岡街67號', '04-2572-1246', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17721/480x360_石岡鄉農會_金碧椪柑-20151216180802.jpg', 24.275887, 120.776317),
(240, '蔥滿好禮', '購買專線：03-9893170\r\n聯絡信箱：lihunggg@ms39.hinet.net\r\n台語俗諺「鼎底若有蔥、無肉嗎也香」，蔥滿好禮嚴選符三星頂級青蔥，纖維柔嫩，蔥白香甜，也適合拌麵、炒飯、配菜、燒肉、沾醬等，方便做菜一罐搞定，是家庭主婦的最愛。', '宜蘭縣三星鄉中山路31號', '03-989-3170', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18694/480x360_souvenir-image-m8paxieggeazadhtslngnw.jpg', 24.667903, 121.652142),
(241, '三好禮', '包種茶油富含蛋白質、單元不飽和脂肪酸、維生素A、E等，對於高溫的穩定性和營養價值均優於一般市面上販售的沙拉油，不僅可養身保健，亦是美容良方。麵線以茶及山藥入味，採用多加水手打麵製麵方法，經低温高濕長時間熟成乾燥，麵線不會龜裂，品質安定，口感滑溜彈性足，湯麵、冷麵或乾拌皆宜。', '新北市坪林區坪林村坪林街103號', '02-2665-7227', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18085/480x360_042-100 三好禮_20111018 (400x320)-20151026114239.jpg', 24.936102, 121.7117779999),
(242, '文山包種茶', '清香芬芳的包種茶，香氣幽雅飄逸，滋味甘潤，入口生津；東方美人茶特殊的熟果香和蜜香，茶湯濃厚香醇，是讓英國伊莉莎白女王念念不忘的茶葉。製成茶包，方便您隨時快速享用兩種特色茶，是味蕾的雙重滿足。\r\n訂購專線：02-26657227', '新北市坪林區坪林村坪林街103號', '02-2665-7227', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18720/480x360_a8112ee8-bc19-45b0-a3c2-809bf9f33a8a.jpeg', 24.936102, 121.7117779999),
(243, '阿里山高山金萱茶', '來自阿里山高海拔優良茶區，嚴選柔軟、芬芳、醇化而不苦澀的茶菁，並經農會茶師嚴格監製及認證，成品的外觀色澤鮮活翠綠，水色金黃，耐沖泡，滋味甘醇滑軟，香氣淡雅，一向都是享譽國際，無論自用或饋贈皆相宜的極品茶。\r\n訂購專線：05-2360311#23', '嘉義市西區博愛路二段459號', '05-236-0311', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17464/480x360_1-20151016173019.jpg', 23.4718835, 120.431524),
(244, '金舞滂米', '阡陌交接的稻田，幻化成時尚的線條符號，黃色代表稻穗的成長，橙、紅色表現豐收的喜氣，不只滿足現代人的視覺期盼，也重新定位新概念的米食文化！', '桃園市蘆竹區龍安街2段968號', '03-379-1881', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18086/480x360_051-099 金舞滂米_20101003 (400X320)-20151026114532.jpg', 25.0047037, 121.2587779),
(245, '梨山雪梨', '產期：11月~翌年2月\r\n規格：一盒2粒\r\n雪梨喜愛海拔高、氣候冷的生長環境，是梨山特選之果。在黃褐色粗皮包覆下，更加襯顯出梨肉的潔白細緻，削皮時豐盈的果汁隨即涓滴而出，果肉清脆甘美且甜度均勻，滿是梨滋味，更具有綿密近乎入口即化的上乘品質，此等梨中極品豈容錯過！', '臺中市和平區東關路3段161號', '04-2594-1518', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17569/480x360_03台中市和平區農會_雪梨-20151217182407.jpg', 24.174661, 120.885178),
(246, '總統梨禮盒 (豐水梨、新興梨)', '產期：5月~10月\r\n規格：高接梨(豐水梨、新光梨)6粒裝(7台斤)\r\n臺中東勢被譽為「高接梨的故鄉」，東勢梨農首先運用嫁接技術，將溫帶梨之花穗嫁接於平地之橫山梨，使平地亦能生產高品質的溫帶梨，以豐水、新興梨及雪梨為大宗，收成之果實無論外型與甜度皆為上品，深受消費者喜愛，堪稱梨中精品。', '臺中市東勢區豐勢路297號', '04-2587-2151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17572/480x360_04東勢區農會_總統梨-20151217182757.jpg', 24.2534386, 120.829146),
(247, '皇梨精美禮盒', '產期：12月~ 翌年2月\r\n規格：高山雪梨( 皇梨)1 粒裝(2 台斤)\r\n臺中東勢被譽為「高接梨的故鄉」，東勢梨農首先運用嫁接技術，將溫帶梨之花穗嫁接於平地之橫山梨，使平地亦能生產高品質的溫帶梨，以豐水、新興梨及雪梨為大宗，收成之果實無論外型與甜度皆為上品，深受消費者喜愛，堪稱梨中精品。', '臺中市東勢區豐勢路297號', '04-2587-2151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17573/480x360_05看不出哪裡_皇梨-20151217183440.jpg', 24.2534386, 120.829146),
(248, '客家擂茶', '購買專線：03-5802207、03-5801073\r\n聯絡信箱：b3003@bps.org.tw\r\n擂茶（又名三生湯）是客家人招待貴客及飲用的茶點。擂為研磨之意，以陶製擂缽將茶葉，花生，芝麻等原料研磨後沖入沸水調勻後飲用。客家擂茶，茶味純，香氣濃，清涼解暑，不僅能生津止渴亦可當保健飲料，也是非常傳統的客家美食。', '新竹縣北埔鄉北埔街94號', '03-580-2207', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18088/480x360_056-101 客家擂茶_20121005 (400X320)-20151026114801.jpg', 24.700475, 121.055203),
(249, '小番茄', '臺南市安南區土壤含鹽份較高，所種植之小蕃茄甜度更高，栽種在溫室中的小番茄，被農民像照料小孩般悉心呵護關懷著，果蒂新鮮，果色鮮紅均勻，果實豐滿光滑、皮薄多汁、糖酸比適中，甜中帶甘，深受消費者青睐。', '臺南市新營區民治路5號', '06-632-4151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17493/480x360_11台南地區農會_小番茄-20151217185529.jpg', 23.31088189999, 120.3208439999),
(250, '金棗鮮果禮盒', '金柑俗名「金棗」，果實飽滿多汁，果皮香甜可食，酸中帶甜的金柑鮮果，除了是令人忍不住憶起戀愛般滋味的「戀人果」，也是春節送禮的好伴手，「吃金棗，年年好」、「金玉滿堂，棗到幸福」，是不是格外應景呢？', '宜蘭縣礁溪鄉中山路1段175號之1', '03-988-2033', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17494/480x360_12礁溪農會_礁溪金棗02-20151217190141.jpg', 24.82079209999, 121.7705359999),
(251, '黑紫玉 (葡萄)', '晶瑩透亮的葡萄如同珍珠瑪瑙般神祕而高貴，好的葡萄色澤紫中帶黑，摸起來堅實；聞起來芳香四溢；吃起來更是圓潤多汁。水里葡萄均採套袋管理，在獨特的氣候與技術管理下，孕育出香、Q、甜且帶有果粉，品質絕佳的葡萄，誠摯向您推薦水果中的寶石&mdash;黑紫玉。', '南投縣水里鄉民生路362號', '04-9277-2108', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17495/480x360_13日光鮮果--08水里黑紫玉葡萄-20151217190448.jpg', 23.8171897, 120.8540962),
(252, '蜜棗精品禮盒', '高樹蜜棗栽培於荖濃溪下游受茂林山下西北風吹襲，不易致病蟲害，由純淨優質水源灌溉滋養，在重重自然環境保護與高樹鄉親的愛心培育之 下，青翠的蜜棗有著驚人的碩大果實，脆甜多汁的果肉，咬下一口，好似春天就在嘴裡迸發，是您不得不嚐鮮的經典饗宴！', '屏東縣高樹鄉南興路 143 號', '08-796-0815', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17496/480x360_17蜜棗-20151217192226.jpg', 22.824074, 120.601138),
(253, '富貴圓滿禮盒', '「不起眼的農產品，經過設計包裝，就能成為精緻禮盒，為農民帶來合理的利潤。」社頭是傳統農業鄉鎮，每年7 月~ 8 月是龍眼產，從山腳路沿線瀰漫烘焙龍眼乾的淡淡香氣與白煙，農民守在磚造「焙灶」工寮內，守著爐火耐心烘焙，饒富人文歷史風味。為協助農民增加收益，農會以桂圓肉、桂圓麵和蜂蜜組成「富貴圓滿」、「富貴樂」與「富貴良緣」3 種大紅禮盒，是送禮的絕佳首選。\r\n訂購專線：04-8735437', '彰化縣社頭鄉社斗路一段360號', '04-873-2516', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17497/480x360_219社頭鄉農會_富貴圓滿禮盒-20151218161636.jpg', 23.896825, 120.5847081999),
(254, '富貴樂禮盒', '「不起眼的農產品，經過設計包裝，就能成為精緻禮盒，為農民帶來合理的利潤。」社頭是傳統農業鄉鎮，每年7 月~ 8 月是龍眼產，從山腳路沿線瀰漫烘焙龍眼乾的淡淡香氣與白煙，農民守在磚造「焙灶」工寮內，守著爐火耐心烘焙，饒富人文歷史風味。為協助農民增加收益，農會以桂圓肉、桂圓麵和蜂蜜組成「富貴圓滿」、「富貴樂」與「富貴良緣」3 種大紅禮盒，是送禮的絕佳首選。\r\n訂購專線：04-8735437', '彰化縣社頭鄉社斗路一段360號', '04-873-2516', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17505/480x360_220社頭鄉農會_富貴樂禮盒-20151218162105.jpg', 23.896825, 120.5847081999),
(255, '濁水溪米醬禮盒', '日光眷顧下的秧苗，在濁水溪水悠悠的灌溉及農夫辛勤的呵護下，終能結成美麗的稻穗；而這一片片金黃飽滿，彷彿知道自己承載了滿滿的心意，總是隨風輕輕的不住點頭言謝，期待著收成，向您傳遞一份愛的穀粒。\r\n訂購專線：05-5863621#166', '雲林縣西螺鎮延平路353號', '05-586-3621', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17534/480x360_217西螺鎮農會_濁水米禮盒-20151218164141.jpg', 23.8003737, 120.4546302),
(256, '菇菇茶集', '咕嚕咕嚕......趕緊泡上一壺心愛的18 號紅茶，與三五好友分享幸福的「菇菇茶集」，小心翼翼地啃著紅茶酥餅、香菇脆片，留下滿口的茶香，溫軟著疲憊的肚皮，讓一整個下午充滿濃濃幸福味。', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17536/480x360_213魚池鄉農會_姑菇茶集-20151218164812.jpg', 23.89618859999, 120.9350395999),
(257, '有福同享組合禮盒', '遵循古法慢火煙燻炭焙，過程繁複勞累，用汗水的鹹化成龍眼的甜；搭配純天然香濃味美的龍眼蜜，交織成一種味道難以忘懷，一份感動無可取代，這份心意就從「有福同享」間蔓延，箇中辛酸只有農民才懂。\r\n訂購專線：049-2693934', '南投縣中寮鄉永平村永平路186號', '04-9269-1111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17537/480x360_212中寮農會_有福同享禮盒(大)-20151218165048.jpg', 23.8787397, 120.7678090999),
(258, '胡麻油禮盒', '「麻油」，它曾伴隨著我們的先人，是他們日常生活中最佳的營養補給品，如今雖然搾油方式或多或少有所改變，但依然是民眾之所愛。善化農會的麻油風味香、濃、醇，品質極佳，一直以來深受許多消費者的喜愛與肯定，相信也是您平日烹調用油的好選擇。', '臺南市善化區中山路242號', '06-583-6111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19314/480x360_4.png', 23.132757, 120.2976479999),
(259, '龍井傳香米禮', '看天吃飯，農業本如此，沒有華麗的陪襯，簡單、樸實之中，隱藏著生活的智慧與軌跡。在品味真實原味的同時，感受根源於大地的食材誠實，心靈彷彿也受到「純‧ 真」的洗禮，那不只是天賜，是汗水種出的美味。', '臺中市龍井區龍門路 40 號', '04-2639-6511', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17538/480x360_210龍井區農會_傳香米禮1-20151218170048.jpg', 24.180667, 120.529265),
(260, '羅漢門龍眼乾', '說到龍眼乾，大家的味蕾一定會帶到濃濃的碳香味，「羅漢門」龍眼乾烘焙，需先去除枝葉放入窯中烘培後，以人工撥殼取出龍眼肉，太陽下曬數日，才能製成香Ｑ甜的龍眼肉。放入嘴內，每次的咀嚼呈現出不同層次的風味，那滋味無法去形容，只有試過的人才知道。', '高雄市內門區內豐村內埔1-1號', '07-667-2161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17539/480x360_209內門區農會_龍眼乾-20151218171431.jpg', 22.94175459999, 120.4613715),
(261, '山形玫瑰花瓣醬', '「遍尋世界玫瑰花種類，終於找到顏色深紅，花型優美，口感甜香的品種。」農會與農民契作，用無毒栽培，種植出最天然的玫瑰花。每日所摘採新鮮花瓣有多種食用方式，冷熱飲可隨季節調整，可沖泡出真正香氣濃郁的「花」茶，而做成果醬、沙拉醬、優格更是別具風味，歡迎您來品嚐！', '南投縣埔里鎮清新里西安路一段六號', '04-9298-6420', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17540/480x360_208百未--埔里農會--07山行玫瑰花瓣醬-20151218171557.jpg', 23.963721, 120.9641679999),
(262, '幸福梅好禮盒', '梅子從5 分熟的青綠果採到金黃軟綿的完熟果，口感各有風情。雖然梅子雖不能像水果一樣直接吃，但卻能變身各式各樣的製品。南投縣農會沿襲老祖母料理加工梅子的傳統手法，製成多款梅製品，酸酸甜甜的好滋味，讓人就像談了場戀愛一般，心情都快樂了起來！', '南投縣南投市南崗三路1號', '04-9225-1170', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17542/480x360_207百味--南投縣農會--06幸福好梅禮盒-20151218172034.jpg', 23.9222475, 120.6723086),
(263, '柴之燒炭焙龍眼乾禮盒', '當龍眼採收季節，經驗老道的師傅，以龍眼樹枝為柴薪，遵循古法、乾柴慢火、煙燻如霧、耐心的將龍眼粒翻焙一遍又一遍，經歷三天兩夜的烘焙，造就完美風味。', '南投縣中寮鄉永平村永平路186號', '04-9269-1111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17543/480x360_205百味--中寮農會--05柴之燒禮盒-20151218172229.jpg', 23.8787397, 120.7678090999),
(264, '雙柚金饌禮盒', '麻豆文旦是最講究的水果。文旦迷們計較的不僅是文旦的產地與外型，還要精挑是否來自麻豆區的特別角落。臺灣文旦柚多以鮮食為主，但農會精選優質麻豆文旦，利用高效能萃取技術及低溫真空濃縮技術製成果茶，用酸甜口感感動每一位遊客，為地方特色產品打造一個新舞臺。', '臺南市麻豆區興國路58號', '06-571-5790', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17507/480x360_203麻豆農會_文旦柚茶02-20151218174449.jpg', 23.176068, 120.2465369999),
(265, '龍眼干', '炎炎夏日，龍眼樹上結實纍纍的果實，在豔陽照射下，如金黃色般的珍珠，充滿著生命力。東山區的龍眼乾以土窯古法烘焙，採收後經過生火慢燻、脫粒、翻焙，去殼去籽，才能做出被稱為「福肉」的龍眼乾。關於東山龍眼的故事還很多，不妨走訪東山，來趟農趣體驗之旅。', '臺南市東山區中興路1號', '06-680-0814', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17544/480x360_201至202東山區農會_龍眼乾(綜合)-20151218181529.jpg', 23.1781599, 120.483966),
(266, '芒果干', '購買專線：06-5731716、06-5731251\r\n聯絡信箱：ching200283@yahoo.com.tw\r\n左鎮是農業小鄉，有著許多不為外鄉民眾週知的新鮮一面，來到左鎮，別忘了區內正夯的伴手禮- 芒果干。左鎮區農會依循古法烘製芒果干，一顆芒果只取4 片果肉的作法，所製作出來的芒果干口感不死甜，反而品嚐得到芒果干特有濃郁香氣與酸甜滋味。', '臺南市左鎮區中正里98-1號', '06-573-1046', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17545/480x360_200百味--左鎮農會--台灣芒果干-20151218175141.jpg', 23.0585278, 120.4077237),
(267, '瓊福滿溢', '瓊，瓊玉。即為美好的意思，以客家人此辛勤栽種的優良好米，加上番茄所製作的番茄米粉，都是在地人的誠意獻禮，希望收到好米與米粉的人，都吃到這份用心與美味，並得到美好福分就像泉水倒到杯子裡滿出來一樣。', '新竹縣芎林鄉富林路二段495巷12號(富林店)', '03-592-1173', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18090/480x360_058-101 瓊福滿溢_20121007 (400X320)-20151026114907.jpg', 24.7742887, 121.0804279),
(268, '太麻里釋迦', '有「日昇之鄉」美名的太麻里，依山傍海，溫暖乾燥的氣候、及排水良好的砂質土壤，讓這裡產出的釋迦個頭碩大，籽小肉多，令人驚歎。撥開樸素暗綠的外表，太麻里大目釋迦白晳宛如奶色，果實飽滿紮實 ，肉香甜Q 彈，營養價值極高，還能有效補充體力，是活力滿載的水果！', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17574/480x360_10日光鮮果-05太麻里釋迦-20151217184559.jpg', 22.604987, 121.001855),
(269, '綺羅香蓮霧', '「綺羅香」乃古代高級珍貴絲織品散發著清香之意，枋寮地區農友細心呵護的黑珍珠蓮霧，型如吊鐘、肉質細膩、色澤紫紅、甜美多汁，故以此為名。蓮霧產期經多年的調節，由夏季水果成為冬季珍品，臺灣幾乎整年都可以吃到蓮霧，「綺羅香蓮霧」，如此百分百完美改造的臺灣之光，洋溢著南臺灣熱情的人情味。\r\n訂購專線：08-8713031', '屏東縣枋寮鄉安樂村安樂路82號', '08-878-5121', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17577/480x360_16枋寮地區農會_黑珍珠蓮霧-20151219135959.jpg', 22.3627913, 120.5965769),
(270, '台灣蜜棗', '新年想要「棗」幸福？「棗」圓滿？請用大社出品汁多爽口棗禮盒。由農會派專員自產銷班130 公頃蜜棗果園中，精選甜度高、肉質細緻、汁多、皮薄及脆度高者包裝成禮盒，為年節送禮最佳首選。', '高雄市大社區三民路391號', '07-351-1111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17578/480x360_18大社區農會_台灣蜜棗-20151217192443.jpg', 22.7296147, 120.346602),
(271, '番石榴', '國產水果拔仔最熱評，拔仔產地直銷享新鮮，帝王、珍珠、紅心皆可口，大社精選最可靠，由農會派專員自產銷班200 公頃芭樂果園中，精選甜度高、肉質細緻、汁多、皮薄及脆度高者包裝成禮盒，不分時節全年度為您傳達心意。', '高雄市大社區三民路391號', '07-351-1111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17579/480x360_19大社區農會_番石榴-20151217192656.jpg', 22.7296147, 120.346602),
(272, '富貴良緣禮盒', '「不起眼的農產品，經過設計包裝，就能成為精緻禮盒，為農民帶來合理的利潤。」社頭是傳統農業鄉鎮，每年7 月~ 8 月是龍眼產，從山腳路沿線瀰漫烘焙龍眼乾的淡淡香氣與白煙，農民守在磚造「焙灶」工寮內，守著爐火耐心烘焙，饒富人文歷史風味。為協助農民增加收益，農會以桂圓肉、桂圓麵和蜂蜜組成「富貴圓滿」、「富貴樂」與「富貴良緣」3 種大紅禮盒，是送禮的絕佳首選。\r\n訂購專線：04-8735437', '彰化縣社頭鄉社斗路一段360號', '04-873-2516', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17516/480x360_221精選--社頭--富貴良緣禮盒-20151218162253.jpg', 23.896825, 120.5847081999),
(273, '穀意禮', '「季節的更替，時光的流轉，眼見又是稻穗金黃熟成時，作田莊稼漢的辛勞，是嘸人完全知影耶！」儘管稻米名氣不若池上米、西螺米響亮， 田中鎮農會仍積極推廣農民辛苦栽種的優質好米；引領民眾認識稻穗的故鄉，感受農民的辛勤耕耘； 以獨特的故事行銷手法，走出「田中米」的自我特色。', '彰化縣田中鎮南北街80號', '04-874-9211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17531/480x360_218田中鎮農會_穀意禮1-20151218163126.jpg', 23.85965819999, 120.5863643),
(274, '有機原釀禮饌醬油組', '滿州原生種小黑豆耐鹽又耐風，顆粒雖小，但豆味濃郁厚實。不必噴灑農藥，就能健康成長。農會看好「食安商機」，研發醬油、蔭油膏、豉鼓等產品，推出「原釀禮饌」有機黑豆醬油，味道芳香甘醇，強調古法釀造、無添加。\r\n訂購專線：08-8801849', '屏東縣滿州鄉中山路 34 號', '08-880-1849', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17532/480x360_215滿洲鄉農會_原釀禮饌-20151218163802.jpg', 22.0195408, 120.83847),
(275, '一提兩麵', '集集山蕉是日據時代專供日本天皇品嚐的貢品。來到集集，除了拜訪古蹟景點，帶個伴手禮自然是少不了的。「一提兩麵」禮盒，內有千山香蕉麵、養生紅龍麵及鄉村蔬菜醬，口感香Q、口味獨特且包裝精美。', '南投縣集集鎮民生路 113 號', '04-9276-1700', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17535/480x360_214集集鎮農會_一提兩麵-20151218164526.jpg', 23.8269924, 120.783617),
(276, '南投梅宴甜菊梅禮盒', '梅子從5 分熟的青綠果採到金黃軟綿的完熟果，口感各有風情。雖然梅子雖不能像水果一樣直接吃，但卻能變身各式各樣的製品。南投縣農會沿襲老祖母料理加工梅子的傳統手法，製成多款梅製品，酸酸甜甜的好滋味，讓人就像談了場戀愛一般，心情都快樂了起來！', '南投縣南投市南崗三路1號', '04-9225-1170', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17541/480x360_206百味--南投縣農會--06南投梅宴甜菊梅禮盒-20151218171832.jpg', 23.9222475, 120.6723086),
(277, '玄海御饌-海鮮禮盒', '寶島臺灣四周環海，魚類資源豐富，玄海御饌收錄全臺各地漁貨之大成，嚴選臺南白蝦、午仔魚，永安石斑魚，沿海土魠魚，以及遠洋漁船捕獲的白鯧、軟絲，共六項上等鮮味，經急速冷凍處理，將最原始的鮮甜美味牢牢封印，是臺灣海洋鮮味的頂級饗宴。\r\n訂購專線：02-89853993', '新北市三重區力行路一段6號', '02-8985-3966', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17546/480x360_199玄海御饌-20151218175432.jpg', 25.0668779, 121.4878575),
(278, '金鑽烏魚子禮盒', '鹿港老街擁有悠久歷史人文風華，街頭巷弄之間常見散發耀眼金色光芒的烏魚子。鹿港烏魚子以傳統古法製成，風味獨特口感絕佳，嚴選成熟烏魚卵製成，飽滿對稱，金黃透澄，古樸木盒外觀宛如鹿港般迷人，有著說不完的動人故事。', '彰化縣鹿港鎮復興路485號4樓', '04-778-8945', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17547/480x360_198彰化漁會_金鑽烏魚子禮盒1-20151218175705.jpg', 24.0587671, 120.434389),
(279, '彰漁蒲燒鰻禮盒', '鹿港地區有鰻魚王國的美稱，出產的鰻魚質地鮮嫩風味絕佳，營養價值極高。十多年來用心堅持品質，精選優質成鰻製成日式浦燒風味，通過HACCP、CAS 等標章認證，以真空包裝加熱即可食用，安全衛生，是年節送禮、犒賞家人的最佳選擇。', '彰化縣鹿港鎮復興路485號4樓', '04-778-8945', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17548/480x360_197上選鮮味--13彰化區漁會--蒲燒鰻禮盒-20151218175911.jpg', 24.0587671, 120.434389),
(280, '淡水魚藏吻魚雙醬', '波瀾壯闊的淡水，澄黃夕陽美景引人入勝，沿海物產豐盛，小星鑽－魩仔魚肉質鮮嫩美味，為頂級上品，富含蛋白質與鈣質，是補充營養的最佳來源。魚藏吻魚雙醬以魩仔魚做基底，分別加上東港櫻花蝦及精選干貝製作而成，口感更加豐富，滿足味蕾享受，吃起來輕鬆無負擔。', '新北市淡水區觀海路199號2樓', '02-2805-5000', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17566/480x360_195淡水區漁會_淡水魚藏雙醬-20151218180522.jpg', 25.183685, 121.411379),
(281, '8 樂鮮果禮盒', '彰化縣社頭鄉由於產區的土質、氣侯極為適合芭樂果樹的生長，為全臺灣最早、最專業、最主要的芭樂產區之一，一年四季均有生產，肉質細緻、甜度高、脆度夠，歷年參加全國芭樂評鑑皆獲團體第一名，絕對是誠意足、份量夠的送禮選擇。\r\n社頭鄉農會長期輔導鄉內果農，加入吉園圃生鮮蔬果產銷班，以自然農法栽種安全、高品質的芭樂，每年並舉辦芭樂品質競賽，鼓勵果農栽種高優質的鮮果，歷年參加全國芭樂評鑑皆獲團體第一名，社頭農會評選出外型、品質、甜度均優異的鮮果，以八顆為單位組成「芭樂鮮果禮盒」，將嚴選果品做差異化行銷，提升果農的收益。', '彰化縣社頭鄉社斗路一段360號', '04-873-2516', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17594/480x360_27日光鮮果-19社頭8樂鮮果-20151218221210.jpg', 23.896825, 120.5847081999),
(282, '特選春 (冬) 茶 (原味)', '除與特選春(冬)茶(中度焙火)相同的原料外，茶葉細嫩、緊結、勻整、墨綠有光澤。茶湯水色澄黃、透明、亮麗。香氣具清香、幽雅、甜和、略帶花香。滋味香甜、甘醇、滑潤、爽口。', '南投縣彰雅村中正路一段231號', '04-9275-1962', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19326/480x360_特選春_(冬)_茶_(原味).jpg', 23.74097, 120.757563),
(283, '文山包種茶 (明月等級)', '文山包種茶以採摘軟嫩茶菁精心焙製而成，為條索狀，色澤墨綠鮮麗，茶湯蜜黃碧綠，入口醇郁濃厚，芳香撲鼻，回味無窮，乃茶中極品。明月、清風級茶葉，香味幽雅、味醇甘潤，是自用、送禮最佳的伴手禮。', '新北市板橋區縣民大道291號', '02-2968-5191', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17644/480x360_51新北市農會_文山包種茶-明月等級-20151218234728.jpg', 25.010467, 121.460372),
(284, '石門鐵觀音極上品禮盒', '石門鐵觀音茶年年入選百大精品，湯色金黃明亮、香氣沈穩、茶湯滑順，入口生津，精緻小巧，攜帶便利。產品包裝設計與概念，融合飲茶浪漫情懷及品茗意境，徜徉湖光水色，清閒優雅渾然忘我，展現茶與生活之藝術。', '新北市石門區(村)中央路2號', '02-2638-1005', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17646/480x360_54石門區農會_鐵觀音1斤-20151218235250.jpg', 25.2909969, 121.5647637999),
(285, '淡水魚藏吻魚鮮醬', '波瀾壯闊的淡水，澄黃夕陽美景引人入勝，沿海物產豐盛，小星鑽－魩仔魚肉質鮮嫩美味，為頂級上品，富含蛋白質與鈣質，是補充營養的最佳來源。魚藏吻魚雙醬以魩仔魚做基底，分別加上東港櫻花蝦及精選干貝製作而成，口感更加豐富，滿足味蕾享受，吃起來輕鬆無負擔。\r\n訂購專線：02-28055000', '新北市淡水區觀海路199號2樓', '02-2805-5000', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17549/480x360_196淡水區漁會_淡水魚藏2-20151218180402.jpg', 25.183685, 121.411379),
(286, '一口包烏魚子', '烏魚子是臺灣最具歷史紋理的美食之一，相傳數百年前的先民，因追捕烏魚來到臺灣定居，歷經多年演變，臺灣烏魚子已是全球聞名的MIT 美食代表。野生烏魚子的品質風味遠勝養殖烏魚子，富有嚼勁的彈牙感，香醇Q 實的味道讓許多饕客流連忘返愛不釋手。古法手工精製，營養價值極高，加上一口吃的輕便包裝，深受民眾喜愛。', '高雄市梓官區漁港2路32號', '07-610-7551', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17653/480x360_190梓官漁會_一口包烏魚子-20151218182254.jpg', 22.727833, 120.2546205999),
(287, '龍膽石斑系列禮盒', '龍膽石斑為深海魚，是石斑魚種類中體型最大的，有「斑王」的稱號。龍膽石斑為高經濟食用魚，富含營養，是宴客餐桌上常見佳餚。具產銷 履歷與SGS 檢驗通過，適合三五好友或小家庭聚餐食用，在家裡也能品嚐頂級的海鮮美味。', '高雄市梓官區漁港2路32號', '07-610-7551', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17654/480x360_191梓官漁會_龍膽石斑系列戀戀蚵仔寮-20151218182611.jpg', 22.727833, 120.2546205999),
(288, '極醬 XO 醬禮盒', '有人說，所謂XO 醬的名稱來源是因為製作時所使用的材料都是高級食材，與白蘭地干邑中的頂級酒XO 一樣屬於最高等級，所以稱為醬中的XO。東港鎮XO 醬以嚴選海鮮食材為基底，飽飽一罐中富含鮮甜的海洋風味及豐富的海鮮餡料，當湯匙一口挖起，吃進嘴滿滿的鮮味及海洋風味，彷彿沐浴在海風中，堪稱XO 醬界的第一把交椅！誰能抗拒！', '高雄市梓官區漁港2路32號', '07-610-7551', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17457/480x360_188梓官漁會_極醬-20151218183114.jpg', 22.727833, 120.2546205999),
(289, '漁婦佳餚', '魩仔魚粥為臺灣飯桌上常見佳餚，是大海賜予人們的禮讚。嚴選產地新鮮現撈魩仔魚，與在地優質好米，搭配鮮採蔬菜如香菇、玉米等，使用溫火熬煮而成，新鮮營養的便利粥，風味絕佳入口即化，十足人情味的漁村文化特色包裝，是老少咸宜的產品。', '高雄市梓官區漁港2路32號', '07-610-7551', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17456/480x360_187梓官漁會_漁婦家餚-20151218183449.jpg', 22.727833, 120.2546205999),
(290, '二尖山高山茶', '南投中寮鄉二尖茶區， 海拔高度1,000~1,200 公尺，經年雲霧繚繞，土壤肥沃雨量適中，優異條件的地理環境，造就出具香、醇、濃、韻、美獨到特色二尖山高山茶。二尖茶以其嫩葉製成，成品外觀油墨亮綠、水色蜜黃澄清、滋味清香甘醇，令人回味無窮。\r\n訂購專線：049-2693934', '南投縣中寮鄉永平村永平路186號', '04-9269-1111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17656/480x360_35中寮鄉農會_二尖茶-20151218230935.jpg', 23.8787397, 120.7678090999),
(291, '合歡山霜韻茶', '生長於合歡山麓的烏龍茶，歷經春雨、夏風、秋霜、冬雪，在手工精摘、火文細焙的呵護下，茶葉出落得色澤翠綠鮮活，茶湯清澈明亮而金黃，滋味滑軟甘醇，香氣持久渾厚，葉肉厚，果膠質含量高，耐沖泡，入喉後茶味綿延彌久，「霜韻茶」實至名歸。', '南投縣仁愛鄉南豐村中正路80-3號', '04-9292-0480', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17657/480x360_36仁愛鄉農會_霜韻茶03-20151218231119.jpg', 24.00481419999, 121.0889033999),
(292, '大禹嶺朱鵲紅茶', '山林間的紅寶石─朱鵲紅茶，座落於山之巔，雲霧瀰漫的大禹嶺茶區，是國內目前海拔高度最高的紅茶。香氣甜潤裡帶秀雅花香，滋味醇郁中隱現甘韻，茶葉外觀條索勻整，茶湯呈美麗的酒紅色，就如同披著一身朱紅亮麗外衣、棲身高海拔山區的酒紅朱雀般珍貴稀有，名茶與珍禽相互輝映。', '南投縣仁愛鄉南豐村中正路80-3號', '04-9292-0480', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17658/480x360_37仁愛鄉農會_朱鵲紅01-20151218231307.jpg', 24.00481419999, 121.0889033999),
(293, '柿餅加工系列產品-柿糬', '來自新埔新鮮柿餅，製作而成的柿糬。本產品採用在地製作柿餅，結合客家麻糬，以花生及山藥為內餡,純手工製作，一入口有柿餅的自然香甜，QQ軟軟的麻糬,蘊藏著濃郁花生或山藥的口味，是一種古早味新感受。', '新竹縣新埔鎮楊新路一段322號', '03-588-4351', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18091/480x360_061-096 柿餅加工系列產品-柿糬_20071226 (400X320-01)-20151026115414.jpg', 24.8310298, 121.0874593),
(294, '杉林溪烏龍茶', '杉林溪茶，一心二葉，片片手採，只挑鮮嫩綠芽，葉芽柔軟，葉面厚實。由於生長環境高寒，終年雲霧籠罩，土壤肥沃雨量適中，造就茶色翠綠清透，呈現淡雅的天然果香，又終年生長杉樹間，以杉木為鄰 ，故其味道有苦中帶甘之口感，益添清雅悠遠。', '南投縣竹山鎮下橫街38號', '04-9264-2186', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17659/480x360_39竹山鎮農會_杉林溪烏龍茶-20151218231716.jpg', 23.756698, 120.6846309999),
(295, '杉林溪烏龍茶 (新品種)', '杉林溪茶，一心二葉，片片手採，只挑鮮嫩綠芽，葉芽柔軟，葉面厚實。由於生長環境高寒，終年雲霧籠罩，土壤肥沃雨量適中，造就茶色翠綠清透，呈現淡雅的天然果香，又終年生長杉樹間，以杉木為鄰 ，故其味道有苦中帶甘之口感，益添清雅悠遠。', '南投縣竹山鎮下橫街38號', '04-9264-2186', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17639/480x360_40竹山鎮農會_杉林溪新品種烏龍茶-20151218231848.jpg', 23.756698, 120.6846309999),
(296, '玉山高海拔優良茶', '高山冷涼、平均日照短，特殊的地理條件，是培植烏龍茶的絕佳環境，凌駕群峰的「玉山高山茶」，葉色澤鮮活翠綠、香氣輕揚悠雅，久聞不厭，沖泡後的茶湯更是溫潤滑順、喉韻生津，讓人口齒留香。', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17640/480x360_41信義鄉農會_玉山烏龍茶2-20151218232346.jpg', 23.68870099999, 120.861791),
(297, '南投茶宴', '南投縣高山林立，有著豐盛、多樣的茶葉製品，設「南投茶宴」以堂皇隆重款待消費者，提供境內優質的、可以驕傲地亮出產品履歷條碼「身分證」的茶葉。高山茶色澤翠綠鮮活，水色蜜綠顯黃，滋味甘醇滑軟，香氣淡雅，歡迎來找茶！\r\n訂購專線：049-2251170', '南投縣南投市南崗三路1號', '04-9225-1170', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17641/480x360_42南投縣農會_南投茶宴-20151218232534.jpg', 23.9222475, 120.6723086),
(298, '日月潭典藏禮盒', '在湖光山色，霧氣瀰漫猶如畫境般美景的日月潭，踏訪紅茶的故鄉。挑TEA，就是要有挑剔的精神，紅玉、阿薩姆、紅韻、藏芽&hellip;&hellip;，變化萬千的是茶韻，始終不變的是對日月潭禮盒對紅茶品質的堅持。\r\n訂購專線：049-2898453', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17662/480x360_43魚池鄉農會_典藏禮盒-20151218232852.jpg', 23.89618859999, 120.9350395999),
(299, '日月潭精選禮盒', '在湖光山色，霧氣瀰漫猶如畫境般美景的日月潭，踏訪紅茶的故鄉。挑TEA，就是要有挑剔的精神，紅玉、阿薩姆、紅韻、藏芽&hellip;&hellip;，變化萬千的是茶韻，始終不變的是對日月潭禮盒對紅茶品質的堅持。', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17643/480x360_44魚池鄉農會_精選禮盒-20151218233023.jpg', 23.89618859999, 120.9350395999),
(300, '日月潭紅璽禮盒', '一次聚集日月潭紅茶4 大茶種：臺茶18 號、臺茶21 號、阿薩姆紅茶及臺灣山茶，各具不同香氣及韻味。', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17664/480x360_45魚池鄉農會_紅席禮盒-20151218233153.jpg', 23.89618859999, 120.9350395999),
(301, '春 (冬) 茶', '純樸古意的茶農、綠油油的茶田、氤氳的茶香，南投可謂「茶的故鄉」。具傳統焙火熟果香、芬芳怡人，茶湯水色明亮、豔麗、琥珀色。滋味甘醇、滑潤、爽口。來自傳統凍頂茶區，焙製方法由傳統工法製作，具地方特色口味。\r\n訂購專線：049-2751962', '南投縣彰雅村中正路一段231號', '04-9275-1962', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17600/480x360_46鹿谷鄉農會_春(冬)茶300公克x2-20151218233323.jpg', 23.74097, 120.757563),
(302, '春( 冬) 茶', '純樸古意的茶農、綠油油的茶田、氤氳的茶香，南投可謂「茶的故鄉」。具傳統焙火熟果香、芬芳怡人，茶湯水色明亮、豔麗、琥珀色。滋味甘醇、滑潤、爽口。來自傳統凍頂茶區，焙製方法由傳統工法製作，具地方特色口味。', '南投縣彰雅村中正路一段231號', '04-9275-1962', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17665/480x360_47鹿谷鄉農會_春(冬)茶150公克x2-20151218233457.jpg', 23.74097, 120.757563),
(303, '特選春 (冬) 茶 (中火)', '產於鹿谷鄉海拔1500公尺高山茶區，常年雲霧繚繞，日夜溫差大，茶菁柔軟肥厚內容豐富，茶葉細嫩，緊結、勻整、墨綠有光澤。茶湯水色澄黃、透明、亮麗、香氣清雅、略帶花香。滋味香甜、甘醇、柔順、飲後口齒留香、生津味無窮。', '南投縣彰雅村中正路一段231號', '04-9275-1962', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19322/480x360_特選春_(冬)_茶_(中火).jpg', 23.74097, 120.757563),
(304, '特選春 (冬) 茶 (中火)', '產於鹿谷鄉海拔1500公尺高山茶區，常年雲霧繚繞，日夜溫差大，茶菁柔軟肥厚內容豐富，茶葉細嫩，緊結、勻整、墨綠有光澤。茶湯水色澄黃、透明、亮麗、香氣清雅、略帶花香。滋味香甜、甘醇、柔順、飲後口齒留香、生津味無窮。', '南投縣彰雅村中正路一段231號', '04-9275-1962', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19318/480x360_特選春_(冬)_茶_(中火)禮盒.jpg', 23.74097, 120.757563),
(305, '吉利/珍珠鮑魚禮盒', '臺灣東北角貢寮依山傍海景觀秀麗，為知名旅遊聖地，東臨太平洋之濱，水質清澈，盛產海鮮名聞遐邇，所孕育出的鮑魚肉質Q 彈，採收鮮活九孔鮑魚製作成開罐即食的鮑魚罐頭，美味有如生鮮現撈，貢寮鮑為品牌保證，是節慶送禮最佳選擇。', '新北市貢寮區新港街91號', '02-2490-1105', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17567/480x360_194貢寮區漁會_貢寮鮑1-20151218180921.jpg', 25.056794, 121.926509),
(306, '鱸魚鬆隨行包', '金目鱸魚為中華料理常見高級食材，肉質細緻綿密，滑溜順口，富含營養價值，常見調理方式為燉湯或清蒸。遵循古法研製的鱸魚鬆，從鱸魚原料開始即用心嚴選通過檢驗，讓魚鬆保留新鮮的傳統風味，香氣四溢的美味來自於製造者的用心，食用方便且利於攜帶，為當地著名人氣產品。', '高雄市永安區新興路27之2號', '07-691-2020', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17568/480x360_193永安區漁會_鱸魚鬆-20151218181226.jpg', 22.8175669, 120.210497),
(307, '農會牌肉酥禮盒', '近來食安問題引起恐慌，為讓大家買的放心，吃的安心，特選CAS 認證健康豬後腿肉，肉質鮮美富有彈性，不添加豆粉、防腐劑、色素及糖精等人工化學物，加入特調醬料細心醃製，並經多道精密程序處理而成，真材實料滋味絕佳，口感香酥，是饋贈親友的最佳伴手禮。\r\n訂購專線：0800-666980', '新北市板橋區縣民大道291號', '02-2968-5191', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17581/480x360_192上選鮮味--新北市農會--農會牌肉鬆禮盒-20151218181412.jpg', 25.010467, 121.460372),
(308, '漁婦佳餚', '有人說，所謂XO 醬的名稱來源是因為製作時所使用的材料都是高級食材，與白蘭地干邑中的頂級酒XO 一樣屬於最高等級，所以稱為醬中的XO。東港鎮XO 醬以嚴選海鮮食材為基底，飽飽一罐中富含鮮甜的海洋風味及豐富的海鮮餡料，當湯匙一口挖起，吃進嘴滿滿的鮮味及海洋風味，彷彿沐浴在海風中，堪稱XO 醬界的第一把交椅！誰能抗拒！', '高雄市梓官區漁港2路32號', '07-610-7551', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17759/480x360_189梓官漁會_漁婦佳餚--烏魚子xo醬-20151218183242.jpg', 22.727833, 120.2546205999),
(309, '花蓮鰹干貝 XO 醬', '天色未亮朦朧之際，漁夫航行於蔚藍東部海洋，隨著鰹魚動向流浪四方。鰹魚是臺灣民眾最喜愛的魚類之一，蛋白質含量極高，進行加工後可製成柴魚片或鰹魚罐頭。而鰹干貝XO 醬，僅採用油脂含量高的頂級肥美鰹魚，嚴選生魚片食用部位作為主要材料，再佐以金華火腿及干貝精製調味而成，濃郁香甜渾然天成，最能代表花蓮在地獨特風味，一入口彷彿海洋鮮味無窮無盡散播開來，不論拌飯拌麵、料理美食皆為一絕。', '花蓮縣花蓮市港濱路37號', '03-822-3118', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17758/480x360_186花蓮區魚會_XO醬-20151218183728.jpg', 23.9962107, 121.6385013),
(310, '煙仔平', '後山花蓮景觀壯麗，水質潔淨，蘊育出最佳魚種品質，鰹魚俗稱炸彈魚，為臺灣東部海域特有的迴游性魚類，夏秋之際為其盛產期，也是鰹魚最為肥美的時節。鰹魚吸收太平洋黑潮精華，富含Omega-3 脂肪酸、EPA、DHA 及多元不飽和脂肪酸，均為人體需要的天然營養元素。本商品拆封後即可使用，共有4 種口味( 蜜汁、辣味、味噌、佃煮) 供消費者選購。', '花蓮縣花蓮市港濱路37號', '03-822-3118', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17757/480x360_185花蓮區漁會_煙仔乎-20151218183911.jpg', 23.9962107, 121.6385013),
(311, '旗魚鬆', '漁夫屏氣凝神，注視著海上偌大身軀的稀客，外形雄壯的旗魚為東港著名特產，也是遊客來到此地必嚐的美食。旗魚白中透肉色，味道甘美鮮脆口感佳，是養分極高的魚類，在臺灣及日本常是壽司與生魚片的珍品。此項產品已蟬聯7 年臺灣農漁會百大精品，受到廣大消費者喜愛，採用嚴選新鮮旗魚製作，入口即能感受香酥鮮甜的原始海洋風味。', '屏東縣東港鎮新生一路73號', '08-832-3121', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17585/480x360_184上選鮮味--屏東東港--旗魚鬆-20151218184050.jpg', 22.4677798, 120.4417895),
(312, '海龍王龍膽石斑分切禮盒', '龍膽石斑本來是深海魚，但因為臺灣具有得天獨厚的地理條件，加上多年來政府政策強力支持下，養殖魚友的養殖技術不斷有新的突破，純熟養殖技術與各種種苗培育經驗，讓這種營養價值高、經濟價值更高的魚種普及化。「海龍王龍膽石斑分切禮盒」突破大型龍膽石斑魚對於一般家庭的食用不便，分切不同部位及份量真空包裝，提供消費者新鮮、安全、方便的新選擇，也滿足每一位送禮者的心。', '屏東縣林邊鄉仁和村仁愛路82號', '08-875-1601', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17586/480x360_183上選鮮味--林邊區農會--龍膽石斑分切禮盒-20151218184331.jpg', 22.432048, 120.515759),
(313, '鯖宴罐頭禮盒', '鯖魚是南方澳名產，全年都可捕獲，從十月到次年農曆年前，是鯖魚最肥美的季節。漁會嚴選南方澳漁港豐富的漁產，製作4 種不同種類之罐頭，其現撈現做之口感，並含豐富DHA、EPA，為全國頂級夢幻逸品，因鯖魚為本地最大宗漁獲，故以「鯖宴」為名，代表以鯖魚為首，其他魚類為輔，提供給消費者之味蕾享受。\r\n訂購專線：03-9972808', '宜蘭縣蘇澳鎮南安里海邊路126號', '03-996-2108', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18548/480x360_5b7391c97ae54aafb7c3e593b4e4ed47.jpg', 24.5833868, 121.8659277),
(314, '臺灣鯛魚鬆 (脯) 禮盒', '歷經多年改良成功，肉質鮮甜沒有土味，體型碩大的臺灣鯛，被譽為臺灣國寶魚，臺南市為全國產量最大的地方，所製成的鯛魚酥香酥可口，色香味俱全，深受消費大眾喜愛，與細軟帶勁的鯛魚脯同為臺灣前進海外市場的頂級旗艦產品。', '臺南市新營區民治路5號', '06-632-4151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17754/480x360_178台南市農會_台灣鯛-20151218190312.jpg', 23.31088189999, 120.3208439999);
INSERT INTO `gift` (`id`, `name`, `feature`, `addr`, `tel`, `picurl`, `lat`, `lng`) VALUES
(315, '虱目魚酥 (脯) 禮盒', '虱目魚被臺南縣誌列為南灜第一特產，臺南可說是虱目魚的故鄉，充滿濃濃道地家鄉味與懷舊情感，肉質鮮嫩爽口，加工而成的虱目魚酥香脆甘鮮，虱目魚脯細軟帶勁，兩者口味獨特極受好評。', '臺南市新營區民治路5號', '06-632-4151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17755/480x360_179台南市農會_虱目魚酥-20151218190653.jpg', 23.31088189999, 120.3208439999),
(316, '安農香腸禮盒', '購買專線：04-26710909\r\n聯絡信箱：yiniuniu33@gmail.com\r\n採用當天現宰的豬後腿肉為原料，分別添加葡萄酒，以及在地特色農作物，製成葡萄酒香腸、大安蔥香腸及芋頭香腸，口感Q 彈多汁有嚼勁，鮮甜美味。', '臺中市大安區中庄里３鄰中松路６號', '04-2671-2229', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17587/480x360_177大安區農會_安農香腸1-20151218190850.jpg', 24.3463873, 120.5870304),
(317, '蜜棗', '燕巢具泥火山獨特地理環境，土質含豐富氧化鎂，所生產的蜜棗皆為網室栽培，皮薄多汁，果實脆美甘甜，鮮翠的果實在黃熟之後各有不同的 風味。「燕之巢」蜜棗皆有吉園圃安全蔬果標章，當天採收當天配送，給您最鮮甜的享受。', '高雄市燕巢區南燕里中民路577號', '07-616-2211#252', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17588/480x360_21燕巢區農會_台灣蜜棗-20151218214806.jpg', 22.7932786, 120.362621),
(318, '珍珠芭樂', '芭樂是燕巢鄉的綠色之寶，燕巢鄉也是珍珠芭樂的夢幻產地。燕巢因經泥火山岩漿土壤沖積，土質含豐富氧化鎂及其他微量元素，造就了珍珠芭樂的獨特風味，果實飽滿脆甜，果肉細緻且肉厚籽少，甘甜中略帶爽口的迷人酸香，不愧為消費者首選。', '高雄市燕巢區南燕里中民路577號', '07-616-2211#252', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17671/480x360_22燕巢區農會_芭樂-20151218215147.jpg', 22.7932786, 120.362621),
(319, '二崙上好禮-金蜜洋香瓜', '瓜農翻鬆泥土，蓋上黑色塑膠布挖洞，種下洋香瓜幼苗，以隧道式棚架每日保護照顧，待幼苗慢慢長大，撥開綠葉隙中見一粒粒碩大的果實，這是瓜農辛勤栽培的甜蜜寶貝。二崙鄉土壤肥沃，排水良好，頂級「金蜜」洋香瓜綿密香甜，風味絕佳，清涼入口，齒香滿溢，令人難以忘懷。', '雲林縣二崙鄉崙東村中興路118號', '05-598-6001', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17632/480x360_23雲林縣二崙鄉農會_金蜜洋香瓜-20151218215516.jpg', 23.773172, 120.412133),
(320, '有機酪梨禮盒', '酪梨營養成份極高、富含優質油脂，有「森林的奶油」及「幸福果」美譽，是補充營營首選果品。農人善待土地，土地也會給予回報，人養地，地養人，中埔有機酪梨是溫暖的有機幸福果。', '嘉義縣中埔鄉内山公路128號', '05-253-2201', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17591/480x360_24中埔鄉農會_有機酪梨-20151218220333.jpg', 23.4728954, 120.5384742),
(321, '有機火龍果禮盒', '火龍果是很好種但很難照顧的水果，在中埔農民細心呵護下，碩大而鮮紅欲滴的有機火龍果，外型吉祥討喜，口感綿密，甜味適中而清爽，低卡又營養，深受現代人喜愛。', '嘉義縣中埔鄉内山公路128號', '05-253-2201', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17592/480x360_25中埔農會_頂級火龍果-20151218220806.jpg', 23.4728954, 120.5384742),
(322, '燒仙草', '購買專線：03-5872010、03-5875288\r\n聯絡信箱：ksn.kusi@msa.hinet.net\r\n1.內容物:仙草粉、太白粉、糖將1包即溶燒仙草倒入杯中，用少許溫開水攪拌溶解，再加入約200cc剛沸騰熱開水，迅速攪拌使之完全溶解即可，食用時可視個人喜好另行添加紅豆、花生、粉圓、八寶豆等材料。2.內容物:仙草粉將即溶仙草3g*1包溶於約1000cc開水中再添適量砂糖即可用。可做仙草茶、仙草凍、仙草冰、燒仙草、仙草雞、仙草排骨等', '新竹縣關西鎮北山里10鄰高橋坑6號', '03-587-4277', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18738/480x360_20200328-23.JPG', 24.8032728, 121.1601904),
(323, '溫室小番茄', '來自「御品紅」的新鮮溫室小番茄，披著櫻桃般血紅色的外衣，活潑的模樣代表是「在欉紅」，每一顆都是用心栽培的成果。個頭嬌小可愛，香味濃郁滿盈，皮薄肉質細緻，多汁的口感，讓人一顆接一顆塞入口停不下來！', '嘉義市西區博愛路二段459號', '05-236-0311', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17593/480x360_26嘉義縣農會_番茄-20151218221024.jpg', 23.4718835, 120.431524),
(324, '梨山茶', '梨山茶具有上等優渥栽種環境的條件，海拔高氣候寒冷，常年雲霧籠罩，日夜溫差大，又因吸收了週遭梨果香味，茶葉苦澀少、更添清香。 農民更堅持手工採一心二葉，採取最鮮嫩，最優質的茶葉，所製成的茶品清雅芬芳，茶湯味後甘醇，回韻悠揚持久。', '臺中市和平區東關路3段161號', '04-2594-1518', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17595/480x360_28台中市和平區農會_梨山茶-20151218221835.jpg', 24.174661, 120.885178),
(325, '韻紅紅茶禮盒 (蜜香)', '木柵「韻紅紅茶｣系列是傳統與創新的完美結合，嚴選一心二葉茶菁製成，外觀條索緊結油潤，水色鮮艷紅亮，茶香優雅，滋味醇厚，喉韻渾厚，七泡有餘香！喝｢韻紅｣呼你｢穩紅｣！', '臺北市文山區木柵路三段77號', '02-2939-8021', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17635/480x360_30木柵區農會_韻紅(蜜香)1-20151218222148.jpg', 24.988743, 121.56723),
(326, '台中八仙山紅茶', '紅茶是一種全發酵茶，茶湯則呈深紅色，發酵作用使得茶葉中的茶多酚和單寧酸減少，產生了茶黃素、茶紅素等新的成份和醇類、醛類、 酮類、酯類等芳香物質，因此香氣撲鼻，少了苦澀味，味道更醇厚。八仙山茶區地理環境及其水質等自然條件因素，使沖泡後產生的茶香、口感相當獨特，讓人為之驚艷，加上產量稀少，實屬茶中珍品。', '臺中市和平區東關路3段161號', '04-2594-1518', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17634/480x360_29台中市和平區農會_八仙山紅茶-20151218222000.jpg', 24.174661, 120.885178),
(327, '觀韻紅紅茶禮盒', '木柵「韻紅紅茶｣系列是傳統與創新的完美結合，嚴選一心二葉茶菁製成，外觀條索緊結油潤，水色鮮艷紅亮，茶香優雅，滋味醇厚，喉韻渾厚，七泡有餘香！喝｢韻紅｣呼你｢穩紅｣！\r\n訂購專線：02-29398021#201', '臺北市文山區木柵路三段77號', '02-2939-8021', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17597/480x360_31木柵區農會_觀韻紅紅茶禮盒8-20151218222336.jpg', 24.988743, 121.56723),
(328, '韻紅紅茶禮盒', '木柵「韻紅紅茶｣系列是傳統與創新的完美結合，嚴選一心二葉茶菁製成，外觀條索緊結油潤，水色鮮艷紅亮，茶香優雅，滋味醇厚，喉韻渾厚，七泡有餘香！喝｢韻紅｣呼你｢穩紅｣！\r\n訂購專線：02-29398021#201', '臺北市文山區木柵路三段77號', '02-2939-8021', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17678/480x360_32木柵區農會_韻紅4-20151218222502.jpg', 24.988743, 121.56723),
(329, '紅烏龍茶茶包', '游走在紅茶與烏龍茶之間的「紅烏龍」，品茶人喻之為柔情俠義、武功高強、深藏不露的俠骨之士。茶湯水色琥珀橙紅，明亮澄清有如紅茶的茶湯色澤，滋味醇厚而圓滑，茶質具熟果香，兼具烏龍茶的清甜和紅茶的甘醇，冷熱泡皆宜，特別是冷泡風味令人驚艷！', '臺東縣鹿野鄉鹿野村中華路二段 25 號', '08-955-1052', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17598/480x360_33鹿野農會_紅烏龍-20151218230202.jpg', 22.9116099, 121.135994),
(330, '台東好茶典藏禮盒', '一壺好茶的誕生，除了需要天然純淨的栽種環境，道道繁複而嚴謹的程序，也是關鍵要素。來自臺東太麻里、鹿野優良茶區的好茶，由茶農精耕、手採、細搓、慢焙而成，嚴選柔軟、芬芳、醇化而不苦澀的茶菁，滋味甘醇滑軟，茶湯色明亮，香氣獨到迷人。\r\n訂購專線：089-513111', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17599/480x360_34台東縣農會_台東好茶-20151218230802.jpg', 22.7555114, 121.1427744),
(331, '杉林溪紅露/綠芽茶包禮盒', '杉林溪茶，一心二葉，片片手採，只挑鮮嫩綠芽，葉芽柔軟，葉面厚實。由於生長環境高寒，終年雲霧籠罩，土壤肥沃雨量適中，造就茶色翠綠清透，呈現淡雅的天然果香，又終年生長杉樹間，以杉木為鄰 ，故其味道有苦中帶甘之口感，益添清雅悠遠。', '南投縣竹山鎮下橫街38號', '04-9264-2186', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17637/480x360_38竹山鎮農會_杉林溪紅露綠芽-20151218231529.jpg', 23.756698, 120.6846309999),
(332, '山美茶蘊禮盒', '三峽地區山景優美，所產的茶回甘蘊香，山美茶蘊訴求慢享生活的茶禪意境，在講求寂與靜的茶禪韻律美學中，凝聚一道心靈軌跡，讓茶香洗淨滌慮，在回甘中品嚐層次的醇美，一享品味生活茶禪意境。', '新北市三峽區長泰街96號', '02-2671-1002', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17669/480x360_53三峽區農會_山美茶蘊禮盒-20151218235114.jpg', 24.93354499999, 121.3761899999),
(333, '茉莉語茶', '燒一壺水，看花瓣在水中舒卷綻放，凝神傾聽花兒低語，啜一口「茉莉語茶」，口感香潤甘甜，品味那份閒適與悠然。那是花農們懷著感恩的心，親手摘下每一朵以安全農法栽種的茉莉花，在花朵盛開之時即用乾燥處理法製得，封存保留住花香原味，在品茗者口中重新綻開&hellip;&hellip;\r\n產地直送，如何訂購茉莉語茶: 花壇鄉農會', '彰化縣花壇鄉花壇村花壇街273號', '04-786-7821', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17680/480x360_72花壇農會_茉莉語茶-20151219002720.jpg', 24.02599, 120.537346),
(334, '將軍花翎春秋又八千', '走入霧峰林家最著名的宅第宮保，不難發現其中懸掛著一塊「春秋又八千」金色祝壽牌匾，其字體出自為清未傑出書法家楊草仙的狂草書跡，筆致圓潤、靈妙奇變、情感豐富、氣勢恢宏。在地的霧峰農會酒莊特別選定霧峰最高級的香米做為原料，精餾監造的純米燒酎，其香醇順口、餘味繞香，搭配這豐富底蘊的字體，以及獨具特色的包裝，絕對是作為長輩祝壽、賀歲的好禮品。', '臺中市霧峰區中正里四德路10號', '04-2339-3404', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17681/480x360_165霧峰農會_春秋又八千01-20151219003219.jpg', 24.0651751, 120.679522),
(335, '大安好酒', '釀酒師研習日本製酒製作流程，再依農作物之特性加以改良，並運用酒本身的溫度，將作物天然香氣封存於酒中，淡雅的酒香伴隨著溫順口感入喉，舌尖餘韻別緻，釀造出屬於臺灣本地的燒酒。', '臺中市大安區中庄里３鄰中松路６號', '04-2671-2229', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17682/480x360_166大安農會_大安好酒-20151219003848.jpg', 24.3463873, 120.5870304),
(336, '特級龍眼蜜', '「龍眼蜜」亦稱「龍眼花蜜」，是蜜蜂採集龍眼花朵所分泌的花蜜，質地滑潤，香味濃郁。龍眼花開季節，正是蜂農釀製「龍眼蜜」的好季節，此時來嚐嚐新鮮的蜂蜜，一口甜甜的滋味與淡淡的花果香氣，這就是幸福的味道！更重要的，它是天然的滋養食品，上天的恩賜與蜜蜂們辛勤努力的成果。\r\n訂購專線：06-6802816', '臺南市東山區中興路1號', '06-680-0814', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17683/480x360_167東山區農會_特級龍眼蜜-20151219004031.jpg', 23.1781599, 120.483966),
(337, '慕麗達諾麗原汁', '喝一口慕麗諾麗果原汁，入口甜中帶酸，不時挑動您的味蕾。嚴選在地農民種植的新鮮諾麗果釀造、自然發酵製成，其原汁可幫助調節生理機能、養顏美容、促進新陳代謝、幫助消化，平常只要加點冰開水或果汁稀釋飲用，就可以享受到酸酸甜甜的幸福口感，果然深受女性朋友喜歡。', '臺南市學甲區華宗路315號', '06-783-2105', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17684/480x360_168學甲區農會_慕麗達諾麗原汁-20151219004259.jpg', 23.230796, 120.1823667999),
(338, '百里飄香', '以新鮮百香果原汁為釀造原料，經過優質酵母菌低溫發酵而成，再進行完全密封低溫熟成後，取其精華酒液而得的百香果釀造酒。酒液色澤澄清且略帶黃色，香氣濃郁，口感滑順，它的酸味及香氣能觸動您整個味蕾。\r\n​&bull; 榮獲2015年德國國際烈酒評鑑金質獎\r\n&bull; 榮獲2012年國內酒莊酒品評鑑銅牌獎\r\n&bull; 榮獲2010年酒莊酒品評鑑銅牌獎\r\n&bull; 榮獲2009年酒莊酒品評鑑銀牌獎\r\n&bull; 榮獲2008年酒莊酒品評鑑金牌獎\r\n&bull; 榮獲2007年酒莊酒品評鑑銀牌獎\r\n&bull; 榮獲2005年酒莊酒品評鑑銀牌獎\r\n訂購專線：049-2423828', '南投縣埔里鎮清新里西安路一段六號', '04-9298-6420', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17685/480x360_169南投縣埔里鎮農會 百里飄香-20151219004435.jpg', 23.963721, 120.9641679999),
(339, '玫瑰花語', '埔里的氣候和水質特佳，是植物生長的最佳環境。運用埔里山城優質安全的玫瑰花，以花入酒，浸漬在地獨特的紅甘蔗基礎酒裡，將花獨特的香芬釋放在酒中，與酒達到完美的結合。美麗色澤的視覺感受加上清香滑潤的口感，甜而不膩，在濃濃的甘蔗酒香中，保留著玫瑰花的香濃芬芳，一口就同時擁有浪漫與幸福的感覺。\r\n訂購專線：049-2423828', '南投縣埔里鎮清新里西安路一段六號', '04-9298-6420', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17618/480x360_170南投縣埔里鎮農會 玫瑰花語-20151219004632.jpg', 23.963721, 120.9641679999),
(340, '玫瑰賞', '埔里的氣候和水質特佳，是植物生長的最佳環境。運用埔里山城優質安全的玫瑰花，以花入酒，浸漬在地獨特的紅甘蔗基礎酒裡，將花獨特的香芬釋放在酒中，與酒達到完美的結合。美麗色澤的視覺感受加上清香滑潤的口感，甜而不膩，在濃濃的甘蔗酒香中，保留著玫瑰花的香濃芬芳，一口就同時擁有浪漫與幸福的感覺。\r\n訂購專線：049-2423828', '南投縣埔里鎮清新里西安路一段六號', '04-9298-6420', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17686/480x360_171南投縣埔里鎮農會 玫瑰賞-20151219004802.jpg', 23.963721, 120.9641679999),
(341, '羅漢門龍眼蜂蜜', '說到「龍眼的故鄉」，你不能不知道「內門」這個地方。這裡每年春天的龍眼花盛開，所散發出的濃郁花香味，蜜蜂紛紛聞香而來，其所採集的花蜜，是天然香純的龍眼花蜜，是極品中的極品。清新的植物香、口感滑潤、生津回味，無論是拿來泡茶、淋在土司或鬆餅上面，都非常美味可口，是媽媽族和小朋友們的最愛。', '高雄市內門區內豐村內埔1-1號', '07-667-2161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17687/480x360_172內門區農會_羅漢果龍眼蜜-20151219004941.jpg', 22.94175459999, 120.4613715),
(342, '2015 新竹縣評鑑龍眼蜜', '龍眼花蜜是蜂蜜之冠，富含花粉粒及活性脢，清涼退火、品味醇美，是天然營養食品，人體最佳活力的來源。農會在今年榮獲新竹縣龍眼蜂蜜評鑑特等獎及頭等獎之殊榮，蜂蜜品質優良，是蜜中之極品，深獲消費者信賴。內含多種微量礦物質，可補充體內所需之營養素，主要為鉀，其次是鈣、鎂、鈉、硫、磷等等，蜂蜜中富含類黃酮及胺基酸等有機成分，對於重視保養身體的您來說，是個最佳選擇。', '新竹縣芎林鄉文山路 989 號', '03-592-1018#9', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17688/480x360_173新竹縣農會_龍眼蜜-20151219005430.jpg', 24.787296, 121.068628),
(343, '湖莓戀', '嚴選大湖草莓精心釀製而成，屬水果釀造酒類，酒精度11％，低溫釀造製程，經過時間的焠鍊，酒液呈現金黃琥珀色澤，打開酒瓶，濃濃的草 莓果香躍然而出，入口甜中帶酸，回韻中帶有苦味，挑動你的味蕾，冰鎮飲用，風味更佳。', '苗栗縣大湖鄉富興村八寮村2-4號', '03-799-4800', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17690/480x360_175大湖地區農會_湖莓戀-20151219005956.jpg', 24.4289864, 120.8660828),
(344, '吉利市光波禮盒(雪梨/綠盒)', '產期：12月~翌年2月\r\n規格：\r\n	高山雪梨(雪梨)6粒裝(8 台斤)\r\n	高山雪梨5粒裝(8台斤)', '臺中市東勢區豐勢路297號', '04-2587-2151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17502/480x360_007 東勢區農會_吉利市光波(綠) (400x320)-20151220004200.jpg', 24.2534386, 120.829146),
(345, '石門鐵觀音極上品禮盒', '石門鐵觀音茶年年入選百大精品，湯色金黃明亮、香氣沈穩、茶湯滑順，入口生津，精緻小巧，攜帶便利。產品包裝設計與概念，融合飲茶浪漫情懷及品茗意境，徜徉湖光水色，清閒優雅渾然忘我，展現茶與生活之藝術。', '新北市石門區(村)中央路2號', '02-2638-1005', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17647/480x360_55石門區農會_鐵觀音半斤-20151218235420.jpg', 25.2909969, 121.5647637999),
(346, '茶顏悅色', '清香芬芳的包種茶，香氣幽雅飄逸，滋味甘潤，入口生津；東方美人茶特殊的熟果香和蜜香，茶湯濃厚香醇，是讓英國伊莉莎白女王念念不忘的茶葉。製成茶包，方便您隨時快速享用兩種特色茶，是味蕾的雙重滿足。', '新北市坪林區坪林村坪林街103號', '02-2665-7227', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17604/480x360_56坪林區農會_茶顏悅色方便茶飲-20151218235555.jpg', 24.936102, 121.7117779999),
(347, '東方美人茶禮盒', '購買專線：03-5802207\r\n聯絡信箱：g1006@bps.org.tw\r\n北埔聞名於世的「膨風茶」，因得天獨厚環境孕育與薰陶，及小綠葉蟬的吸吮與蘊釀，使其茶湯有濃郁的花香、果香、蜜香渾然天成，非一般茶葉所能比擬之奇特風味、堪稱茶中極品。', '新竹縣北埔鄉北埔街94號', '03-580-2207', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17650/480x360_57北埔鄉農會_東方美人茶-20151218235730.jpg', 24.700475, 121.055203),
(348, '東方美人茶禮盒(4兩)', '新竹以「膨風茶」聞名於世，其外觀奇特細緻、1 心2葉，心呈白毫，有紅、白、黃、褐、綠等5色，又稱白毫烏龍或東方美人茶，因得天獨厚環境孕育及茶葉綠小蟬的吸吮與蘊釀，使茶湯富含濃郁花香、果香與蜜香，堪稱茶中極品。\r\n訂購專線：03-5800216#7', '新竹縣峨眉鄉峨眉村8鄰12號', '03-580-0216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17651/480x360_58峨眉鄉農會_東方美人茶(紅)6-20151218235919.jpg', 24.6887921, 121.0195946),
(349, '東方美人茶禮盒 (半斤)', '當桐花落下，是浮塵子盡情吸食茶菁的季節，所製成的東方美人茶，是大地對新竹的恩賜，是在地對傳統的堅持，自然、甘醇、回韻留香，代表峨眉湖畔的美人，高貴大方又典雅，品嚐一抹紅的靜謐。', '新竹縣峨眉鄉峨眉村8鄰12號', '03-580-0216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17652/480x360_59峨眉鄉農會_東方美人茶(白)1-20151219000053.jpg', 24.6887921, 121.0195946),
(350, '阿里山經典紅茶禮盒', '來自阿里山山脈高海拔優良茶區，分佈在北回歸線南、北50 公里內，海拔1,000-1,500 公尺間臺地上，氣候陰冷，終年雲霧籠罩，日夜溫差大，極適合茶樹培育。經茶農深耕、手採、細搓、輕揉慢烘勻焙，再經本會茶師嚴格監製及認證，確保品質，盛名享譽國際，是自用饋贈兩相宜的極品茶。', '嘉義縣竹崎鄉竹崎村中山路111號', '05-261-2120', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17608/480x360_60竹崎地區農會_阿里山經典紅茶禮盒-20151219000303.jpg', 23.5216026, 120.550813),
(351, '阿里山高山茶禮盒', '來自阿里山山脈高海拔優良茶區，分佈在北回歸線南、北50 公里內，海拔1,000-1,500 公尺間臺地上，氣候陰冷，終年雲霧籠罩，日夜溫差大，極適合茶樹培育。經茶農深耕、手採、細搓、輕揉慢烘勻焙，再經本會茶師嚴格監製及認證，確保品質，盛名享譽國際，是自用饋贈兩相宜的極品茶。\r\n訂購專線：05-2612120#201', '嘉義縣竹崎鄉竹崎村中山路111號', '05-261-2120', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17609/480x360_61竹崎地區農會_阿里山高山茶-20151219000448.jpg', 23.5216026, 120.550813),
(352, '阿里山高山茶', '到嘉義梅山來，感受被雲霧繚繞、漫步在雲端的氛圍，不僅有美景，還有好茶為伴。由茶農精耕、手採、細搓、輕揉、慢焙、所製之精緻茶葉，滋味甘醇滑軟，具獨特的香氣、喉韻及金黃茶色、耐沖泡，為梅山鄉阿里山高山茶樹立良好的信譽品質。', '嘉義縣梅山鄉中山路127號', '05-262-2100', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17602/480x360_64梅山鄉農會_雲端上的甘露-20151219000811.jpg', 23.581617, 120.558779),
(353, '阿里山高山茶 (紅茶)', '到嘉義梅山來，感受被雲霧繚繞、漫步在雲端的氛圍，不僅有美景，還有好茶為伴。由茶農精耕、手採、細搓、輕揉、慢焙、所製之精緻茶葉，滋味甘醇滑軟，具獨特的香氣、喉韻及金黃茶色、耐沖泡，為梅山鄉阿里山高山茶樹立良好的信譽品質。', '嘉義縣梅山鄉中山路127號', '05-262-2100', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17603/480x360_65梅山鄉農會_阿里山高山--紅茶-20151219001002.jpg', 23.581617, 120.558779),
(354, '阿里山高山茶 (梅山茶區)', '到嘉義梅山來，感受被雲霧繚繞、漫步在雲端的氛圍，不僅有美景，還有好茶為伴。由茶農精耕、手採、細搓、輕揉、慢焙、所製之精緻茶葉，滋味甘醇滑軟，具獨特的香氣、喉韻及金黃茶色、耐沖泡，為梅山鄉阿里山高山茶樹立良好的信譽品質。', '嘉義縣梅山鄉中山路127號', '05-262-2100', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17605/480x360_66梅山鄉農會_阿里山--梅山茶區-20151219001152.jpg', 23.581617, 120.558779),
(355, '阿里山高山茶(青心烏龍)', '精選純正阿里山脈生產手採茶，茶區平均海拔1300~1500公尺,，茶葉色澤鮮活翠綠，茶色金黃明亮而且耐沖泡，飲之香氣馥郁芬芳，入口濃厚甘潤而不生澀，誠為愛好品茗者不容錯過的優質高山茶。\r\n訂購專線：05-2591360', '嘉義縣番路鄉下坑村菜公店109-1號', '05-259-2360', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17606/480x360_67番路鄉農會_阿里山高山茶2-20151219001450.jpg', 23.46359299999, 120.5542659999),
(356, '茉莉賞茶御品禮盒(烏龍+紅茶)', '「茉莉賞茶御品禮盒」嚴選高山烏龍茶、紅茶，加以窨合花壇鄉安全農法栽種的茉莉花，並承襲古老「窨花拼和」製茶工藝，製作工序繁複，完美調和茉莉與茶葉香氣，充分發揮「茶引花香、花增茶味」的特色。花香味清新、茶湯味鮮甜，自用安心、喝來沁心；外包裝高貴典雅，送禮送得貼心。\r\n訂購專線：04-7877558', '彰化縣花壇鄉花壇村花壇街273號', '04-786-7821', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17611/480x360_70花壇農會_茉莉御品禮盒-20151219002230.jpg', 24.02599, 120.537346),
(357, '心意足桑葚禮盒', '嚴選新鮮桑椹，掌握最佳採收時機及在地榨汁製作，無論是添加冰糖蒸煮及濃縮精製而成的果汁，或是經過3 ~ 6 個月自然發酵和時間浸釀的果醋，營養價值都非常高，略帶酸甜的口感，嚐到的每一口都是幸福，冰鎮過後，風味更是一絕。在這個講求健康養生的年代，這類的鹼性食品可以調整體內酸鹼值、促進健康，對無肉不歡及偏酸性體質的現代人來說, 是個值得推薦的健康好飲品。\r\n訂購專線：05-3412003', '嘉義縣義竹鄉仁里村421號', '05-341-1301', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17689/480x360_174義竹鄉農會_果醋-20151219005646.jpg', 23.3384173, 120.241176),
(358, '吉利市光波禮盒(豐水梨、新興梨/紅盒)', '產期：5月~10月\r\n規格：\r\n	高山雪梨(豐水梨、新興梨)7粒裝(7 台斤)\r\n	高山雪梨(豐水梨、新光梨)8粒裝(7台斤)', '臺中市東勢區豐勢路297號', '04-2587-2151', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17722/480x360_006 東勢區農會_吉利市光波(紅) (400x320)-20151220003127.jpg', 24.2534386, 120.829146),
(359, '阿里山鄒特產 (茶包組)', '嚴選來自阿里山高海拔之手採頂級烏龍，100% 在地生產，茶色翠綠清透，茶韻清揚，滋味甘醇，令人齒頰生津。卷縮的茶葉在水中緩緩舒展開來，茶香綻放，思緒也隨著輕揚&hellip;&hellip;，高山茶湯，質軟順口，香氣濃郁，值得行家細細品味。', '嘉義縣阿里山鄉樂野村4鄰114號', '05-256-2502', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17704/480x360_063 阿里山鄉農會_阿里山高山茶1 (400x320)-20151220005057.jpg', 23.4690425, 120.701457),
(360, '富麗幸福禮盒', '在旅途中，我們可以寄一張風景明信片，對友人訴說旅程的點點滴滴。富麗幸福禮盒，以明信片風格包裝的六袋好米，不只為親朋好友呈現旅途所見花蓮的風景，還有花蓮的味道。', '花蓮縣富里鄉羅山村9鄰東湖6號', '03-882-1705', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17612/480x360_073 花蓮富里鄉_幸福禮盒 (400x320)-20151220152232.jpg', 23.1838646, 121.2969674),
(361, '味自慢頂級壽司米', '壽司好吃，不只要食材新鮮，還要搭配香甜的壽司米。要吃到如此好吃的米不用跑壽司店，橫跨四條溪流的雲林斗南鎮出產的「味自慢頂 級壽司米」，用日本先進低溫碾米設備加工，外觀清透、內容飽滿、味道香甜，讓您在家也能嚐到高級壽司店才有的風味。', '雲林縣斗南鎮大同路10號', '05-595-0535', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17615/480x360_089 斗南農會_味百慢01 (400x320)-20151220181419.jpg', 23.6775271, 120.47588),
(362, '土地之歌有機系列', '花東縱谷，全臺灣最晚被開墾的地帶，有最少污染的水土。長在這沒有化肥與農藥的乾淨的土地上，潔淨又美味的有機臺稉74 號米，是對這塊良田福地的歌頌，象徵人與土地的共生共榮。 新鮮良米經慈心有機認證，以CAS 認證碾米廠碾製，全程低溫保存，讓響徹花東縱谷的「土地之歌」，傳到你家廚房。', '花蓮縣花蓮市國福里中山路二段1號', '03-856-9033', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18550/480x360_c39ee100da93463d8c77254160e131d9.jpg', 24.010114, 121.583013),
(363, '特等米 1.5 公斤禮盒', '池上鄉位處花東縱谷最純淨自然的稻米產區，鄉內水田土壤肥沃，溪水夾帶著豐富的有機礦物質，還有全臺唯一的內陸淡水沼澤「大坡池」調節水位。 池上米過去在日據時代是進貢日本天皇的米，故被稱為「貢米」。名聞遐邇的「池上飯包」，就是發源於此地，池上飯包所標榜的材料，正是池上米。\r\n俗話說：「天才是一分的天賦加上九十九分的努力所造就出來的。」池上鄉雖然擁有天然的稻米生長環境，與優良稻米品種的支援，但是農民種植稻米的用心與專業，才是讓池上米享譽全國的主要因素。 池上一年四季不同景觀，春天，萬物欣欣向榮的絕色之美；夏季，放眼望去是一整片綠油油的田野，隨風搖曳的稻子因為陽光照射，像是綠海波浪；秋天，大地慢慢轉換成金黃色的稻浪，稻穗飽滿隨風輕輕 擺動，一波波金黃色稻浪在你眼前翻滾黃金地毯；進入隆冬時節，田園裡蒼翠不再，伯朗大道、天堂路兩旁大片金黃油菜花盛開美不勝收，讓喧囂擾嚷心靈，得到放鬆的純粹。\r\n訂購專線：089-864880', '臺東縣池上鄉台東縣新興村85-6號', '08-986-4880', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17705/480x360_075 池上鄉農會_特等米 (400x320)-20151220154704.jpg', 23.08902709999, 121.2278084999),
(364, '池上生活米禮盒-馬卡龍香米禮盒', '池上鄉位處花東縱谷最純淨自然的稻米產區，鄉內水田土壤肥沃，溪水夾帶著豐富的有機礦物質，還有全臺唯一的內陸淡水沼澤「大坡池」調節水位。 池上米過去在日據時代是進貢日本天皇的米，故被稱為「貢米」。名聞遐邇的「池上飯包」，就是發源於此地，池上飯包所標榜的材料，正是池上米。\r\n俗話說：「天才是一分的天賦加上九十九分的努力所造就出來的。」池上鄉雖然擁有天然的稻米生長環境，與優良稻米品種的支援，但是農民種植稻米的用心與專業，才是讓池上米享譽全國的主要因素。池上一年四季不同景觀，春天，萬物欣欣向榮的絕色之美；夏季，放眼望去是一整片綠油油的田野，隨風搖曳的稻子因為陽光照射，像是綠海波浪；秋天，大地慢慢轉換成金黃色的稻浪，稻穗飽滿隨風輕輕 擺動，一波波金黃色稻浪在你眼前翻滾黃金地毯；進入隆冬時節，田園裡蒼翠不再，伯朗大道、天堂路兩旁大片金黃油菜花盛開美不勝收，讓喧囂擾嚷心靈，得到放鬆的純粹。\r\n訂購專線：089-864880\r\n產地直送，如何訂購   池上鄉農會 (csfa.com.tw)', '臺東縣池上鄉台東縣新興村85-6號', '08-986-4880', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17707/480x360_077 池上鄉農會_馬卡龍香米禮盒 (400x320)-20151220161235.jpg', 23.08902709999, 121.2278084999),
(365, '樂禾趣', '從上空鳥瞰桃園，可以看見數不盡的埤塘波光粼粼，百年來灌溉桃園的大地從來不變，但是田地卻是不斷求新求變，種出好吃的稻米。尤其新屋得天獨厚，兼有生氣蓬勃的漁港與肥沃的稻田。樂禾趣禮盒精選最好的「新香」米，外觀晶瑩剔透，內容結實飽滿，烹煮時散發出陣陣濃郁宜人的芋頭香，吃起來更是口感香Q 甜美。\r\n訂購專線：03-4772124#210', '桃園市新屋區新屋里中華路 242 號', '03-477-2124', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17679/480x360_087 新屋鄉農會_樂禾趣 (400x320)-20151220180820.jpg', 24.9723065, 121.107596),
(366, 'CAS 首選好米', '雲林斗南鎮有四條溪流橫貫，水源充沛、土地肥沃，所產稻米為雲林之最。但是好米還要更好，農會以「田間生產紀錄」、「農業經營專 區」、「地產地銷」等嚴格的生產管控，通過 CAS 認證、ISO-22000 及 HAMLP 國際食品安全驗證，生產「CAS 首選好米」。香甜的滋味、 有彈性的口感，是斗南農民的驕傲。', '雲林縣斗南鎮大同路10號', '05-595-0535', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17614/480x360_088 斗南農會_cas首選好米02 (400x320)-20151220181223.jpg', 23.6775271, 120.47588),
(367, '米滿良緣', '米滿良緣禮盒，有東方的如意圖騰設計。 「米滿良緣」象徵著圓滿豐足的含義，代表婚姻不只是愛情圓滿，更蘊含兩人攜手走向富足的未來。', '雲林縣二崙鄉崙東村中興路118號', '05-598-6001', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17616/480x360_090 在地好米--二崙農會米滿良緣 (400x320)-20151220181728.jpg', 23.773172, 120.412133),
(368, '黃金囍米禮盒', '北緯 23.5&deg; 北回歸線，赤道的最北位置所經過的太保市，日夜溫差大、日照恰當、土壤豐腴，又有嘉南大圳源源不絕的灌溉，是連年豐收的沃野。太保農民守護著稻田與太陽約定，他們以金黃色的稻作立契，不讓農藥、化肥污染這片土地，替有機太保米「香 Q 好吃」掛保證。禮盒附上檜木筷子，讓吃飯時享受檜木香味混和太保米的美味，雙重享受。', '嘉義縣太保市太保里58號', '05-371-1101', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17675/480x360_091 太保農會_黃金囍米 (400x320)-20151220181936.jpg', 23.4576038, 120.3320694),
(369, '豐和日粒禮盒', '北緯 23.5&deg; 北回歸線，赤道的最北位置所經過的太保市，日夜溫差大、日照恰當、土壤豐腴，又有嘉南大圳源源不絕的灌溉，是連年豐收的沃野。太保農民守護著稻田與太陽約定，他們以金黃色的稻作立契，不讓農藥、化肥污染這片土地，替有機太保米「香 Q 好吃」掛保證。禮盒附上檜木筷子，讓吃飯時享受檜木香味混和太保米的美味，雙重享受。', '嘉義縣太保市太保里58號', '05-371-1101', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17676/480x360_092 太保農會_豐禾日粒 (400x320)-20151220182511.jpg', 23.4576038, 120.3320694),
(370, '溪州黑鑽紫黑米', '位在濁水溪沿岸的溪州鄉，日日受到帶有稀有礦物元素的濁水溪滋潤，各種穀物欣欣向榮、營養豐富。 在這肥沃的濁水溪岸最不可多得的，是溪州馳名的紫黑米。紫黑米含有高量的花青素、賴胺酸、蛋白質。在豐饒的濁水溪邊栽種出的黑糯米尤其營養好吃，且經重金屬污染、農藥殘留檢驗合格，是您營養補給的最佳選擇。', '彰化縣溪州鄉溪州村中央路三段324號', '04-889-5610', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17730/480x360_094 溪州鄉農會_紫黑米 (400x320)-20151220183114.jpg', 23.85153659999, 120.4949632),
(371, '知竹嚐樂米', '濁水溪濁而肥沃，在下游的濁水溪沖積扇留下一片沃野，位於沖積扇西南端的竹塘鄉，百年來以得天獨厚的肥沃水源灌溉稻田，如今稻米界新星誕生於此。台稉 9 號「竹塘米」在年年稻米競賽中，為竹塘鄉民帶來榮耀，正因為吸收了濁水溪的精華，竹塘米擁有獨一無二的美味口感，快來品嚐！\r\n訂購專線：04-8972002#302', '彰化縣竹塘鄉竹元村東陽路1段16號', '04-897-2002', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17731/480x360_095 竹塘鄉農會_竹塘米 (400x320)-20151220183808.jpg', 23.85944119999, 120.4243546),
(372, '幸福穗稻禮盒', '沐浴溫暖陽光下，生長於大甲溪與大肚溪滋潤的土地上，加上臺中農民用心耕種，今年又是豐收的一年。滿田稻穗垂掛，頂級越光米當期新米粒粒飽滿。每口咬下，都是天地人的精華。搭配麻布袋造型的古樸編織材質外盒，再現懷舊農村風情，「幸福穂稻禮盒」給您滿滿的幸福味。', '臺中市西區向上路1段95號', '04-2302-3560', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17732/480x360_096 台中地區農會_幸福穗稻 (400x320)-20151220184128.jpg', 24.14655949999, 120.6632846),
(373, '養生糙米系列(糙米粥+糙米脆片)', '濁水溪畔以產米聞名，出產的埤頭鄉【臺梗九號】糙米，富含植物纖維及營養素，具有養生保健的功能。以糙米為基底所研發而成的粥品及脆片，口感豐富、香味濃郁，是全家早餐、宵夜、點心、零嘴的好伴侶。', '彰化縣埤頭鄉合興村斗苑西路92號', '04-892-2211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17749/480x360_153埤頭鄉農會_養生糙米-20151222093915.jpg', 23.8913137, 120.4634237999),
(374, '山味米禮盒', '關山鎮就像一個大公園，一邊是海岸山脈，另一邊則是中央山脈，位於兩山凹處的就是曠野平疇的關山了。 來關山，當然不能錯過品質優良的關山米，甜度、亮度、保存度都有好名聲。關山米產區，取新武呂溪來自中央山脈純淨的水源，加上設計優良的關山大圳，提供良好灌溉系統，使得關山鎮的稻米 「得天獨厚」，已成為全台稻米最優良的產區之一，像臺梗139 號、關山香米，都是近年來頗受好評的米種。\r\n「關山米」成功背景因素，最重要的還是在於人和，因為有一群致力於品質提昇的專業農友用心的付出，當然農糧單位及各農會的全力輔導，也是功不可沒。', '臺東縣關山鎮和平路78號', '08-981-1022', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17661/480x360_078 關山鎮農會_山味米禮盒 (400x320)-20151220163632.jpg', 23.04794679999, 121.1641561),
(375, 'CAS 關山良質米', '關山鎮就像一個大公園，一邊是海岸山脈，另一邊則是中央山脈，位於兩山凹處的就是曠野平疇的關山了。 來關山，當然不能錯過品質優良的關山米，甜度、亮度、保存度都有好名聲。\r\n關山米產區，取新武呂溪來自中央山脈純淨的水源，加上設計優良的關山大圳，提供良好灌溉系統，使得關山鎮的稻米 「得天獨厚」，已成為全台稻米最優良的產區之一，像臺梗139 號、關山香米，都是近年來頗受好評的米種。 「關山米」成功背景因素，最重要的還是在於人和，因為有一群致力於品質提昇的專業農友用心的付出，當然農糧單位及各農會的全力輔導，也是功不可沒。', '臺東縣關山鎮和平路78號', '08-981-1022', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17663/480x360_079 關山鎮農會_良質米 (400x320)-20151220165958.jpg', 23.04794679999, 121.1641561),
(376, '關山好米禮盒', '關山鎮就像一個大公園，一邊是海岸山脈，另一邊則是中央山脈，位於兩山凹處的就是曠野平疇的關山了。 來關山，當然不能錯過品質優良的關山米，甜度、亮度、保存度都有好名聲。關山米產區，取新武呂溪來自中央山脈純淨的水源，加上設計優良的關山大圳，提供良好灌溉系統，使得關山鎮的稻米 「得天獨厚」，已成為全台稻米最優良的產區之一，像臺梗139 號、關山香米，都是近年來頗受好評的米種。 「關山米」成功背景因素，最重要的還是在於人和，因為有一群致力於品質提昇的專業農友用心的付出，當然農糧單位及各農會的全力輔導，也是功不可沒。\r\n訂購專線：089-814903', '臺東縣關山鎮和平路78號', '08-981-1022', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17666/480x360_080 關山鎮農會_好米禮盒 (400x320)-20151220170604.jpg', 23.04794679999, 121.1641561),
(377, '關於這裡米禮盒', '關山鎮就像一個大公園，一邊是海岸山脈，另一邊則是中央山脈，位於兩山凹處的就是曠野平疇的關山了。 來關山，當然不能錯過品質優良的關山米，甜度、亮度、保存度都有好名聲。關山米產區，取新武呂溪來自中央山脈純淨的水源，加上設計優良的關山大圳，提供良好灌溉系統，使得關山鎮的稻米 「得天獨厚」，已成為全台稻米最優良的產區之一，像臺梗139 號、關山香米，都是近年來頗受好評的米種。 「關山米」成功背景因素，最重要的還是在於人和，因為有一群致力於品質提昇的專業農友用心的付出，當然農糧單位及各農會的全力輔導，也是功不可沒。', '臺東縣關山鎮和平路78號', '08-981-1022', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17667/480x360_081 關山鎮農會_關於這裡米禮盒 (400x320)-20151220170856.jpg', 23.04794679999, 121.1641561),
(378, '夢田之宴花漾禮盒', '太平洋邊、冬山河與蘭陽溪間，宜蘭五結鄉的沃野已開墾兩百多年。受充分水源的滋潤，年年產出量多又好吃的稻米。鄰近的濱海溼地，每年冬天吸引大量候鳥捕食充足的魚蝦，是土地乾淨的證明。現在，五結鄉百年良田要推出全新風味，有香Q 的蘭陽五農米、鮮米、瓊香出眾的五農香米、源自日本的越光米。吃完一頓有蘭陽風味的飯後，再來一杯用宜蘭綠茶與稻米炒製的玄米茶，頓時清爽無比。\r\n訂購專線：03-9503190', '宜蘭縣五結鄉五結中路二段7號', '03-950-1161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17668/480x360_082 在地好米--五結鄉--夢田之宴花樣禮盒 (400x320)-20151220171213.jpg', 24.6851467, 121.7976477),
(379, '夢田之宴伴手禮盒', '太平洋邊、冬山河與蘭陽溪間，宜蘭五結鄉的沃野已開墾兩百多年。受充分水源的滋潤，年年產出量多又好吃的稻米。鄰近的濱海溼地，每年冬天吸引大量候鳥捕食充足的魚蝦，是土地乾淨的證明。現在，五結鄉百年良田要推出全新風味，有香Q 的蘭陽五農米、鮮米、瓊香出眾的五農香米、源自日本的越光米。吃完一頓有蘭陽風味的飯後，再來一杯用宜蘭綠茶與稻米炒製的玄米茶，頓時清爽無比。', '宜蘭縣五結鄉五結中路二段7號', '03-950-1161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17672/480x360_083 在地好米--五結鄉--夢田之宴伴手禮 (400x320)-20151220171420.jpg', 24.6851467, 121.7976477),
(380, '糙米產品系列組合', '濁水溪畔以產米聞名，出產的埤頭鄉【臺梗九號】糙米，富含植物纖維及營養素，具有養生保健的功能。以糙米為基底所研發而成的粥品及脆片，口感豐富、香味濃郁，是全家早餐、宵夜、點心、零嘴的好伴侶。', '彰化縣埤頭鄉合興村斗苑西路92號', '04-892-2211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17748/480x360_152埤頭鄉農會_養生糙米-20151222093850.jpg', 23.8913137, 120.4634237999),
(381, '養生糙米系列(什穀糙米漿+糙米脆片)', '濁水溪畔以產米聞名，出產的埤頭鄉【臺梗九號】糙米，富含植物纖維及營養素，具有養生保健的功能。以糙米為基底所研發而成的粥品及脆片，口感豐富、香味濃郁，是全家早餐、宵夜、點心、零嘴的好伴侶。', '彰化縣埤頭鄉合興村斗苑西路92號', '04-892-2211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17750/480x360_154埤頭鄉農會_養生糙米2-20151222093932.jpg', 23.8913137, 120.4634237999),
(382, '養生糙米系列(糙米粥+什穀糙米漿)', '濁水溪畔以產米聞名，出產的埤頭鄉【臺梗九號】糙米，富含植物纖維及營養素，具有養生保健的功能。以糙米為基底所研發而成的粥品及脆片，口感豐富、香味濃郁，是全家早餐、宵夜、點心、零嘴的好伴侶。', '彰化縣埤頭鄉合興村斗苑西路92號', '04-892-2211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17751/480x360_155埤頭鄉農會_養生糙米1-20151222093946.jpg', 23.8913137, 120.4634237999),
(383, '國姓客庄咖啡', '臺灣人愛咖啡，早已名揚海外。九份二山的國姓客庄咖啡，在農民不辭辛勞、用心照料之下所生產出來的咖啡豆，粒粒圓潤、碩大飽滿，每嚐一口盡是濃郁香醇、回甘純厚，是咖啡迷不容錯過的好滋味。', '南投縣國姓鄉中正路二段357號', '04-9272-1510', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17511/480x360_150國姓鄉農會_客庄咖啡-20151222093445.jpg', 24.024487, 120.846814),
(384, '福肉', '炎炎夏日，龍眼樹上結實纍纍的果實，在豔陽照射下，如金黃色般的珍珠，充滿著生命力。東山區的龍眼乾以土窯古法烘焙，採收後經過生火慢燻、脫粒、翻焙，去殼去籽，才能做出被稱為「福肉」的龍眼乾。關於東山龍眼的故事還很多，不妨走訪東山，來趟農趣體驗之旅。\r\n訂購電話：06-6802816', '臺南市東山區中興路1號', '06-680-0814', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17752/480x360_201至202東山區農會_龍眼乾-20151222095947.jpg', 23.1781599, 120.483966),
(385, '冷凍即煮山藥禮盒', '環繞台北市區的青山上，滿是自然的瑰寶。士林區農會的「冷凍即煮山藥」，使用的是在山明水秀的陽明山採收的優質山藥。鮮採的陽明山山藥經削皮切塊、真空包裝後直接冷凍，保存山藥的美味與營養，而且不添加任何添加物。烹調免退冰，料理方便，讓您即刻享受營養衛生的美食。', '臺北市士林區文林路 342 號', '02-2882-8959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17709/480x360_098 士林區_山藥2 (400x320)-20151220230004.jpg', 25.0932124, 121.523289),
(386, '洛神花', '有低污染淨土，與太平洋海風的吹拂，台東洛神花紫紅鮮豔，不需要色素，厚實的花瓣可沖泡出濃郁的紫色洛神茶，還含有豐富的花青素、黃酮素、多酚，營養豐富，作為冷飲、熱飲都好喝。', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17710/480x360_099 台東縣農會_洛神花 (400x320)-20151220230443.jpg', 22.7555114, 121.1427744),
(387, '原色金針 (無硫)', '有低污染淨土，與太平洋海風的吹拂，台東洛神花紫紅鮮豔，不需要色素，厚實的花瓣可沖泡出濃郁的紫色洛神茶，還含有豐富的花青素、黃酮素、多酚，營養豐富，作為冷飲、熱飲都好喝。', '臺東縣卑南鄉台東縣溫泉村(路)388號', '089-513111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17692/480x360_100 台東縣農會_原色金針 (400x320)-20151220230619.jpg', 22.6955793, 121.022134),
(388, '小米', '台東地區豐富優美的原住民族文化，台東縣農會為了推薦部落傳統食材給消費大眾，推出「鳥兒歡唱─紅藜、樹豆與小米」，將部落健康美食介紹給社會大眾。 談到小米，就會想到原住民的小米酒，這說明小米和原住民之間息息相關。小米又稱為「栗」，它的黏性較強，柔軟富有彈性，也可製成糕餅，是相當美味的食物；在許多原住民的豐年祭中，更是必備的祭品之一，以祈求小米能年年豐收。', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17711/480x360_101 至103台東縣農會_小米 樹豆 紅藜 (400x320)-20151220231100.jpg', 22.7555114, 121.1427744),
(389, '紅藜', '台東地區豐富優美的原住民族文化，台東縣農會為了推薦部落傳統食材給消費大眾，推出「鳥兒歡唱─紅藜、樹豆與小米」，將部落健康美食介紹給社會大眾。 紅藜，這樣一個翠綠垂墜狀的植物，長在原住民的部落，已經數千年，除了用來釀製小米酒外，也是非常重要的副食品，最常加在米飯中一起食用。原住民朋友就說，吃了紅黎釀製的小米酒會讓人「精神愉快，心情開心、可以解除煩惱」。', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17693/480x360_101 至103台東縣農會_小米 樹豆 紅藜 (400x320)-20151220231250.jpg', 22.7555114, 121.1427744),
(390, '樹豆', '台東地區豐富優美的原住民族文化，台東縣農會為了推薦部落傳統食材給消費大眾，推出「鳥兒歡唱─紅藜、樹豆與小米」，將部落健康美食介紹給社會大眾。 提起「樹豆」，多數人一定流露出「那是什麼東西？」樹豆，被認為是幸福的代表。曾有一個傳說，一顆會跳動的樹豆，把美麗的女孩帶到鄰村去，因此得到好姻緣，從此樹豆大量被種植，以感念它帶來的恩賜。', '臺東縣卑南鄉台東縣溫泉村(路)388號', '089-513111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17694/480x360_101 至103台東縣農會_小米 樹豆 紅藜 (400x320)-20151220231550.jpg', 22.6955793, 121.022134),
(391, '洛神花', '台東太麻里，全台灣第一個迎接太陽東昇的地方。每天，洛神花沐浴在清晨自海平面升起的陽光，受陣陣清爽吹拂，在太麻里這片少受工 業污染的土地上欣欣向榮。經過仔細的乾燥加工後，洛神花依舊紅潤如紅寶石，不需人工染色或添加物。將洛神花置滾水中煮過，滿壺水是鮮豔亮麗的紫紅色，一口飲下，生津止渴，熱飲、冰鎮皆適宜。\r\n購買專線：08-9781531\r\n聯絡信箱：taimali03@taimalifarmer.com.tw', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17695/480x360_104 太麻里地區農會_洛神花 (400x320)-20151220231745.jpg', 22.604987, 121.001855),
(392, '真空綠竹筍', '竹子與關廟更有不解之緣，古早時候關廟的竹編器具早已暢銷全臺。今日的關廟利用前人留下的蒼翠竹林，生產富含纖維質的新鮮綠竹筍。收割竹筍，必須在天亮之前掘地將竹筍從竹子的根部割下。若到太陽出來後，竹筍吸收到日光，就會發芽長成竹子不能吃了。可見每一稞竹筍，都是農民辛勞的結晶。關廟區農會出品的真空包綠竹筍，利用高溫高壓蒸煮技術，將竹筍日出前的鮮﹑嫩﹑甜鎖住，加工過程不添加防腐劑，安全衛生，獲得國際品質及食品安全認證。\r\n產地直送，如何訂購: 台南市關廟區農會', '臺南市關廟區中正路963號', '06-596-6278', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17696/480x360_105 關廟農會_綠竹筍 (400x320)-20151220232127.jpg', 22.9624989, 120.3284754),
(393, '芝麻醬', '台南西港有名的胡麻，不只可以榨油還可以製作香醇美味的芝麻醬。由老師傅精選西港芝麻洗淨、曬乾、烘焙、研磨而成的芝麻醬，不管是塗抹麵包、拌麵或拌沙拉，風味香醇美味，令人回味無窮。\r\n產地直送，如何訂購: 台南市西港區農會', '臺南市西港區文化路2號', '06-795-2706', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17697/480x360_106 西港區農會_芝麻醬 (400x320)-20151220232706.jpg', 23.1236716, 120.2051215),
(394, '黑麻油', '300 年前的西港區，曾是風帆片片的臺江內海港口。 多年後，滄海變桑田，繁榮的海港變成肥沃的田野，西港如今以油脂豐厚的胡麻聞名。西港區農會嚴格把關土壤與農藥殘留的契作農田，種出上等胡麻，遵古法煉製，產出的黑麻油與清麻油，營養、香醇又美味。', '臺南市西港區文化路2號', '06-795-2706', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17698/480x360_107 西港區農會_黑麻油 (400x320)-20151220232855.jpg', 23.1236716, 120.2051215),
(395, '清麻油', '300 年前的西港區，曾是風帆片片的臺江內海港口。 多年後，滄海變桑田，繁榮的海港變成肥沃的田野，西港如今以油脂豐厚的胡麻聞名。西港區農會嚴格把關土壤與農藥殘留的契作農田，種出上等胡麻，遵古法煉製，產出的黑麻油與清麻油，營養、香醇又美味。', '臺南市西港區文化路2號', '06-795-2706', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17699/480x360_108 西港區農會_清麻油 (400x320)-20151220233141.jpg', 23.1236716, 120.2051215),
(396, 'A 贏黑豆蔭油禮盒', '昔時倒風內海風帆片片，下營更是繁華，一度被稱作「小揚州」。歷經一番滄海桑田後，港口已不再，但是留給下營一片肥沃的原野。如今下營有三寶：白鵝.蠶桑.黑豆，尤其以黑豆台南 3 號及台南 5 號，是本地獨有的極品蔭油原料。\r\nA 贏黑豆蔭油採傳統陶缸釀製，留住下營黑豆特有的香蘊，提供家庭更優質的烹調食材，在飲食色. 香.味俱全之外，並兼顧安全.衛生.營養的需求，是在地、健康、美味、自然的產品。', '臺南市下營區新興里中山路1段322號', '06-689-2209', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17700/480x360_109 下營區農會_A贏黑豆禮盒 (400x320)-20151220233404.jpg', 23.2372631, 120.2672728999),
(397, '胡麻清油', '熱帶氣候下的嘉南平原，終年陽光普照，孕育各種作物。在曾文溪蜿蜒而過的善化區，從來是甘蔗盛產地，現在更有出名的胡麻，粒粒飽滿，最適合榨油。尤其善化區農會以「真」的精神生產的胡麻油，完全採用善化地區契作的胡麻，農田多達 150 公頃，產量充足，不怕買不到，就怕不知道！', '臺南市善化區中山路242號', '06-583-6111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19316/480x360_3.png', 23.132757, 120.2976479999),
(398, '胡麻油', '熱帶氣候下的嘉南平原，終年陽光普照，孕育各種作物。在曾文溪蜿蜒而過的善化區，從來是甘蔗盛產地，現在更有出名的胡麻，粒粒飽滿，最適合榨油。尤其善化區農會以「真」的精神生產的胡麻油，完全採用善化地區契作的胡麻，農田多達 150 公頃，產量充足，不怕買不到，就怕不知道！', '臺南市善化區中山路242號', '06-583-6111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/19312/480x360_2.png', 23.132757, 120.2976479999),
(399, '原味毛豆禮盒', '在遙遠的明鄭時期，位於來往台南府城與山區的這個地方形成新的市鎮，故名新市。熙熙攘攘的商賈在新市建造繁榮的市鎮，不過景象多元的新市還有生氣蓬勃的田園，現今生產全國知名，還遠銷日本的毛豆。新市人引以為傲的優質非基改毛豆由嚴格管理的契作農田種植。為了讓顧客吃到最新鮮甘甜的毛豆，農民不辭辛苦在清晨太陽出來前，毛豆上還淌著露水時快速採收，並於 4 小時內嚴選、精心製作，冷凍保存新鮮原味，是下飯配酒的好菜。\r\n訂購專線：06-5998545', '臺南市新市區復興路1之1號', '06-589-9888', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17702/480x360_113 新市區農會_原味毛豆 (400x320)-20151220234813.jpg', 23.0792851, 120.2955182),
(400, '幸福袋', '有「紅豆故鄉」之盛名的萬丹鄉，所生產的紅豆粒粒飽滿不空心、色澤鮮紅亮麗，煮起來的紅豆香味濃郁、質感酥鬆且皮薄，品質相當優良，深得消費大眾喜愛。無論是煮紅豆湯，或是作為糕餅內餡，都可以實實在在地感受到綿密香濃的口感，所帶來的幸福好滋味。', '屏東縣萬丹鄉萬丹路一段25號', '08-777-2007', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17713/480x360_156萬丹鄉農會_幸福袋1-20151221155403.jpg', 22.58455, 120.488925),
(401, '紅豆湯', '有「紅豆故鄉」之盛名的萬丹鄉，所生產的紅豆粒粒飽滿不空心、色澤鮮紅亮麗，煮起來的紅豆香味濃郁、質感酥鬆且皮薄，品質相當優良，深得消費大眾喜愛。無論是煮紅豆湯，或是作為糕餅內餡，都可以實實在在地感受到綿密香濃的口感，所帶來的幸福好滋味。', '屏東縣萬丹鄉萬丹路一段25號', '08-777-2007', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17714/480x360_157萬丹鄉農會_紅豆湯1-20151221155534.jpg', 22.58455, 120.488925),
(402, '羅董有機糙米奶', '「羅董有機糙米奶」，選用蘭陽平原栽培的有機糙米為主要原料，並融合焙炒的加工方式，呈現出渾厚的米香，在堅持所有飲品使用玻璃瓶為包裝容器，及兼顧環境保護下，以保留住食物的天然原味。\r\n訂購專線：039574525#25\r\n產地直送，如何訂購: 羅董養生商品形象網 (loton.com.tw)', '宜蘭縣羅東鎮純精路一段109號', '03-951-8667', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17718/480x360_162羅東農會_有機糙米奶01-20151221161329.jpg', 24.6709527, 121.763845),
(403, '芋香毛豆禮盒', '在遙遠的明鄭時期，位於來往台南府城與山區的這個地方形成新的市鎮，故名新市。熙熙攘攘的商賈在新市建造繁榮的市鎮，不過景象多元的新市還有生氣蓬勃的田園，現今生產全國知名，還遠銷日本的毛豆。\r\n新市人引以為傲的優質非基改毛豆由嚴格管理的契作農田種植。為了讓顧客吃到最新鮮甘甜的毛豆，農民不辭辛苦在清晨太陽出來前，毛豆上還淌著露水時快速採收，並於 4 小時內嚴選、精心製作，冷凍保存新鮮原味，是下飯配酒的好菜。', '臺南市新市區復興路1之1號', '06-589-9888', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17703/480x360_114 新市區農會_芋香毛豆 (400x320)-20151220234944.jpg', 23.0792851, 120.2955182),
(404, '茉莉賞茶御品禮盒(烏龍+語茶)', '彰化縣花壇鄉，一個地如其名的地方，盛產清香的茉莉花，製成花茶用熱水一沖，瞬間馨香四溢，彷彿置身茉莉花叢。若混和同樣是本地名產鮮甜的烏龍茶，或是有奶香的金萱茶，甘甜的茶湯味加上沁鼻幽香，又是不同層次的感動。茉莉賞茶御品禮盒，把朵朵潔白的乾燥茉莉花置於玻璃瓶中，給您帶來不同的視覺享受，讓您在送禮中宛如華族般高貴優雅。', '彰化縣花壇鄉花壇村花壇街273號', '04-786-7821', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17512/480x360_115 花壇農會_茉莉御品-20151220235511.jpg', 24.02599, 120.537346),
(405, '茉莉賞茶極品禮盒', '彰化縣花壇鄉，一個地如其名的地方，盛產清香的茉莉花，製成花茶用熱水一沖，瞬間馨香四溢，彷彿置身茉莉花叢。若混和同樣是本地名產鮮甜的烏龍茶，或是有奶香的金萱茶，甘甜的茶湯味加上沁鼻幽香，又是不同層次的感動。茉莉賞茶御品禮盒，把朵朵潔白的乾燥茉莉花置於玻璃瓶中，給您帶來不同的視覺享受，讓您在送禮中宛如華族般高貴優雅。', '彰化縣花壇鄉花壇村花壇街273號', '04-786-7821', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17513/480x360_116 花壇農會_茉莉賞茶 (400x320)-20151220235716.jpg', 24.02599, 120.537346),
(406, '魚池香菇禮盒', '自古人們就上山摘取香菇食用，因產量有限，摘取須靠運氣，故可稱上「山珍海味」，直到二次大戰後，採用人工栽培方法，才使得產量大增，讓人們吃香菇不需要再靠運氣。魚池鄉的香菇多以太空包方式種植，品質優良，不論炒香菇、煮香菇雞湯，都令人讚不絕口。不論自己吃，或年節送禮，絕對是禮「輕」情義重的好選擇。\r\n訂購專線：049-2898453', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17514/480x360_117 原鄉美食--11魚池農會--魚池香菇禮盒 (400x320)-20151221000043.jpg', 23.89618859999, 120.9350395999),
(407, '苦茶油', '玉山、中央山脈、阿里山等名山橫貫的南投縣，在那沒有農藥污染的翠綠山林中，長著難得的製油珍寶－油茶樹。製作苦茶油的油茶樹周年長青，它的果實被稱為稱為「天綠菓」，因為它開花結果到採收長達 300 天以上，費時、耗工。用高山出產、耗時全年栽培的油茶果製作的「南投苦茶油」，純天然、耐高溫，是料理最佳良品。\r\n訂購專線：049-2251170', '南投縣南投市南崗三路1號', '04-9225-1170', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17518/480x360_118 南投縣農會_苦茶油 (400x320)-20151221000849.jpg', 23.9222475, 120.6723086),
(408, '紫鬱金薑黃粉', '南投青翠群山與清澈溪流間，藏著無數大自然的寶藏。薑黃－咖哩的原料，也是印度古醫學的常用藥材，在南投的好山好水中得到絕佳生機。薑黃含有高量薑黃素成份，對人體具有保健作用，日本天皇以此為御用養生聖品。名間鄉生產的薑黃有紫鬱金、秋鬱金、紅薑黃三種，風味各有特色，嚴選高海拔萬年紅礫土栽培種植，堅持自然農法管理，使用最新生技製程，完整保留高單位薑黃素成份，而無農藥殘留，純淨天然！', '南投縣名間鄉彰南路26號', '04-9273-2111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17519/480x360_119 至121名間鄉農會_禮盒 (400x320)-20151221001109.jpg', 23.8368341, 120.703988),
(409, '頂級黑金剛花生禮盒', '元長鄉因土壤肥沃，氣候適宜，每年黑金剛花生種植面積高達 1,000 公頃以上，居全台之冠。由於黑金剛花生相對於其它品種之花生有較低的油脂含量，加上其花生仁表膜含有花青素，讓黑金剛花生呈紫黑色，更受廣大之消費者喜愛，這也是近年來黑金剛花生急速竄起的主要原因。元長鄉農會邀您品嚐黑金剛花生香甜脆的最佳天然風味。\r\n訂購專線：05-78820056', '雲林縣元長鄉長南村中山路42號', '05-788-2005', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17524/480x360_122 原鄉美食--14元長鄉--黑金剛禮盒 (400x320)-20151221001915.jpg', 23.6501714, 120.3135554),
(410, '白醬油禮盒', '雲林西螺，台灣第一的黑豆產地，更擁有獨一無二的傳統蔭油釀造技術，從一百多年前傳承至今，現在推出兼具傳統又有突破性的新產品－白醬油。運用一世紀傳承下來的釀造技術，將黑豆蒸煮甕釀後的白醬油，透著琥珀色的光澤與甘甜味的口感。在加熱後，能將菜餚的美味更帶往另一風味層次。', '雲林縣西螺鎮延平路353號', '05-586-3621', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17526/480x360_124 原鄉美食--16西螺農會--白醬油禮盒 (400x320)-20151221002405.jpg', 23.8003737, 120.4546302),
(411, '包種茶油', '有來自雪山清澈泉水的灌溉，坪林鄉有滿山青綠的茶園。從這塊福田出產的，除了有名的包種茶外，還有用新鮮茶籽製成的包種茶油。「茶籽油成分不易造假，農會完全使用包種茶籽榨油，百分之百純天然。」食安風暴後，家庭主婦對於食用油選擇更是謹慎，新北市坪林區農會自製的包種茶油也因而大賣。', '新北市坪林區坪林村坪林街103號', '02-2665-7227', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17527/480x360_125 坪林區農會_包種茶油 (400x320)-20151221002602.jpg', 24.936102, 121.7117779999),
(412, '蜜汁紅豆', '有「紅豆故鄉」之盛名的萬丹鄉，所生產的紅豆粒粒飽滿不空心、色澤鮮紅亮麗，煮起來的紅豆香味濃郁、質感酥鬆且皮薄，品質相當優良，深得消費大眾喜愛。無論是煮紅豆湯，或是作為糕餅內餡，都可以實實在在地感受到綿密香濃的口感，所帶來的幸福好滋味。', '屏東縣萬丹鄉萬丹路一段25號', '08-777-2007', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17715/480x360_158萬丹鄉農會_蜜汁紅豆1-20151221160015.jpg', 22.58455, 120.488925),
(413, '花生湯', '花生，原名「落花生」，亦名番豆，臺灣話稱為土豆，相傳宋元之間廣東商人得自海上諸國，種於沙地上，民諺有「常吃花生能養生，吃了花生不想葷」。雲林縣是花生的故鄉，精心調處的「雲林花生湯」，口味迎合大眾，味美香醇，富含營養，夏季消暑飲品，冬季滋補食品。', '雲林縣斗南鎮永安街57號', '05-597-4101', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17716/480x360_159雲林縣農會_花生湯禮盒-20151221160358.jpg', 23.6784845, 120.4825552),
(414, '八卦山咖啡', '唇齒留香、回甘強烈，是八掛山咖啡留給品客的一抹印象。在山泉水灌溉、傳統日曬、自然風涼乾等用心之下所烘焙出的新鮮咖啡豆，品質穩定、香醇、微酸、無苦澀，是咖啡中的新極品。', '彰化縣彰化市忠孝里辭修路119號', '04-725-1171', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17717/480x360_160彰化市農會_八卦山咖啡-20151221161005.jpg', 24.086618, 120.53876),
(415, '羅董養生皮蛋', '有一句老顧客的話，講的很傳神：「皮蛋溏心的蛋黃，嚐起來的美味不輸大閘蟹的蟹膏」。所以好的皮蛋不用過度調味直接吃或加點蠔油、蔥花就很美味，這也是農會長期以來對「羅董養生皮蛋」品質的要求與堅持所在。\r\n訂購專線：03-9574525#25', '宜蘭縣羅東鎮純精路一段109號', '03-951-8667', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18552/480x360_6b29279c80e6429589eb5a9f32e0218c.jpg', 24.6709527, 121.763845),
(416, '農好黑蒜精', '清明節前後，雲林農家一齊出動，採收當季最新鮮的大蒜，攻占全國 85% 的大蒜市占率。「農好黑蒜精」選用最佳蒜頭，進行 2~3 個月酶化發酵，讓白蒜本身的蛋白質轉化成人體必需胺基酸，消除了辛蒜氣味，顏色轉黑了，內容更營養，含有大量的多酚、天然檸檬酸和鐵、鋅質。「農好黑蒜精」隨時開罐即可飲用，送禮自用皆相宜。\r\n建議售價: 950元\r\n訂購專線：04-2485-3063#512', '臺中市大里區中興路二段522號', '04-2485-3063', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17712/480x360_129 中華民國農會_農好黑蒜精1 (400x320)-20151221003848.jpg', 24.112515, 120.690106),
(417, '筊白筍脆片', '一片田野風光映入眼簾， 這裡是三芝「美人腿」的家鄉。三芝獨特水梯田地形所培育出的筊白筍都是筍肉潔白、光滑纖美、香甜鮮翠，口感 遠近馳名，製作成「筊白筍脆片」，更是一絕，讓人一口接一口！', '新北市三芝區中山路一段 6 號', '02-2636-3111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17753/480x360_130 三芝區農會_筊白筍脆片 (400x320)-20151222133803.jpg', 25.2583618, 121.498994),
(418, 'A 贏生黑豆', '黑豆在古代藥典中出現很早，秦漢時期，中國第一部藥學書專著《神農草本經》就已經有黑豆的記載。尤以最著明的明朝李時珍所著《本草綱目》亦記載：黑豆氣味甘、平、無毒。「A 贏生黑豆」展現下營鄉農會產品自然原料、傳統生產的品牌堅持。', '臺南市下營區新興里中山路1段322號', '06-689-2209', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17723/480x360_131下營區農會_A贏黑豆-20151221175627.jpg', 23.2372631, 120.2672728999),
(419, '土豆人家', '色澤黝黑光亮，口感細緻香甜的北港鎮黑金剛土豆又稱長生果，其營養成分高，富含花青素，花生仁飽滿，香氣十足，口感濃郁細緻。在農會積極改造之下，將土豆搖身一變為優質的在地產業，更是北港鎮的金字招牌。', '雲林縣北港鎮中正路20號', '05-783-2031', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17728/480x360_136土豆人家2-20151221180342.jpg', 23.5688534, 120.304131),
(420, '加比山頂級咖啡豆禮盒', '品嚐咖啡是一種生活的態度，也是一門藝術。位於加比山的古坑頂級咖啡豆，經專家評鑑，採購烘焙而成，其獨特之處，在於不苦不澀、入口滑潤，奢華的風味浸潤在舌尖與整個味蕾，是行家眼中的極品之選。\r\n訂購電話：05-5821009', '雲林縣古坑鄉古坑村中華路19號', '05-582-3102', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17729/480x360_137古坑鄉農會_加比山頂級咖啡豆禮盒-20151221180505.jpg', 23.6435676, 120.5606759),
(421, '加比山典藏咖啡豆禮盒', '品嚐咖啡是一種生活的態度，也是一門藝術。位於加比山的古坑頂級咖啡豆，經專家評鑑，採購烘焙而成，其獨特之處，在於不苦不澀、入口滑潤，奢華的風味浸潤在舌尖與整個味蕾，是行家眼中的極品之選。', '雲林縣古坑鄉古坑村中華路19號', '05-582-3102', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17458/480x360_138古坑鄉農會_典藏咖啡豆禮盒-20151221180635.jpg', 23.6435676, 120.5606759),
(422, '玉井芒果汁布丁', '芒果的香濃與果乾的Q 彈，沉浸在蜜糖的柔情蜜意當中，香、酥、Q 的口感，在唇齒之間恣意奔放，不時觸動人心。咬一口玉井芒果酥，感受到天堂的喜悅與幸福的滋味，此時體驗著濃濃情意，細細品味，甜蜜湧上心頭。而芒果汁布丁口口都是驚喜，其風味絕佳、動感多汁，品嚐的每一口都是種享受。', '臺南市玉井區中正路139號', '06-574-2216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17459/480x360_139玉井區農會_芒果汁布丁-20151221180751.jpg', 23.17685709999, 120.4852097),
(423, '紅運高棗', '購買專線：03-7231626\r\n聯絡信箱：kungnon.food@msa.hinet.net\r\n公館鄉紅棗品種可以追溯至120年前，地方耆老陳煥南從廣東潮安引進栽種至今，紅運高棗精力湯是精選紅棗搭配五穀粉、豆粉混勻組合而成，無添加人工香料、色素及防腐劑，營養豐富均衡美味。', '苗栗縣公館鄉館東村大同路266號', '03-722-5211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18097/480x360_076-099 紅運高棗_20101014 (400X320)-20151026153759.jpg', 24.50464069999, 120.8273643999),
(424, '蓮藕粉精裝禮盒', '每年11 月到農曆過年前，是臺南白河鎮製作藕粉的季節。藕粉做起「相當費工，從挖蓮藕、洗粉到曝曬，每個步驟都遵循古法，相當耗時費工，婦女們」幾乎全體總動員。為了做出最好的藕粉，婆婆媽媽從早到晚忙個不停。說到藕粉，含有維生」素C、蛋白質，是營養價值很高的養生食品。', '臺南市白河區三民路412號', '06-685-0923', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17735/480x360_141-樂活飲食-白河農會--蓮藕粉禮盒-20151221181027.jpg', 23.3516817, 120.4157373),
(425, '紫米餅禮盒', '紫米在古時是皇帝食用的米，又稱「貢米」。如今這難得珍品落腳臺東池上鄉，栽種在池上潔淨的水土上，經過池上鄉親的努力耕耘，豐收不斷，紫米不再是屬於皇帝的貢品，任誰都能一嚐古代皇帝獨享的好滋味。池上鄉農會出品的紫米餅以古法製作，口感紮實飽滿厚實而綿密、不甜不膩的。單片包裝設計不沾手，是您佐茶最佳點心，也是上好的伴手禮。', '臺東縣池上鄉台東縣新興村85-6號', '08-986-4880', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17736/480x360_142池上鄉農會_紫米餅禮盒-20151221181146.jpg', 23.08902709999, 121.2278084999),
(426, '芝麻糖', '購買專線：06-7955217\r\n聯絡信箱：a059a059@yahoo.com.tw\r\n芝麻的營養成分豐富，是養生哲學中的最佳好食材。嚴選本土在地原料，香醇美味、口感絕佳的高鈣芝麻糖，是芝麻與麥芽糖混合而成，以純手工精心製作，香脆可口、唇齒留香，是泡茶族的最愛。其芝麻粉食用方式多元，可拌入蜂蜜當果醬，或加入牛奶、豆漿、優酪乳或優格，風味極佳，是老少咸宜的優質產品。', '臺南市西港區文化路2號', '06-795-2706', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17737/480x360_143西港區農會_芝麻糖-20151221181255.jpg', 23.1236716, 120.2051215),
(427, '芝麻粉', '芝麻的營養成分豐富，是養生哲學中的最佳好食材。嚴選本土在地原料，香醇美味、口感絕佳的高鈣芝麻糖，是芝麻與麥芽糖混合而成，以純手工精心製作，香脆可口、唇齒留香，是泡茶族的最愛。其芝麻粉食用方式多元，可拌入蜂蜜當果醬，或加入牛奶、豆漿、優酪乳或優格，風味極佳，是老少咸宜的優質產品。', '臺南市西港區文化路2號', '06-795-2706', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17738/480x360_144西港區農會_芝麻粉-20151221181527.jpg', 23.1236716, 120.2051215),
(428, '臺灣東山．濾泡式咖啡', '以「阿拉比卡」品種栽培為主的東山咖啡，品質優良、口感極佳，是臺灣本土咖啡之光。多年來農民不斷積極投入研發，以取得美國CQI 認證資格，並成功登陸美國CQI國際網路平臺，讓全世界愛好咖啡者，都 可以品嚐到東山咖啡。', '臺南市東山區中興路1號', '06-680-0814', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17739/480x360_145東山區農會_咖啡-20151221181710.jpg', 23.1781599, 120.483966),
(429, '妖八度- 梅精壯氧飲料', '有清朝貢品之美稱的紅景天，在信義鄉農會採用產學合作技術的帶領下，將紅景天等特殊漢方結合於飲料內。運動過後，可作為養分補給，讓身體充滿活力； 亦可當平時保健及飲品，或送禮皆合宜。', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17740/480x360_146信義鄉農會_梅精壯氧飲料-20151221181832.jpg', 23.68870099999, 120.861791),
(430, '紅豆湯', '古法熬煮而成的蜜豆，甜淡適中，是道地的好口味。其黑豆含維生素與多種礦物質。而紅豆則採用萬丹鄉栽種的國產紅豆，其紅豆顆粒碩大，口感細緻綿密，並含植物蛋白質與維生素E。打開即食，調理方便，送禮自用兩相宜。', '屏東縣屏東市瑞民路6號3樓', '08-722-3805', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17741/480x360_147屏東縣農會_紅豆湯-20151221182027.jpg', 22.6631428, 120.5075365),
(431, '蜜豆禮盒', '古法熬煮而成的蜜豆，甜淡適中，是道地的好口味。其黑豆含維生素與多種礦物質。而紅豆則採用萬丹鄉栽種的國產紅豆，其紅豆顆粒碩大，口感細緻綿密，並含植物蛋白質與維生素E。打開即食，調理方便，送禮自用兩相宜。', '屏東縣屏東市瑞民路6號3樓', '08-722-3805', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17742/480x360_148樂活飲食--屏東縣農會--蜜紅豆黑豆禮盒-20151221182447.jpg', 22.6631428, 120.5075365),
(432, '東方美人茶飲', '東方美人茶原稱膨風茶。相傳早期有一茶農因茶園受蟲害侵食，不甘損失，乃挑至城中販售，沒想到竟因風味特殊而大受歡迎。回鄉後，茶農向鄉人提及此事，竟被指為「膨風」，從此膨風茶之名不脛而走。喜歡喝東方美人茶的人可以喝得更便利了，峨眉鄉農會推出了東方美人茶罐裝茶飲，讓民眾「花小錢，也能品嘗好茶」。', '新竹縣峨眉鄉峨眉村8鄰12號', '03-580-0216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17743/480x360_149峨眉鄉農會_東方美人茶7-20151221182607.jpg', 24.6887921, 121.0195946),
(433, '峰田小町-綜合鮮菇乾', '霧峰是臺灣菇類的主要產地，尤其金針菇的品質達到國際水準之上，大規模的生產農場使霧峰榮獲「菇類王國」之美譽。走入當地菇園裡，一朵一傘的鮮甜好菇，是大自然以時間孕育出的美味，充滿了新鮮豐沛的天然活力！「峰田小町」將一點一滴最天然的色香味，完美保留在一片片原色原味、香酥清脆的鮮菇片裡，是兼顧香脆口感美味與膳食纖維質的好零食。', '臺中市霧峰區中正里四德路10號', '04-2339-3404', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17720/480x360_164霧峰農會_小町鮮姑乾-20151221162025.jpg', 24.0651751, 120.679522),
(434, '幸福禮盒', '紅棗、紫蘇均為公館特有農產，長久以來均被視為中藥材使用。公館鄉農會食品廠特別將紅棗製成可以一嘴一口的健康零嘴的紅棗干；紫蘇則開發成可作為佐菜香料的紫蘇醬，夾土司、配稀飯、拌飯或拌麵皆適宜。紅棗干和紫蘇醬再搭配客家名產福菜而組成禮盒，口味多元，送禮大方、又健康', '苗栗縣公館鄉館東村大同路266號', '03-722-5211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18098/480x360_077-099 幸福禮盒_20101015 (400X320)-20151026153834.jpg', 24.50464069999, 120.8273643999),
(435, '香蕉戀汝', '臺灣擁有「香蕉王國」美譽，藉由香蕉盛產國及乳品加工技術優勢，實實在在添加15% 國產香蕉原汁，沒有添加任何色素，讓消費者品嚐真正臺灣在地好味道。當香蕉遇上牛奶，水「乳」「蕉」融的好滋味，微微的酸、蜜蜜的甜，蹦出戀愛般的好滋味。', '臺中市大里區中興路二段522號', '04-2485-3063', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17724/480x360_132中華民國農會_香蕉戀汝-20151221175814.jpg', 24.112515, 120.690106),
(436, 'FACE MILK', '四十多年的專業製造經驗，以現代化設備生產製造，採取超高溫殺菌及連續靜水壓減菌塔滅菌生產，保證不含防腐劑，品質卓越。健康的乳源，高品質的保久乳，口味多樣、質優味美，為國內玻璃瓶裝保久乳領導品牌。', '臺中市大里區中興路二段522號', '04-2485-3063', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17725/480x360_133中華民國農會_FACE MILK-20151221175936.jpg', 24.112515, 120.690106),
(437, '有機黑木耳飲', '重視健康的你有沒有發現市面上出現愈來愈多木耳飲品？不僅占據了便利商店的一個角落，網路購物、電視購物都在大聲販賣，甚至還出現黑木耳專賣店。 原來，木耳富含蛋白質、礦物質、多種維生素、膠質與膳食纖維，素有「植物性燕窩」稱號。冬山鄉農會推出「有機黑木耳飲」與「有機白雪耳飲」，是忙碌的現代人補充營養的「方便飲」。\r\n產地直送，如何訂購：冬山鄉農會購物商城', '宜蘭縣冬山鄉中正路39號', '03-959-1122', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17726/480x360_135冬山鄉農會_黑木耳飲-20151221180056.jpg', 24.6326533, 121.793597),
(438, '有機白雪耳飲', '重視健康的你有沒有發現市面上出現愈來愈多木耳飲品？不僅占據了便利商店的一個角落，網路購物、電視購物都在大聲販賣，甚至還出現黑木耳專賣店。 原來，木耳富含蛋白質、礦物質、多種維生素、膠質與膳食纖維，素有「植物性燕窩」稱號。冬山鄉農會推出「有機黑木耳飲」與「有機白雪耳飲」，是忙碌的現代人補充營養的「方便飲」。\r\n產地直送，如何訂購：冬山鄉農會購物商城', '宜蘭縣冬山鄉中正路39號', '03-959-1122', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17727/480x360_134冬山鄉農會_白雪耳飲-20151221180215.jpg', 24.6326533, 121.793597),
(439, '玉井芒果酥', '芒果的香濃與果乾的Q 彈，沉浸在蜜糖的柔情蜜意當中，香、酥、Q 的口感，在唇齒之間恣意奔放，不時觸動人心。咬一口玉井芒果酥，感受到天堂的喜悅與幸福的滋味，此時體驗著濃濃情意，細細品味，甜蜜湧上心頭。而芒果汁布丁口口都是驚喜，其風味絕佳、動感多汁，品嚐的每一口都是種享受。', '臺南市玉井區中正路139號', '06-574-2216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/17734/480x360_140玉井區農會_芒果酥-20151221180910.jpg', 23.17685709999, 120.4852097),
(440, '香煎芋糕', '購買專線：03-7226868\r\n產地直送，如何訂購: 巧軒餐館\r\n聯絡信箱：a037226868@yahoo.com.tw\r\n公館鄉種植的檳榔心芋頭品質一流，因後龍溪源頭無水源污染，富含礦物質，種出的芋頭特別綿密、鬆軟，利用當地食材及家鄉豐富的資源，精心研發，為在地的農民創造更大的效益。 香煎芋糕有別於傳統的芋粿，加上在來米、上等豬肉、香菇、油蔥，手工製作的芋糕切片煎過後，口感外酥內軟，芋頭香味濃郁，無添加任何防腐劑，芋頭經過農藥檢驗，大家可安心食用。', '苗栗縣公館鄉石墻村11鄰223-1號', '03-722-6868', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18510/480x360_9ba74b535b3947979514f6fa9dd622da.jpg', 24.472237, 120.8195033),
(441, '幸福心食作-香蕉脆片', '選用中寮鄉高海拔新鮮香蕉，一片片金黃誘人的香蕉脆片，酥脆的口感，絕對讓您一口接著一口停不下來。', '南投縣中寮鄉永平村永平路186號', '04-9269-1111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18515/480x360_991bebaaee134d1ba01a11faabd84521.jpg', 23.8787397, 120.7678090999),
(442, '老少配-蘿蔔雞湯原料組', '購買專線：08-9814903\r\n聯絡信箱：dx0911@yahoo.com.tw\r\n由在地生產之蘿蔔進行醃漬及存放20年以上，並搭配3-5年蘿蔔乾，組成老少配原料組，成為最有古早氣息的菜餚，讓民眾購買回去後，不須任何調味即可煮出一鍋香濃可口的老蘿蔔雞湯，完全可以吃到食材原味，濃濃的鄉土味讓人回味無窮。', '臺東縣關山鎮和平路78號', '08-981-1022', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18522/480x360_e84ec4319b1d413ea940171117aceb52.jpg', 23.04794679999, 121.1641561),
(443, '關農米乖乖', '購買專線：08-9814903\r\n聯絡信箱：arnu111@yahoo.com.tw\r\n關農米乖乖係採用關山在地良質米，不以傳統國外玉米澱粉進口原料，而採用米製作的米乖乖，連結長者的美好回憶，兒童多了一項新選擇，還能成為吃得到米香的貼心伴手禮，送禮自用兩相宜。', '臺東縣關山鎮和平路78號', '08-981-1022', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18523/480x360_7d3a732f9c9c434a99da3d3d8312b683.jpg', 23.04794679999, 121.1641561),
(444, '蜜黑豆', '購買專線：08-7223805分機335\r\n聯絡信箱：ddt200287@hotmail.com\r\n採用屏東在地高雄七號黑豆，以古法熬煮傳承美味，拆封即可食用。含豐富植物蛋白質與維生素。搭配米(稀)飯、吐司麵包、煮湯圓，或牛奶等混合食用，更方便調理。', '屏東縣屏東市瑞民路6號3樓', '08-722-3805', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18526/480x360_14ef5926710a46e7afe08f7c033b71da.jpg', 22.6631428, 120.5075365),
(445, '銘泉金鑽旺來禮盒', '購買專線：08-7990220\r\n線上訂購: 銘泉生態休閒農場\r\n聯絡信箱：sn45685203@yahoo.com.tw\r\n銘泉聞名的鳳梨是屏東的銘果，選用友善栽種的有機鳳梨做為內餡，吃起來甜中帶酸，酸中帶香，最費工的是每顆內餡都需熬製6-7小時才能完成！\r\n酥皮中加入屏東在地穀類紅寶石之稱有機紅藜米與自然放牧的好蛋，皆由農場所栽種與飼養，吃起來除了安心，更增添了機能性的營養成分，全用鳳梨當餡料的豪氣，才是食材的真滋味。\r\n100%天然鳳梨乾經低溫乾燥保留天然好味道，利用陶缸釀造有機糙米醋為基底，加入有機鳳梨靜置融合，為健康打氣，為人生提味。', '屏東縣瑪家鄉佳義村11鄰泰平巷114-20號', '08-799-0220', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18528/480x360_38571de51c3d459c81690836044f7983.jpg', 22.662026800425792, 120.63174962997437),
(446, '池上米餅', '購買專線：08-9864880\r\n使用在地食材台東池上無污染的優質米，細心拌入伯朗大道的稻香，創新研發製作成點心酥不但口感酥脆，也散發天然的稻米香味，化為美味與情感兼具的池上米餅，是您最佳的伴手禮選擇。', '臺東縣池上鄉台東縣新興村85-6號', '08-986-4880', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18851/480x360_20200428-01.jpg', 23.08902709999, 121.2278084999),
(447, '古早味仙草', '購買專線：03-5872010\r\n聯絡信箱：csm0972132672@yahoo.com.tw\r\n將傳統古早味仙草凍加工製成易開罐，方便攜帶，美味可口的，罐內是一整顆仙草凍喔!', '新竹縣關西鎮北山里10鄰高橋坑6號', '03-587-4277', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18532/480x360_7f110a7742934f7a93f81defb6dc7799.jpg', 24.8032728, 121.1601904),
(448, '飛鼠請假', '購買專線：04-92791949\r\n聯絡信箱：hsinifa@gmail.com \r\n信義在地嚴選成熟黃梅低溫發酵後進橡木桶熟成，以國外 白葡萄酒或紅葡萄酒製作模式，移植至梅子上，除了黃梅 果香外，在橡木桶的加乘效果讓香氣更為豐富有櫻桃、花香撲鼻的感覺，為最原汁原味的梅酒亦是梅酒之首創。', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18534/480x360_4a425b11491e4f69a2519cde0b682a6d.jpg', 23.68870099999, 120.861791),
(449, '玉井愛文芒果干', '購買專線：06-5748551\r\n聯絡信箱：mey877@yahoo.com.tw\r\n以新鮮愛文芒果肉製成，美味爽口不膩，且無任何添加物，完全保存芒果的獨特風味，是具健康、營養的最佳休閒食品。', '臺南市玉井區中正路139號', '06-574-2216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18538/480x360_61e6c0cec4974958812be5cce0e26e2a.jpg', 23.17685709999, 120.4852097),
(450, '紅藜好棒棒', '購買專線：08-9513111#15\r\n聯絡信箱：lucky.a168@msa.hinet.net\r\n選用台灣原生種脫殼紅藜和台東在地糙米製。\r\n酥脆好滋味，是您健康零食的好選擇。', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18542/480x360_cf669fcc2f4746909b95c41a626eecb4.jpg', 22.7555108, 121.142776),
(451, '東方美人茶禮盒', '北埔茶葉以『膨風茶』又叫「東方美人茶」聞名於世，以受到小綠葉蟬咬食過的青心大冇茶樹的嫩葉種，用手採一心 一葉或一心二葉的嫩葉為茶菁，採重度發酵方式所製作出來的烏龍茶，為臺灣烏龍茶中最高品質的代表。', '新竹縣北埔鄉北埔街94號', '03-580-2207', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18554/480x360_9f994920ad2b484aa927d34739e0b751.jpg', 24.700475, 121.055203),
(452, '六香田米禮盒', '購買專線：0905-365658\r\n聯絡信箱：yam2aster@gmail.com\r\n我們的米，取用台灣西部甲及優良水體灌溉，無化學農藥耕作，守護寶山水庫集水區優良環境耕作，確保每一口飯都是純淨。在飯桌上，用心和口，深深記住家的味道。飯桌之外，就用整粒糙米和玄米糠製成的沖泡米麩，為生活中打拼的每一個人，帶來大自然滿滿的元氣。', '新竹縣竹東鎮中興路二段297巷137號', '0916-335-213', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18556/480x360_ec9ca9be547746ee94a595b2293585c8.jpg', 24.759802, 121.05899),
(453, '紅棗脆條巧克力', '購買專線：03-7231626\r\n聯絡信箱：K703588@gmail.com\r\n公館鄉是台灣唯一的紅棗專區，由農會契作收購，嚴選製作紅棗干，再搭配頂級巧克力，酥脆米香粒，舞動在舌尖，香甜中蘊含者甜蜜的幸福。', '苗栗縣公館鄉館東村大同路266號', '03-722-5211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18558/480x360_86c44e81a9264aa78602219f3b3f505a.jpg', 24.50464069999, 120.8273643999),
(454, '冰薯', '苗栗縣西湖鄉是一連十二年獲得台灣環保評鑑第一名的好地方，全鄉好山好水，鄉民世代疼惜這片土地，用最傳統', '苗栗縣西湖鄉三湖村4鄰店仔街71號', '03-792-1715', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18957/480x360_55720201209.jpg', 24.557856401703386, 120.75734812462542),
(455, '橄欖禮盒', '購買專線：03-5760161\r\n聯絡信箱：grace.mrolive@gmail.com\r\n橄欖全身是寶，素有生命之樹美名，於新竹寶山的獨特天然環境與氣候下，孕育出天然不受污染的優質尖仁綠橄欖，以古法製做四種不同口味，鹹、辣、甘、甜，便是古早滋味與兒時回憶翻騰之時。', '新竹縣寶山鄉油田村三峰路一段88號', '03-576-0296', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18560/480x360_7a44234dcd434d8896abfffeea505b0f.jpg', 24.721567, 120.998137),
(456, '有機原生種山苦瓜片', '購買專線：03-8656888\r\n產地直送，如何訂購: 壽豐鄉農會\r\n聯絡信箱：service@shoufong.org\r\n嚴選壽豐「有機原生種山苦瓜」，將山苦瓜整顆切片，低溫烘乾，口感清潤，味甘微苦，保留山苦瓜最自然清香。', '花蓮縣壽豐鄉豐文路105號', '03-865-3101', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18564/480x360_f4c2fa037aba4b3cb44ad0e05b6eff78.jpg', 23.8453491, 121.4976064),
(457, '原生種山苦瓜藤茶包', '購買專線：03-8656888\r\n產地直送，如何訂購：壽豐鄉農會\r\n聯絡信箱：service@shoufong.org\r\n嚴選壽豐「有機原生種山苦瓜之藤蔓(嚴選離地1公分以上直徑大於0.3公分)」，低溫烘乾，口感清潤，味甘微苦，保留山苦瓜最自然清香。', '花蓮縣壽豐鄉豐文路105號', '03-865-3101', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18566/480x360_ea9127b07d974fe799df8c41c7c299ff.jpg', 23.8453491, 121.4976064),
(458, '小農日記禮盒', '購買專線：08-9513111\r\n產地直送，如何訂購：臺東縣農會 (toyugimall.com.tw)\r\n聯絡信箱：lucky.a168@msa.hinet.net\r\n台東農特產品好漾精選，我們是這片大地的小小農夫，但有大大的夢想，謙卑敬愛環境，用心培養作物，用自己的雙手撫摸我的土地。台東在地特色，一次滿足。', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18569/480x360_5f461f7766704199a1d8c8855600dbc0.jpg', 22.7555108, 121.142776),
(459, '山海經脈-花果三重奏', '購買專線：08-9513111\r\n產地直送，如何訂購: 臺東縣農會\r\n聯絡信箱：lucky.a168@msa.hinet.net\r\n取自在地生產在地製造，最新鮮，零污染農產品。純天然食材製成無任何不良食品添加物，是最可安心食用之飲品。', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18570/480x360_787f49d4fbf34d2098311619e2bc4480.jpg', 22.7555108, 121.142776),
(460, '富麗米香花生糖', '購買專線：03-8821991\r\n產地直送、如何訂購 : 歡迎光臨～富里鄉農會 (fulifa.org.tw)\r\n聯絡信箱：aaw8266@gmail.com\r\n純正手作的「富麗米香花生糖」採用花蓮的富麗白米，由操刀十年米香的老師傅親手炮製及堅持要求生花生仁開始翻炒西點師傅製作，讓每口都能咬出爆米香口感及香氣，口齒留香，彷彿回到小時候最愛的那個滋味。', '花蓮縣富里鄉羅山村9鄰東湖6號', '03-882-1705', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18572/480x360_df3087a3057d45fc820190025ffd88c9.jpg', 23.1838646, 121.2969674),
(461, '池上生活米禮盒', '購買專線：089-864880\r\n線上訂購 : 池上鄉農會\r\n聯絡信箱：chc81150@gmail.com\r\n平實的池上農夫，帶著關懷珍惜土地的情感，用心栽種頂級池上米，池上生活米禮盒，一次可品嚐到5種風味的米，成就你我口中奢侈感。', '臺東縣池上鄉台東縣新興村85-6號', '08-986-4880', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18574/480x360_57a162ced9df4b3c9f2d8944f0979795.jpg', 23.08902709999, 121.2278084999),
(462, '嬌澳蝦餅', '購買專線：03-9962108#228\r\n產地直送，如何訂購 : 蘇澳區漁會 (suaofish.org.tw)\r\n聯絡信箱：johnshell83@yahoo.com.tw\r\n選用宜蘭海撈鮮蝦-長角鬥士赤蝦(全蝦)製作而成，不油炸，不含防腐劑，有別於一般油炸蝦餅，味道單純、美味，讓人感受濃郁的鮮蝦味道。', '宜蘭縣蘇澳鎮南安里海邊路126號', '03-996-2108', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18578/480x360_d529b3ef4cfb4b979e47895446ea4aec.jpg', 24.5833868, 121.8659277),
(463, '花現金針山-安全金針', '每年的8~10月是金針山花開的季節，金針花原名萱草，每朵花盛開的時間都只有一天，因此又被稱為「一日美人」，每到夏天一大片澄黃色的花海在風中搖曳，讓人置身夢境中的浪漫中。「花現金針山-安全金針」嚴選太麻里海拔1375公尺之高山金針，不燻硫磺，符合國家安全標準，可以安心食用。', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18580/480x360_95f21afc97fd4bdbabb0e1bc6f69c147.jpg', 22.604987, 121.001855),
(464, '屏農紅豆湯', '購買專線：08-7223805分機335\r\n產地直送，如何訂購：屏東縣農會\r\n聯絡信箱：ddt200287@hotmail.com\r\n精選屏東萬丹鄉盛產之頂級紅豆，具產地標章認證及原料檢驗溯源二維碼。\r\n紅豆顆粒碩大晶瑩、口感細緻綿密，實實在在的用料，以傳統工法製造，甜度適中，道地珍饌古早味，紅豆營養滿載，送禮自用兩相宜。', '屏東縣屏東市瑞民路6號3樓', '08-722-3805', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18582/480x360_663e383bb7314b67bdc92188aa2a2d27.jpg', 22.6631428, 120.5075365),
(465, '92咖啡禮盒', '購買專線：04-92721879\r\n產地直送、如何訂購: 南投縣國姓鄉農會\r\n聯絡信箱：029fcrezo@gmail.com\r\n因九份二山海拔近1200公尺，又處兩溪的匯流點、溼氣充沛、日夜溫差約10℃、土壤肥沃、排水性佳、日照又穩定，咖啡豆生長速度緩慢，是最適合咖啡樹生長的地方，採自然友善耕法栽種，讓咖啡豆的品質保持優良。', '南投縣國姓鄉中正路二段357號', '04-9272-1510', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18586/480x360_a10edf5d7a66440c8fee1899ed994eef.jpg', 24.024487, 120.846814);
INSERT INTO `gift` (`id`, `name`, `feature`, `addr`, `tel`, `picurl`, `lat`, `lng`) VALUES
(466, '禾樂幸福-手作米Pizza', 'Q彈爽口米飯再配上綿密鬆軟的大甲芋頭，利用特製的米穀粉手工揉製，在嘴裡咀嚼米飯香甜又散發出芋頭自然清香，讓您吃得安心，溫暖在心，每一口都是幸福的滋味!', '臺中市大甲區中山路1段372號', '04-2686-3990', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18590/480x360_15ab0981d65c422e908c5b2a59dc0c19.jpg', 24.334949, 120.615858),
(467, '鳳梨心乾', '嚴選關廟新鮮的台農17號金鑽鳳梨，不含人工色素香料，去頭去尾，以手工切法，只選取中間鳳梨心低溫烘焙，保留鳳梨果實纖維，將天然的風味濃縮在鳳梨心乾裡。\r\n產地直送，如何訂購: 關廟區農會', '臺南市關廟區中正路963號', '06-596-6278', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18592/480x360_b2af763aea6748708d5d2ad2511d7647.jpg', 22.9624989, 120.3284754),
(468, '鳳梨果乾', '購買專線：06-595 2352\r\n產地直送，如何訂購: 台南市關廟區農會\r\n  \r\n  聯絡信箱：john09262000@hotmail.com\r\n  \r\n  嚴選關廟新鮮的台農17號金鑽鳳梨，不含人工色素香料，去頭去尾，以手工切片，以低溫烘焙製成，保留鳳梨果實纖維，將天然的風味濃縮在鳳梨果乾內。', '臺南市關廟區中正路963號', '06-596-6278', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18594/480x360_5f5b0a5e910d4ea4a7eba3c7954710b7.jpg', 22.9624989, 120.3284754),
(469, '待客以鱒-醃鱒', '鱒魚，魚中貴族，肉質細嫩，甜美多汁，無腥味，無小骨刺，不需刮鱗片，含有豐富蛋白質，低脂肪且低膽固醇。本產品係新鮮鱒魚經挑選醃製真空包裝，急速冷凍而成，可煎、可烤、可炸、再加點新鮮檸檬汁 美味無窮是過年、過節、最佳伴手禮。', '苗栗縣南庄鄉中正路60號', '03-782-3155', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18102/480x360_082-098 待客以鱒-醃鱒_20091016 (400X320)-20151026154255.jpg', 24.5998088, 120.9987935),
(470, '友善農耕禮盒', '購買專線：05-5968583\r\n聯絡信箱：dn.farm@msa.hinet.net\r\n斗南町越光米源自日本天皇御用米種(來自日本福井原種) ，米粒晶瑩飽滿帶有光澤透明感，煮後散發出珍珠光澤，芳香撲鼻，特有米飯香氣令人無法抗拒；米質具黏性、彈性及甜度特佳， 即使冷卻後的米飯依然能保持即佳的黏彈性，香Ｑ爽口。', '雲林縣斗南鎮田頭里延平北路111號', '05-596-8583', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18604/480x360_83b7aac80d44420fb06afdecf866b0ee.jpg', 23.7130497, 120.4833299),
(471, '蓮子豆奶布丁', '選用觀音在地生產蓮子，加入健康概念古早味豆奶，製成老少咸宜的蓮子豆奶布丁。', '桃園市觀音區藍埔里11鄰52號', '03-497-1202', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18606/480x360_a8122851188947ac9fe9d66f1efadc2e.jpg', 25.0078319, 121.1116417),
(472, '黑金剛花生', '購買專線：05-7730640\r\n聯絡信箱：p650.p650@mas.hinet.net\r\n北港土地長出的黑金剛個頭飽滿、色澤黝黑光亮，種皮的深黑色是天然色素，富含青花素，莢果網紋深邃，炒焙後的口感細緻清香，具有「長生果」的美稱。', '雲林縣北港鎮中正路20號', '05-783-2031', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18610/480x360_45dafd13676c41e891c32adf5d0bb72d.jpg', 23.5688534, 120.304131),
(473, '透紅佳人蓮霧果乾', '購買專線：08-8660012、0917-237297\r\n產地直送，如何訂購 : 屏東縣佳冬鄉農會 \r\n聯絡信箱：ok10010274@gmail.com\r\n以100%冬鄉透紅佳人好蓮霧鮮果製成，經過低溫乾燥工法製作，完整封存蓮霧纖維、香甜微果酸的滋味，安全無添加物、低熱量，吃得無負擔。', '屏東縣佳冬鄉佳冬村佳和路64號', '08-866-0012', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18612/480x360_fbcde0cc2b844067b680ba6b5507707b.jpg', 22.412898, 120.5567282),
(474, '呷促米米餅-鹽酥雞金針風味', '購買專線：03-8821705\r\n產地直送，如何訂購: 歡迎光臨～富里鄉農會 (fulifa.org.tw)\r\n聯絡信箱：manson921@gmail.com\r\n呷促米米餅，一個玩味有趣的零嘴，堅持使用全國最大有機稻作的富里鄉地稻米，更別說還取用了全球十大花海之一的六十石山金針，旅行途中的您來訪到了富里，走看金針花海、踏訪有機村，絕不能錯過了這極具代表性的伴手，一口一回味讓旅行途中的您，可以分享給朋友們來自富里的回憶。', '花蓮縣富里鄉羅山村9鄰東湖6號', '03-882-1705', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18614/480x360_e6e98d7a061e4708939b8d041899bef0.jpg', 23.1838646, 121.2969674),
(475, '風華綻現-茉莉烏龍茶', '以汝窯為藍本，傳遞茉莉花壇出產之無毒茉莉花因種植過程艱辛、生產數量有限而成為令人傾心的茶界珍品，完美調和茉莉花茶與品茗賞玩之回甘韻味。\r\n產地直送，如何訂購: 茉莉花壇夢想館', '彰化縣花壇鄉花壇村花壇街273號', '04-786-7821', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18616/480x360_945fadf4b2694f4d93f967de3ee9f7d3.jpg', 24.02599, 120.537346),
(476, '美濃紅豆', '購買專線：07-6831624、07-6833496\r\n聯絡信箱：Sunset1121@hotmail.com\r\n美濃盛產紅豆，年產11萬公斤，農會因應近幾年的健康風潮，自2013年起推動友善環境耕種，從契作紅豆開始，採無農藥的自然落葉法，希望消費者能享用每一顆用心栽種美濃紅豆。', '高雄市美濃區清水里中正路三段100號', '07-6831624', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18622/480x360_874b33445727451eb918512726b42569.jpg', 22.9025301, 120.541316),
(477, '純釀梅', '購買專線：04-92721510#60、0917-659530\r\n產地直送，如何訂購 : 姓農小舖\r\n聯絡信箱：ksc2724011@gmail.com\r\n使用最天然、最古老了方式釀製而成，梅子吃完後的梅汁，還可加水沖泡成醇香釀梅汁！', '南投縣國姓鄉中正路二段357號', '04-9272-1510', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18624/480x360_7d0a249faf084055a7ee96eeaefa4c78.jpg', 24.024487, 120.846814),
(478, '阿里山高山茶-日出雲露', '購買專線：05-2622100*717、0911-699637\r\n聯絡信箱：cheinyungyi@yahoo.com.tw\r\n本梅山茶區位於海拔1000公尺以上阿里山山脈之高山茶區，茶葉由茶農精耕、手採、細搓、輕揉、慢焙、所製之精緻茶葉，滋味甘醇滑軟，具獨特的淡雅牛奶香氣、喉韻強、耐沖泡，茶湯色澤鮮活翠綠，為梅山鄉阿里山高山茶特色，並樹立良好的信譽品質。', '嘉義縣梅山鄉中山路127號', '05-262-2100', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18626/480x360_94cf97597a82476c9ca45ae75e8eda17.jpg', 23.581617, 120.558779),
(479, '滬尾南瓜起士紅藜麥餅乾', '購買專線：02-262393057\r\n產地直送，如何訂購 : 淡水區農會\r\n聯絡信箱：hwa8989da@yahoo.com.tw\r\n以天然酵母自然風味的南瓜起士餅乾，再添加紅藜麥豐富食感，精製研發，豐富食感，風味自然。', '新北市淡水區中正路42-1號', '02-2620-2290', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18628/480x360_0ca6223fae8f4691b9e74ecefd4f42e8.jpg', 25.1694714, 121.4435245),
(480, '黑娘媽頂級黑豆釀蔭油', '購買專線：05-3741145*141、0937-557868\r\n聯絡信箱：sunshineququ@hotmail.com\r\n新港鄉農會「黑娘媽」醬油，醬油原料來自契作的非基改黑豆，契作模式為統一播種、統一用藥、統一採收，還依據TAP作業規範獲得產銷履歷安全認證，讓消費者可以「食在安心」。', '嘉義縣新港鄉登雲路111巷2號', '05-374-1148', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18630/480x360_ab59e161a10649e8b31ab24af1dd63a1.jpg', 23.5559585, 120.3440271),
(481, '旗魚酥', '購買專線：04-7786669、0982-878742\r\n產地直送，如何訂購  : 彰化區漁會供銷部\r\n聯絡信箱：Chfa302@chfa.org.tw\r\n精選台灣漁民捕獲之上等旗魚製作，營養成分高、獨特台灣口味，不添加防腐劑、塑化劑及色素，台灣名產，送禮、自用兩相宜。', '彰化縣鹿港鎮復興路485號4樓', '04-778-8945', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18684/480x360_f67d92a289f74df6b175b49e1b78f785.jpg', 24.0587671, 120.434389),
(482, '白珍珠花生', '澎湖的白膜花生，帶殼蒸煮，口感香甜綿密，保有花生原有的營養與風味，冷凍、熱食均宜。', '澎湖縣馬公市大勇街30號', '06-927-2335', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18634/480x360_50233ba864944b079983fe2366b2f163.jpg', 23.5718492, 119.5721153),
(483, '香茹茶', '購買專線：0963-432927\r\n聯絡信箱：Jacky28.chen@msa.hinet.net\r\n強風、鹽霧、乾旱、曝日不利於植物生長的環境下，孕育出的澎湖風茹茶，沖泡後有濃郁茶香，故稱為香茹，其根部如人蔘狀，民間俗稱山蔘，清香甘醇，可消暑解渴。', '澎湖縣馬公市大勇街30號', '06-927-2335', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18636/480x360_09eab8dadfdf43c990acd09489213926.jpg', 23.5718492, 119.5721153),
(484, '蕎麥雪花片', '購買專線：0935-207297\r\n線上訂購：二林鎮農會 蕎薏小舖\r\n聯絡信箱：n_lp_kung@yahoo.com.tw\r\n天然高纖、素食無糖，保養輕盈的聖品。\r\n依個人喜好單獨用熱開水沖泡飲用，亦可與牛奶、咖啡或其他口味之飲品一起沖跑泡飲用。', '彰化縣二林鎮南光里儒林路2段260號', '04-896-1191', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18682/480x360_8b9b875f967d489d91f48d339f55a2aa.jpg', 23.8964285, 120.369443),
(485, '紅薏仁雪花片', '購買專線：0935-207297\r\n產地直送，如何訂購: 二林鎮農會 蕎薏小舖\r\n聯絡信箱：n_lp_kung@yahoo.com.tw\r\n由紅薏仁磨成漿，經蒸煮糊化過程乾燥而成，絕無任何添加物，讓您吃的健康，身體無負擔。', '彰化縣二林鎮南光里儒林路2段260號', '04-896-1191', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18638/480x360_bc39af81d9b944b0aec125502ee39d6d.jpg', 23.8964285, 120.369443),
(486, '阿里山高山茶', '購買專線：05-2612120 #201\r\n聯絡信箱：sankenlin009@yahoo.com.tw\r\n高山茶生長環境氣溫較低，常年雲霧籠罩，濕度足夠，日照及水分充足，使茶葉生長出柔軟、芬芳，醇化而不苦澀之高山茶葉。', '嘉義縣竹崎鄉竹崎村中山路111號', '05-261-2120', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18640/480x360_7f94724d0dca4244ae352095de5c7d9e.jpg', 23.5216026, 120.550813),
(487, '縱穀好禮', '購買專線：08-9814903\r\n產地直送，如何訂購 : 關山鎮農會\r\n聯絡信箱：solio940223@yahoo.com.tw\r\n細數關山優質好米-白米、糙米、香米、黑糯米及小米，一個禮盒、完整呈現，不用眼花撩亂、無法取捨，更能一次滿足您的味蕾；各種米將在嘴裡演繹不同的故事，唯一相同的是滿足與美味，不可錯過的關山好米盡在縱穀好禮內。', '臺東縣關山鎮和平路78號', '08-981-1022', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18688/480x360_67ad9bebedad4bd3bf795dad06e3a2ac.jpg', 23.04794679999, 121.1641561),
(488, '金蜜急凍芒果冰禮盒', '採用新鮮的金蜜芒果，經過清洗、削皮、去籽後急速冷凍製成全國唯一純天然的金密急凍鮮果冰棒，完全保留金蜜芒果的原味。\r\n產地直送，如何訂購 : 彰化縣埔心鄉農會', '彰化縣埔心鄉忠義北路100號', '04-829-3171', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18642/480x360_1c1aaa3481e844f3bc47a304765146a0.jpg', 23.954959, 120.543161),
(489, '金蜜芒果家族禮盒', '嚴選埔心鄉金蜜芒果經清洗潔淨，低溫烘培製成果乾，完全沒有食品添加物，保留金蜜芒果的香氣與鮮甜。\r\n嚴選埔心鄉金蜜芒果製成果醬，保留金蜜芒果的香濃原味。\r\n產地直送，如何訂購 : 彰化縣埔心鄉農會', '彰化縣埔心鄉忠義北路100號', '04-829-3171', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18644/480x360_40e5a63f4ef842fd9a14b48ae185fc2c.jpg', 23.954959, 120.543161),
(490, '精選紅茶禮盒', '購買專線：0921-008077\r\n產地直送，如何訂購: 魚池鄉農會\r\n聯絡信箱：serviceyuchi@hotmail.com.tw\r\n日本人自印度引進的「阿薩姆茶種」，曾在倫敦拍賣會中名列頂級，也是日本天皇的御用珍品。滋味濃郁帶有天然的麥芽香，亦適合做成加味茶。\r\n「台茶18號-紅玉紅茶」歷經五十餘年育種試驗，茶湯水色艷紅，散發出天然薄荷香帶著些微肉桂香氣，是日月潭茶區最有人氣的一支紅茶。', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18646/480x360_568d29406ed74014b9343fdbf93f50d5.jpg', 23.89618859999, 120.9350395999),
(491, '懷古茶簍-全體驗', '購買專線：0921-008077\r\n產地直送，如何訂購: 魚池鄉農會\r\n聯絡信箱：serviceyuchi@hotmail.com.tw\r\n竹篾順著編織的紋路滑動、淡淡的茶葉香慢慢地滲入鼻腔，凝視著一只只復刻的小茶簍，如同徜徉在茶園裡，幸福感猶然而生。茶簍包裝為日月潭茶區特有的採茶竹簍造型，以等比例縮小製成，除了裡面茶包膠膜是塑膠外，其餘皆是選用埔里在地紙廠做的環保包材，是一份愛護地球的心意。', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18648/480x360_4fca49b9dab747cfbfb0689a29eeda48.jpg', 23.89618859999, 120.9350395999),
(492, '龍眼乾果', '龍眼乾又名桂圓，每年七至八月為龍眼盛產期，加工烘焙二、三天左右，以人工撥殼取出龍眼肉後經日曬，口感更是Q甜好吃。', '高雄市內門區內豐村內埔1-1號', '07-667-2161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18650/480x360_a4ece94b040a467eac1eee6f8ec4a343.jpg', 22.94175459999, 120.4613715),
(493, '茶顏悅色', '購買專線：02-26657227、0922-843491\r\n聯絡信箱：suyin1078@yahoo.com.tw\r\n坪林的包種茶是香氣特別幽雅而飄逸的清茶，滋味甘潤，是茶中極品；蜜香紅茶具獨特的熟果香和蜜香，入口甘潤圓滑，堪稱絕色好茶。包種茶與蜜香紅茶製成茶包，方便消費者於職場或外出，隨時快速享用兩種特色茶，符合現代人生活忙碌之需求，為兼具環保、便利與地方特色的最佳伴手禮。', '新北市坪林區坪林村坪林街103號', '02-2665-7227', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18652/480x360_78f86b691edb4efaa81f66ac0acd0800.jpg', 24.936102, 121.7117779999),
(494, '信手拈茶-玫瑰紅茶', '購買專線：04-92222021、0921-335100\r\n產地直送，如何訂購: 南投縣農會\r\n聯絡信箱：sky69486948@gmail.com\r\n南投十分適合茶樹生長，自古就有台灣原生茶生長，居民遷入後，茶葉栽種技術及製茶工藝提升，為台灣重要茶葉產區之一。玫瑰紅茶，醇郁的紅茶佐以優雅甘甜的玫瑰花香，滑潤順口，養顏潤色、青春美麗。', '南投縣南投市南崗三路1號', '04-9225-1170', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18654/480x360_9520ec9042de4f169b663e0312dd76d8.jpg', 23.9222475, 120.6723086),
(495, '十三巡-大禹嶺', '購買專線：04-92222021、0921-335100\r\n產地直送，如何訂購: 南投縣農會\r\n聯絡信箱：sky69486948@gmail.com\r\n「南投好茶」已響譽國際，透過茶葉產銷履歷制度及產地證明標章進行農產品衛生安全認證把關，匯集十三鄉鎮市、八大茶區之萃，致力於產地耕耘，為茶農廣闢通路，創立「十三巡」品牌。', '南投縣南投市南崗三路1號', '04-9225-1170', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18656/480x360_a82c295ad5f74ffead2b73bc1db28a81.jpg', 23.9222475, 120.6723086),
(496, '十三巡-日月潭紅茶', '購買專線：04-92222021、0921-335100\r\n產地直送，如何訂購: 南投縣農會 (nthfa.org.tw)\r\n聯絡信箱：sky69486948@gmail.com\r\n十三巡日月潭紅茶：產地在魚池鄉日月潭茶區，台茶十八號，天然薄荷芬芳香氣，潤滑順口。', '南投縣南投市南崗三路1號', '04-9225-1170', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18658/480x360_c74ea49cfe754f8399540acf4244dbd6.jpg', 23.9222475, 120.6723086),
(497, '馬卡龍香米禮盒', '購買專線：08-9864880#14、0937-533328\r\n產地直送，如何訂購: 池上鄉農會\r\n聯絡信箱：u530101@yahoo.com.tw\r\n色彩繽紛的馬卡龍香米禮盒，是一份有特殊芋香的香米，粒粒晶瑩剔透，具有黏彈性、適合做炒飯、泡飯、便當。', '臺東縣池上鄉台東縣新興村85-6號', '08-986-4880', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18691/480x360_657dd696cba24e8097db156ac46789e8.jpg', 23.08902709999, 121.2278084999),
(498, '山海經脈-洛神花原味茶', '購買專線：08-9513111#15\r\n產地直送，如何訂購: 臺東縣農會\r\n聯絡信箱：lucky.a168@msa.hinet.net\r\n採新鮮洛神萼片，直接乾燥而成，保留洛神天然原味，富蘋果酸，汁液呈鮮紅色，味酸甘似初戀的滋味。', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18667/480x360_b77d0defde1c4164a6ff3a6f72a64ce9.jpg', 22.7555108, 121.142776),
(499, '手工黑豆蛋捲', '購買專線：05-5863621#167、0928-952273\r\n聯絡信箱：Ca64217504@gmail.com\r\n採用自己栽種的台灣黑豆，口感豐富、酥香、濃郁的黑豆香，一口咬下瞬間產生滿足的幸福感。', '雲林縣西螺鎮延平路353號', '05-586-3621', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18668/480x360_64387997b3fc4edc856089ba3f444763.jpg', 23.8003737, 120.4546302),
(500, '堅持無糖烏梅精強湯', '購買專線：04-92791949、0919-006914\r\n聯絡信箱：takahunter@hotmail.com\r\n產地直送，如何訂購: 信義鄉農會\r\n嚴選信義青梅原料，經過七天六夜不眠不休低溫烘焙，變成傳統純正烏梅，經過熬煮並加入梅精調色調味，孕育出最最最天然的無糖烏梅湯。', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18670/480x360_cd97f9725c8249e2b25b71512acd6ade.jpg', 23.68870099999, 120.861791),
(501, '熊愛梅片', '購買專線：04-92791949、0919-006914\r\n聯絡信箱：takahunter@hotmail.com\r\n嚴選信義青梅原料，每片薄片於舌尖化開，享受酸甜好滋味，隨身包更攜帶方便！', '南投縣信義鄉明德村新開巷11號', '0975-801-959', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18672/480x360_871471bc95e0407382facb5c7bb0b312.jpg', 23.68870099999, 120.861791),
(502, '產銷履歷 大安禮尋', '購買專線：04-26710909\r\n產地直送，如何訂購: 台中大安區農會 飛天豬生活館\r\n聯絡信箱：yiniuniu33@gmail.com\r\n安農肉品選用大安區肉品市場合格電宰的健康豬隻，只採用肉質結實有彈性的上等豬後腿肉，由通過 ISO 22000與HACCP食品安全驗證的大安區肉品市場肉品加工廠，以現代化設備遵循古法技術精心調理製作，展現高優質新鮮肉品的鮮美風味，健康、營養、衛生，是自用送禮的最佳選擇。', '臺中市大安區中庄里３鄰中松路６號', '04-2671-2229', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18674/480x360_32b3389163bf40b6b73545e5c82b6fc9.jpg', 24.3463873, 120.5870304),
(503, 'CAS龍崎竹炭片', '購買專線：06-5941114\r\n聯絡信箱：longcifas@gmail.com\r\nCAS標章驗證竹炭產品，不僅有國家為你把關，買來使用也比較安心，黑黝黝的竹炭片能除防潮除臭，還可改善水質、放電鍋中煮出來的白米飯更是香Q可口。', '臺南市龍崎區崎頂里7鄰223號', '06-594-1114', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18678/480x360_62d1c77a1fbc40f1a0eac6fa499d8db3.jpg', 22.966049, 120.360127),
(504, 'CAS龍崎竹醋液', '購買專線：06-5941114\r\n聯絡信箱：longcifas@gmail.com\r\n竹醋液是竹炭燒製過程中所產生的天然珍貴精華液體，PH值約為3-4，其主要成份以「醋酸」為主，也含有數百種天然有機物，廣泛運用於除臭抑菌、改善異味、入浴泡澡、軟化角質&hellip;等，效果頗受好評。', '臺南市龍崎區崎頂里7鄰223號', '06-594-1114', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18680/480x360_94208c67d90245ef8b57f69770d149af.jpg', 22.966049, 120.360127),
(505, '布農阿嬤的酒davus', '台東延平鄉布農部落以在地天然原料釀製阿嬤的小米酒，是為了祭天、感恩。布農小米酒 (davuz) 加上著友情的編織，希望分享給您這份甜美的喜悅。\r\n在布農族射日傳說裡，天上原本有兩個太陽，因曬死獵人的孩子而招致獵人射瞎，被射瞎的太陽變成了月亮。\r\n月亮與獵人達成了共存協議，月亮教導布農族人播種小米，族人則用小米釀酒祭天、祭月、祭人。\r\n台東延平鄉布農部落以在地天然原料釀製阿嬤小米酒，13%，香、醇、可口順喉，小口輕酌，暖你心房。', '臺東縣延平鄉桃源村11鄰昇平路191號', '08-956-1211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18692/480x360_87d05354d71a41afb08169bda724175e.jpg', 22.905841725183507, 121.09098270535469),
(506, '黃金柚子皮', '購買專線：06-6935666\r\n聯絡信箱：hungtzann@gmail.com\r\n嚴格篩選新鮮柚子皮，保留天然維他命、礦物質，產製過程中除了糖之外，不添加人工色素、糖精、防腐劑等添加物，豐富飽滿的鮮甜果味、果肉柔軟香Q，美味可口很受人喜愛。', '臺南市官田區建業路3號', '06-579-2818', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18712/480x360_20200328-10.jpg', 23.20696239999, 120.3299236999),
(507, '藍莓醋', '購買專線：03-5857148\r\n聯絡信箱：spfm8910@ms59.hinet.net\r\n嚴選農場特產小藍莓釀製而成，添加蜂蜜提味，與藍莓相輔相成，藍莓果的清香與酸甜滋味，造就出極具特色風味的藍莓醋。使用方法除了飲用之外，亦能作為佐醬與沙拉之調理用，是一瓶兼具多用途的好選擇。', '新竹縣五峰鄉桃山村民石380號', '03-585-6192', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18722/480x360_20200328-15.JPG', 24.5276476, 121.1178128),
(508, '紅茶梅', '購買專線：04-92898453\r\n聯絡信箱：serviceyuchi@hotmail.com.tw\r\n採用阿薩姆條型茶當原料及台灣在地黃梅，時間自然熟成；醃製過程嚴格把關茶梅品質，讓您品嚐最天然的紅茶梅。', '南投縣魚池鄉魚池街439號', '04-9289-5505', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18724/480x360_20200328-16.jpg', 23.89618859999, 120.9350395999),
(509, '薑汁餅乾', '購買專線：03-7951530\r\n聯絡信箱：mile951332@yahoo.com.tw\r\n（圖片為示意圖）\r\n無人工添加物.無香精.無香料.無防腐劑.非基因黃豆.熬煮8小時.手工製造.風味獨特。雲洞仙居是個消磨時光的最佳去處，老闆娘出身田媽媽家政班，善長一系列以「薑」為主題的點心，所以不論是薑汁撞奶、薑汁奶酪或現烤的薑汁餅乾，每每成為饕客最難忘的飯後點心！雲洞仙居介於大湖與三義之交界，居高臨下，可以欣賞日出、夕陽及變化萬千的雲海奇景，同時也是四季採果的絕佳去處，無論任何時節，都能盡情體驗採果樂趣', '苗栗縣大湖鄉栗林村薑麻園6號', '03-795-1530', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18728/480x360_20200328-18(2).jpg', 24.38572021051563, 120.82813024520874),
(510, '米鳳梨酥', '購買專線：05-6626009\r\n聯絡信箱：le_riz@yahoo.com.tw\r\n樂米工坊位於雲林縣土庫鎮，稻米產地主要是以濁水溪米為主，利用米穀粉來替代麵粉，米鳳梨酥吃起來較酥不油膩，少油、少糖，口感較輕爽。', '雲林縣土庫鎮建國路35巷3號', '05-662-6009', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18734/480x360_20200328-21.JPG', 23.6785502, 120.3977753),
(511, '金柑吸凍禮盒', '購買專線：03-9882033*110\r\n聯絡信箱：john.4h@gmail.com\r\n嚴選宜蘭礁溪安全認證的新鮮金柑鮮果醬汁製成，口感酸甜，不含色素、香料、塑化劑及防腐劑，用吸管就可直接食用，健康又美味。', '宜蘭縣礁溪鄉中山路1段175號之1', '03-988-2033', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18736/480x360_20200328-22.jpg', 24.82079209999, 121.7705359999),
(512, '富麗有機白米', '選用品種為高雄139號，產自富里鄉羅山有機示範村，在有機之栽培技術下，完全沒有使用化學肥料及農藥，純淨自然，是您最安心安全的選擇。', '花蓮縣富里鄉羅山村9鄰東湖6號', '03-882-1705', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18748/480x360_2富里鄉農會-有機白米jpg_w700px(2).jpg', 23.1838646, 121.2969674),
(513, '頭等倉伴手米禮盒', '日治時期台灣的重要產物，由北到南區域分別為 北茶（茶葉）中米（稻米）南糖（製糖業）當時也是台灣出口，或是供應台灣本土居民生活的重要物產\r\n其中由於稻米的改良，由原本的稻米改種出的新品種蓬萊米，更讓日本人視為重要政績，而也因此當時台灣中部（即當時的台中州廳行政區域），成為了日本人重要的米倉區域，深受當時政府的重視，也因此更積極開發台中州廳區域，也讓當時台中州廳所在地，現今台中市成為了中部人文薈萃的文化城市。\r\n但殖民時期對殖民區域居民的不公，連日常米食都劃分出等級，當時的老居民都知道，台中州廳區域生產的稻米，最好的稻米大部分都集中至台中市來，且連倉儲米糧也依等級存放，供應日本統治高層食用的稻米，皆必須存放在離倉最高的小閣樓，或二樓倉房，普通老百姓無緣嚐到，故當時流傳著一首打油詩\r\n台灣好米 台中州廳 等級最高 頭等倉米\r\n好米高高 阿本米蟲 台灣命賤 蕃薯當米\r\n \r\n抱持著對過去土地的感念，與對過去歷史的情愫，台中地區農會以比當時更嚴苛的標準，選出最為頂級的大台中區域稻米推出頭等倉米，希望讓當年無緣品嚐的在地居民，與台灣土地的晚輩，能品嚐到當年大墩（台中古地名）最引以為傲的米食飯香。', '臺中市西區向上路1段95號', '04-2302-3560', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18764/480x360_9台中地區農會頭等倉伴手禮盒（2公斤裝）jpg_w700px.jpg', 24.14655949999, 120.6632846),
(514, '夢田有機越光米(有機)', '宜蘭因地理、環境氣候等因素非常適合栽種越光米。經農會嚴選來自日本之原生稻種。全年一期耕作，米粒晶瑩剔透、油亮有光澤，軟中帶Q、香味可口。既使簡單調味或單吃，也能展現十足香氣及彈牙口感。', '宜蘭縣五結鄉五結中路二段7號', '03-950-1161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18766/480x360_12五結鄉農會夢田有機越光白米1公斤jpg_w700px.jpg', 24.6851467, 121.7976477),
(515, '夢田越光米', '晶瑩剔透之米中極品\r\n引進日本越光米稻種來本鄉耕作，栽種面積逐年增加，是台灣少數能種植越光米的地區之一；栽種出來的品質並不遜於日本當地所生產的，為台灣的No. 1。每一粒的越光米都是晶瑩剔透，最適合做壽司或蓋飯，本會又推出越光米禮盒，年節贈禮最實用。', '宜蘭縣五結鄉五結中路二段7號', '03-950-1161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18768/480x360_13五結鄉農會夢田越光米1公斤jpg_w700px.jpg', 24.6851467, 121.7976477),
(516, '百變薑餅人-提著幸福去旅行', '位於苗栗縣大湖鄉的薑麻園，海拔 500 至 800 多公尺，由於地形、土質、及天然氣候，其所生產的生薑的品質及數量，廣受各界讚譽。因此運用當地特產製成造型可愛的薑餅人，搖身一變成為旅途中隨手拾得的幸福，適合您與家人朋友一同分享。', '苗栗縣大湖鄉栗林村薑麻園6號', '03-795-1530', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18108/480x360_090-100 百變薑餅人-提著幸福去旅行_20111023 (400X320)-20151026160652.jpg', 24.38572021051563, 120.82813024520874),
(517, '田穗台梗九號', '&quot;稻穗的故鄉、田中的心意\r\n來自濁水溪優良水源灌溉的滋潤，及田中稻米產銷專區的全體契作班員的用心、用認真與汗水，像照顧自己的孩子般來呵護看著稻子－以飽滿的身段低頭微笑時，班員的重情、用心付出使得田中台梗九號米及台農71號香米粒粒飽滿晶亮，顆顆精挑細選口感香滑Ｑ嫩。\r\n充滿幸福滋味的良質米是您每餐必備、維繫全家健康的最佳選擇。 &quot;', '彰化縣田中鎮南北街80號', '04-874-9211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18774/480x360_16田中鎮農會田穗米1.2公斤jpg_w700px.jpg', 23.85965819999, 120.5863643),
(518, '田中台稉九號米', '&quot;稻穗的故鄉、田中的心意\r\n來自濁水溪優良水源灌溉的滋潤，及田中稻米產銷專區的全體契作班員的用心、用認真與汗水，像照顧自己的孩子般來呵護看著稻子－以飽滿的身段低頭微笑時，班員的重情、用心付出使得田中台梗九號米及台農71號香米粒粒飽滿晶亮，顆顆精挑細選口感香滑Ｑ嫩。\r\n充滿幸福滋味的良質米是您每餐必備、維繫全家健康的最佳選擇。 &quot;', '彰化縣田中鎮南北街80號', '04-874-9211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18776/480x360_17田中鎮農會田中九號米2公斤jpg_w700px.jpg', 23.85965819999, 120.5863643),
(519, '鹽水日曬意麵(寬麵)', '保有傳統手工意麵製麵工法\r\n台灣生產台灣製造小麥麵粉、產銷履歷玉米粉及全鴨蛋入麵,意想不到的全新口感\r\n精挑細選油蔥醬料包，完美搭配\r\n透過日曬增加麵體飽滿度及Q度,吃起來相當彈牙\r\n產品規格&售價：\r\n四包一袋裝\r\n空鍋放入800C.C.冷水,煮開後放入乾意麵,隨時撥鬆以免黏著,再煮3至4分鐘，\r\n撈起放入空碗加入獨家醬料包拌均勻即可食用。', '臺南市鹽水區西門路21號', '06-652-5071', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18788/480x360_7鹽水區農會-意麵2jpg_w700px.jpg', 23.319378, 120.2657841),
(520, '五結好禮-稻米禮盒', '適地適種優質米「夢田越光米」，米粒晶瑩剔透，口感及Q度均比一般米還要來的高，是目前全世界高品質稻米的代表。五結鄉農會推薦越光米伴手禮盒、女兒禮、吉米果子，以精緻五結好禮與您結緣。', '宜蘭縣五結鄉五結中路二段7號', '03-950-1161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18066/480x360_009-098 五結好禮-稻米禮盒_20091016 (400x320)-20151023171317.jpg', 24.6851467, 121.7976477),
(521, '溫泉米粉', '用優質溫泉米製成之溫泉純米粉、純米含高口感綿密好吃以冰水磨米法一貫作業完成，食用安全、衛生。', '宜蘭縣礁溪鄉中山路1段175號之1', '03-988-2033', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18803/480x360_13礁溪鄉農會-溫泉米粉3jpg_w700px.jpg', 24.82079209999, 121.7705359999),
(522, '溫泉糙米米粉', '用優質溫泉糙米製成之溫泉糙米純米粉，純米含高口感綿密好吃以冰水磨米法一貫作業完成，食用安全、衛生。', '宜蘭縣礁溪鄉中山路1段175號之1', '03-988-2033', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18805/480x360_14礁溪鄉農會-溫泉糙米米粉4jpg_w700px.jpg', 24.82079209999, 121.7705359999),
(523, '黃金蕃薯紅麴麵線', '', '彰化縣線西鄉寓埔村中央路二段20號', '04-758-3571', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18810/480x360_16線西鄉農會-黃金蕃薯紅麴麵線Ajpg_w700px(1).jpg', 24.130791, 120.4714953),
(524, '禾樂幸福芋鄉米粉湯', '', '臺中市大甲區中山路1段372號', '04-2686-3990', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18825/480x360_25大甲區農會米粉1jpg_w700px(1).jpg', 24.334949, 120.615858),
(525, '田中の牛奶麵麵', '跨越 八卦山脈尋覓 雪白濃郁清爽的香味遇見了 田中の好滋味\r\n在八卦山脈下的東南隅，田中鎮大崙幽靜的鄉間小徑，是田中農會輔導的酪農產銷專區，數大便是美黑白相間的大乳牛、擠出的新鮮好乳，結合田中農會對於優質營養麵條的堅持，在優閒雅緻中見著田中農會對牛奶麵麵品質的耐心與用心，照著每一步驟來、傳統手工手打；慢慢揉；慢慢曬，秉著重視養生健康的好理念，就如同做給自家人吃的心意，絕不添加防腐劑，田中農會對於品質要求嚴格，近乎苛求，堅持採用新鮮\r\n的現擠牛乳及高級麵粉作材料，純樸自然中看見了感動的用心。', '彰化縣田中鎮南北街80號', '04-874-9211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18827/480x360_26田中鎮農會牛奶麵麵jpg_w700px.jpg', 23.85965819999, 120.5863643),
(526, '芋香豆腐乳', '成分:黃豆、米、糖、酒、芋頭、鹽 保存期限２年 中平芋頭引用後龍溪富含礦物質的水，加上土質與環境條件', '苗栗縣銅鑼鄉銅鑼村永樂路22號', '03-798-1008', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31828/480x360_souvenir-image-nfkk6utx9ucysyiew3ahfw.jpg', 24.4879589, 120.7882386),
(527, '善化芝麻拌麵', '芝麻醬包是100％本地胡麻製作\r\n產地直送，如何訂購: 台南市善化區農會', '臺南市善化區中山路242號', '06-583-6111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18835/480x360_30善化區農會芝麻拌麵2jpg_w700px.jpg', 23.132757, 120.2976479999),
(528, '夢田之宴花漾禮盒', '引進日本新瀉原生稻種以宜蘭特有黑質營養土壤及雪山山脈留下的無汙染水質耕作，採用宜蘭全一期耕作方式，四個月的耕作，八個月的休耕養息並通過產銷履歷驗證米粒晶瑩，口感好、甜度高，即使簡單調味或單吃，也能展現十足香氣與彈牙口感。', '宜蘭縣五結鄉五結中路二段7號', '03-950-1161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18855/480x360_五結鄉農會.jpg', 24.6851467, 121.7976477),
(529, '香胚茶', '「香胚美人茶」是獨一無二的，用黑糯米的稻胚製成，經食品工業研究所分析，富含游離胺酸和花青素，花青素是天然抗氧化物，經過研究證實可以清除體內廢物，兼具保護眼睛的功能。', '嘉義縣太保市太保里58號', '05-371-1101', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31836/480x360_souvenir-image-759t5_aivuc5da5ktbhaaw.jpg', 23.4576038, 120.3320694),
(530, '安全金針花系列', '產於太麻里金針山海拔800-1400公尺，又名「雪針」，太麻里金針山環境氣候獨特，所生產金針特別鮮嫩香脆，風味絕佳，鐵的含量豐富，製作過程未薰硫磺又名「安全金針」。', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18858/480x360_54520201209.jpg', 22.604987, 121.001855),
(531, '紫蘇梅', '梅山之美，美在環山清新與竹林的幽靜翠綠，連綿的山巒與飄渺的雲海，交織成煦陽閃耀的現代淨土。梅山甘蔗種植於海拔1000公尺以上高山，天然純淨不受污染，以古法純手工研製成香糖，不添加防腐劑等人工化學物，並搭配當地特產「梅」，精心釀製成紫蘇梅，是年節送禮的好選擇。', '嘉義縣梅山鄉中山路127號', '05-262-2100', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18861/480x360_55220201209.jpg', 23.581617, 120.558779),
(532, '天然星健康粽(素)', '購買連結：奧丁丁市集-花蓮縣壽豐鄉農會', '花蓮縣壽豐鄉豐文路105號', '03-865-3101', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31841/480x360_souvenir-image-sg16fnctquowhjqxyaaswa.jpg', 23.8453491, 121.4976064),
(533, '古早味米香', '1.蘭麗米-使用台梗9號稻米,米粒飽滿透明,米飯香甜Q軟口感佳;真空包裝可保存六個月,適合現在家庭食用習慣。\r\n2.蘭麗香米-台農71號,白米有芋頭香味;米粒大而飽滿.透明度高,米飯黏Q彈性好,食用口感佳. 產品採真空包裝,保存期限長達六個月。\r\n使用方法： 開封後可放冰箱保存,避免生米蟲。', '臺南市後壁區頂安里300號', '06-636-1844', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/30158/480x360_souvenir-image-1y1z4pvpgkocnsqwu2jyqw.jpg', 23.3457755, 120.3540177),
(534, '長濱八仙米禮盒', '長濱鄉稻田面積約一千公頃，由於灌溉的水源是來自八仙洞附近山區的山泉水，所以出產的良質米以在地的景點八仙洞為名，注重安全、衛生、品質等要件。', '臺東縣長濱鄉長濱村7鄰58號', '08-983-2089', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31829/480x360_souvenir-image-i7e7o9d13umu0rholpjphg.jpg', 23.31691749999, 121.4551271),
(535, '長濱禮盒組-金剛獻好禮', '苦茶油是用油茶之種子經榨油機壓榨而得，油茶為山茶科山茶屬之常綠小喬木，苦茶油中所含的山茶甘素對於人體有很大的益處。苦茶含有豐富的蛋白質、維生素A、E等，更是單元不飽和脂肪酸含量最豐富之食用油。', '臺東縣長濱鄉長濱村7鄰58號', '08-983-2089', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31825/480x360_souvenir-image-exo5pcghg0emwqdcdwuvhw.jpg', 23.31691749999, 121.4551271),
(536, '柚香美人果茶', '以文旦柚果肉及釀造醋釀製而成，經過濾及高溫滅菌後裝瓶完成，保留了文旦柚本身的香味及營養成份等特性，為求健康概念特別以水果自然甜份釀製，不加糖及蜂蜜，因此口感較酸烈，食用時請依各人口味增加糖及蜂蜜。', '新北市八里區中山路2段366號', '02-2610-2996', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18865/480x360_58020201209.jpg', 25.14990489999, 121.4044363),
(537, '藺草手工藝品-草蓆、草帽', '藺草，是過去歲月中帶給許多苑裡人生計與回憶的重要植物，藺草編織的帽蓆，精緻美觀、透氣、吸汗、還散發清香；而藺編的收入也提供了許多人的就業與就學的機會。這樣的歷史事實，包含著辛酸、智慧，也包含著台灣先民善於運用自然資源的巧思與手藝。　 　\r\n藺編綿密而細緻的紋路是生活的態度，柔軟而充滿韌性的手感則是對生活的堅持，然而傳統工藝沒落之後的傳承、延續與創新，便成了當務之急。93年7月份藺草文化館成立後大力推動本項符合在地特色與環保之產品，希望讓傳統延續下去。', '苗栗縣苑裡鎮山腳里灣麗路99號', '03-774-0148', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18866/480x360_59020201209.jpg', 24.414397, 120.685623),
(538, '筍漬 醬筍', '前人生活困苦，物資缺乏，沒有冰箱可以保存食物，總是把醬筍醃的又鹹又甜重口味以利存放。蔡家媳婦陳玉女嫁到大坑已經近30年，大家都叫她「蔡媽」，對料理非常有一套的她，將地方特色食材加以發揮利用，醬筍是當地婦女必學的醃製品，蔡媽按照現代人生活飲食習慣，將口味改良，清新帶有一番風味的醃製筍，除了可以吃到厚厚的思念家鄉味，更可嚐到那份健康親切的幸福味。\r\n線上訂購: 大坑休閒農場', '臺南市新化區大坑里82號', '06-594-1555', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18867/480x360_59520201209.jpg', 23.0072204, 120.3904996),
(539, '竹醋沐光禮盒', '為推廣本鄉竹林產業產值低及無利用價值竹材再利用，提高竹子產業及其附加價值，並活絡地方文化及休閒產業。「竹好炭」意味著「祝好賺」，藉由開發多樣化竹炭相關系列產品，以增加在地青年就業機會、農民收入、農會收益，創造本鄉竹林產業再利用和無限生機。', '臺南市龍崎區崎頂里7鄰223號', '06-594-1114', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31843/480x360_souvenir-image-mer_hbfn90sicumas4tyrq.png', 22.966049, 120.360127),
(540, '平交道菓菜酥禮盒', '雲林縣的柳橙產量佔全國4成之多，且香甜多汁，雲林縣政府希望讓更多消費者吃到好吃的雲林黃金橙，結合了民間企業開發出許多柳丁特產', '雲林縣褒忠鄉新湖村復興路17-2號', '05-697-2425', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/31820/480x360_souvenir-image-gztgdgavvuuskvuhejqvpa.jpg', 23.70798879999, 120.285347),
(541, '銅鑼杭菊茶', '苗栗縣銅鑼地區於民國50年代開始種植杭菊，由中藥材轉變農村觀光休閒。今花茶系列飲品加入東方美人茶，沖泡後更有意想不到之風味。', '苗栗縣銅鑼鄉銅鑼村永樂路22號', '03-798-1008', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18871/480x360_60320201209.jpg', 24.4879589, 120.7882386),
(542, '山海經脈洛神花蜜餞', '「山海經」是中國最早介紹有關於自然界礦物質的一本著作，在此「山海」與台東天然的山、海景相呼應，期許心靈、生理養生觀念，可以沿著人體的經脈運行，採台東火紅盛開的新鮮洛神花萼製作，保留了其原始的酸味及香氣，味道酸甜似初戀的滋味，風味絕佳，希望傳遞台東優質農產的特色。\r\n產地直送，如何訂購: 台東縣農會', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18875/480x360_60620201209.jpg', 22.7555108, 121.142776),
(543, '新鮮飲禮盒', '公館即飲醋系列嚴選在地紅棗、紫蘇、桑椹、洛神、金桔等製造，絕無污染及農藥殘留，讓消費者買得安心、用得放心。', '苗栗縣公館鄉館東村大同路266號', '03-722-5211', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18881/480x360_61020201209.jpg', 24.50464069999, 120.8273643999),
(544, '荔枝蜂蜜酒', '採用霧峰當地盛產的蜂蜜與荔枝原汁、以及埔里的優質好水經低溫發酵所釀造，清淡滑順、天然新鮮的金黃玉液，趁冰涼沁心時咕嚕飲下，享受青春洋溢的醺甜！\n《當初╱如今》荔枝蜂蜜酒是掌生榖粒與來自台中的霧峰農會酒莊初次共同呈現的美好，美好的時光千金不喚，我們用時間副詞說酒話，真心珍惜這些將時間濃縮的產物。', '臺中市霧峰區中正里四德路10號', '04-2339-3404', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18885/480x360_61220201209.jpg', 24.0651751, 120.679522),
(545, '時光寶盒', '嚴選新鮮愛文芒果、土芒果、鳳梨，手工製作，不添加色素、防腐劑，多道烘焙封存最溫潤的口感，片片原汁原味，多層次風味，用心呵護每一個製作過程，傳遞溫暖的手作幸福，讓最簡單的食物，片片獨一無二清新果香，讓您一口接一口回味在心頭，是你我最愛的小秘密。', '臺南市玉井區中正路139號', '06-574-2216', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18891/480x360_61520201209.jpg', 23.17685709999, 120.4852097),
(546, '蕃茄乾', '品質新鮮度嚴格篩選台灣在地番茄，保留天然維他命、礦物質，產製過程中除了糖之外，不添加人工色素、糖精、防腐劑等添加物，豐富飽滿的鮮甜果味、果肉柔軟香Q，美味可口很受人喜愛。', '臺南市官田區建業路3號', '06-579-2818', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18893/480x360_61620201209.jpg', 23.20696239999, 120.3299236999),
(547, '水果酒禮盒', '有洛神、桂圓、芒果等3種口味，產品未添加防腐劑，期限3個月。', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18894/480x360_62020201209.jpg', 22.604987, 121.001855),
(548, '原汁禮盒', '有洛神、桂圓、芒果等3種口味，產品未添加防腐劑，期限3個月。', '臺東縣太麻里鄉太麻里街161號', '08-978-0400', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18896/480x360_62120201209.jpg', 22.604987, 121.001855),
(549, '瑞穗蜜香紅茶', '每年三月間是文旦柚樹開花的時節，當柚花遇到瑞穗有名的天鶴茶，就成了香氣迷人的上品柚花茶。運用了一年才綻開一次的柚花與茶葉共同烘焙而成的花茶，不但可 以喝到茶葉的甘醇，回甘時還帶有誘人的天然芳香。', '花蓮縣瑞穗鄉中山路一段128號', '03-887-2226', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/30180/480x360_souvenir-image-jbx5khue0kegp176nr5q2g.jpg', 23.496431, 121.381484),
(550, '桑椹汁(無糖)', '自然生態農法栽種桑椹，由人工精心選果、清洗、風乾、急速冷凍，熬煮過程中不加一滴水和化學添加物，為國產水果抗氧化能力第一名。\r\n產地直送，如何訂購: 張媽媽休閒農場', '高雄市大樹區興田路116-1號', '07-656-3635', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18900/480x360_63220201209.jpg', 22.747174358116073, 120.44812560081482),
(551, '嬌澳蝦餅(胡椒口味)', '來自南方澳專屬限定好滋味，選用蘇澳特產-長角鬥士赤蝦，金黃色圓圓的飛盤形狀非常討喜，一片一口咬下鮮脆響聲，飽滿鮮蝦味充滿整個口腔。\r\n產地直送，如何訂購 : 蘇澳區漁會', '宜蘭縣蘇澳鎮南安里海邊路126號', '03-996-2108', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18902/480x360_63920201209.jpg', 24.5833868, 121.8659277),
(552, '金萱紅茶', '特選小葉種台茶12號金萱茶菁，以全發酵製作，茶湯色澤艷紅誘人、茶香清新撲鼻，一口飲下可以品嘗到特有奶香和甘蔗香，廣受紅茶愛好者歡迎。\r\n產地直送，如何訂購: 名間鄉農會', '南投縣名間鄉彰南路26號', '04-9273-2111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18906/480x360_64120201209.jpg', 23.8368341, 120.703988),
(553, '鮮紅豆真空包盒裝', '來自『紅豆的故鄉』屏東萬丹的嚴選國寶級風味紅豆，經過SGS檢驗及381項農藥殘留檢驗無農藥殘留，紅豆粒粒飽滿、色澤鮮紅亮麗，適合各種料理。\r\n產地直送，如何訂購 : 屏東縣萬丹鄉農會', '屏東縣萬丹鄉萬丹路一段25號', '08-777-2007', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18908/480x360_64320201209.jpg', 22.58455, 120.488925),
(554, '萬丹紅豆湯禮盒', '嚴選萬丹紅豆獨家製程熬煮，每一口都吃得到顆粒飽滿的紅豆，口感綿密且不軟爛，佐以些微甜度，更加凸顯萬丹紅豆獨特風味及香氣。\r\n產地直送，如何訂購: 萬丹鄉農會', '屏東縣萬丹鄉萬丹路一段25號', '08-777-2007', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18910/480x360_64420201209.jpg', 22.58455, 120.488925),
(555, '黑米紅豆粥禮盒', '精選萬丹『紅豆』、『黑米』熬煮製成，完整保留紅豆及黑米的營養成份，擁有豐富膳食纖維、天然花青素及多種微量元素，搭配鮮奶更是絕配！\r\n產地直送，如何訂購: 萬丹鄉農會', '屏東縣萬丹鄉萬丹路一段25號', '08-777-2007', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18912/480x360_64520201209.jpg', 22.58455, 120.488925),
(556, '紅藜紅豆粥', '寶石般的『紅藜』加上鑽石般『紅豆』，紅豆獨有香氣與綿密細緻味蕾，融入紅藜煮熟特殊風味，美味與營養最佳完美結合，隨時隨地吃的健康安心。\r\n產地直送，如何訂購: 屏東縣農會', '屏東縣屏東市瑞民路6號3樓', '08-722-3805', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18914/480x360_64620201209.jpg', 22.6631428, 120.5075365),
(557, '龍膽休閒禮盒組(龍膽麻辣切片+龍膽魚肉丁角)', '高級餐廳獨有龍膽石斑變身居家休閒零食，『龍膽石斑魚麻辣切片』少了魚腥味多了扎實與Q彈口感，加上獨家辣椒配方，將魚肉鮮味直接升級。『龍膽魚肉丁角』以魚漿作成丁角基底，中間鋪上滿滿鹹蛋肉鬆及肉乾丁加上芝麻點綴，完美呈現黃金比例海陸雙拼饗宴。\r\n產地直送，如何訂購: 永安漁會購物網', '高雄市永安區新興路27之2號', '07-691-2020', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18916/480x360_64720201209.jpg', 22.8175669, 120.210497),
(558, '養生黑蒜禮盒', '來自『蒜頭故鄉』，選用新鮮生蒜，長時間自然發酵，由原本乳白色變成黑褐色，提供人體每日所需18種「胺基酸」，不辣口、無任何添加劑，最天然健康養生食品。\r\n產地直送，如何訂購: 土庫鎮農會', '雲林縣土庫鎮建國路37-1號', '05-662-9111', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18918/480x360_65120201209.jpg', 23.67755049999, 120.3898291),
(559, '茗水間阿里山高山茶', '採集阿里山高海拔茶農精心所種植的茶葉，製作出清香甘醇具有獨特風味的「高山烏龍茶」，茶湯入喉甘醇圓潤、飲後口齒留香生津解渴，適合四季飲用。\r\n產地直送，如何訂購: 中埔鄉農會', '嘉義縣中埔鄉内山公路128號', '05-253-2201', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18920/480x360_65320201209.jpg', 23.4728954, 120.5384742),
(560, '佛手瓜泡菜', '來自阿里山奮起湖最天然山珍野味，透過媽媽味古道廚娘巧手，清脆鮮甜，高山佛手瓜化身餐桌下飯餐點，熟客一致好評、回購率最高的山林美。快來嘗一口，你一定也會愛上這道爽口的酸甜漬菜。', '嘉義縣竹崎鄉中和村奮起湖165-2號(奮起湖鐵道旁)', '05-256-1645', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18924/480x360_65520201209.jpg', 23.506149294418364, 120.69569081068039),
(561, '冷凍蒲燒鰻', '日本人首選的養生進補食材，特選鹿港優質成鰻，富含豐富蛋白質、維生素、不飽和脂肪酸等，通過食品GMP及台灣優良農產品認證，高貴不貴現代養生好物蒲燒鰻。\r\n產地直送，如何訂購冷凍蒲燒鰻: 彰化區漁會供銷部', '彰化縣鹿港鎮復興路485號4樓', '04-778-8945', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18926/480x360_65620201209.jpg', 24.0587671, 120.434389),
(562, '御品苿莉語茶', '選用『茉莉花故鄉』花壇鄉生產之無毒茉莉，花農們遵循古法，親手摘下每一朵以安全農法栽種的茉莉花，並將這份單純而美好的幸福與您分享。歡迎一起體驗這個綿延半世紀的清甜花香。', '彰化縣花壇鄉花壇村花壇街273號', '04-786-7821', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18928/480x360_65720201209.jpg', 24.02599, 120.537346),
(563, '芋燒酎+薯燒酎', '以在地盛產芋頭和番薯，運用日本燒酎專業製作工法，透過酒本身溫度，將食材天然香氣封存於酒中，淡雅酒香伴隨著溫順口感入喉，釀造出專屬台灣本地燒酒。\r\n產地直送，如何訂購芋燒耐+薯燒耐: 大安區農會', '臺中市大安區中庄里３鄰中松路６號', '04-2671-2229', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18930/480x360_65820201209.jpg', 24.3463873, 120.5870304),
(564, '飛天豬腸鮮禮盒', '堅持「三安、四不、一堅持」食安原則，以「安心呷、農為您」品質承諾，選用衛生電宰國產豬肉，製成包含鹹豬肉、香腸、貢丸等禮盒。\r\n產地直送，如何訂購飛天豬腸鮮禮盒: 大安區農會', '臺中市大安區中庄里３鄰中松路６號', '04-2671-2229', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18932/480x360_65920201209.jpg', 24.3463873, 120.5870304),
(565, '黃金大豆魯豬腳', '運用當地生產的優質大豆、及擁有產銷履歷的豬隻，開發出黃金大豆魯豬腳，Ｑ嫩豬腳肉充滿膠質，還多了一股濃郁豆香：減輕油膩感，可搭配麵線、白飯食用，醬香、肉嫩Ｑ彈，在嘴裡達成完美平衡，讓人唇齒留香。\r\n產地直送，如何訂購黃金大豆魯豬腳: 梧棲區農會', '臺中市梧棲區台中市草湳里港埠路一段545號', '04-2639-2611', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18934/480x360_66020201209.jpg', 24.2369404, 120.528115),
(566, '山珍好禮(乾香菇)', '嚴選臺中市新社區香菇，香菇大朵、肉厚、香味十足，產製過程經過新社農會層層把關，從製包、栽培、採收、包裝等，都經過SGS檢驗合格，過程嚴格篩選，讓消費者食的安心。\r\n產地直送，如何訂購山珍好禮: 新社區農會', '臺中市新社區新社里中和街4段226號', '04-2581-1511', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18936/480x360_66120201209.jpg', 24.2421857, 120.8072061),
(567, '四角林咖啡莊園咖啡濾掛盒', '以無農藥方式種植咖啡樹，咖啡樹種植區域也是百萬螢火蟲的原始棲地，每年四月至五月，莊園有百萬螢火蟲翩翩飛舞，證明所生產的咖啡豆天然純淨、絕無污染。咖啡蘊藏的香氣揉合了野薑花韻、山梅果酸及焦糖等風味，值得品嘗。\r\n產地直送，如何訂購四角林咖啡莊園咖啡濾掛盒: 臺中市農會', '臺中市東勢區勢林街1號', '04-25887161', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18938/480x360_66220201209.jpg', 24.289295641723815, 120.88823318481445),
(568, '可樂果-米穀酥(蒜味)', '可樂果-米穀酥採用池上鄉農會契作的高雄147號香米，品質優良、米香十足，經過研磨成純米穀粉，委託聯華食品製作，推出螺旋造型、口感獨特的酥脆米香口感，佐以經典蒜香調味，讓你涮嘴不停手，一口接一口!\r\n產地直送，如何訂購可樂果米穀酥: 池上鄉農會', '臺東縣池上鄉台東縣新興村85-6號', '08-986-4880', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18940/480x360_66420201209.jpg', 23.08902709999, 121.2278084999),
(569, '山海經脈-高山野菊(油菊)', '嚴選小農高山種植之野菊，風味清香、原色原味，栽種過程不使用化學農藥及化學肥料，消費者可食用得安心。包裝設計簡潔透明，從小小的瓶口倒出野菊花別有一番趣味。\r\n產地直送，如何訂購: 臺東縣農會', '臺東縣台東市新生路268號', '08-932-4377', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18942/480x360_66520201209.jpg', 22.7555114, 121.1427744),
(570, '毛豆香腸禮盒', '毛豆香腸嚴選採用熱量低、肉質佳、含高蛋白的後腿肉，肉中無筋香腸的肥瘦比例適中，不會過肥過膩，搭配毛豆顆粒吃起來鮮甜軟Q又涮嘴，不管單吃或是搭配蒜片都很開胃！\r\n產地直送，如何訂購: 新市區農會', '臺南市新市區復興路1之1號', '06-589-9888', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18944/480x360_66820201209.jpg', 23.0792851, 120.2955182),
(571, '哈密瓜醬瓜', '選用台灣在地哈密瓜，經過古法釀製哈密瓜醬瓜，用於煮湯（哈密瓜雞湯）或絞肉（蜜瓜鮮肉）風味絕佳。', '宜蘭縣壯圍鄉新南村霧罕路3號', '03-925-3517', 'https://ezgo.ardswc.gov.tw/_api/content/images/souvenir/18949/480x360_61720201209.jpg', 24.7205496, 121.8050125),
(572, '布萊德超值禮盒', '要買要快', '布萊德大公司', '04-12345678', 'https://greateimg', 24, 123),
(573, '布萊德超值禮盒', '要買要快', '布萊德大公司', '04-12345678', 'https://greateimg', 24, 123);
